INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('At', 26, 'pt', '[{"numero": 1, "texto": "E Agripa disse a Paulo: É permitido a ti falar por ti mesmo.Então Paulo, estendendo a mão, respondeu em sua defesa:"}, {"numero": 2, "texto": "Eu me considero feliz, rei Agripa, de que diante de ti eu esteja hoje fazendo minha defesa de todas as coisas de que sou acusado pelos judeus;"}, {"numero": 3, "texto": "Principalmente [por] eu saber que tu sabes de todos os costumes e questões que há entre os judeus; por isso eu te rogo que tu me ouças com paciência."}, {"numero": 4, "texto": "Ora, a minha vida é conhecida por todos os judeus, desde a [minha] juventude, que desde o princípio tem sido entre [os de] minha nação em Jerusalém;"}, {"numero": 5, "texto": "Eles me conhecem desde o começo, se quiserem testemunhar, de que conforme a mais rigorosa divisão de nossa religião, eu vivi [como] fariseu."}, {"numero": 6, "texto": "E agora, pela esperança da promessa que por Deus foi dada aos nossos pais, eu estou [aqui] sendo julgado."}, {"numero": 7, "texto": "À qual nossas doze tribos, servindo continuamente [a Deus] de dia e de noite, esperam chegar; pela qual esperança, rei Agripa, eu sou acusado pelos judeus."}, {"numero": 8, "texto": "Por que se julga como incrível entre vós que Deus ressuscite aos mortos?"}, {"numero": 9, "texto": "Eu realmente tinha pensado comigo mesmo, que contra o nome de Jesus eu tinha que fazer muitas oposições."}, {"numero": 10, "texto": "O que eu também fiz em Jerusalém; e tendo recebido autoridade dos chefes dos sacerdotes, eu pus em prisões a muitos dos santos; e quando eles eram mortos, eu [também] dava meu voto contra [eles] ."}, {"numero": 11, "texto": "E tendo lhes dado punição muitas vezes por todas as sinagogas, eu os forcei a blasfemarem. E estando extremamente enfurecido contra eles, até nas cidades estrangeiras eu os persegui;"}, {"numero": 12, "texto": "Nas quais, indo eu até Damasco, com autoridade e comissão dos chefes dos sacerdotes;"}, {"numero": 13, "texto": "Ao meio dia, vi no caminho, rei, uma luz do céu, que brilhava muito mais que o sol, e que encheu de claridade ao redor de mim e dos que iam comigo."}, {"numero": 14, "texto": "E todos nós, tendo caído ao chão, eu ouvi uma voz que falava a mim, e dizia em língua hebraica: Saulo, Saulo, por que me persegues? Duro é para ti dar coices contra os aguilhões."}, {"numero": 15, "texto": "E eu disse: Quem és, Senhor? E ele disse: Eu sou Jesus, a quem tu persegues."}, {"numero": 16, "texto": "Mas levanta-te, e fica de pé, porque para isto eu apareci a ti, para te predeterminar como trabalhador e testemunha, tanto das coisas que [já] tens visto, como das coisas que eu [ainda] aparecerei a ti;"}, {"numero": 17, "texto": "Livrando-te d [este] povo, e [dos] gentios, aos quais agora eu te envio."}, {"numero": 18, "texto": "Para abrir os olhos deles, e das trevas converterem à luz, e do poder de Satanás [converterem] a Deus; para que recebam perdão dos pecados, e herança entre os santificados pela fé em mim."}, {"numero": 19, "texto": "Portanto, rei Agripa, eu não fui desobediente à visão celestial."}, {"numero": 20, "texto": "Mas sim, primeiramente aos [que estavam] em Damasco e Jerusalém, e por toda a terra da Judeia, e aos gentios anunciei que se arrependessem, e se convertessem a Deus, fazendo obras dignas de arrependimento."}, {"numero": 21, "texto": "Por causa disto os judeus me pegaram no Templo, e procuravam [me] matar."}, {"numero": 22, "texto": "Porém tendo eu obtido socorro de Deus, permaneço até o dia de hoje, dando testemunho tanto a pequenos como a grandes; não dizendo nada além dos que as [coisas] que os profetas e Moisés tinham dito que estavam para acontecer;"}, {"numero": 23, "texto": "[Isto é] , que o Cristo sofreria, e sendo o primeiro da ressurreição dos mortos, ia anunciar a luz a este povo e aos gentios."}, {"numero": 24, "texto": "E tendo [Paulo] dito isto em [sua] defesa, Festo disse em alta voz: Tu estás louco, Paulo; as muitas escrituras te fizeram enlouquecer!"}, {"numero": 25, "texto": "Mas ele [respondeu] : Eu não estou louco, excelentíssimo Festo; mas eu declaro palavras de verdade e de um são juízo;"}, {"numero": 26, "texto": "Porque o rei, a quem eu estou falando livremente, ele sabe [muito bem] destas coisas; porque eu não creio que nenhuma disto lhe seja oculto; por que isto não foi feito num canto."}, {"numero": 27, "texto": "Rei Agripa, tu crês nos profetas? Eu sei que tu crês."}, {"numero": 28, "texto": "E Agripa disse a Paulo: Por pouco tu me convences a me tornar cristão."}, {"numero": 29, "texto": "E Paulo disse: Meu desejo a Deus é que, por pouco ou por muito, não somente tu, mas todos os que estão me ouvindo hoje, tais vos tornásseis assim como eu sou, a não ser por estas correntes."}, {"numero": 30, "texto": "E tendo ele dito isto, o rei se levantou, e [também] o governador, Berenice, e os que estavam sentados com eles."}, {"numero": 31, "texto": "E reunindo-se à parte, falavam uns aos outros, dizendo: Este homem nada faz [que seja] digno de morte ou de prisões."}, {"numero": 32, "texto": "E Agripa disse a Festo: Este homem podia ser solto, se ele não tivesse apelado a César."}]'::jsonb, 'Almeida Livre'),
  ('At', 26, 'en', '[{"numero": 1, "texto": "Then Agrippa said unto Paul, Thou art permitted to speak for thyself. Then Paul stretched forth the hand, and answered for himself:"}, {"numero": 2, "texto": "I think myself happy, king Agrippa, because I shall answer for myself this day before thee touching all the things whereof I am accused of the Jews:"}, {"numero": 3, "texto": "Especially because I know thee to be expert in all customs and questions which are among the Jews: wherefore I beseech thee to hear me patiently."}, {"numero": 4, "texto": "My manner of life from my youth, which was at the first among mine own nation at Jerusalem, know all the Jews;"}, {"numero": 5, "texto": "Which knew me from the beginning, if they would testify, that after the most straitest sect of our religion I lived a Pharisee."}, {"numero": 6, "texto": "And now I stand and am judged for the hope of the promise made of God, unto our fathers:"}, {"numero": 7, "texto": "Unto which promise our twelve tribes, instantly serving God day and night, hope to come. For which hope''s sake, king Agrippa, I am accused of the Jews."}, {"numero": 8, "texto": "Why should it be thought a thing incredible with you, that God should raise the dead?"}, {"numero": 9, "texto": "I verily thought with myself, that I ought to do many things contrary to the name of Jesus of Nazareth."}, {"numero": 10, "texto": "Which thing I also did in Jerusalem: and many of the saints did I shut up in prison, having received authority from the chief priests; and when they were put to death, I gave my voice against them."}, {"numero": 11, "texto": "And I punished them oft in every synagogue, and compelled them to blaspheme; and being exceedingly mad against them, I persecuted them even unto strange cities."}, {"numero": 12, "texto": "Whereupon as I went to Damascus with authority and commission from the chief priests,"}, {"numero": 13, "texto": "At midday, O king, I saw in the way a light from heaven, above the brightness of the sun, shining round about me and them which journeyed with me."}, {"numero": 14, "texto": "And when we were all fallen to the earth, I heard a voice speaking unto me, and saying in the Hebrew tongue, Saul, Saul, why persecutest thou me? it is hard for thee to kick against the pricks."}, {"numero": 15, "texto": "And I said, Who art thou, Lord? And he said, I am Jesus whom thou persecutest."}, {"numero": 16, "texto": "But rise, and stand upon thy feet: for I have appeared unto thee for this purpose, to make thee a minister and a witness both of these things which thou hast seen, and of those things in the which I will appear unto thee;"}, {"numero": 17, "texto": "Delivering thee from the people, and from the Gentiles, unto whom now I send thee,"}, {"numero": 18, "texto": "To open their eyes, and to turn them from darkness to light, and from the power of Satan unto God, that they may receive forgiveness of sins, and inheritance among them which are sanctified by faith that is in me."}, {"numero": 19, "texto": "Whereupon, O king Agrippa, I was not disobedient unto the heavenly vision:"}, {"numero": 20, "texto": "But shewed first unto them of Damascus, and at Jerusalem, and throughout all the coasts of Judaea, and then to the Gentiles, that they should repent and turn to God, and do works meet for repentance."}, {"numero": 21, "texto": "For these causes the Jews caught me in the temple, and went about to kill me."}, {"numero": 22, "texto": "Having therefore obtained help of God, I continue unto this day, witnessing both to small and great, saying none other things than those which the prophets and Moses did say should come:"}, {"numero": 23, "texto": "That Christ should suffer, and that he should be the first that should rise from the dead, and should shew light unto the people, and to the Gentiles."}, {"numero": 24, "texto": "And as he thus spake for himself, Festus said with a loud voice, Paul, thou art beside thyself; much learning doth make thee mad."}, {"numero": 25, "texto": "But he said, I am not mad, most noble Festus; but speak forth the words of truth and soberness."}, {"numero": 26, "texto": "For the king knoweth of these things, before whom also I speak freely: for I am persuaded that none of these things are hidden from him; for this thing was not done in a corner."}, {"numero": 27, "texto": "King Agrippa, believest thou the prophets? I know that thou believest."}, {"numero": 28, "texto": "Then Agrippa said unto Paul, Almost thou persuadest me to be a Christian."}, {"numero": 29, "texto": "And Paul said, I would to God, that not only thou, but also all that hear me this day, were both almost, and altogether such as I am, except these bonds."}, {"numero": 30, "texto": "And when he had thus spoken, the king rose up, and the governor, and Bernice, and they that sat with them:"}, {"numero": 31, "texto": "And when they were gone aside, they talked between themselves, saying, This man doeth nothing worthy of death or of bonds."}, {"numero": 32, "texto": "Then said Agrippa unto Festus, This man might have been set at liberty, if he had not appealed unto Caesar."}]'::jsonb, 'King James Version'),
  ('At', 26, 'fr', '[{"numero": 1, "texto": "Agrippa dit à Paul: Il t''''est permis de parler pour ta défense. Et Paul, ayant étendu la main, se justifia en ces termes:"}, {"numero": 2, "texto": "Je m''''estime heureux, roi Agrippa, d''''avoir aujourd''''hui à me justifier devant toi de toutes les choses dont je suis accusé par les Juifs,"}, {"numero": 3, "texto": "car tu connais parfaitement leurs coutumes et leurs discussions. Je te prie donc de m''''écouter avec patience."}, {"numero": 4, "texto": "Ma vie, dès les premiers temps de ma jeunesse, est connue de tous les Juifs, puisqu''''elle s''''est passée à Jérusalem, au milieu de ma nation."}, {"numero": 5, "texto": "Ils savent depuis longtemps, s''''ils veulent le déclarer, que j''''ai vécu pharisien, selon la secte la plus rigide de notre religion."}, {"numero": 6, "texto": "Et maintenant, je suis mis en jugement parce que j''''espère l''''accomplissement de la promesse que Dieu a faite à nos pères,"}, {"numero": 7, "texto": "et à laquelle aspirent nos douze tribus, qui servent Dieu continuellement nuit et jour. C''''est pour cette espérance, ô roi, que je suis accusé par des Juifs!"}, {"numero": 8, "texto": "Quoi! vous semble-t-il incroyable que Dieu ressuscite les morts?"}, {"numero": 9, "texto": "Pour moi, j''''avais cru devoir agir vigoureusement contre le nom de Jésus de Nazareth."}, {"numero": 10, "texto": "C''''est ce que j''''ai fait à Jérusalem. J''''ai jeté en prison plusieurs des saints, ayant reçu ce pouvoir des principaux sacrificateurs, et, quand on les mettait à mort, je joignais mon suffrage à celui des autres."}, {"numero": 11, "texto": "je les ai souvent châtiés dans toutes les synagogues, et je les forçais à blasphémer. Dans mes excès de fureur contre eux, je les persécutais même jusque dans les villes étrangères."}, {"numero": 12, "texto": "C''''est dans ce but que je me rendis à Damas, avec l''''autorisation et la permission des principaux sacrificateurs."}, {"numero": 13, "texto": "Vers le milieu du jour, ô roi, je vis en chemin resplendir autour de moi et de mes compagnons une lumière venant du ciel, et dont l''''éclat surpassait celui du soleil."}, {"numero": 14, "texto": "Nous tombâmes tous par terre, et j''''entendis une voix qui me disait en langue hébraïque: Saul, Saul, pourquoi me persécutes-tu? Il te serait dur de regimber contre les aiguillons."}, {"numero": 15, "texto": "Je répondis: Qui es-tu, Seigneur? Et le Seigneur dit: Je suis Jésus que tu persécutes."}, {"numero": 16, "texto": "Mais lève-toi, et tiens-toi sur tes pieds; car je te suis apparu pour t''''établir ministre et témoin des choses que tu as vues et de celles pour lesquelles je t''''apparaîtrai."}, {"numero": 17, "texto": "Je t''''ai choisi du milieu de ce peuple et du milieu des païens, vers qui je t''''envoie,"}, {"numero": 18, "texto": "afin que tu leur ouvres les yeux, pour qu''''ils passent des ténèbres à la lumière et de la puissance de Satan à Dieu, pour qu''''ils reçoivent, par la foi en moi, le pardon des péchés et l''''héritage avec les sanctifiés."}, {"numero": 19, "texto": "En conséquence, roi Agrippa, je n''''ai point résisté à la vision céleste:"}, {"numero": 20, "texto": "à ceux de Damas d''''abord, puis à Jérusalem, dans toute la Judée, et chez les païens, j''''ai prêché la repentance et la conversion à Dieu, avec la pratique d''''oeuvres dignes de la repentance."}, {"numero": 21, "texto": "Voilà pourquoi les Juifs se sont saisis de moi dans le temple, et ont tâché de me faire périr."}, {"numero": 22, "texto": "Mais, grâce au secours de Dieu, j''''ai subsisté jusqu''''à ce jour, rendant témoignage devant les petits et les grands, sans m''''écarter en rien de ce que les prophètes et Moïse ont déclaré devoir arriver,"}, {"numero": 23, "texto": "savoir que le Christ souffrirait, et que, ressuscité le premier d''''entre les morts, il annoncerait la lumière au peuple et aux nations."}, {"numero": 24, "texto": "Comme il parlait ainsi pour sa justification, Festus dit à haute voix: Tu es fou, Paul! Ton grand savoir te fait déraisonner."}, {"numero": 25, "texto": "Je ne suis point fou, très excellent Festus, répliqua Paul; ce sont, au contraire, des paroles de vérité et de bon sens que je prononce."}, {"numero": 26, "texto": "Le roi est instruit de ces choses, et je lui en parle librement; car je suis persuadé qu''''il n''''en ignore aucune, puisque ce n''''est pas en cachette qu''''elles se sont passées."}, {"numero": 27, "texto": "Crois-tu aux prophètes, roi Agrippa?... Je sais que tu y crois."}, {"numero": 28, "texto": "Et Agrippa dit à Paul: Tu vas bientôt me persuader de devenir chrétien!"}, {"numero": 29, "texto": "Paul répondit: Que ce soit bientôt ou que ce soit tard, plaise à Dieu que non seulement toi, mais encore tous ceux qui m''''écoutent aujourd''''hui, vous deveniez tels que je suis, à l''''exception de ces liens!"}, {"numero": 30, "texto": "Le roi, le gouverneur, Bérénice, et tous ceux qui étaient assis avec eux se levèrent,"}, {"numero": 31, "texto": "et, en se retirant, ils se disaient les uns aux autres: Cet homme n''''a rien fait qui mérite la mort ou la prison."}, {"numero": 32, "texto": "Et Agrippa dit à Festus: Cet homme pouvait être relâché, s''''il n''''en eût pas appelé à César."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 26, 'es', '[{"numero": 1, "texto": "ENTONCES Agripa dijo á Pablo: Se te permite hablar por ti mismo. Pablo entonces, extendiendo la mano, comenzó á responder por sí, diciendo:"}, {"numero": 2, "texto": "Acerca de todas las cosas de que soy acusado por los Judíos, oh rey Agripa, me tengo por dichoso de que haya hoy de defenderme delante de ti;"}, {"numero": 3, "texto": "Mayormente sabiendo tú todas las costumbres y cuestiones que hay entre los Judíos: por lo cual te ruego que me oigas con paciencia."}, {"numero": 4, "texto": "Mi vida pues desde la mocedad, la cual desde el principio fué en mi nación, en Jerusalem, todos los Judíos la saben:"}, {"numero": 5, "texto": "Los cuales tienen ya conocido que yo desde el principio, si quieren testificarlo, conforme á la más rigurosa secta de nuestra religión he vivido Fariseo."}, {"numero": 6, "texto": "Y ahora, por la esperanza de la promesa que hizo Dios á nuestros padres, soy llamado en juicio;"}, {"numero": 7, "texto": "A la cual promesa nuestras doce tribus, sirviendo constantemente de día y de noche, esperan que han de llegar. Por la cual esperanza, oh rey Agripa, soy acusado de los Judíos."}, {"numero": 8, "texto": "¡Qué! ¿Júzgase cosa increíble entre vosotros que Dios resucite los muertos?"}, {"numero": 9, "texto": "Yo ciertamente había pensado deber hacer muchas cosas contra el nombre de Jesús de Nazaret:"}, {"numero": 10, "texto": "Lo cual también hice en Jerusalem, y yo encerré en cárceles á muchos de los santos, recibida potestad de los príncipes de los sacerdotes; y cuando eran matados, yo dí mi voto."}, {"numero": 11, "texto": "Y muchas veces, castigándolos por todas las sinagogas, los forcé á blasfemar; y enfurecido sobremanera contra ellos, los perseguí hasta en las ciudades extrañas."}, {"numero": 12, "texto": "En lo cual ocupado, yendo á Damasco con potestad y comisión de los príncipes de los sacerdotes,"}, {"numero": 13, "texto": "En mitad del día, oh rey, vi en el camino una luz del cielo, que sobrepujaba el resplandor del sol, la cual me rodeó y á los que iban conmigo."}, {"numero": 14, "texto": "Y habiendo caído todos nosotros en tierra, oí una voz que me hablaba, y decía en lengua hebraica: Saulo, Saulo, ¿por qué me persigues? Dura cosa te es dar coces contra los aguijones."}, {"numero": 15, "texto": "Yo entonces dije: ¿Quién eres, Señor? Y el Señor dijo: Yo soy Jesús, á quien tú persigues."}, {"numero": 16, "texto": "Mas levántate, y ponte sobre tus pies; porque para esto te he aparecido, para ponerte por ministro y testigo de las cosas que has visto, y de aquellas en que apareceré á ti:"}, {"numero": 17, "texto": "Librándote del pueblo y de los Gentiles, á los cuales ahora te envío,"}, {"numero": 18, "texto": "Para que abras sus ojos, para que se conviertan de las tinieblas á la luz, y de la potestad de Satanás á Dios; para que reciban, por la fe que es en mí, remisión de pecados y suerte entre los santificados."}, {"numero": 19, "texto": "Por lo cual, oh rey Agripa, no fuí rebelde á la visión celestial:"}, {"numero": 20, "texto": "Antes anuncié primeramente á los que están en Damasco, y Jerusalem, y por toda la tierra de Judea, y á los Gentiles, que se arrepintiesen y se convirtiesen á Dios, haciendo obras dignas de arrepentimiento."}, {"numero": 21, "texto": "Por causa de esto los Judíos, tomándome en el templo, tentaron matarme."}, {"numero": 22, "texto": "Mas ayudado del auxilio de Dios, persevero hasta el día de hoy, dando testimonio á pequeños y á grandes, no diciendo nada fuera de las cosas que los profetas y Moisés dijeron que habían de venir:"}, {"numero": 23, "texto": "Que Cristo había de padecer, y ser el primero de la resurrección de los muertos, para anunciar luz al pueblo y á los Gentiles."}, {"numero": 24, "texto": "Y diciendo él estas cosas en su defensa, Festo á gran voz dijo: Estás loco, Pablo: las muchas letras te vuelven loco."}, {"numero": 25, "texto": "Mas él dijo: No estoy loco, excelentísimo Festo, sino que hablo palabras de verdad y de templanza."}, {"numero": 26, "texto": "Pues el rey sabe estas cosas, delante del cual también hablo confiadamente. Pues no pienso que ignora nada de esto; pues no ha sido esto hecho en algún rincón."}, {"numero": 27, "texto": "¿Crees, rey Agripa, á los profetas? Yo sé que crees."}, {"numero": 28, "texto": "Entonces Agripa dijo á Pablo: Por poco me persuades á ser Cristiano."}, {"numero": 29, "texto": "Y Pablo dijo: ¡Pluguiese á Dios que por poco ó por mucho, no solamente tú, mas también todos los que hoy me oyen, fueseis hechos tales cual yo soy, excepto estas prisiones!"}, {"numero": 30, "texto": "Y como hubo dicho estas cosas, se levantó el rey, y el presidente, y Bernice, y los que se habían sentado con ellos;"}, {"numero": 31, "texto": "Y como se retiraron aparte, hablaban los unos á los otros, diciendo: Ninguna cosa digna ni de muerte, ni de prisión, hace este hombre."}, {"numero": 32, "texto": "Y Agripa dijo á Festo: Podía este hombre ser suelto, si no hubiera apelado á César."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 27, 'pt', '[{"numero": 1, "texto": "E quando foi determinado que tínhamos que navegar para a Itália, entregaram a Paulo e alguns outros prisioneiros, a um centurião, por nome Júlio, do esquadrão imperial."}, {"numero": 2, "texto": "E embarcando [-nos] em um navio adramitino, estando a navegar pelos lugares [costeiros] da Ásia, nós partimos, estando conosco Aristarco, o macedônio de Tessalônica."}, {"numero": 3, "texto": "E no [dia] seguinte, chegamos a Sidom; e Júlio, tratando bem a Paulo, permitiu [-lhe] que fosse aos amigos, para [receber] cuidado [deles] ."}, {"numero": 4, "texto": "E tendo partido dali, nós fomos navegando abaixo do Chipre, porque os ventos estavam contrários."}, {"numero": 5, "texto": "E tendo passado ao longo do mar da Cilícia e Panfília, viemos a Mira em Lícia."}, {"numero": 6, "texto": "E o centurião, tendo achado ali um navio de Alexandria, que estava navegando para a Itália, nos fez embarcar nele."}, {"numero": 7, "texto": "E indo navegando lentamente já por muitos dias, chegando com dificuldade em frente a Cnido, o vento, não nos permitindo [continuar por ali] ,navegamos abaixo de Creta, em frente a Salmone."}, {"numero": 8, "texto": "E tendo com dificuldade percorrido sua costa, chegamos a um certo lugar, chamado Bons Portos, perto do qual estava a cidade de Laseia."}, {"numero": 9, "texto": "E tendo passado muito tempo, e sendo a navegação já perigosa, porque também já tinha passado o jejum, Paulo [os] exortava,"}, {"numero": 10, "texto": "Dizendo-lhes: Homens, eu vejo que a navegação vai ser com violência e muito dano, não somente de carga e do navio, mas também de nossas vidas."}, {"numero": 11, "texto": "Porém o centurião cria mais no capitão e no dono do navio do que no que Paulo dizia."}, {"numero": 12, "texto": "E não sendo aquele porto adequado para passar o inverno, a maioria preferiu partir dali, para ver se podiam chegar a Fênix, que é um porto de Creta, voltada para o lado do vento sudoeste e noroeste, para ali passarem o inverno."}, {"numero": 13, "texto": "E ao ventar brandamente ao sul, pareceu-lhes que eles já tinham o que queriam; e levantando a vela, foram por perto da costa de Creta."}, {"numero": 14, "texto": "Mas não muito depois houve contra ela um vento violento, chamado Euroaquilão."}, {"numero": 15, "texto": "E tendo o navio sido tomado por ele, e não podendo navegar contra o vento, nós deixamos sermos levados [por ele] ."}, {"numero": 16, "texto": "E correndo abaixo de uma pequena ilha, chamada Clauda, com dificuldade conseguimos manter o barquinho de reserva;"}, {"numero": 17, "texto": "O qual, tendo sido levado para cima, usaram de suportes [para] reforçarem o navio; e temendo irem de encontro aos bancos de areia, eles baixaram as velas e [deixaram] ir à deriva."}, {"numero": 18, "texto": "E sendo muito afligidos pela tempestade, no [dia] seguinte jogaram a carga para fora [do navio] ."}, {"numero": 19, "texto": "E no terceiro [dia] , com as nossas próprias mãos jogamos fora os instrumentos do navio."}, {"numero": 20, "texto": "E não aparecendo ainda o sol, nem estrelas havia muitos dias, e sendo afligidos por não pouca tempestade, desde então tínhamos perdido toda a esperança de sermos salvos."}, {"numero": 21, "texto": "E havendo muito [tempo] que não havia o que comer, então Paulo, ficando de pé no meio deles, disse: Homens, vós devíeis ter dado atenção a mim, e não terdes partido de Creta, e [assim] evitar esta situação ruim e prejuízo."}, {"numero": 22, "texto": "Mas agora eu vos exorto a terdes bom ânimo; porque haverá nenhuma perda de vida de vós, além [somente da perda] do navio."}, {"numero": 23, "texto": "Porque esta mesma noite esteve comigo um anjo de Deus, a quem eu pertenço e a quem eu sirvo;"}, {"numero": 24, "texto": "Dizendo: Não temas, Paulo; é necessário que tu sejas apresentado a César; e eis que Deus tem te dado [a vida] a todos quantos navegam contigo."}, {"numero": 25, "texto": "Portanto, homens, tende bom ânimo; porque eu creio em Deus que assim será, conforme o que me foi dito."}, {"numero": 26, "texto": "Mas é necessário que sejamos lançados a uma ilha."}, {"numero": 27, "texto": "E quando veio a décima quarta noite, sendo lançados de um lado para o outro no [mar] Adriático, por volta da meia noite os marinheiros suspeitaram de que estavam se aproximando de alguma terra [firme] ."}, {"numero": 28, "texto": "E tendo lançado o prumo, acharam vinte braças; e passando um pouco mais adiante, voltando a lançar o prumo, acharam quinze braças."}, {"numero": 29, "texto": "E temendo de irem de encontro a lugares rochosos, lançaram da popa quatro âncoras, desejando que o dia viesse [logo] ."}, {"numero": 30, "texto": "E [quando] os marinheiros estavam procurando fugir do navio, e baixando o barquinho de reserva ao mar, como que queriam largar as âncoras da proa,"}, {"numero": 31, "texto": "Paulo disse ao centurião e aos soldados: Se estes não ficarem no navio, vós não podeis vos salvar."}, {"numero": 32, "texto": "Então os soldados cortaram os cabos do barquinho de reserva, e o deixaram cair."}, {"numero": 33, "texto": "E até enquanto o dia estava vindo, Paulo exortava a todos que comessem alguma coisa, dizendo: Hoje já é o décimo quarto dia, em que estais esperando, continuando sem comer, nada tendo experimentado."}, {"numero": 34, "texto": "Portanto eu vos exorto para que comais alguma coisa, pois é bom para vossa saúde; porque nenhum cabelo cairá de vossa cabeça."}, {"numero": 35, "texto": "E tendo dito isto, e tomando o pão, ele agradeceu a Deus na presença de todos; e partindo [-o] , começou a comer."}, {"numero": 36, "texto": "E todos, tendo ficado mais encorajados, também pegaram [algo] para comer."}, {"numero": 37, "texto": "E éramos todos no navio duzentas e setenta e seis almas."}, {"numero": 38, "texto": "E estando saciados de comer, eles tiraram peso do navio, lançando o trigo ao mar."}, {"numero": 39, "texto": "E tendo vindo o dia, não reconheciam a terra; mas enxergaram uma enseada que tinha praia, na qual planejaram, se pudessem, levar o navio."}, {"numero": 40, "texto": "E tendo levantado as âncoras, deixaram [-no] ir ao mar, soltando também as amarras dos lemes, e levantando a vela maior ao vento, foram de levando [-o] à praia."}, {"numero": 41, "texto": "Mas tendo caído em um lugar onde dois mares se encontram, encalharam ali o navio; e fixa a proa, ficou imóvel, mas a popa estava se destruindo com a força das ondas."}, {"numero": 42, "texto": "Então o conselho dos soldados foi de que matassem aos presos, para que nenhum [deles] fugisse a nado."}, {"numero": 43, "texto": "Mas o centurião, querendo salvar a Paulo, impediu a intenção deles; e mandou que aqueles que pudessem nadar fossem os primeiros a se lançassem [ao mar] e chegassem à terra [firme] ."}, {"numero": 44, "texto": "E [depois] os demais, uns em tábuas, e outros em pedaços do navio. E assim aconteceu, que todos se salvaram em terra."}]'::jsonb, 'Almeida Livre'),
  ('At', 27, 'en', '[{"numero": 1, "texto": "And when it was determined that we should sail into Italy, they delivered Paul and certain other prisoners unto one named Julius, a centurion of Augustus'' band."}, {"numero": 2, "texto": "And entering into a ship of Adramyttium, we launched, meaning to sail by the coasts of Asia; one Aristarchus, a Macedonian of Thessalonica, being with us."}, {"numero": 3, "texto": "And the next day we touched at Sidon. And Julius courteously entreated Paul, and gave him liberty to go unto his friends to refresh himself."}, {"numero": 4, "texto": "And when we had launched from thence, we sailed under Cyprus, because the winds were contrary."}, {"numero": 5, "texto": "And when we had sailed over the sea of Cilicia and Pamphylia, we came to Myra, a city of Lycia."}, {"numero": 6, "texto": "And there the centurion found a ship of Alexandria sailing into Italy; and he put us therein."}, {"numero": 7, "texto": "And when we had sailed slowly many days, and scarce were come over against Cnidus, the wind not suffering us, we sailed under Crete, over against Salmone;"}, {"numero": 8, "texto": "And, hardly passing it, came unto a place which is called The fair havens; nigh whereunto was the city of Lasea."}, {"numero": 9, "texto": "Now when much time was spent, and when sailing was now dangerous, because the fast was now already past, Paul admonished them,"}, {"numero": 10, "texto": "And said unto them, Sirs, I perceive that this voyage will be with hurt and much damage, not only of the lading and ship, but also of our lives."}, {"numero": 11, "texto": "Nevertheless the centurion believed the master and the owner of the ship, more than those things which were spoken by Paul."}, {"numero": 12, "texto": "And because the haven was not commodious to winter in, the more part advised to depart thence also, if by any means they might attain to Phenice, and there to winter; which is an haven of Crete, and lieth toward the south west and north west."}, {"numero": 13, "texto": "And when the south wind blew softly, supposing that they had obtained their purpose, loosing thence, they sailed close by Crete."}, {"numero": 14, "texto": "But not long after there arose against it a tempestuous wind, called Euroclydon."}, {"numero": 15, "texto": "And when the ship was caught, and could not bear up into the wind, we let her drive."}, {"numero": 16, "texto": "And running under a certain island which is called Clauda, we had much work to come by the boat:"}, {"numero": 17, "texto": "Which when they had taken up, they used helps, undergirding the ship; and, fearing lest they should fall into the quicksands, strake sail, and so were driven."}, {"numero": 18, "texto": "And we being exceedingly tossed with a tempest, the next day they lightened the ship;"}, {"numero": 19, "texto": "And the third day we cast out with our own hands the tackling of the ship."}, {"numero": 20, "texto": "And when neither sun nor stars in many days appeared, and no small tempest lay on us, all hope that we should be saved was then taken away."}, {"numero": 21, "texto": "But after long abstinence Paul stood forth in the midst of them, and said, Sirs, ye should have hearkened unto me, and not have loosed from Crete, and to have gained this harm and loss."}, {"numero": 22, "texto": "And now I exhort you to be of good cheer: for there shall be no loss of any man''s life among you, but of the ship."}, {"numero": 23, "texto": "For there stood by me this night the angel of God, whose I am, and whom I serve,"}, {"numero": 24, "texto": "Saying, Fear not, Paul; thou must be brought before Caesar: and, lo, God hath given thee all them that sail with thee."}, {"numero": 25, "texto": "Wherefore, sirs, be of good cheer: for I believe God, that it shall be even as it was told me."}, {"numero": 26, "texto": "Howbeit we must be cast upon a certain island."}, {"numero": 27, "texto": "But when the fourteenth night was come, as we were driven up and down in Adria, about midnight the shipmen deemed that they drew near to some country;"}, {"numero": 28, "texto": "And sounded, and found it twenty fathoms: and when they had gone a little further, they sounded again, and found it fifteen fathoms."}, {"numero": 29, "texto": "Then fearing lest we should have fallen upon rocks, they cast four anchors out of the stern, and wished for the day."}, {"numero": 30, "texto": "And as the shipmen were about to flee out of the ship, when they had let down the boat into the sea, under colour as though they would have cast anchors out of the foreship,"}, {"numero": 31, "texto": "Paul said to the centurion and to the soldiers, Except these abide in the ship, ye cannot be saved."}, {"numero": 32, "texto": "Then the soldiers cut off the ropes of the boat, and let her fall off."}, {"numero": 33, "texto": "And while the day was coming on, Paul besought them all to take meat, saying, This day is the fourteenth day that ye have tarried and continued fasting, having taken nothing."}, {"numero": 34, "texto": "Wherefore I pray you to take some meat: for this is for your health: for there shall not an hair fall from the head of any of you."}, {"numero": 35, "texto": "And when he had thus spoken, he took bread, and gave thanks to God in presence of them all: and when he had broken it, he began to eat."}, {"numero": 36, "texto": "Then were they all of good cheer, and they also took some meat."}, {"numero": 37, "texto": "And we were in all in the ship two hundred threescore and sixteen souls."}, {"numero": 38, "texto": "And when they had eaten enough, they lightened the ship, and cast out the wheat into the sea."}, {"numero": 39, "texto": "And when it was day, they knew not the land: but they discovered a certain creek with a shore, into the which they were minded, if it were possible, to thrust in the ship."}, {"numero": 40, "texto": "And when they had taken up the anchors, they committed themselves unto the sea, and loosed the rudder bands, and hoised up the mainsail to the wind, and made toward shore."}, {"numero": 41, "texto": "And falling into a place where two seas met, they ran the ship aground; and the forepart stuck fast, and remained unmoveable, but the hinder part was broken with the violence of the waves."}, {"numero": 42, "texto": "And the soldiers'' counsel was to kill the prisoners, lest any of them should swim out, and escape."}, {"numero": 43, "texto": "But the centurion, willing to save Paul, kept them from their purpose; and commanded that they which could swim should cast themselves first into the sea, and get to land:"}, {"numero": 44, "texto": "And the rest, some on boards, and some on broken pieces of the ship. And so it came to pass, that they escaped all safe to land."}]'::jsonb, 'King James Version'),
  ('At', 27, 'fr', '[{"numero": 1, "texto": "Lorsqu''''il fut décidé que nous nous embarquerions pour l''''Italie, on remit Paul et quelques autres prisonniers à un centenier de la cohorte Auguste, nommé Julius."}, {"numero": 2, "texto": "Nous montâmes sur un navire d''''Adramytte, qui devait côtoyer l''''Asie, et nous partîmes, ayant avec nous Aristarque, Macédonien de Thessalonique."}, {"numero": 3, "texto": "Le jour suivant, nous abordâmes à Sidon; et Julius, qui traitait Paul avec bienveillance, lui permit d''''aller chez ses amis et de recevoir leurs soins."}, {"numero": 4, "texto": "Partis de là, nous longeâmes l''''île de Chypre, parce que les vents étaient contraires."}, {"numero": 5, "texto": "Après avoir traversé la mer qui baigne la Cilicie et la Pamphylie, nous arrivâmes à Myra en Lycie."}, {"numero": 6, "texto": "Et là, le centenier, ayant trouvé un navire d''''Alexandrie qui allait en Italie, nous y fit monter."}, {"numero": 7, "texto": "Pendant plusieurs jours nous naviguâmes lentement, et ce ne fut pas sans difficulté que nous atteignîmes la hauteur de Cnide, où le vent ne nous permit pas d''''aborder. Nous passâmes au-dessous de l''''île de Crète, du côté de Salmone."}, {"numero": 8, "texto": "Nous la côtoyâmes avec peine, et nous arrivâmes à un lieu nommé Beaux Ports, près duquel était la ville de Lasée."}, {"numero": 9, "texto": "Un temps assez long s''''était écoulé, et la navigation devenait dangereuse, car l''''époque même du jeûne était déjà passée. C''''est pourquoi Paul avertit"}, {"numero": 10, "texto": "les autres, en disant: O hommes, je vois que la navigation ne se fera pas sans péril et sans beaucoup de dommage, non seulement pour la cargaison et pour le navire, mais encore pour nos personnes."}, {"numero": 11, "texto": "Le centenier écouta le pilote et le patron du navire plutôt que les paroles de Paul."}, {"numero": 12, "texto": "Et comme le port n''''était pas bon pour hiverner, la plupart furent d''''avis de le quitter pour tâcher d''''atteindre Phénix, port de Crète qui regarde le sud-ouest et le nord-ouest, afin d''''y passer l''''hiver."}, {"numero": 13, "texto": "Un léger vent du sud vint à souffler, et, se croyant maîtres de leur dessein, ils levèrent l''''ancre et côtoyèrent de près l''''île de Crète."}, {"numero": 14, "texto": "Mais bientôt un vent impétueux, qu''''on appelle Euraquilon, se déchaîna sur l''''île."}, {"numero": 15, "texto": "Le navire fut entraîné, sans pouvoir lutter contre le vent, et nous nous laissâmes aller à la dérive."}, {"numero": 16, "texto": "Nous passâmes au-dessous d''''une petite île nommée Clauda, et nous eûmes de la peine à nous rendre maîtres de la chaloupe;"}, {"numero": 17, "texto": "après l''''avoir hissée, on se servit des moyens de secours pour ceindre le navire, et, dans la crainte de tomber sur la Syrte, on abaissa les voiles. C''''est ainsi qu''''on se laissa emporter par le vent."}, {"numero": 18, "texto": "Comme nous étions violemment battus par la tempête, le lendemain on jeta la cargaison à la mer,"}, {"numero": 19, "texto": "et le troisième jour nous y lançâmes de nos propres mains les agrès du navire."}, {"numero": 20, "texto": "Le soleil et les étoiles ne parurent pas pendant plusieurs jours, et la tempête était si forte que nous perdîmes enfin toute espérance de nous sauver."}, {"numero": 21, "texto": "On n''''avait pas mangé depuis longtemps. Alors Paul, se tenant au milieu d''''eux, leur dit: O hommes, il fallait m''''écouter et ne pas partir de Crète, afin d''''éviter ce péril et ce dommage."}, {"numero": 22, "texto": "Maintenant je vous exhorte à prendre courage; car aucun de vous ne périra, et il n''''y aura de perte que celle du navire."}, {"numero": 23, "texto": "Un ange du Dieu à qui j''''appartiens et que je sers m''''est apparu cette nuit,"}, {"numero": 24, "texto": "et m''''a dit: Paul, ne crains point; il faut que tu comparaisses devant César, et voici, Dieu t''''a donné tous ceux qui naviguent avec toi."}, {"numero": 25, "texto": "C''''est pourquoi, ô hommes, rassurez-vous, car j''''ai cette confiance en Dieu qu''''il en sera comme il m''''a été dit."}, {"numero": 26, "texto": "Mais nous devons échouer sur une île."}, {"numero": 27, "texto": "La quatorzième nuit, tandis que nous étions ballottés sur l''''Adriatique, les matelots, vers le milieu de la nuit, soupçonnèrent qu''''on approchait de quelque terre."}, {"numero": 28, "texto": "Ayant jeté la sonde, ils trouvèrent vingt brasses; un peu plus loin, ils la jetèrent de nouveau, et trouvèrent quinze brasses."}, {"numero": 29, "texto": "Dans la crainte de heurter contre des écueils, ils jetèrent quatre ancres de la poupe, et attendirent le jour avec impatience."}, {"numero": 30, "texto": "Mais, comme les matelots cherchaient à s''''échapper du navire, et mettaient la chaloupe à la mer sous prétexte de jeter les ancres de la proue,"}, {"numero": 31, "texto": "Paul dit au centenier et aux soldats: Si ces hommes ne restent pas dans le navire, vous ne pouvez être sauvés."}, {"numero": 32, "texto": "Alors les soldats coupèrent les cordes de la chaloupe, et la laissèrent tomber."}, {"numero": 33, "texto": "Avant que le jour parût, Paul exhorta tout le monde à prendre de la nourriture, disant: C''''est aujourd''''hui le quatorzième jour que vous êtes dans l''''attente et que vous persistez à vous abstenir de manger."}, {"numero": 34, "texto": "Je vous invite donc à prendre de la nourriture, car cela est nécessaire pour votre salut, et il ne se perdra pas un cheveu de la tête d''''aucun de vous."}, {"numero": 35, "texto": "Ayant ainsi parlé, il prit du pain, et, après avoir rendu grâces à Dieu devant tous, il le rompit, et se mit à manger."}, {"numero": 36, "texto": "Et tous, reprenant courage, mangèrent aussi."}, {"numero": 37, "texto": "Nous étions, dans le navire, deux cent soixante-seize personnes en tout."}, {"numero": 38, "texto": "Quand ils eurent mangé suffisamment, ils allégèrent le navire en jetant le blé à la mer."}, {"numero": 39, "texto": "Lorsque le jour fut venu, ils ne reconnurent point la terre; mais, ayant aperçu un golfe avec une plage, ils résolurent d''''y pousser le navire, s''''ils le pouvaient."}, {"numero": 40, "texto": "Ils délièrent les ancres pour les laisser aller dans la mer, et ils relâchèrent en même temps les attaches des gouvernails; puis ils mirent au vent la voile d''''artimon, et se dirigèrent vers le rivage."}, {"numero": 41, "texto": "Mais ils rencontrèrent une langue de terre, où ils firent échouer le navire; et la proue, s''''étant engagée, resta immobile, tandis que la poupe se brisait par la violence des vagues."}, {"numero": 42, "texto": "Les soldats furent d''''avis de tuer les prisonniers, de peur que quelqu''''un d''''eux ne s''''échappât à la nage."}, {"numero": 43, "texto": "Mais le centenier, qui voulait sauver Paul, les empêcha d''''exécuter ce dessein. Il ordonna à ceux qui savaient nager de se jeter les premiers dans l''''eau pour gagner la terre,"}, {"numero": 44, "texto": "et aux autres de se mettre sur des planches ou sur des débris du navire. Et ainsi tous parvinrent à terre sains et saufs."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 27, 'es', '[{"numero": 1, "texto": "MAS como fué determinado que habíamos de navegar para Italia, entregaron á Pablo y á algunos otros presos á un centurión, llamado Julio, de la compañía Augusta."}, {"numero": 2, "texto": "Así que, embarcándonos en una nave Adrumentina, partimos, estando con nosotros Aristarco, Macedonio de Tesalónica, para navegar junto á los lugares de Asia."}, {"numero": 3, "texto": "Y otro día llegamos á Sidón; y Julio, tratando á Pablo con humanidad, permitióle que fuese á los amigos, para ser de ellos asistido."}, {"numero": 4, "texto": "Y haciéndonos á la vela desde allí, navegamos bajo de Cipro, porque los vientos eran contrarios."}, {"numero": 5, "texto": "Y habiendo pasado la mar de Cilicia y Pamphylia, arribamos á Mira, ciudad de Licia."}, {"numero": 6, "texto": "Y hallando allí el centurión una nave Alejandrina que navegaba á Italia, nos puso en ella."}, {"numero": 7, "texto": "Y navegando muchos días despacio, y habiendo apenas llegado delante de Gnido, no dejándonos el viento, navegamos bajo de Creta, junto á Salmón."}, {"numero": 8, "texto": "Y costeándola difícilmente, llegamos á un lugar que llaman Buenos Puertos, cerca del cual estaba la ciudad de Lasea."}, {"numero": 9, "texto": "Y pasado mucho tiempo, y siendo ya peligrosa la navegación, porque ya era pasado el ayuno, Pablo amonestaba,"}, {"numero": 10, "texto": "Diciéndoles: Varones, veo que con trabajo y mucho daño, no sólo de la cargazón y de la nave, mas aun de nuestras personas, habrá de ser la navegación."}, {"numero": 11, "texto": "Mas el centurión creía más al piloto y al patrón de la nave, que á lo que Pablo decía."}, {"numero": 12, "texto": "Y no habiendo puerto cómodo para invernar, muchos acordaron pasar aún de allí, por si pudiesen arribar á Fenice é invernar allí, que es un puerto de Creta que mira al Nordeste y Sudeste."}, {"numero": 13, "texto": "Y soplando el austro, pareciéndoles que ya tenían lo que deseaban, alzando velas, iban cerca de la costa de Creta."}, {"numero": 14, "texto": "Mas no mucho después dió en ella un viento repentino, que se llama Euroclidón."}, {"numero": 15, "texto": "Y siendo arrebatada la nave, y no pudiendo resistir contra el viento, la dejamos, y éramos llevados."}, {"numero": 16, "texto": "Y habiendo corrido á sotavento de una pequeña isla que se llama Clauda, apenas pudimos ganar el esquife:"}, {"numero": 17, "texto": "El cual tomado, usaban de remedios, ciñendo la nave; y teniendo temor de que diesen en la Sirte, abajadas las velas, eran así llevados."}, {"numero": 18, "texto": "Mas siendo atormentados de una vehemente tempestad, al siguiente día alijaron;"}, {"numero": 19, "texto": "Y al tercer día nosotros con nuestras manos arrojamos los aparejos de la nave."}, {"numero": 20, "texto": "Y no pareciendo sol ni estrellas por muchos días, y viniendo una tempestad no pequeña, ya era perdida toda la esperanza de nuestra salud."}, {"numero": 21, "texto": "Entonces Pablo, habiendo ya mucho que no comíamos, puesto en pie en medio de ellos, dijo: Fuera de cierto conveniente, oh varones, haberme oído, y no partir de Creta, y evitar este inconveniente y daño."}, {"numero": 22, "texto": "Mas ahora os amonesto que tengáis buen ánimo; porque ninguna pérdida habrá de persona de vosotros, sino solamente de la nave."}, {"numero": 23, "texto": "Porque esta noche ha estado conmigo el ángel del Dios del cual yo soy, y al cual sirvo,"}, {"numero": 24, "texto": "Diciendo: Pablo, no temas; es menester que seas presentado delante de César; y he aquí, Dios te ha dado todos los que navegan contigo."}, {"numero": 25, "texto": "Por tanto, oh varones, tened buen ánimo; porque yo confío en Dios que será así como me ha dicho;"}, {"numero": 26, "texto": "Si bien es menester que demos en una isla."}, {"numero": 27, "texto": "Y venida la décimacuarta noche, y siendo llevados por el mar Adriático, los marineros á la media noche sospecharon que estaban cerca de alguna tierra;"}, {"numero": 28, "texto": "Y echando la sonda, hallaron veinte brazas; y pasando un poco más adelante, volviendo á echar la sonda, hallaron quince brazas."}, {"numero": 29, "texto": "Y habiendo temor de dar en lugares escabrosos, echando cuatro anclas de la popa, deseaban que se hiciese de día."}, {"numero": 30, "texto": "Entonces procurando los marineros huir de la nave, echado que hubieron el esquife á la mar, aparentando como que querían largar las anclas de proa,"}, {"numero": 31, "texto": "Pablo dijo al centurión y á los soldados: Si éstos no quedan en la nave, vosotros no podéis salvaros."}, {"numero": 32, "texto": "Entonces los soldados cortaron los cabos del esquife, y dejáronlo perder."}, {"numero": 33, "texto": "Y como comenzó á ser de día, Pablo exhortaba á todos que comiesen, diciendo: Este es el décimocuarto día que esperáis y permanecéis ayunos, no comiendo nada."}, {"numero": 34, "texto": "Por tanto, os ruego que comáis por vuestra salud: que ni aun un cabello de la cabeza de ninguno de vosotros perecerá."}, {"numero": 35, "texto": "Y habiendo dicho esto, tomando el pan, hizo gracias á Dios en presencia de todos, y partiendo, comenzó á comer."}, {"numero": 36, "texto": "Entonces todos teniendo ya mejor ánimo, comieron ellos también."}, {"numero": 37, "texto": "Y éramos todas las personas en la nave doscientas setenta y seis."}, {"numero": 38, "texto": "Y satisfechos de comida, aliviaban la nave, echando el grano á la mar."}, {"numero": 39, "texto": "Y como se hizo de día, no conocían la tierra: mas veían un golfo que tenía orilla, al cual acordaron echar, si pudiesen, la nave."}, {"numero": 40, "texto": "Cortando pues las anclas, las dejaron en la mar, largando también las ataduras de los gobernalles; y alzada la vela mayor al viento, íbanse á la orilla."}, {"numero": 41, "texto": "Mas dando en un lugar de dos aguas, hicieron encallar la nave; y la proa, hincada, estaba sin moverse, y la popa se abría con la fuerza de la mar."}, {"numero": 42, "texto": "Entonces el acuerdo de los soldados era que matasen los presos, porque ninguno se fugase nadando."}, {"numero": 43, "texto": "Mas el centurión, queriendo salvar á Pablo, estorbó este acuerdo, y mandó que los que pudiesen nadar, se echasen los primeros, y saliesen á tierra;"}, {"numero": 44, "texto": "Y los demás, parte en tablas, parte en cosas de la nave. Y así aconteció que todos se salvaron saliendo á tierra."}]'::jsonb, 'Reina-Valera 1909'),
  ('At', 28, 'pt', '[{"numero": 1, "texto": "E tendo sobrevivido, então souberam que a ilha se chamava Malta."}, {"numero": 2, "texto": "E os nativos demonstraram para conosco uma benevolência incomum; porque, tendo acendido uma fogueira, recolheram a nós todos, por causa da chuva que estava caindo, e por causa do frio."}, {"numero": 3, "texto": "E tendo Paulo recolhido uma quantidade de gravetos, e pondo-os no fogo, saiu uma víbora do calor, e fixou [os dentes] na mão dele."}, {"numero": 4, "texto": "E quando os nativos vieram o animal pendurado na mão dele, disseram uns aos outros: Certamente este homem é assassino, ao qual, tendo sobrevivido do mar, a justiça não o deixa viver."}, {"numero": 5, "texto": "Porém, ele, tendo sacudido o animal ao fogo, sofreu nenhum mal."}, {"numero": 6, "texto": "E eles esperavam que ele fosse inchar, ou cair morto de repente. Mas tendo esperado muito, e vendo que nenhum incômodo tinha lhe sobrevindo, mudaram [de opinião] , e diziam que ele era um deus."}, {"numero": 7, "texto": "E perto daquele mesmo lugar o homem mais importante da ilha, por nome Públio, tinha algumas propriedades; o qual nos recebeu e nos hospedou por três dias gentilmente."}, {"numero": 8, "texto": "E aconteceu que o pai de Públio estava de cama, doente de febres e disenteria; ao qual Paulo entrou, e tendo orado, pôs as mãos sobre ele, e o curou."}, {"numero": 9, "texto": "Tendo então isto acontecido, também vieram a ele outros que tinham enfermidades, e foram curados;"}, {"numero": 10, "texto": "Os quais nos honraram com muitas honras; e estando [nós] para navegar, [nos] entregaram as coisas necessárias."}, {"numero": 11, "texto": "E três meses depois, nós partimos em um navio de Alexandria, que tinha passado o inverno na ilha; o qual tinha como símbolo os gêmeos Castor e Pólux."}, {"numero": 12, "texto": "E chegando a Siracusa, ficamos [ali] três dias."}, {"numero": 13, "texto": "De onde, tendo indo ao redor da costa, chegamos a Régio; e um dia depois, ventando ao sul, viemos o segundo dia a Putéoli."}, {"numero": 14, "texto": "Onde, tendo achado [alguns] irmãos, eles nos rogaram que ficássemos com eles por sete dias; e assim viemos a Roma."}, {"numero": 15, "texto": "E os irmãos, ao ouvirem [notícias] sobre nós, desde lá nos saíram ao encontro até a praça de Ápio, e as três tavernas; e Paulo, tendo os visto, agradeceu a Deus, e tomou coragem."}, {"numero": 16, "texto": "E quando chegamos a Roma, o centurião entregou os prisioneiros ao chefe da guarda, mas a Paulo foi permitido morar por si mesmo à parte, junto com o soldado que o guardava."}, {"numero": 17, "texto": "E aconteceu que, três dias depois, Paulo chamou juntos os chefes dos judeus; e ao se reunirem, disse-lhes: Homens irmãos, tendo eu nada feito contra o povo, ou contra os costumes dos pais, [mesmo assim] eu vim preso desde Jerusalém, entregue em mãos dos romanos."}, {"numero": 18, "texto": "Os quais, tendo me investigado, queriam [me] soltar, por não haver em mim nenhum crime de morte."}, {"numero": 19, "texto": "Mas os judeus, dizendo em contrário, eu fui forçado a apelar a César; [mas] não como que eu tenha que acusar a minha nação."}, {"numero": 20, "texto": "Então por esta causa eu vos chamei até mim, para [vos] ver e falar; porque pela esperança de Israel eu estou agora preso nesta corrente."}, {"numero": 21, "texto": "Mas eles lhe disseram: Nós nem recebemos cartas da Judeia relacionadas a ti, nem algum dos irmãos, tendo vindo aqui, tem nos informado ou falado de ti algum mal."}, {"numero": 22, "texto": "Mas nós queríamos ouvir de ti o que tu pensas; porque, quanto a esta seita, conhecemos que em todo lugar [há quem] fale contra ela."}, {"numero": 23, "texto": "E tendo eles lhe determinado um dia, muitos vieram até onde ele estava morando; aos quais ele declarava e dava testemunho do Reino de Deus; e procurava persuadi-los quanto a Jesus, tanto pela Lei de Moisés, como [pelos] profetas, desde a manhã até a tarde."}, {"numero": 24, "texto": "E alguns criam nas coisas que ele dizia; mas outros não criam."}, {"numero": 25, "texto": "E estando discordantes entre si, despediram-se, tendo Paulo disto [esta] palavra: O Espírito Santo corretamente falou a nossos pais por meio de Isaías o profeta,"}, {"numero": 26, "texto": "Dizendo: Vai a este povo, e dize: De fato ouvireis, mas de maneira nenhuma entendereis; e de fato vereis, mas de maneira nenhuma enxergareis."}, {"numero": 27, "texto": "Porque o coração deste povo está insensível, seus ouvidos ouvem com dificuldade, e seus olhos estão fechados; para que em maneira nenhuma vejam com os olhos, nem ouçam com os ouvidos, nem entendam com o coração, e se convertam, e eu os cure."}, {"numero": 28, "texto": "Portanto seja conhecido por vós que a salvação de Deus foi enviada aos gentios; e eles [a] ouvirão."}, {"numero": 29, "texto": "E havendo ele dito isto, os judeus foram embora, havendo entre eles grande discussão."}, {"numero": 30, "texto": "E Paulo ficou dois anos inteiros em sua própria casa alugada; e recebia a todos quantos vinham a ele;"}, {"numero": 31, "texto": "Pregando o Reino de Deus, e ensinando com ousadia a doutrina do Senhor Jesus Cristo, sem impedimento algum."}]'::jsonb, 'Almeida Livre'),
  ('At', 28, 'en', '[{"numero": 1, "texto": "And when they were escaped, then they knew that the island was called Melita."}, {"numero": 2, "texto": "And the barbarous people shewed us no little kindness: for they kindled a fire, and received us every one, because of the present rain, and because of the cold."}, {"numero": 3, "texto": "And when Paul had gathered a bundle of sticks, and laid them on the fire, there came a viper out of the heat, and fastened on his hand."}, {"numero": 4, "texto": "And when the barbarians saw the venomous beast hang on his hand, they said among themselves, No doubt this man is a murderer, whom, though he hath escaped the sea, yet vengeance suffereth not to live."}, {"numero": 5, "texto": "And he shook off the beast into the fire, and felt no harm."}, {"numero": 6, "texto": "Howbeit they looked when he should have swollen, or fallen down dead suddenly: but after they had looked a great while, and saw no harm come to him, they changed their minds, and said that he was a god."}, {"numero": 7, "texto": "In the same quarters were possessions of the chief man of the island, whose name was Publius; who received us, and lodged us three days courteously."}, {"numero": 8, "texto": "And it came to pass, that the father of Publius lay sick of a fever and of a bloody flux: to whom Paul entered in, and prayed, and laid his hands on him, and healed him."}, {"numero": 9, "texto": "So when this was done, others also, which had diseases in the island, came, and were healed:"}, {"numero": 10, "texto": "Who also honoured us with many honours; and when we departed, they laded us with such things as were necessary."}, {"numero": 11, "texto": "And after three months we departed in a ship of Alexandria, which had wintered in the isle, whose sign was Castor and Pollux."}, {"numero": 12, "texto": "And landing at Syracuse, we tarried there three days."}, {"numero": 13, "texto": "And from thence we fetched a compass, and came to Rhegium: and after one day the south wind blew, and we came the next day to Puteoli:"}, {"numero": 14, "texto": "Where we found brethren, and were desired to tarry with them seven days: and so we went toward Rome."}, {"numero": 15, "texto": "And from thence, when the brethren heard of us, they came to meet us as far as Appii forum, and The three taverns: whom when Paul saw, he thanked God, and took courage."}, {"numero": 16, "texto": "And when we came to Rome, the centurion delivered the prisoners to the captain of the guard: but Paul was suffered to dwell by himself with a soldier that kept him."}, {"numero": 17, "texto": "And it came to pass, that after three days Paul called the chief of the Jews together: and when they were come together, he said unto them, Men and brethren, though I have committed nothing against the people, or customs of our fathers, yet was I delivered prisoner from Jerusalem into the hands of the Romans."}, {"numero": 18, "texto": "Who, when they had examined me, would have let me go, because there was no cause of death in me."}, {"numero": 19, "texto": "But when the Jews spake against it, I was constrained to appeal unto Caesar; not that I had ought to accuse my nation of."}, {"numero": 20, "texto": "For this cause therefore have I called for you, to see you, and to speak with you: because that for the hope of Israel I am bound with this chain."}, {"numero": 21, "texto": "And they said unto him, We neither received letters out of Judaea concerning thee, neither any of the brethren that came shewed or spake any harm of thee."}, {"numero": 22, "texto": "But we desire to hear of thee what thou thinkest: for as concerning this sect, we know that every where it is spoken against."}, {"numero": 23, "texto": "And when they had appointed him a day, there came many to him into his lodging; to whom he expounded and testified the kingdom of God, persuading them concerning Jesus, both out of the law of Moses, and out of the prophets, from morning till evening."}, {"numero": 24, "texto": "And some believed the things which were spoken, and some believed not."}, {"numero": 25, "texto": "And when they agreed not among themselves, they departed, after that Paul had spoken one word, Well spake the Holy Ghost by Esaias the prophet unto our fathers,"}, {"numero": 26, "texto": "Saying, Go unto this people, and say, Hearing ye shall hear, and shall not understand; and seeing ye shall see, and not perceive:"}, {"numero": 27, "texto": "For the heart of this people is waxed gross, and their ears are dull of hearing, and their eyes have they closed; lest they should see with their eyes, and hear with their ears, and understand with their heart, and should be converted, and I should heal them."}, {"numero": 28, "texto": "Be it known therefore unto you, that the salvation of God is sent unto the Gentiles, and that they will hear it."}, {"numero": 29, "texto": "And when he had said these words, the Jews departed, and had great reasoning among themselves."}, {"numero": 30, "texto": "And Paul dwelt two whole years in his own hired house, and received all that came in unto him,"}, {"numero": 31, "texto": "Preaching the kingdom of God, and teaching those things which concern the Lord Jesus Christ, with all confidence, no man forbidding him."}]'::jsonb, 'King James Version'),
  ('At', 28, 'fr', '[{"numero": 1, "texto": "Après nous être sauvés, nous reconnûmes que l''''île s''''appelait Malte."}, {"numero": 2, "texto": "Les barbares nous témoignèrent une bienveillance peu commune; ils nous recueillirent tous auprès d''''un grand feu, qu''''ils avaient allumé parce que la pluie tombait et qu''''il faisait grand froid."}, {"numero": 3, "texto": "Paul ayant ramassé un tas de broussailles et l''''ayant mis au feu, une vipère en sortit par l''''effet de la chaleur et s''''attacha à sa main."}, {"numero": 4, "texto": "Quand les barbares virent l''''animal suspendu à sa main, ils se dirent les uns aux autres: Assurément cet homme est un meurtrier, puisque la Justice n''''a pas voulu le laisser vivre, après qu''''il a été sauvé de la mer."}, {"numero": 5, "texto": "Paul secoua l''''animal dans le feu, et ne ressentit aucun mal."}, {"numero": 6, "texto": "Ces gens s''''attendaient à le voir enfler ou tomber mort subitement; mais, après avoir longtemps attendu, voyant qu''''il ne lui arrivait aucun mal, ils changèrent d''''avis et dirent que c''''était un dieu."}, {"numero": 7, "texto": "Il y avait, dans les environs, des terres appartenant au principal personnage de l''''île, nommé Publius, qui nous reçut et nous logea pendant trois jours de la manière la plus amicale."}, {"numero": 8, "texto": "Le père de Publius était alors au lit, malade de la fièvre et de la dysenterie; Paul, s''''étant rendu vers lui, pria, lui imposa les mains, et le guérit."}, {"numero": 9, "texto": "Là-dessus, vinrent les autres malades de l''''île, et ils furent guéris."}, {"numero": 10, "texto": "On nous rendit de grands honneurs, et, à notre départ, on nous fournit les choses dont nous avions besoin."}, {"numero": 11, "texto": "Après un séjour de trois mois, nous nous embarquâmes sur un navire d''''Alexandrie, qui avait passé l''''hiver dans l''''île, et qui portait pour enseigne les Dioscures."}, {"numero": 12, "texto": "Ayant abordé à Syracuse, nous y restâmes trois jours."}, {"numero": 13, "texto": "De là, en suivant la côte, nous atteignîmes Reggio; et, le vent du midi s''''étant levé le lendemain, nous fîmes en deux jours le trajet jusqu''''à Pouzzoles,"}, {"numero": 14, "texto": "où nous trouvâmes des frères qui nous prièrent de passer sept jours avec eux. Et c''''est ainsi que nous allâmes à Rome."}, {"numero": 15, "texto": "De Rome vinrent à notre rencontre, jusqu''''au Forum d''''Appius et aux Trois Tavernes, les frères qui avaient entendu parler de nous. Paul, en les voyant, rendit grâces à Dieu, et prit courage."}, {"numero": 16, "texto": "Lorsque nous fûmes arrivés à Rome, on permit à Paul de demeurer en son particulier, avec un soldat qui le gardait."}, {"numero": 17, "texto": "Au bout de trois jours, Paul convoqua les principaux des Juifs; et, quand ils furent réunis, il leur adressa ces paroles: Hommes frères, sans avoir rien fait contre le peuple ni contre les coutumes de nos pères, j''''ai été mis en prison à Jérusalem et livré de là entre les mains des Romains."}, {"numero": 18, "texto": "Après m''''avoir interrogé, ils voulaient me relâcher, parce qu''''il n''''y avait en moi rien qui méritât la mort."}, {"numero": 19, "texto": "Mais les Juifs s''''y opposèrent, et j''''ai été forcé d''''en appeler à César, n''''ayant du reste aucun dessein d''''accuser ma nation."}, {"numero": 20, "texto": "Voilà pourquoi j''''ai demandé à vous voir et à vous parler; car c''''est à cause de l''''espérance d''''Israël que je porte cette chaîne."}, {"numero": 21, "texto": "Ils lui répondirent: Nous n''''avons reçu de Judée aucune lettre à ton sujet, et il n''''est venu aucun frère qui ait rapporté ou dit du mal de toi."}, {"numero": 22, "texto": "Mais nous voudrions apprendre de toi ce que tu penses, car nous savons que cette secte rencontre partout de l''''opposition."}, {"numero": 23, "texto": "Ils lui fixèrent un jour, et plusieurs vinrent le trouver dans son logis. Paul leur annonça le royaume de Dieu, en rendant témoignage, et en cherchant, par la loi de Moïse et par les prophètes, à les persuader de ce qui concerne Jésus. L''''entretien dura depuis le matin jusqu''''au soir."}, {"numero": 24, "texto": "Les uns furent persuadés par ce qu''''il disait, et les autres ne crurent point."}, {"numero": 25, "texto": "Comme ils se retiraient en désaccord, Paul n''''ajouta que ces mots: C''''est avec raison que le Saint-Esprit, parlant à vos pères par le prophète Esaïe,"}, {"numero": 26, "texto": "a dit: Va vers ce peuple, et dis: Vous entendrez de vos oreilles, et vous ne comprendrez point; Vous regarderez de vos yeux, et vous ne verrez point."}, {"numero": 27, "texto": "Car le coeur de ce peuple est devenu insensible; Ils ont endurci leurs oreilles, et ils ont fermé leurs yeux, De peur qu''''ils ne voient de leurs yeux, qu''''ils n''''entendent de leurs oreilles, Qu''''ils ne comprennent de leur coeur, Qu''''ils ne se convertissent, et que je ne les guérisse."}, {"numero": 28, "texto": "Sachez donc que ce salut de Dieu a été envoyé aux païens, et qu''''ils l''''écouteront."}, {"numero": 29, "texto": "Lorsqu''''il eut dit cela, les Juifs s''''en allèrent, discutant vivement entre eux."}, {"numero": 30, "texto": "Paul demeura deux ans entiers dans une maison qu''''il avait louée. Il recevait tous ceux qui venaient le voir,"}, {"numero": 31, "texto": "prêchant le royaume de Dieu et enseignant ce qui concerne le Seigneur Jésus-Christ, en toute liberté et sans obstacle."}]'::jsonb, 'Louis Segond 1910'),
  ('At', 28, 'es', '[{"numero": 1, "texto": "Y CUANDO escapamos, entonces supimos que la isla se llamaba Melita."}, {"numero": 2, "texto": "Y los bárbaros nos mostraron no poca humanidad; porque, encendido un fuego, nos recibieron á todos, á causa de la lluvia que venía, y del frío."}, {"numero": 3, "texto": "Entonces habiendo Pablo recogido algunos sarmientos, y puéstolos en el fuego, una víbora, huyendo del calor, le acometió á la mano."}, {"numero": 4, "texto": "Y como los bárbaros vieron la víbora colgando de su mano, decían los unos á los otros: Ciertamente este hombre es homicida, á quien, escapado de la mar, la justicia no deja vivir."}, {"numero": 5, "texto": "Mas él, sacudiendo la víbora en el fuego, ningún mal padeció."}, {"numero": 6, "texto": "Empero ellos estaban esperando cuándo se había de hinchar, ó caer muerto de repente; mas habiendo esperado mucho, y viendo que ningún mal le venía, mudados, decían que era un dios."}, {"numero": 7, "texto": "En aquellos lugares había heredades del principal de la isla, llamado Publio, el cual nos recibió y hospedó tres días humanamente."}, {"numero": 8, "texto": "Y aconteció que el padre de Publio estaba en cama, enfermo de fiebres y de disentería: al cual Pablo entró, y después de haber orado, le puso las manos encima, y le sanó:"}, {"numero": 9, "texto": "Y esto hecho, también los otros que en la isla tenían enfermedades, llegaban, y eran sanados:"}, {"numero": 10, "texto": "Los cuales también nos honraron con muchos obsequios; y cuando partimos, nos cargaron de las cosas necesarias."}, {"numero": 11, "texto": "Así que, pasados tres meses, navegamos en una nave Alejandrina que había invernado en la isla, la cual tenía por enseña á Cástor y Pólux."}, {"numero": 12, "texto": "Y llegados á Siracusa, estuvimos allí tres días."}, {"numero": 13, "texto": "De allí, costeando alrededor, vinimos á Regio; y otro día después, soplando el austro, vinimos al segundo día á Puteolos:"}, {"numero": 14, "texto": "Donde habiendo hallado hermanos, nos rogaron que quedásemos con ellos siete días; y luego vinimos á Roma;"}, {"numero": 15, "texto": "De donde, oyendo de nosotros los hermanos, nos salieron á recibir hasta la plaza de Appio, y Las Tres Tabernas: á los cuales como Pablo vió, dió gracias á Dios, y tomó aliento."}, {"numero": 16, "texto": "Y como llegamos á Roma, el centurión entregó los presos al prefecto de los ejércitos, mas á Pablo fué permitido estar por sí, con un soldado que le guardase."}, {"numero": 17, "texto": "Y aconteció que tres días después, Pablo convocó á los principales de los Judíos; á los cuales, luego que estuvieron juntos, les dijo: Yo, varones hermanos, no habiendo hecho nada contra el pueblo, ni contra los ritos de la patria, he sido entregado preso desde Jerusalem en manos de los Romanos;"}, {"numero": 18, "texto": "Los cuales, habiéndome examinado, me querían soltar, por no haber en mí ninguna causa de muerte."}, {"numero": 19, "texto": "Mas contradiciendo los Judíos, fuí forzado á apelar á César; no que tenga de qué acusar á mi nación."}, {"numero": 20, "texto": "Así que, por esta causa, os he llamado para veros y hablaros; porque por la esperanza de Israel estoy rodeado de esta cadena."}, {"numero": 21, "texto": "Entonces ellos le dijeron: Nosotros ni hemos recibido cartas tocante á ti de Judea, ni ha venido alguno de los hermanos que haya denunciado ó hablado algún mal de ti."}, {"numero": 22, "texto": "Mas querríamos oir de ti lo que sientes; porque de esta secta notorio nos es que en todos lugares es contradicha."}, {"numero": 23, "texto": "Y habiéndole señalado un día, vinieron á él muchos á la posada, á los cuales declaraba y testificaba el reino de Dios, persuadiéndoles lo concerniente á Jesús, por la ley de Moisés y por los profetas, desde la mañana hasta la tarde."}, {"numero": 24, "texto": "Y algunos asentían á lo que se decía, mas algunos no creían."}, {"numero": 25, "texto": "Y como fueron entre sí discordes, se fueron, diciendo Pablo esta palabra: Bien ha hablado el Espíritu Santo por el profeta Isaías á nuestros padres,"}, {"numero": 26, "texto": "Diciendo: Ve á este pueblo, y diles: De oído oiréis, y no entenderéis; y viendo veréis, y no percibiréis:"}, {"numero": 27, "texto": "Porque el corazón de este pueblo se ha engrosado, y de los oídos oyeron pesadamente, y sus ojos taparon; porque no vean con los ojos, y oigan con los oídos, y entiendan de corazón, y se conviertan, y yo los sane."}, {"numero": 28, "texto": "Séaos pues notorio que á los Gentiles es enviada esta salud de Dios: y ellos oirán."}, {"numero": 29, "texto": "Y habiendo dicho esto, los Judíos salieron, teniendo entre sí gran contienda."}, {"numero": 30, "texto": "Pablo empero, quedó dos años enteros en su casa de alquiler, y recibía á todos los que á él venían,"}, {"numero": 31, "texto": "Predicando el reino de Dios y enseñando lo que es del Señor Jesucristo con toda libertad, sin impedimento."}]'::jsonb, 'Reina-Valera 1909'),
  ('Cl', 1, 'pt', '[{"numero": 1, "texto": "Paulo, apóstolo de Jesus Cristo pela vontade de Deus, e o irmão Timóteo,"}, {"numero": 2, "texto": "aos santos e fiéis irmãos em Cristo, que estão em Colossos. [Haja] em vós a graça e paz da parte de Deus nosso Pai, e do Senhor Jesus Cristo."}, {"numero": 3, "texto": "Agradecemos ao Deus e Pai do nosso Senhor Jesus Cristo, sempre orando por vós;"}, {"numero": 4, "texto": "pois ouvimos falar da vossa fé em Cristo Jesus, e do amor [que tendes] para com todos os santos;"}, {"numero": 5, "texto": "por causa da esperança que está reservada para vós nos céus. Anteriormente ouvistes dessa esperança pala palavra da verdade do evangelho,"}, {"numero": 6, "texto": "que já chegou a vós, como também em todo o mundo; e vai frutificando assim como entre vós, desde o dia em que ouvistes e conhecestes a graça de Deus em verdade."}, {"numero": 7, "texto": "Aprendestes o evangelho por Epafras, nosso amado cooperador, que é um fiel servidor de Cristo em vosso favor."}, {"numero": 8, "texto": "Ele também nos declarou o vosso amor no Espírito."}, {"numero": 9, "texto": "Por isso também, desde o dia que [o] ouvimos, não paramos de orar por vós, e de pedir que sejais cheios do conhecimento da sua vontade, em toda sabedoria e entendimento espiritual;"}, {"numero": 10, "texto": "para que possais andar dignamente [diante] do Senhor, agradando-lhe em tudo, frutificando em toda boa obra, e crescendo no conhecimento de Deus;"}, {"numero": 11, "texto": "capacitados em todo fortalecimento, segundo o poder da sua glória, em toda perseverança e paciência com alegria,"}, {"numero": 12, "texto": "agradecendo ao Pai, que nos capacitou a participar da herança dos santos na luz."}, {"numero": 13, "texto": "Ele nos tirou do domínio das trevas, e nos transportou para o reino do seu amado Filho,"}, {"numero": 14, "texto": "em quem temos a libertação pelo seu sangue: o perdão dos pecados."}, {"numero": 15, "texto": "Ele é a imagem do Deus invisível, o primogênito de toda a criação;"}, {"numero": 16, "texto": "porque nele foram criadas todas as coisas que há nos céus e na terra, visíveis e invisíveis, sejam tronos, sejam domínios, sejam governos, sejam autoridades; todas as coisas foram criadas por ele e para ele."}, {"numero": 17, "texto": "Ele existe antes de todas as coisas, e nele todas as coisas se mantêm."}, {"numero": 18, "texto": "E ele é a cabeça do corpo, da Igreja; ele é o princípio [e] o primogênito dentre os mortos, para que tenha a primazia entre todos."}, {"numero": 19, "texto": "Pois foi do agrado [do Pai] que toda a plenitude habitasse nele;"}, {"numero": 20, "texto": "e, havendo por ele feito a paz pelo sangue da sua cruz, por meio dele reconciliasse consigo mesmo todas as coisas, tanto as que estão na terra, como as que estão nos céus."}, {"numero": 21, "texto": "Vós éreis separados [dele] , e inimigos no entendimento, em más obras. Porém agora ele vos reconciliou,"}, {"numero": 22, "texto": "no seu corpo de carne, pela morte, para vos apresentar diante dele santos, irrepreensíveis e inculpáveis;"}, {"numero": 23, "texto": "se, de fato, permaneceis fundados e firmes na fé, e não vos afastais da esperança do evangelho que ouvistes, que é pregado a toda criatura que há abaixo do céu, e do qual eu, Paulo, fui feito servidor."}, {"numero": 24, "texto": "Agora me alegro nos meus sofrimentos por vós, e cumpro na minha carne o restante das aflições de Cristo, em benefício do seu corpo, que é a Igreja."}, {"numero": 25, "texto": "Dela eu fui feito servidor segundo a responsabilidade da parte de Deus que me foi dada para o vosso benefício, a fim de cumprir a palavra de Deus,"}, {"numero": 26, "texto": "o mistério que estava oculto desde os princípios dos tempos e das gerações; mas agora foi manifesto aos seus santos."}, {"numero": 27, "texto": "A eles Deus quis fazer que conhecessem as riquezas da glória deste mistério entre os gentios, que é Cristo em vós, a esperança da glória."}, {"numero": 28, "texto": "Ele é quem anunciamos, advertindo a toda pessoa, e ensinando a toda pessoa, com toda sabedoria; a fim de que apresentemos toda pessoa [como] completa em Cristo Jesus."}, {"numero": 29, "texto": "Para isso eu também trabalho, lutando conforme a eficácia dele, que age em mim com poder."}]'::jsonb, 'Almeida Livre'),
  ('Cl', 1, 'en', '[{"numero": 1, "texto": "Paul, an apostle of Jesus Christ by the will of God, and Timotheus our brother,"}, {"numero": 2, "texto": "To the saints and faithful brethren in Christ which are at Colosse: Grace be unto you, and peace, from God our Father and the Lord Jesus Christ."}, {"numero": 3, "texto": "We give thanks to God and the Father of our Lord Jesus Christ, praying always for you,"}, {"numero": 4, "texto": "Since we heard of your faith in Christ Jesus, and of the love which ye have to all the saints,"}, {"numero": 5, "texto": "For the hope which is laid up for you in heaven, whereof ye heard before in the word of the truth of the gospel;"}, {"numero": 6, "texto": "Which is come unto you, as it is in all the world; and bringeth forth fruit, as it doth also in you, since the day ye heard of it, and knew the grace of God in truth:"}, {"numero": 7, "texto": "As ye also learned of Epaphras our dear fellowservant, who is for you a faithful minister of Christ;"}, {"numero": 8, "texto": "Who also declared unto us your love in the Spirit."}, {"numero": 9, "texto": "For this cause we also, since the day we heard it, do not cease to pray for you, and to desire that ye might be filled with the knowledge of his will in all wisdom and spiritual understanding;"}, {"numero": 10, "texto": "That ye might walk worthy of the Lord unto all pleasing, being fruitful in every good work, and increasing in the knowledge of God;"}, {"numero": 11, "texto": "Strengthened with all might, according to his glorious power, unto all patience and longsuffering with joyfulness;"}, {"numero": 12, "texto": "Giving thanks unto the Father, which hath made us meet to be partakers of the inheritance of the saints in light:"}, {"numero": 13, "texto": "Who hath delivered us from the power of darkness, and hath translated us into the kingdom of his dear Son:"}, {"numero": 14, "texto": "In whom we have redemption through his blood, even the forgiveness of sins:"}, {"numero": 15, "texto": "Who is the image of the invisible God, the firstborn of every creature:"}, {"numero": 16, "texto": "For by him were all things created, that are in heaven, and that are in earth, visible and invisible, whether they be thrones, or dominions, or principalities, or powers: all things were created by him, and for him:"}, {"numero": 17, "texto": "And he is before all things, and by him all things consist."}, {"numero": 18, "texto": "And he is the head of the body, the church: who is the beginning, the firstborn from the dead; that in all things he might have the preeminence."}, {"numero": 19, "texto": "For it pleased the Father that in him should all fulness dwell;"}, {"numero": 20, "texto": "And, having made peace through the blood of his cross, by him to reconcile all things unto himself; by him, I say, whether they be things in earth, or things in heaven."}, {"numero": 21, "texto": "And you, that were sometime alienated and enemies in your mind by wicked works, yet now hath he reconciled"}, {"numero": 22, "texto": "In the body of his flesh through death, to present you holy and unblameable and unreproveable in his sight:"}, {"numero": 23, "texto": "If ye continue in the faith grounded and settled, and be not moved away from the hope of the gospel, which ye have heard, and which was preached to every creature which is under heaven; whereof I Paul am made a minister;"}, {"numero": 24, "texto": "Who now rejoice in my sufferings for you, and fill up that which is behind of the afflictions of Christ in my flesh for his body''s sake, which is the church:"}, {"numero": 25, "texto": "Whereof I am made a minister, according to the dispensation of God which is given to me for you, to fulfil the word of God;"}, {"numero": 26, "texto": "Even the mystery which hath been hid from ages and from generations, but now is made manifest to his saints:"}, {"numero": 27, "texto": "To whom God would make known what is the riches of the glory of this mystery among the Gentiles; which is Christ in you, the hope of glory:"}, {"numero": 28, "texto": "Whom we preach, warning every man, and teaching every man in all wisdom; that we may present every man perfect in Christ Jesus:"}, {"numero": 29, "texto": "Whereunto I also labour, striving according to his working, which worketh in me mightily."}]'::jsonb, 'King James Version'),
  ('Cl', 1, 'fr', '[{"numero": 1, "texto": "Paul, apôtre de Jésus Christ par la volonté de Dieu, et le frère Timothée,"}, {"numero": 2, "texto": "aux saints et fidèles frères en Christ qui sont à Colosses; que la grâce et la paix vous soient données de la part de Dieu notre Père!"}, {"numero": 3, "texto": "Nous rendons grâces à Dieu, le Père de notre Seigneur Jésus-Christ, et nous ne cessons de prier pour vous,"}, {"numero": 4, "texto": "ayant été informés de votre foi en Jésus-Christ et de votre charité pour tous les saints,"}, {"numero": 5, "texto": "cause de l''''espérance qui vous est réservée dans les cieux, et que la parole de la vérité, la parole de l''''Evangile vous a précédemment fait connaître."}, {"numero": 6, "texto": "Il est au milieu de vous, et dans le monde entier; il porte des fruits, et il va grandissant, comme c''''est aussi le cas parmi vous, depuis le jour où vous avez entendu et connu la grâce de Dieu conformément à la vérité,"}, {"numero": 7, "texto": "d''''après les instructions que vous avez reçues d''''Epaphras, notre bien-aimé compagnon de service, qui est pour vous un fidèle ministre de Christ,"}, {"numero": 8, "texto": "et qui nous a appris de quelle charité l''''Esprit vous anime."}, {"numero": 9, "texto": "C''''est pour cela que nous aussi, depuis le jour où nous en avons été informés, nous ne cessons de prier Dieu pour vous, et de demander que vous soyez remplis de la connaissance de sa volonté, en toute sagesse et intelligence spirituelle,"}, {"numero": 10, "texto": "pour marcher d''''une manière digne du Seigneur et lui être entièrement agréables, portant des fruits en toutes sortes de bonnes oeuvres et croissant par la connaissance de Dieu,"}, {"numero": 11, "texto": "fortifiés à tous égards par sa puissance glorieuse, en sorte que vous soyez toujours et avec joie persévérants et patients."}, {"numero": 12, "texto": "Rendez grâces au Père, qui vous a rendus capables d''''avoir part à l''''héritage des saints dans la lumière,"}, {"numero": 13, "texto": "qui nous a délivrés de la puissance des ténèbres et nous a transportés dans le royaume du Fils de son amour,"}, {"numero": 14, "texto": "en qui nous avons la rédemption, la rémission des péchés."}, {"numero": 15, "texto": "Il est l''''image du Dieu invisible, le premier-né de toute la création."}, {"numero": 16, "texto": "Car en lui ont été créées toutes les choses qui sont dans les cieux et sur la terre, les visibles et les invisibles, trônes, dignités, dominations, autorités. Tout a été créé par lui et pour lui."}, {"numero": 17, "texto": "Il est avant toutes choses, et toutes choses subsistent en lui."}, {"numero": 18, "texto": "Il est la tête du corps de l''''Eglise; il est le commencement, le premier-né d''''entre les morts, afin d''''être en tout le premier."}, {"numero": 19, "texto": "Car Dieu a voulu que toute plénitude habitât en lui;"}, {"numero": 20, "texto": "il a voulu par lui réconcilier tout avec lui-même, tant ce qui est sur la terre que ce qui est dans les cieux, en faisant la paix par lui, par le sang de sa croix."}, {"numero": 21, "texto": "Et vous, qui étiez autrefois étrangers et ennemis par vos pensées et par vos mauvaises oeuvres, il vous a maintenant réconciliés"}, {"numero": 22, "texto": "par sa mort dans le corps de sa chair, pour vous faire paraître devant lui saints, irrépréhensibles et sans reproche,"}, {"numero": 23, "texto": "si du moins vous demeurez fondés et inébranlables dans la foi, sans vous détourner de l''''espérance de l''''Evangile que vous avez entendu, qui a été prêché à toute créature sous le ciel, et dont moi Paul, j''''ai été fait ministre."}, {"numero": 24, "texto": "Je me réjouis maintenant dans mes souffrances pour vous; et ce qui manque aux souffrances de Christ, je l''''achève en ma chair, pour son corps, qui est l''''Eglise."}, {"numero": 25, "texto": "C''''est d''''elle que j''''ai été fait ministre, selon la charge que Dieu m''''a donnée auprès de vous, afin que j''''annonçasse pleinement la parole de Dieu,"}, {"numero": 26, "texto": "le mystère caché de tout temps et dans tous les âges, mais révélé maintenant à ses saints,"}, {"numero": 27, "texto": "qui Dieu a voulu faire connaître quelle est la glorieuse richesse de ce mystère parmi les païens, savoir: Christ en vous, l''''espérance de la gloire."}, {"numero": 28, "texto": "C''''est lui que nous annonçons, exhortant tout homme, et instruisant tout homme en toute sagesse, afin de présenter à Dieu tout homme, devenu parfait en Christ."}, {"numero": 29, "texto": "C''''est à quoi je travaille, en combattant avec sa force, qui agit puissamment en moi."}]'::jsonb, 'Louis Segond 1910'),
  ('Cl', 1, 'es', '[{"numero": 1, "texto": "PABLO, apóstol de Jesucristo por la voluntad de Dios, y el hermano Timoteo,"}, {"numero": 2, "texto": "A los santos y hermanos fieles en Cristo que están en Colosas: Gracia y paz á vosotros de Dios Padre nuestro, y del Señor Jesucristo."}, {"numero": 3, "texto": "Damos gracias al Dios y Padre del Señor nuestro Jesucristo, siempre orando por vosotros:"}, {"numero": 4, "texto": "Habiendo oído vuestra fe en Cristo Jesús, y el amor que tenéis á todos los santos,"}, {"numero": 5, "texto": "A causa de la esperanza que os está guardada en los cielos, de la cual habéis oído ya por la palabra verdadera del evangelio:"}, {"numero": 6, "texto": "El cual ha llegado hasta vosotros, como por todo el mundo; y fructifica y crece, como también en vosotros, desde el día que oísteis y conocisteis la gracia de Dios en verdad,"}, {"numero": 7, "texto": "Como habéis aprendido de Epafras, nuestro consiervo amado, el cual es un fiel ministro de Cristo á favor vuestro;"}, {"numero": 8, "texto": "El cual también nos ha declarado vuestro amor en el Espíritu."}, {"numero": 9, "texto": "Por lo cual también nosotros, desde el día que lo oímos, no cesamos de orar por vosotros, y de pedir que seáis llenos del conocimiento de su voluntad, en toda sabiduría y espiritual inteligencia;"}, {"numero": 10, "texto": "Para que andéis como es digno del Señor, agradándole en todo, fructificando en toda buena obra, y creciendo en el conocimiento de Dios:"}, {"numero": 11, "texto": "Corroborados de toda fortaleza, conforme á la potencia de su gloria, para toda tolerancia y largura de ánimo con gozo;"}, {"numero": 12, "texto": "Dando gracias al Padre que nos hizo aptos para participar de la suerte de los santos en luz:"}, {"numero": 13, "texto": "Que nos ha librado de la potestad de las tinieblas, y trasladado al reino de su amado Hijo;"}, {"numero": 14, "texto": "En el cual tenemos redención por su sangre, la remisión de pecados:"}, {"numero": 15, "texto": "El cual es la imagen del Dios invisible, el primogénito de toda criatura."}, {"numero": 16, "texto": "Porque por él fueron criadas todas las cosas que están en los cielos, y que están en la tierra, visibles é invisibles; sean tronos, sean dominios, sean principados, sean potestades; todo fué criado por él y para él."}, {"numero": 17, "texto": "Y él es antes de todas las cosas, y por él todas las cosas subsisten:"}, {"numero": 18, "texto": "Y él es la cabeza del cuerpo que es la iglesia; él que es el principio, el primogénito de los muertos, para que en todo tenga el primado."}, {"numero": 19, "texto": "Por cuanto agradó al Padre que en él habitase toda plenitud,"}, {"numero": 20, "texto": "Y por él reconciliar todas las cosas á sí, pacificando por la sangre de su cruz, así lo que está en la tierra como lo que está en los cielos."}, {"numero": 21, "texto": "A vosotros también, que erais en otro tiempo extraños y enemigos de ánimo en malas obras, ahora empero os ha reconciliado"}, {"numero": 22, "texto": "En el cuerpo de su carne por medio de muerte, para haceros santos, y sin mancha, é irreprensibles delante de él:"}, {"numero": 23, "texto": "Si empero permanecéis fundados y firmes en la fe, y sin moveros de la esperanza del evangelio que habéis oído; el cual es predicado á toda criatura que está debajo del cielo; del cual yo Pablo soy hecho ministro."}, {"numero": 24, "texto": "Que ahora me gozo en lo que padezco por vosotros, y cumplo en mi carne lo que falta de las aflicciones de Cristo por su cuerpo, que es la iglesia;"}, {"numero": 25, "texto": "De la cual soy hecho ministro, según la dispensación de Dios que me fué dada en orden á vosotros, para que cumpla la palabra de Dios;"}, {"numero": 26, "texto": "A saber, el misterio que había estado oculto desde los siglos y edades, mas ahora ha sido manifestado á sus santos:"}, {"numero": 27, "texto": "A los cuales quiso Dios hacer notorias las riquezas de la gloria de este misterio entre los Gentiles; que es Cristo en vosotros la esperanza de gloria:"}, {"numero": 28, "texto": "El cual nosotros anunciamos, amonestando á todo hombre, y enseñando en toda sabiduría, para que presentemos á todo hombre perfecto en Cristo Jesús:"}, {"numero": 29, "texto": "En lo cual aun trabajo, combatiendo según la operación de él, la cual obra en mí poderosamente."}]'::jsonb, 'Reina-Valera 1909'),
  ('Cl', 3, 'pt', '[{"numero": 1, "texto": "Portanto, se fostes ressuscitados com Cristo, buscai as coisas de cima, onde Cristo está sentado à direita de Deus."}, {"numero": 2, "texto": "Pensai nas coisas de cima, não nas que [estão] na terra."}, {"numero": 3, "texto": "Pois já morrestes, e a vossa vida está escondida com Cristo em Deus."}, {"numero": 4, "texto": "Quando Cristo, [que é] a nossa vida, se manifestar, então também vós vos manifestareis com ele em glória."}, {"numero": 5, "texto": "Portanto, mortificai as partes carnais que há em vós que são terrenas; [são elas] : o pecado sexual, a impureza, a paixão depravada, o desejo maligno, e a ganância, que é idolatria."}, {"numero": 6, "texto": "Por causa delas que a ira de Deus vem sobre os filhos da desobediência."}, {"numero": 7, "texto": "Nessas coisas também vós andastes antes, quando vivíeis nelas."}, {"numero": 8, "texto": "Mas agora, abandonai, vós também, todas [estas coisas] : a ira, a fúria, a malícia, a maledicência, e as palavras vergonhosas da vossa boca."}, {"numero": 9, "texto": "Não mintais uns aos outros, pois já vos despistes do velho ser humano com os seus costumes,"}, {"numero": 10, "texto": "e vos revestistes do novo, que se renova em conhecimento, conforme a imagem daquele que o criou."}, {"numero": 11, "texto": "Nisso não há grego, nem judeu, nem circunciso, nem incircunciso, bárbaro, cita, escravo, [nem] livre; mas Cristo é tudo, e em todos."}, {"numero": 12, "texto": "Por isso, como escolhidos de Deus, santos e amados, revesti-vos de sentimentos de misericórdia, bondade, humildade, mansidão, e paciência."}, {"numero": 13, "texto": "Suportai-vos uns aos outros, e perdoai-vos uns aos outros, se alguém tiver queixa contra outro. Como Cristo vos perdoou, assim também [fazei] ."}, {"numero": 14, "texto": "E acima de tudo isto, [revesti-vos] do amor, que é o vínculo da perfeição."}, {"numero": 15, "texto": "E a paz de Deus, para a qual também fostes chamados em um [só] corpo, governe em vossos corações, e sede gratos."}, {"numero": 16, "texto": "A palavra de Cristo habite abundantemente em vós com toda sabedoria, ensinando-vos e advertindo-vos uns aos outros; e cantai ao Senhor com salmos, hinos, e cânticos espirituais, com graça no vosso coração."}, {"numero": 17, "texto": "E tudo quanto fizerdes, por palavras ou por obras, [fazei] tudo no nome do Senhor Jesus, dando por meio dele graças ao Deus e Pai."}, {"numero": 18, "texto": "Mulheres, sede submissas aos vossos próprios maridos, como convém no Senhor."}, {"numero": 19, "texto": "Maridos, amai às esposas, e não as trateis amargamente."}, {"numero": 20, "texto": "Filhos, obedecei em tudo aos pais, porque isso é agradável ao Senhor."}, {"numero": 21, "texto": "Pais, não provoqueis aos vossos filhos, para que não percam o ânimo."}, {"numero": 22, "texto": "Escravos, obedecei em tudo aos [vossos] senhores segundo a carne, não servindo apenas quando observados, como que para satisfazer às pessoas, mas sim, com sinceridade de coração, temendo a Deus."}, {"numero": 23, "texto": "E tudo quanto fizerdes, fazei de coração, como para o Senhor, e não para as pessoas."}, {"numero": 24, "texto": "Pois sabeis que recebereis do Senhor a recompensa da herança, porque servis ao Senhor Cristo."}, {"numero": 25, "texto": "Mas aquele que fizer injustiça receberá conforme a injustiça que cometer; e não há acepção de pessoas."}]'::jsonb, 'Almeida Livre'),
  ('Cl', 3, 'en', '[{"numero": 1, "texto": "If ye then be risen with Christ, seek those things which are above, where Christ sitteth on the right hand of God."}, {"numero": 2, "texto": "Set your affection on things above, not on things on the earth."}, {"numero": 3, "texto": "For ye are dead, and your life is hid with Christ in God."}, {"numero": 4, "texto": "When Christ, who is our life, shall appear, then shall ye also appear with him in glory."}, {"numero": 5, "texto": "Mortify therefore your members which are upon the earth; fornication, uncleanness, inordinate affection, evil concupiscence, and covetousness, which is idolatry:"}, {"numero": 6, "texto": "For which things'' sake the wrath of God cometh on the children of disobedience:"}, {"numero": 7, "texto": "In the which ye also walked some time, when ye lived in them."}, {"numero": 8, "texto": "But now ye also put off all these; anger, wrath, malice, blasphemy, filthy communication out of your mouth."}, {"numero": 9, "texto": "Lie not one to another, seeing that ye have put off the old man with his deeds;"}, {"numero": 10, "texto": "And have put on the new man, which is renewed in knowledge after the image of him that created him:"}, {"numero": 11, "texto": "Where there is neither Greek nor Jew, circumcision nor uncircumcision, Barbarian, Scythian, bond nor free: but Christ is all, and in all."}, {"numero": 12, "texto": "Put on therefore, as the elect of God, holy and beloved, bowels of mercies, kindness, humbleness of mind, meekness, longsuffering;"}, {"numero": 13, "texto": "Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye."}, {"numero": 14, "texto": "And above all these things put on charity, which is the bond of perfectness."}, {"numero": 15, "texto": "And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful."}, {"numero": 16, "texto": "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord."}, {"numero": 17, "texto": "And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him."}, {"numero": 18, "texto": "Wives, submit yourselves unto your own husbands, as it is fit in the Lord."}, {"numero": 19, "texto": "Husbands, love your wives, and be not bitter against them."}, {"numero": 20, "texto": "Children, obey your parents in all things: for this is well pleasing unto the Lord."}, {"numero": 21, "texto": "Fathers, provoke not your children to anger, lest they be discouraged."}, {"numero": 22, "texto": "Servants, obey in all things your masters according to the flesh; not with eyeservice, as menpleasers; but in singleness of heart, fearing God;"}, {"numero": 23, "texto": "And whatsoever ye do, do it heartily, as to the Lord, and not unto men;"}, {"numero": 24, "texto": "Knowing that of the Lord ye shall receive the reward of the inheritance: for ye serve the Lord Christ."}, {"numero": 25, "texto": "But he that doeth wrong shall receive for the wrong which he hath done: and there is no respect of persons."}]'::jsonb, 'King James Version'),
  ('Cl', 3, 'fr', '[{"numero": 1, "texto": "Si donc vous êtes ressuscités avec Christ, cherchez les choses d''''en haut, où Christ est assis à la droite de Dieu."}, {"numero": 2, "texto": "Affectionnez-vous aux choses d''''en haut, et non à celles qui sont sur la terre."}, {"numero": 3, "texto": "Car vous êtes morts, et votre vie est cachée avec Christ en Dieu."}, {"numero": 4, "texto": "Quand Christ, votre vie, paraîtra, alors vous paraîtrez aussi avec lui dans la gloire."}, {"numero": 5, "texto": "Faites donc mourir les membres qui sont sur la terre, l''''impudicité, l''''impureté, les passions, les mauvais désirs, et la cupidité, qui est une idolâtrie."}, {"numero": 6, "texto": "C''''est à cause de ces choses que la colère de Dieu vient sur les fils de la rébellion,"}, {"numero": 7, "texto": "parmi lesquels vous marchiez autrefois, lorsque vous viviez dans ces péchés."}, {"numero": 8, "texto": "Mais maintenant, renoncez à toutes ces choses, à la colère, à l''''animosité, à la méchanceté, à la calomnie, aux paroles déshonnêtes qui pourraient sortir de votre bouche."}, {"numero": 9, "texto": "Ne mentez pas les uns aux autres, vous étant dépouillés du vieil homme et de ses oeuvres,"}, {"numero": 10, "texto": "et ayant revêtu l''''homme nouveau, qui se renouvelle, dans la connaissance, selon l''''image de celui qui l''''a créé."}, {"numero": 11, "texto": "Il n''''y a ici ni Grec ni Juif, ni circoncis ni incirconcis, ni barbare ni Scythe, ni esclave ni libre; mais Christ est tout et en tous."}, {"numero": 12, "texto": "Ainsi donc, comme des élus de Dieu, saints et bien-aimés, revêtez-vous d''''entrailles de miséricorde, de bonté, d''''humilité, de douceur, de patience."}, {"numero": 13, "texto": "Supportez-vous les uns les autres, et, si l''''un a sujet de se plaindre de l''''autre, pardonnez-vous réciproquement. De même que Christ vous a pardonné, pardonnez-vous aussi."}, {"numero": 14, "texto": "Mais par-dessus toutes ces choses revêtez-vous de la charité, qui est le lien de la perfection."}, {"numero": 15, "texto": "Et que la paix de Christ, à laquelle vous avez été appelés pour former un seul corps, règne dans vos coeurs. Et soyez reconnaissants."}, {"numero": 16, "texto": "Que la parole de Christ habite parmi vous abondamment; instruisez-vous et exhortez-vous les uns les autres en toute sagesse, par des psaumes, par des hymnes, par des cantiques spirituels, chantant à Dieu dans vos coeurs sous l''''inspiration de la grâce."}, {"numero": 17, "texto": "Et quoi que vous fassiez, en parole ou en oeuvre, faites tout au nom du Seigneur Jésus, en rendant par lui des actions de grâces à Dieu le Père."}, {"numero": 18, "texto": "Femmes, soyez soumises à vos maris, comme il convient dans le Seigneur."}, {"numero": 19, "texto": "Maris, aimez vos femmes, et ne vous aigrissez pas contre elles."}, {"numero": 20, "texto": "Enfants, obéissez en toutes choses à vos parents, car cela est agréable dans le Seigneur."}, {"numero": 21, "texto": "Pères, n''''irritez pas vos enfants, de peur qu''''ils ne se découragent."}, {"numero": 22, "texto": "Serviteurs, obéissez en toutes choses à vos maîtres selon la chair, non pas seulement sous leurs yeux, comme pour plaire aux hommes, mais avec simplicité de coeur, dans la crainte du Seigneur."}, {"numero": 23, "texto": "Tout ce que vous faites, faites-le de bon coeur, comme pour le Seigneur et non pour des hommes,"}, {"numero": 24, "texto": "sachant que vous recevrez du Seigneur l''''héritage pour récompense. Servez Christ, le Seigneur."}, {"numero": 25, "texto": "Car celui qui agit injustement recevra selon son injustice, et il n''''y a point d''''acception de personnes."}]'::jsonb, 'Louis Segond 1910'),
  ('Cl', 3, 'es', '[{"numero": 1, "texto": "SI habéis pues resucitado con Cristo, buscad las cosas de arriba, donde está Cristo sentado á la diestra de Dios."}, {"numero": 2, "texto": "Poned la mira en las cosas de arriba, no en las de la tierra."}, {"numero": 3, "texto": "Porque muertos sois, y vuestra vida está escondida con Cristo en Dios."}, {"numero": 4, "texto": "Cuando Cristo, vuestra vida, se manifestare, entonces vosotros también seréis manifestados con él en gloria."}, {"numero": 5, "texto": "Amortiguad, pues, vuestros miembros que están sobre la tierra: fornicación, inmundicia, molicie, mala concupiscencia, y avaricia, que es idolatría:"}, {"numero": 6, "texto": "Por las cuales cosas la ira de Dios viene sobre los hijos de rebelión."}, {"numero": 7, "texto": "En las cuales vosotros también anduvisteis en otro tiempo viviendo en ellas."}, {"numero": 8, "texto": "Mas ahora, dejad también vosotros todas estas cosas: ira, enojo, malicia, maledicencia, torpes palabras de vuestra boca."}, {"numero": 9, "texto": "No mintáis los unos á los otros, habiéndoos despojado del viejo hombre con sus hechos,"}, {"numero": 10, "texto": "Y revestídoos del nuevo, el cual por el conocimiento es renovado conforme á la imagen del que lo crió;"}, {"numero": 11, "texto": "Donde no hay Griego ni Judío, circuncisión ni incircuncisión, bárbaro ni Scytha, siervo ni libre; mas Cristo es el todo, y en todos."}, {"numero": 12, "texto": "Vestíos pues, como escogidos de Dios, santos y amados, de entrañas de misericordia, de benignidad, de humildad, de mansedumbre, de tolerancia;"}, {"numero": 13, "texto": "Sufriéndoos los unos á los otros, y perdonándoos los unos á los otros si alguno tuviere queja del otro: de la manera que Cristo os perdonó, así también hacedlo vosotros."}, {"numero": 14, "texto": "Y sobre todas estas cosas vestíos de caridad, la cual es el vínculo de la perfección."}, {"numero": 15, "texto": "Y la paz de Dios gobierne en vuestros corazones, á la cual asimismo sois llamados en un cuerpo; y sed agradecidos."}, {"numero": 16, "texto": "La palabra de Cristo habite en vosotros en abundancia en toda sabiduría, enseñándoos y exhortándoos los unos á los otros con salmos é himnos y canciones espirituales, con gracia cantando en vuestros corazones al Señor."}, {"numero": 17, "texto": "Y todo lo que hacéis, sea de palabra, ó de hecho, hacedlo todo en el nombre del Señor Jesús, dando gracias á Dios Padre por él."}, {"numero": 18, "texto": "Casadas, estad sujetas á vuestros maridos, como conviene en el Señor."}, {"numero": 19, "texto": "Maridos, amad á vuestras mujeres, y no seáis desapacibles con ellas."}, {"numero": 20, "texto": "Hijos, obedeced á vuestros padres en todo; porque esto agrada al Señor."}, {"numero": 21, "texto": "Padres, no irritéis á vuestros hijos, porque no se hagan de poco ánimo."}, {"numero": 22, "texto": "Siervos, obedeced en todo á vuestros amos carnales, no sirviendo al ojo, como los que agradan á los hombres, sino con sencillez de corazón, temiendo á Dios:"}, {"numero": 23, "texto": "Y todo lo que hagáis, hacedlo de ánimo, como al Señor, y no á los hombres;"}, {"numero": 24, "texto": "Sabiendo que del Señor recibiréis la compensación de la herencia: porque al Señor Cristo servís."}, {"numero": 25, "texto": "Mas el que hace injuria, recibirá la injuria que hiciere; que no hay acepción de personas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 1, 'pt', '[{"numero": 1, "texto": "No ano terceiro do reinado de Jeoaquim, rei de Judá, Nabucodonosor, rei da Babilônia, veio a Jerusalém, e a cercou."}, {"numero": 2, "texto": "E o Senhor entregou em suas mãos a Jeoaquim, rei de Judá, e uma parte dos vasos da casa de Deus, e os trouxe à terra de Sinar, para a casa de seu deus; e pôs os vasos na casa do tesouro de seu deus."}, {"numero": 3, "texto": "E o rei disse a Aspenaz, chefe de seus eunucos, que trouxesse [alguns] dos filhos de Israel, da família real, e dos príncipes,"}, {"numero": 4, "texto": "Rapazes em quem não houvesse defeito físico algum, de boa aparência, entendidos em toda sabedoria, sábios em conhecimento, de boa inteligência, e que tivessem habilidade em prestar assistência no palácio do rei; e que os ensinassem as letras e a língua dos caldeus."}, {"numero": 5, "texto": "E o rei lhes determinou uma porção diária de alimento, da comida do rei, e do vinho que bebia; e que [assim] fossem tratados por três anos, para que ao fim eles estivessem diante do rei."}, {"numero": 6, "texto": "E foram entre eles, dos filhos de Judá, Daniel, Ananias, Misael e Azarias,"}, {"numero": 7, "texto": "Aos quais o chefe dos eunucos pôs [outros] nomes: a Daniel, Beltessazar; a Ananias, Sadraque; a Misael, Mesaque; e a Azarias, Abednego."}, {"numero": 8, "texto": "E Daniel propôs em seu coração de não se contaminar com a porção diária de alimento da comida do rei, nem no vinho que ele bebia; então pediu ao chefe dos eunucos para não se contaminar."}, {"numero": 9, "texto": "(Pois Deus concedeu a Daniel o agrado e o favor do chefe dos eunucos.)"}, {"numero": 10, "texto": "E disse o chefe dos eunucos a Daniel: Tenho medo de meu senhor o rei, que determinou vossa comida e vossa bebida; pois, e se ele perceber que vossos rostos estão com pior aparência que os dos rapazes que são semelhantes a vós? Assim poríeis minha cabeça em risco diante do rei."}, {"numero": 11, "texto": "Então disse Daniel a Melsar, a quem o chefe dos eunucos havia ordenado sobre Daniel, Ananias, Misael, e Azarias:"}, {"numero": 12, "texto": "Faze um teste, eu te peço, com teus servos por dez dias, e dê-nos legumes para comer, e água para beber."}, {"numero": 13, "texto": "Então se vejam diante de ti nossos rostos, e os rostos dos rapazes que comem da porção de alimento da comida do rei; e faze com teus servos conforme o que vires."}, {"numero": 14, "texto": "E ele consentiu-lhes nisto, e fez teste com eles por dez dias."}, {"numero": 15, "texto": "E ao fim dos dez dias foi visto que eles estavam com rostos de melhor aparência e mais bem nutridos que os outros rapazes que comiam da porção de alimento do rei."}, {"numero": 16, "texto": "Foi assim que Melsar lhes tirou a porção de alimento deles, e o vinho que deviam beber, e continuou a lhes dar legumes."}, {"numero": 17, "texto": "Quanto a estes quatro rapazes, Deus lhes deu conhecimento e inteligência em todas as letras e sabedoria; Daniel, porém, teve entendimento em toda visão e sonhos."}, {"numero": 18, "texto": "E quando terminaram os dias dos quais o rei tinha dito que os trouxessem, o chefe dos eunucos os trouxe diante de Nabucodonosor."}, {"numero": 19, "texto": "E o rei falou com eles, e entre todos eles não foi achado [alguém] como Daniel, Ananias, Misael, e Azarias; e assim se tornaram assistentes diante do rei."}, {"numero": 20, "texto": "E em todo negócio de sabedoria [e] inteligência que o rei lhes demandou, achou-os dez vezes melhores que todos os magos e astrólogos que havia em todo o seu reino."}, {"numero": 21, "texto": "E Daniel esteve até o primeiro ano do rei Ciro."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 1, 'en', '[{"numero": 1, "texto": "In the third year of the reign of Jehoiakim king of Judah came Nebuchadnezzar king of Babylon unto Jerusalem, and besieged it."}, {"numero": 2, "texto": "And the Lord gave Jehoiakim king of Judah into his hand, with part of the vessels of the house of God: which he carried into the land of Shinar to the house of his god; and he brought the vessels into the treasure house of his god."}, {"numero": 3, "texto": "And the king spake unto Ashpenaz the master of his eunuchs, that he should bring certain of the children of Israel, and of the king''s seed, and of the princes;"}, {"numero": 4, "texto": "Children in whom was no blemish, but well favoured, and skilful in all wisdom, and cunning in knowledge, and understanding science, and such as had ability in them to stand in the king''s palace, and whom they might teach the learning and the tongue of the Chaldeans."}, {"numero": 5, "texto": "And the king appointed them a daily provision of the king''s meat, and of the wine which he drank: so nourishing them three years, that at the end thereof they might stand before the king."}, {"numero": 6, "texto": "Now among these were of the children of Judah, Daniel, Hananiah, Mishael, and Azariah:"}, {"numero": 7, "texto": "Unto whom the prince of the eunuchs gave names: for he gave unto Daniel the name of Belteshazzar; and to Hananiah, of Shadrach; and to Mishael, of Meshach; and to Azariah, of Abednego."}, {"numero": 8, "texto": "But Daniel purposed in his heart that he would not defile himself with the portion of the king''s meat, nor with the wine which he drank: therefore he requested of the prince of the eunuchs that he might not defile himself."}, {"numero": 9, "texto": "Now God had brought Daniel into favour and tender love with the prince of the eunuchs."}, {"numero": 10, "texto": "And the prince of the eunuchs said unto Daniel, I fear my lord the king, who hath appointed your meat and your drink: for why should he see your faces worse liking than the children which are of your sort? then shall ye make me endanger my head to the king."}, {"numero": 11, "texto": "Then said Daniel to Melzar, whom the prince of the eunuchs had set over Daniel, Hananiah, Mishael, and Azariah,"}, {"numero": 12, "texto": "Prove thy servants, I beseech thee, ten days; and let them give us pulse to eat, and water to drink."}, {"numero": 13, "texto": "Then let our countenances be looked upon before thee, and the countenance of the children that eat of the portion of the king''s meat: and as thou seest, deal with thy servants."}, {"numero": 14, "texto": "So he consented to them in this matter, and proved them ten days."}, {"numero": 15, "texto": "And at the end of ten days their countenances appeared fairer and fatter in flesh than all the children which did eat the portion of the king''s meat."}, {"numero": 16, "texto": "Thus Melzar took away the portion of their meat, and the wine that they should drink; and gave them pulse."}, {"numero": 17, "texto": "As for these four children, God gave them knowledge and skill in all learning and wisdom: and Daniel had understanding in all visions and dreams."}, {"numero": 18, "texto": "Now at the end of the days that the king had said he should bring them in, then the prince of the eunuchs brought them in before Nebuchadnezzar."}, {"numero": 19, "texto": "And the king communed with them; and among them all was found none like Daniel, Hananiah, Mishael, and Azariah: therefore stood they before the king."}, {"numero": 20, "texto": "And in all matters of wisdom and understanding, that the king enquired of them, he found them ten times better than all the magicians and astrologers that were in all his realm."}, {"numero": 21, "texto": "And Daniel continued even unto the first year of king Cyrus."}]'::jsonb, 'King James Version'),
  ('Dn', 1, 'fr', '[{"numero": 1, "texto": "La troisième année du règne de Jojakim, roi de Juda, Nebucadnetsar, roi de Babylone, marcha contre Jérusalem, et l''''assiégea."}, {"numero": 2, "texto": "Le Seigneur livra entre ses mains Jojakim, roi de Juda, et une partie des ustensiles de la maison de Dieu. Nebucadnetsar emporta les ustensiles au pays de Schinear, dans la maison de son dieu, il les mit dans la maison du trésor de son dieu."}, {"numero": 3, "texto": "Le roi donna l''''ordre à Aschpenaz, chef de ses eunuques, d''''amener quelques-uns des enfants d''''Israël de race royale ou de famille noble,"}, {"numero": 4, "texto": "de jeunes garçons sans défaut corporel, beaux de figure, doués de sagesse, d''''intelligence et d''''instruction, capables de servir dans le palais du roi, et à qui l''''on enseignerait les lettres et la langue des Chaldéens."}, {"numero": 5, "texto": "Le roi leur assigna pour chaque jour une portion des mets de sa table et du vin dont il buvait, voulant les élever pendant trois années, au bout desquelles ils seraient au service du roi."}, {"numero": 6, "texto": "Il y avait parmi eux, d''''entre les enfants de Juda, Daniel, Hanania, Mischaël et Azaria."}, {"numero": 7, "texto": "Le chef des eunuques leur donna des noms, à Daniel celui de Beltschatsar, à Hanania celui de Schadrac, à Mischaël celui de Méschac, et à Azaria celui d''''Abed-Nego."}, {"numero": 8, "texto": "Daniel résolut de ne pas se souiller par les mets du roi et par le vin dont le roi buvait, et il pria le chef des eunuques de ne pas l''''obliger à se souiller."}, {"numero": 9, "texto": "Dieu fit trouver à Daniel faveur et grâce devant le chef des eunuques."}, {"numero": 10, "texto": "Le chef des eunuques dit à Daniel: Je crains mon seigneur le roi, qui a fixé ce que vous devez manger et boire; car pourquoi verrait-il votre visage plus abattu que celui des jeunes gens de votre âge? Vous exposeriez ma tête auprès du roi."}, {"numero": 11, "texto": "Alors Daniel dit à l''''intendant à qui le chef des eunuques avait remis la surveillance de Daniel, de Hanania, de Mischaël et d''''Azaria:"}, {"numero": 12, "texto": "Eprouve tes serviteurs pendant dix jours, et qu''''on nous donne des légumes à manger et de l''''eau à boire;"}, {"numero": 13, "texto": "tu regarderas ensuite notre visage et celui des jeunes gens qui mangent les mets du roi, et tu agiras avec tes serviteurs d''''après ce que tu auras vu."}, {"numero": 14, "texto": "Il leur accorda ce qu''''ils demandaient, et les éprouva pendant dix jours."}, {"numero": 15, "texto": "Au bout de dix jours, ils avaient meilleur visage et plus d''''embonpoint que tous les jeunes gens qui mangeaient les mets du roi."}, {"numero": 16, "texto": "L''''intendant emportait les mets et le vin qui leur étaient destinés, et il leur donnait des légumes."}, {"numero": 17, "texto": "Dieu accorda à ces quatre jeunes gens de la science, de l''''intelligence dans toutes les lettres, et de la sagesse; et Daniel expliquait toutes les visions et tous les songes."}, {"numero": 18, "texto": "Au terme fixé par le roi pour qu''''on les lui amenât, le chef des eunuques les présenta à Nebucadnetsar."}, {"numero": 19, "texto": "Le roi s''''entretint avec eux; et, parmi tous ces jeunes gens, il ne s''''en trouva aucun comme Daniel, Hanania, Mischaël et Azaria. Ils furent donc admis au service du roi."}, {"numero": 20, "texto": "Sur tous les objets qui réclamaient de la sagesse et de l''''intelligence, et sur lesquels le roi les interrogeait, il les trouvait dix fois supérieurs à tous les magiciens et astrologues qui étaient dans tout son royaume."}, {"numero": 21, "texto": "Ainsi fut Daniel jusqu''''à la première année du roi Cyrus."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 1, 'es', '[{"numero": 1, "texto": "EN el año tercero del reinado de Joacim rey de Judá, vino Nabucodonosor rey de Babilonia á Jerusalem, y cercóla."}, {"numero": 2, "texto": "Y el Señor entregó en sus manos á Joacim rey de Judá, y parte de los vasos de la casa de Dios, y trájolos á tierra de Sinar, á la casa de su dios: y metió los vasos en la casa del tesoro de su dios."}, {"numero": 3, "texto": "Y dijo el rey á Aspenaz, príncipe de sus eunucos, que trajese de los hijos de Israel, del linaje real de los príncipes,"}, {"numero": 4, "texto": "Muchachos en quienes no hubiese tacha alguna, y de buen parecer, y enseñados en toda sabiduría, y sabios en ciencia, y de buen entendimiento, é idóneos para estar en el palacio del rey; y que les enseñase las letras y la lengua de los Caldeos."}, {"numero": 5, "texto": "Y señalóles el rey ración para cada día de la ración de la comida del rey, y del vino de su beber: que los criase tres años, para que al fin de ellos estuviesen delante del rey."}, {"numero": 6, "texto": "Y fueron entre ellos, de los hijos de Judá, Daniel, Ananías, Misael y Azarías:"}, {"numero": 7, "texto": "A los cuales el príncipe de los eunucos puso nombres: y puso á Daniel, Beltsasar; y á Ananías, Sadrach; y á Misael, Mesach; y á Azarías, Abed-nego."}, {"numero": 8, "texto": "Y Daniel propuso en su corazón de no contaminarse en la ración de la comida del rey, ni en el vino de su beber: pidió por tanto al príncipe de los eunucos de no contaminarse."}, {"numero": 9, "texto": "(Y puso Dios á Daniel en gracia y en buena voluntad con el príncipe de los eunucos.)"}, {"numero": 10, "texto": "Y dijo el príncipe de los eunucos á Daniel: Tengo temor de mi señor el rey, que señaló vuestra comida y vuestra bebida; pues luego que él habrá visto vuestros rostros más tristes que los de los muchachos que son semejantes á vosotros, condenaréis para con el rey mi cabeza."}, {"numero": 11, "texto": "Entonces dijo Daniel á Melsar, que estaba puesto por el príncipe de los eunucos sobre Daniel, Ananías, Misael, y Azarías:"}, {"numero": 12, "texto": "Prueba, te ruego, tus siervos diez días, y dennos legumbres á comer, y agua á beber."}, {"numero": 13, "texto": "Parezcan luego delante de ti nuestros rostros, y los rostros de los muchachos que comen de la ración de la comida del rey; y según que vieres, harás con tus siervos."}, {"numero": 14, "texto": "Consintió pues con ellos en esto, y probó con ellos diez días."}, {"numero": 15, "texto": "Y al cabo de los diez días pareció el rostro de ellos mejor y más nutrido de carne, que los otros muchachos que comían de la ración de la comida del rey."}, {"numero": 16, "texto": "Así fué que Melsar tomaba la ración de la comida de ellos, y el vino de su beber, y dábales legumbres."}, {"numero": 17, "texto": "Y á estos cuatro muchachos dióles Dios conocimiento é inteligencia en todas letras y ciencia: mas Daniel tuvo entendimiento en toda visión y sueños."}, {"numero": 18, "texto": "Pasados pues los días al fin de los cuales había dicho el rey que los trajesen, el príncipe de los eunucos los trajo delante de Nabucodonosor."}, {"numero": 19, "texto": "Y el rey habló con ellos, y no fué hallado entre todos ellos otro como Daniel, Ananías, Misael, y Azarías: y así estuvieron delante del rey."}, {"numero": 20, "texto": "Y en todo negocio de sabiduría é inteligencia que el rey les demandó, hallólos diez veces mejores que todos los magos y astrólogos que había en todo su reino."}, {"numero": 21, "texto": "Y fué Daniel hasta el año primero del rey Ciro."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 2, 'pt', '[{"numero": 1, "texto": "E no segundo ano do reinado de Nabucodonosor, sonhou Nabucodonosor sonhos, e seu espírito se perturbou, de modo que perdeu o sono."}, {"numero": 2, "texto": "E o rei mandou chamar magos, astrólogos, encantadores, e sábios dos caldeus, para que explicassem ao rei seus sonhos. Eles vieram, e se apresentaram diante do rei."}, {"numero": 3, "texto": "E o rei lhes disse: Sonhei um sonho, e meu espírito está perturbado para saber o sonho."}, {"numero": 4, "texto": "Então os caldeus falaram ao rei em língua aramaica: Ó rei, vive para sempre vive! Dize o sonho a teus servos, e mostraremos a interpretação."}, {"numero": 5, "texto": "Então o rei respondeu aos caldeus, e disse: Minha decisão é firme: se não me mostrardes o sonho e sua interpretação, sereis despedaçados, e vossas casas se tornarão em monturos."}, {"numero": 6, "texto": "Mas se mostrardes o sonho e sua interpretação, recebereis de mim presentes, recompensas e grande honra; portanto, mostrai-me o sonho e sua interpretação."}, {"numero": 7, "texto": "Responderam pela segunda vez, e disseram: Diga o rei o sonho a seus servos, e mostraremos sua interpretação."}, {"numero": 8, "texto": "O rei respondeu, e disse: Eu bem sei que vós quereis ganhar tempo; porque sabeis que minha decisão é firme."}, {"numero": 9, "texto": "Pois se não me mostrardes o sonho, haverá uma única sentença para vós. Pois preparastes uma resposta mentirosa e perversa para dizer diante de mim, até que o tempo se mude; portanto, dizei-me o sonho, para que eu tenha certeza de que podeis me mostrar sua interpretação."}, {"numero": 10, "texto": "Os caldeus responderam diante do rei, e disseram: Ninguém há sobre a terra que possa mostrar a palavra do rei; pois nenhum rei, príncipe, nem governante, jamais exigiu coisa semelhante a algum mago, astrólogo, ou caldeu."}, {"numero": 11, "texto": "Pois a coisa que o rei exige é tão difícil que não há quem a possa revelar diante do rei, a não ser os deuses, cuja morada não é entre a raça humana."}, {"numero": 12, "texto": "Por isso o rei se irou muito e se enfureceu; então mandou matar a todos os sábios da Babilônia."}, {"numero": 13, "texto": "E publicou-se o decreto, e os sábios foram condenados à morte; e buscaram a Daniel e a seus companheiros para serem mortos."}, {"numero": 14, "texto": "Então Daniel falou de forma cautelosa e prudente a Arioque, capitão dos da guarda do rei, que tinha saído para matar os sábios de Babilônia."}, {"numero": 15, "texto": "Ele respondeu e disse a Arioque, capitão do rei: Por que houve este mandamento do rei tão repentinamente? Então Arioque explicou o ocorrido a Daniel."}, {"numero": 16, "texto": "E Daniel entrou, e pediu ao rei que lhe desse tempo para que ele mostrasse a interpretação ao rei."}, {"numero": 17, "texto": "Então Daniel foi para sua casa, e contou o ocorrido a Ananias, Misael, e Azarias, seus companheiros,"}, {"numero": 18, "texto": "Para que pedissem misericórdia do Deus do céu sobre este mistério, e que Daniel e seus companheiros não perecessem juntamente com os demais sábios da Babilônia."}, {"numero": 19, "texto": "Então o mistério foi revelado a Daniel em visão de noite; então Daniel louvou ao Deus do céu."}, {"numero": 20, "texto": "Daniel falou, e disse: Bendito seja o nome de Deus para todo o sempre! Porque a ele pertence a sabedoria e o poder."}, {"numero": 21, "texto": "E ele é o que muda os tempos e as estações; ele tira os reis, e confirma os reis; ele é o que dá a sabedoria aos sábios, e a conhecimento aos entendidos;"}, {"numero": 22, "texto": "Ele revela o profundo e o escondido; conhece o que está nas trevas, e a luz mora com ele."}, {"numero": 23, "texto": "A ti, ó Deus de meus pais, te agradeço e louvo, pois tu me deste sabedoria e poder, e agora me fizeste saber o que te pedimos; porque tu nos fizeste saber o assunto do rei."}, {"numero": 24, "texto": "Depois disto Daniel veio a Arioque, ao qual o rei tinha constituído para matar os sábios da Babilônia; ele veio, e disse-lhe assim: Não mates os sábios da Babilônia; leva-me diante do rei, que eu mostrarei ao rei a interpretação."}, {"numero": 25, "texto": "Então Arioque levou depressa a Daniel diante do rei, e disse-lhe assim: Achei um homem dos do cativos de Judá, o qual mostrará ao rei a interpretação."}, {"numero": 26, "texto": "Respondeu o rei, e disse a Daniel (cujo nome era Beltessazar): Podes tu me explicar o sonho que vi, e sua interpretação?"}, {"numero": 27, "texto": "Daniel respondeu diante do rei, e disse: O mistério que o rei demanda, nem sábios, nem astrólogos, nem magos, nem adivinhos podem explicar ao rei;"}, {"numero": 28, "texto": "Mas há um Deus nos céus, o qual revela os mistérios; ele, pois, fez saber ao rei Nabucodonosor o que haverá de acontecer no fim dos dias. Teu sonho, e as visões de tua cabeça sobre tua cama, são o seguinte:"}, {"numero": 29, "texto": "Enquanto tu, ó rei, estava em tua cama, vieram teus pensamentos saber o irá acontecer no futuro; pois aquele que revela os mistérios te mostrou o que haverá de acontecer."}, {"numero": 30, "texto": "E a mim foi revelado este mistério, não porque em mim há mais sabedoria que em todos os viventes, mas sim para que eu explique a interpretação ao rei, e assim entendas os pensamentos de teu coração."}, {"numero": 31, "texto": "Tu, ó rei, estavas vendo, e eis uma grande estátua. Esta estátua, que era muito grande, e tinha um esplendor excelente, estava em pé diante de ti; e sua aparência era terrível."}, {"numero": 32, "texto": "A cabeça da estátua era de ouro puro; seus peito e seus braços, de prata; seu ventre e suas coxas, de bronze;"}, {"numero": 33, "texto": "Suas pernas de ferro; seus pés, em parte de ferro, e em parte de barro."}, {"numero": 34, "texto": "Estavas tu vendo, até que uma pedra foi cortada sem [auxílio de] mãos, a qual feriu a estátua em seus pés de ferro e de barro, e os esmigalhou."}, {"numero": 35, "texto": "Então foi juntamente esmigalhado o ferro, o barro, o bronze, a prata e o ouro, e se tornaram como o pó das eiras de verão; e o vento os levou, e nunca se achou algum lugar para eles. Mas a pedra que feriu a estátua, se tornou um grande monte, que encheu toda a terra."}, {"numero": 36, "texto": "Este é o sonho; a interpretação dele também diremos diante do rei."}, {"numero": 37, "texto": "Tu, ó rei, és rei de reis; pois o Deus do céu te deu o reino, poder, força, e majestade."}, {"numero": 38, "texto": "E onde quer que habitam filhos de homens, animais do campo, e aves do céu, ele os entregou em tuas mãos, e fez com que tivesses domínio sobre tudo; tu és a cabeça de ouro."}, {"numero": 39, "texto": "E depois de ti se levantará outro reino inferior ao; e outro terceiro reino de bronze, o qual dominará toda a terra."}, {"numero": 40, "texto": "E o quarto reino será forte como o ferro; e tal como o ferro esmigalha e despedaça tudo, e tal como o ferro que quebra todas estas coisas, assim também ele esmigalhará e quebrará."}, {"numero": 41, "texto": "E o que viste dos pés e dos dedos, em parte de barro de oleiro, e em parte de ferro, isso será um o reino dividido; mas haverá nele [algo] da força do ferro, conforme o que viste o ferro misturado com o barro mole."}, {"numero": 42, "texto": "E os dedos dos pés em parte de ferro, e em parte de barro, são que em parte o reino será forte, e em parte será frágil."}, {"numero": 43, "texto": "Quanto ao que viste, o ferro misturado com barro mole, misturar-se-ão com semente humana, mas não se ligarão um ao outro, como o ferro não se mistura com o barro."}, {"numero": 44, "texto": "Mas nos dias destes reis, o Deus do céu levantará um reino que nunca será destruído; e este reino não será deixado para outro povo; ao contrário, esmigalhará e consumirá todos estes reinos, e [tal reino] permanecerá para sempre."}, {"numero": 45, "texto": "Por isso viste que do monte foi cortada uma pedra sem [auxílio de] mãos, a qual esmigalhou o ferro, o bronze, o barro, a prata, e o ouro. O grande Deus mostrou ao rei o que irá acontecer no futuro. O sonho é verdadeiro, e sua interpretação é fiel."}, {"numero": 46, "texto": "Então o rei Nabucodonosor caiu com o rosto ao chão, prostrou-se diante de Daniel, e mandou que lhe sacrificassem oferta de alimento e incensos."}, {"numero": 47, "texto": "O rei respondeu a Daniel, e disse: Certamente vosso Deus é o Deus dos deuses, o Senhor dos reis, e o revelador dos mistérios, pois pudeste revelar este mistério."}, {"numero": 48, "texto": "Então o rei engrandeceu a Daniel, e lhe deu muitos e grandes presentes, e o pôs por governador de toda a província da Babilônia, e por príncipe dos governadores sobre todos os sábios de Babilônia."}, {"numero": 49, "texto": "E Daniel pediu do rei, e ele pôs sobre os negócios da província de Babilônia a Sadraque, Mesaque, e Abednego; porém Daniel [ficou] na corte do rei."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 2, 'en', '[{"numero": 1, "texto": "And in the second year of the reign of Nebuchadnezzar Nebuchadnezzar dreamed dreams, wherewith his spirit was troubled, and his sleep brake from him."}, {"numero": 2, "texto": "Then the king commanded to call the magicians, and the astrologers, and the sorcerers, and the Chaldeans, for to shew the king his dreams. So they came and stood before the king."}, {"numero": 3, "texto": "And the king said unto them, I have dreamed a dream, and my spirit was troubled to know the dream."}, {"numero": 4, "texto": "Then spake the Chaldeans to the king in Syriack, O king, live for ever: tell thy servants the dream, and we will shew the interpretation."}, {"numero": 5, "texto": "The king answered and said to the Chaldeans, The thing is gone from me: if ye will not make known unto me the dream, with the interpretation thereof, ye shall be cut in pieces, and your houses shall be made a dunghill."}, {"numero": 6, "texto": "But if ye shew the dream, and the interpretation thereof, ye shall receive of me gifts and rewards and great honour: therefore shew me the dream, and the interpretation thereof."}, {"numero": 7, "texto": "They answered again and said, Let the king tell his servants the dream, and we will shew the interpretation of it."}, {"numero": 8, "texto": "The king answered and said, I know of certainty that ye would gain the time, because ye see the thing is gone from me."}, {"numero": 9, "texto": "But if ye will not make known unto me the dream, there is but one decree for you: for ye have prepared lying and corrupt words to speak before me, till the time be changed: therefore tell me the dream, and I shall know that ye can shew me the interpretation thereof."}, {"numero": 10, "texto": "The Chaldeans answered before the king, and said, There is not a man upon the earth that can shew the king''s matter: therefore there is no king, lord, nor ruler, that asked such things at any magician, or astrologer, or Chaldean."}, {"numero": 11, "texto": "And it is a rare thing that the king requireth, and there is none other that can shew it before the king, except the gods, whose dwelling is not with flesh."}, {"numero": 12, "texto": "For this cause the king was angry and very furious, and commanded to destroy all the wise men of Babylon."}, {"numero": 13, "texto": "And the decree went forth that the wise men should be slain; and they sought Daniel and his fellows to be slain."}, {"numero": 14, "texto": "Then Daniel answered with counsel and wisdom to Arioch the captain of the king''s guard, which was gone forth to slay the wise men of Babylon:"}, {"numero": 15, "texto": "He answered and said to Arioch the king''s captain, Why is the decree so hasty from the king? Then Arioch made the thing known to Daniel."}, {"numero": 16, "texto": "Then Daniel went in, and desired of the king that he would give him time, and that he would shew the king the interpretation."}, {"numero": 17, "texto": "Then Daniel went to his house, and made the thing known to Hananiah, Mishael, and Azariah, his companions:"}, {"numero": 18, "texto": "That they would desire mercies of the God of heaven concerning this secret; that Daniel and his fellows should not perish with the rest of the wise men of Babylon."}, {"numero": 19, "texto": "Then was the secret revealed unto Daniel in a night vision. Then Daniel blessed the God of heaven."}, {"numero": 20, "texto": "Daniel answered and said, Blessed be the name of God for ever and ever: for wisdom and might are his:"}, {"numero": 21, "texto": "And he changeth the times and the seasons: he removeth kings, and setteth up kings: he giveth wisdom unto the wise, and knowledge to them that know understanding:"}, {"numero": 22, "texto": "He revealeth the deep and secret things: he knoweth what is in the darkness, and the light dwelleth with him."}, {"numero": 23, "texto": "I thank thee, and praise thee, O thou God of my fathers, who hast given me wisdom and might, and hast made known unto me now what we desired of thee: for thou hast now made known unto us the king''s matter."}, {"numero": 24, "texto": "Therefore Daniel went in unto Arioch, whom the king had ordained to destroy the wise men of Babylon: he went and said thus unto him; Destroy not the wise men of Babylon: bring me in before the king, and I will shew unto the king the interpretation."}, {"numero": 25, "texto": "Then Arioch brought in Daniel before the king in haste, and said thus unto him, I have found a man of the captives of Judah, that will make known unto the king the interpretation."}, {"numero": 26, "texto": "The king answered and said to Daniel, whose name was Belteshazzar, Art thou able to make known unto me the dream which I have seen, and the interpretation thereof?"}, {"numero": 27, "texto": "Daniel answered in the presence of the king, and said, The secret which the king hath demanded cannot the wise men, the astrologers, the magicians, the soothsayers, shew unto the king;"}, {"numero": 28, "texto": "But there is a God in heaven that revealeth secrets, and maketh known to the king Nebuchadnezzar what shall be in the latter days. Thy dream, and the visions of thy head upon thy bed, are these;"}, {"numero": 29, "texto": "As for thee, O king, thy thoughts came into thy mind upon thy bed, what should come to pass hereafter: and he that revealeth secrets maketh known to thee what shall come to pass."}, {"numero": 30, "texto": "But as for me, this secret is not revealed to me for any wisdom that I have more than any living, but for their sakes that shall make known the interpretation to the king, and that thou mightest know the thoughts of thy heart."}, {"numero": 31, "texto": "Thou, O king, sawest, and behold a great image. This great image, whose brightness was excellent, stood before thee; and the form thereof was terrible."}, {"numero": 32, "texto": "This image''s head was of fine gold, his breast and his arms of silver, his belly and his thighs of brass,"}, {"numero": 33, "texto": "His legs of iron, his feet part of iron and part of clay."}, {"numero": 34, "texto": "Thou sawest till that a stone was cut out without hands, which smote the image upon his feet that were of iron and clay, and brake them to pieces."}, {"numero": 35, "texto": "Then was the iron, the clay, the brass, the silver, and the gold, broken to pieces together, and became like the chaff of the summer threshingfloors; and the wind carried them away, that no place was found for them: and the stone that smote the image became a great mountain, and filled the whole earth."}, {"numero": 36, "texto": "This is the dream; and we will tell the interpretation thereof before the king."}, {"numero": 37, "texto": "Thou, O king, art a king of kings: for the God of heaven hath given thee a kingdom, power, and strength, and glory."}, {"numero": 38, "texto": "And wheresoever the children of men dwell, the beasts of the field and the fowls of the heaven hath he given into thine hand, and hath made thee ruler over them all. Thou art this head of gold."}, {"numero": 39, "texto": "And after thee shall arise another kingdom inferior to thee, and another third kingdom of brass, which shall bear rule over all the earth."}, {"numero": 40, "texto": "And the fourth kingdom shall be strong as iron: forasmuch as iron breaketh in pieces and subdueth all things: and as iron that breaketh all these, shall it break in pieces and bruise."}, {"numero": 41, "texto": "And whereas thou sawest the feet and toes, part of potters'' clay, and part of iron, the kingdom shall be divided; but there shall be in it of the strength of the iron, forasmuch as thou sawest the iron mixed with miry clay."}, {"numero": 42, "texto": "And as the toes of the feet were part of iron, and part of clay, so the kingdom shall be partly strong, and partly broken."}, {"numero": 43, "texto": "And whereas thou sawest iron mixed with miry clay, they shall mingle themselves with the seed of men: but they shall not cleave one to another, even as iron is not mixed with clay."}, {"numero": 44, "texto": "And in the days of these kings shall the God of heaven set up a kingdom, which shall never be destroyed: and the kingdom shall not be left to other people, but it shall break in pieces and consume all these kingdoms, and it shall stand for ever."}, {"numero": 45, "texto": "Forasmuch as thou sawest that the stone was cut out of the mountain without hands, and that it brake in pieces the iron, the brass, the clay, the silver, and the gold; the great God hath made known to the king what shall come to pass hereafter: and the dream is certain, and the interpretation thereof sure."}, {"numero": 46, "texto": "Then the king Nebuchadnezzar fell upon his face, and worshipped Daniel, and commanded that they should offer an oblation and sweet odours unto him."}, {"numero": 47, "texto": "The king answered unto Daniel, and said, Of a truth it is, that your God is a God of gods, and a Lord of kings, and a revealer of secrets, seeing thou couldest reveal this secret."}, {"numero": 48, "texto": "Then the king made Daniel a great man, and gave him many great gifts, and made him ruler over the whole province of Babylon, and chief of the governors over all the wise men of Babylon."}, {"numero": 49, "texto": "Then Daniel requested of the king, and he set Shadrach, Meshach, and Abednego, over the affairs of the province of Babylon: but Daniel sat in the gate of the king."}]'::jsonb, 'King James Version'),
  ('Dn', 2, 'fr', '[{"numero": 1, "texto": "La seconde année du règne de Nebucadnetsar, Nebucadnetsar eut des songes. Il avait l''''esprit agité, et ne pouvait dormir."}, {"numero": 2, "texto": "Le roi fit appeler les magiciens, les astrologues, les enchanteurs et les Chaldéens, pour qu''''ils lui disent ses songes. Ils vinrent, et se présentèrent devant le roi."}, {"numero": 3, "texto": "Le roi leur dit: J''''ai eu un songe; mon esprit est agité, et je voudrais connaître ce songe."}, {"numero": 4, "texto": "Les Chaldéens répondirent au roi en langue araméenne: O roi, vis éternellement! dis le songe à tes serviteurs, et nous en donnerons l''''explication."}, {"numero": 5, "texto": "Le roi reprit la parole et dit aux Chaldéens: La chose m''''a échappé; si vous ne me faites connaître le songe et son explication, vous serez mis en pièces, et vos maisons seront réduites en un tas d''''immondices."}, {"numero": 6, "texto": "Mais si vous me dites le songe et son explication, vous recevrez de moi des dons et des présents, et de grands honneurs. C''''est pourquoi dites-moi le songe et son explication."}, {"numero": 7, "texto": "Ils répondirent pour la seconde fois: Que le roi dise le songe à ses serviteurs, et nous en donnerons l''''explication."}, {"numero": 8, "texto": "Le roi reprit la parole et dit: Je m''''aperçois, en vérité, que vous voulez gagner du temps, parce que vous voyez que la chose m''''a échappé."}, {"numero": 9, "texto": "Si donc vous ne me faites pas connaître le songe, la même sentence vous enveloppera tous; vous voulez vous préparer à me dire des mensonges et des faussetés, en attendant que les temps soient changés. C''''est pourquoi dites-moi le songe, et je saurai si vous êtes capables de m''''en donner l''''explication."}, {"numero": 10, "texto": "Les Chaldéens répondirent au roi: Il n''''est personne sur la terre qui puisse dire ce que demande le roi; aussi jamais roi, quelque grand et puissant qu''''il ait été, n''''a exigé une pareille chose d''''aucun magicien, astrologue ou Chaldéen."}, {"numero": 11, "texto": "Ce que le roi demande est difficile; il n''''y a personne qui puisse le dire au roi, excepté les dieux, dont la demeure n''''est pas parmi les hommes."}, {"numero": 12, "texto": "Là-dessus le roi se mit en colère, et s''''irrita violemment. Il ordonna qu''''on fasse périr tous les sages de Babylone."}, {"numero": 13, "texto": "La sentence fut publiée, les sages étaient mis à mort, et l''''on cherchait Daniel et ses compagnons pour les faire périr."}, {"numero": 14, "texto": "Alors Daniel s''''adressa d''''une manière prudente et sensée à Arjoc, chef des gardes du roi, qui était sorti pour mettre à mort les sages de Babylone."}, {"numero": 15, "texto": "Il prit la parole et dit à Arjoc, commandant du roi: Pourquoi la sentence du roi est-elle si sévère? Arjoc exposa la chose à Daniel."}, {"numero": 16, "texto": "Et Daniel se rendit vers le roi, et le pria de lui accorder du temps pour donner au roi l''''explication."}, {"numero": 17, "texto": "Ensuite Daniel alla dans sa maison, et il instruisit de cette affaire Hanania, Mischaël et Azaria, ses compagnons,"}, {"numero": 18, "texto": "les engageant à implorer la miséricorde du Dieu des cieux, afin qu''''on ne fît pas périr Daniel et ses compagnons avec le reste des sages de Babylone."}, {"numero": 19, "texto": "Alors le secret fut révélé à Daniel dans une vision pendant la nuit. Et Daniel bénit le Dieu des cieux."}, {"numero": 20, "texto": "Daniel prit la parole et dit: Béni soit le nom de Dieu, d''''éternité en éternité! A lui appartiennent la sagesse et la force."}, {"numero": 21, "texto": "C''''est lui qui change les temps et les circonstances, qui renverse et qui établit les rois, qui donne la sagesse aux sages et la science à ceux qui ont de l''''intelligence."}, {"numero": 22, "texto": "Il révèle ce qui est profond et caché, il connaît ce qui est dans les ténèbres, et la lumière demeure avec lui."}, {"numero": 23, "texto": "Dieu de mes pères, je te glorifie et je te loue de ce que tu m''''as donné la sagesse et la force, et de ce que tu m''''as fait connaître ce que nous t''''avons demandé, de ce que tu nous as révélé le secret du roi."}, {"numero": 24, "texto": "Après cela, Daniel se rendit auprès d''''Arjoc, à qui le roi avait ordonné de faire périr les sages de Babylone; il alla, et lui parla ainsi: Ne fais pas périr les sages de Babylone! Conduis-moi devant le roi, et je donnerai au roi l''''explication."}, {"numero": 25, "texto": "Arjoc conduisit promptement Daniel devant le roi, et lui parla ainsi: J''''ai trouvé parmi les captifs de Juda un homme qui donnera l''''explication au roi."}, {"numero": 26, "texto": "Le roi prit la parole et dit à Daniel, qu''''on nommait Beltschatsar: Es-tu capable de me faire connaître le songe que j''''ai eu et son explication?"}, {"numero": 27, "texto": "Daniel répondit en présence du roi et dit: Ce que le roi demande est un secret que les sages, les astrologues, les magiciens et les devins, ne sont pas capables de découvrir au roi."}, {"numero": 28, "texto": "Mais il y a dans les cieux un Dieu qui révèle les secrets, et qui a fait connaître au roi Nebucadnetsar ce qui arrivera dans la suite des temps. Voici ton songe et les visions que tu as eues sur ta couche."}, {"numero": 29, "texto": "Sur ta couche, ô roi, il t''''est monté des pensées touchant ce qui sera après ce temps-ci; et celui qui révèle les secrets t''''a fait connaître ce qui arrivera."}, {"numero": 30, "texto": "Si ce secret m''''a été révélé, ce n''''est point qu''''il y ait en moi une sagesse supérieure à celle de tous les vivants; mais c''''est afin que l''''explication soit donnée au roi, et que tu connaisses les pensées de ton coeur."}, {"numero": 31, "texto": "O roi, tu regardais, et tu voyais une grande statue; cette statue était immense, et d''''une splendeur extraordinaire; elle était debout devant toi, et son aspect était terrible."}, {"numero": 32, "texto": "La tête de cette statue était d''''or pur; sa poitrine et ses bras étaient d''''argent; son ventre et ses cuisses étaient d''''airain;"}, {"numero": 33, "texto": "ses jambes, de fer; ses pieds, en partie de fer et en partie d''''argile."}, {"numero": 34, "texto": "Tu regardais, lorsqu''''une pierre se détacha sans le secours d''''aucune main, frappa les pieds de fer et d''''argile de la statue, et les mit en pièces."}, {"numero": 35, "texto": "Alors le fer, l''''argile, l''''airain, l''''argent et l''''or, furent brisés ensemble, et devinrent comme la balle qui s''''échappe d''''une aire en été; le vent les emporta, et nulle trace n''''en fut retrouvée. Mais la pierre qui avait frappé la statue devint une grande montagne, et remplit toute la terre."}, {"numero": 36, "texto": "Voilà le songe. Nous en donnerons l''''explication devant le roi."}, {"numero": 37, "texto": "O roi, tu es le roi des rois, car le Dieu des cieux t''''a donné l''''empire, la puissance, la force et la gloire;"}, {"numero": 38, "texto": "il a remis entre tes mains, en quelque lieu qu''''ils habitent, les enfants des hommes, les bêtes des champs et les oiseaux du ciel, et il t''''a fait dominer sur eux tous: c''''est toi qui es la tête d''''or."}, {"numero": 39, "texto": "Après toi, il s''''élèvera un autre royaume, moindre que le tien; puis un troisième royaume, qui sera d''''airain, et qui dominera sur toute la terre."}, {"numero": 40, "texto": "Il y aura un quatrième royaume, fort comme du fer; de même que le fer brise et rompt tout, il brisera et rompra tout, comme le fer qui met tout en pièces."}, {"numero": 41, "texto": "Et comme tu as vu les pieds et les orteils en partie d''''argile de potier et en partie de fer, ce royaume sera divisé; mais il y aura en lui quelque chose de la force du fer, parce que tu as vu le fer mêlé avec l''''argile."}, {"numero": 42, "texto": "Et comme les doigts des pieds étaient en partie de fer et en partie d''''argile, ce royaume sera en partie fort et en partie fragile."}, {"numero": 43, "texto": "Tu as vu le fer mêlé avec l''''argile, parce qu''''ils se mêleront par des alliances humaines; mais ils ne seront point unis l''''un à l''''autre, de même que le fer ne s''''allie point avec l''''argile."}, {"numero": 44, "texto": "Dans le temps de ces rois, le Dieu des cieux suscitera un royaume qui ne sera jamais détruit, et qui ne passera point sous la domination d''''un autre peuple; il brisera et anéantira tous ces royaumes-là, et lui-même subsistera éternellement."}, {"numero": 45, "texto": "C''''est ce qu''''indique la pierre que tu as vue se détacher de la montagne sans le secours d''''aucune main, et qui a brisé le fer, l''''airain, l''''argile, l''''argent et l''''or. Le grand Dieu a fait connaître au roi ce qui doit arriver après cela. Le songe est véritable, et son explication est certaine."}, {"numero": 46, "texto": "Alors le roi Nebucadnetsar tomba sur sa face et se prosterna devant Daniel, et il ordonna qu''''on lui offrît des sacrifices et des parfums."}, {"numero": 47, "texto": "Le roi adressa la parole à Daniel et dit: En vérité, votre Dieu est le Dieu des dieux et le Seigneur des rois, et il révèle les secrets, puisque tu as pu découvrir ce secret."}, {"numero": 48, "texto": "Ensuite le roi éleva Daniel, et lui fit de nombreux et riches présents; il lui donna le commandement de toute la province de Babylone, et l''''établit chef suprême de tous les sages de Babylone."}, {"numero": 49, "texto": "Daniel pria le roi de remettre l''''intendance de la province de Babylone à Schadrac, Méschac et Abed-Nego. Et Daniel était à la cour du roi."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 2, 'es', '[{"numero": 1, "texto": "Y EN el segundo año del reinado de Nabucodonosor, soñó Nabucodonosor sueños, y perturbóse su espíritu, y su sueño se huyó de él."}, {"numero": 2, "texto": "Y mandó el rey llamar magos, astrólogos, y encantadores, y Caldeos, para que mostrasen al rey sus sueños. Vinieron pues, y se presentaron delante del rey."}, {"numero": 3, "texto": "Y el rey les dijo: He soñado un sueño, y mi espíritu se ha perturbado por saber del sueño."}, {"numero": 4, "texto": "Entonces hablaron los Caldeos al rey en lengua aramea: Rey, para siempre vive: di el sueño á tus siervos, y mostraremos la declaración."}, {"numero": 5, "texto": "Respondió el rey y dijo á los Caldeos: El negocio se me fué: si no me mostráis el sueño y su declaración, seréis hechos cuartos, y vuestras casas serán puestas por muladares."}, {"numero": 6, "texto": "Y si mostrareis el sueño y su declaración, recibiréis de mí dones y mercedes y grande honra: por tanto, mostradme el sueño y su declaración."}, {"numero": 7, "texto": "Respondieron la segunda vez, y dijeron: Diga el rey el sueño á sus siervos, y mostraremos su declaración."}, {"numero": 8, "texto": "El rey respondió, y dijo: Yo conozco ciertamente que vosotros ponéis dilaciones, porque veis que el negocio se me ha ido."}, {"numero": 9, "texto": "Si no me mostráis el sueño, una sola sentencia será de vosotros. Ciertamente preparáis respuesta mentirosa y perversa que decir delante de mí, entre tanto que se muda el tiempo: por tanto, decidme el sueño, para que yo entienda que me podéis mostrar su declaración."}, {"numero": 10, "texto": "Los Caldeos respondieron delante del rey, y dijeron: No hay hombre sobre la tierra que pueda declarar el negocio del rey: demás de esto, ningún rey, príncipe, ni señor, preguntó cosa semejante á ningún mago, ni astrólogo, ni Caldeo."}, {"numero": 11, "texto": "Finalmente, el negocio que el rey demanda, es singular, ni hay quien lo pueda declarar delante del rey, salvo los dioses cuya morada no es con la carne."}, {"numero": 12, "texto": "Por esto el rey con ira y con grande enojo, mandó que matasen á todos los sabios de Babilonia."}, {"numero": 13, "texto": "Y publicóse el mandamiento, y los sabios eran llevados á la muerte; y buscaron á Daniel y á sus compañeros para matarlos."}, {"numero": 14, "texto": "Entonces Daniel habló avisada y prudentemente á Arioch, capitán de los de la guarda del rey, que había salido para matar los sabios de Babilonia."}, {"numero": 15, "texto": "Habló y dijo á Arioch capitán del rey: ¿Qué es la causa que este mandamiento se publica de parte del rey tan apresuradamente? Entonces Arioch declaró el negocio á Daniel."}, {"numero": 16, "texto": "Y Daniel entró, y pidió al rey que le diese tiempo, y que él mostraría al rey la declaración."}, {"numero": 17, "texto": "Fuése luego Daniel á su casa, y declaró el negocio á Ananías, Misael, y Azarías, sus compañeros,"}, {"numero": 18, "texto": "Para demandar misericordias del Dios del cielo sobre este misterio, y que Daniel y sus compañeros no pereciesen con los otros sabios de Babilonia."}, {"numero": 19, "texto": "Entonces el arcano fué revelado á Daniel en visión de noche; por lo cual bendijo Daniel al Dios del cielo."}, {"numero": 20, "texto": "Y Daniel habló, y dijo: Sea bendito el nombre de Dios de siglo hasta siglo: porque suya es la sabiduría y la fortaleza:"}, {"numero": 21, "texto": "Y él es el que muda los tiempos y las oportunidades: quita reyes, y pone reyes: da la sabiduría á los sabios, y la ciencia á los entendidos:"}, {"numero": 22, "texto": "El revela lo profundo y lo escondido: conoce lo que está en tinieblas, y la luz mora con él."}, {"numero": 23, "texto": "A ti, oh Dios de mis padres, confieso y te alabo, que me diste sabiduría y fortaleza, y ahora me enseñaste lo que te pedimos; pues nos has enseñado el negocio del rey."}, {"numero": 24, "texto": "Después de esto Daniel entró á Arioch, al cual el rey había puesto para matar á los sabios de Babilonia; fué, y díjole así: No mates á los sabios de Babilonia: llévame delante del rey, que yo mostraré al rey la declaración."}, {"numero": 25, "texto": "Entonces Arioch llevó prestamente á Daniel delante del rey, y díjole así: Un varón de los trasportados de Judá he hallado, el cual declarará al rey la interpretación."}, {"numero": 26, "texto": "Respondió el rey, y dijo á Daniel, al cual llamaban Beltsasar: ¿Podrás tú hacerme entender el sueño que vi, y su declaración?"}, {"numero": 27, "texto": "Daniel respondió delante del rey, y dijo: El misterio que el rey demanda, ni sabios, ni astrólogos, ni magos, ni adivinos lo pueden enseñar al rey."}, {"numero": 28, "texto": "Mas hay un Dios en los cielos, el cual revela los misterios, y él ha hecho saber al rey Nabucodonosor lo que ha de acontecer á cabo de días. Tu sueño, y las visiones de tu cabeza sobre tu cama, es esto:"}, {"numero": 29, "texto": "Tú, oh rey, en tu cama subieron tus pensamientos por saber lo que había de ser en lo por venir; y el que revela los misterios te mostró lo que ha de ser."}, {"numero": 30, "texto": "Y á mí ha sido revelado este misterio, no por sabiduría que en mí haya más que en todos los vivientes, sino para que yo notifique al rey la declaración, y que entendieses los pensamientos de tu corazón."}, {"numero": 31, "texto": "Tú, oh rey, veías, y he aquí una grande imagen. Esta imagen, que era muy grande, y cuya gloria era muy sublime, estaba en pie delante de ti, y su aspecto era terrible."}, {"numero": 32, "texto": "La cabeza de esta imagen era de fino oro; sus pechos y sus brazos, de plata; su vientre y sus muslos, de metal;"}, {"numero": 33, "texto": "Sus piernas de hierro; sus pies, en parte de hierro, y en parte de barro cocido."}, {"numero": 34, "texto": "Estabas mirando, hasta que una piedra fué cortada, no con mano, la cual hirió á la imagen en sus pies de hierro y de barro cocido, y los desmenuzó."}, {"numero": 35, "texto": "Entonces fué también desmenuzado el hierro, el barro cocido, el metal, la plata y el oro, y se tornaron como tamo de las eras del verano: y levantólos el viento, y nunca más se les halló lugar. Mas la piedra que hirió á la imagen, fué hecha un gran monte, que hinchió toda la tierra."}, {"numero": 36, "texto": "Este es el sueño: la declaración de él diremos también en presencia del rey."}, {"numero": 37, "texto": "Tú, oh rey, eres rey de reyes; porque el Dios del cielo te ha dado reino, potencia, y fortaleza, y majestad."}, {"numero": 38, "texto": "Y todo lo que habitan hijos de hombres, bestias del campo, y aves del cielo, él ha entregado en tu mano, y te ha hecho enseñorear sobre todo ello: tú eres aquella cabeza de oro."}, {"numero": 39, "texto": "Y después de ti se levantará otro reino menor que tú; y otro tercer reino de metal, el cual se enseñoreará de toda la tierra."}, {"numero": 40, "texto": "Y el reino cuarto será fuerte como hierro; y como el hierro desmenuza y doma todas las cosas, y como el hierro que quebranta todas estas cosas, desmenuzará y quebrantará."}, {"numero": 41, "texto": "Y lo que viste de los pies y los dedos, en parte de barro cocido de alfarero, y en parte de hierro, el reino será dividido; mas habrá en él algo de fortaleza de hierro, según que viste el hierro mezclado con el tiesto de barro."}, {"numero": 42, "texto": "Y por ser los dedos de los pies en parte de hierro, y en parte de barro cocido, en parte será el reino fuerte, y en parte será frágil."}, {"numero": 43, "texto": "Cuanto á aquello que viste, el hierro mezclado con tiesto de barro, mezclaránse con simiente humana, mas no se pegarán el uno con el otro, como el hierro no se mistura con el tiesto."}, {"numero": 44, "texto": "Y en los días de estos reyes, levantará el Dios del cielo un reino que nunca jamás se corromperá: y no será dejado á otro pueblo este reino; el cual desmenuzará y consumirá todos estos reinos, y él permanecerá para siempre."}, {"numero": 45, "texto": "De la manera que viste que del monte fué cortada una piedra, no con manos, la cual desmenuzó al hierro, al metal, al tiesto, á la plata, y al oro; el gran Dios ha mostrado al rey lo que ha de acontecer en lo por venir: y el sueño es verdadero, y fiel su declaración."}, {"numero": 46, "texto": "Entonces el rey Nabucodonosor cayó sobre su rostro, y humillóse á Daniel, y mandó que le sacrificasen presentes y perfumes."}, {"numero": 47, "texto": "El rey habló á Daniel, y dijo: Ciertamente que el Dios vuestro es Dios de dioses, y el Señor de los reyes, y el descubridor de los misterios, pues pudiste revelar este arcano."}, {"numero": 48, "texto": "Entonces el rey engrandeció á Daniel, y le dió muchos y grandes dones, y púsolo por gobernador de toda la provincia de Babilonia, y por príncipe de los gobernadores sobre todos los sabios de Babilonia."}, {"numero": 49, "texto": "Y Daniel solicitó del rey, y él puso sobre los negocios de la provincia de Babilonia á Sadrach, Mesach, y Abed-nego: y Daniel estaba á la puerta del rey."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 3, 'pt', '[{"numero": 1, "texto": "O rei Nabucodonosor fez uma estátua de ouro, cuja altura era de sessenta côvados, sua largura de seis côvados; ergueu-a no campo de Dura, na província da Babilônia."}, {"numero": 2, "texto": "E o rei Nabucodonosor mandou juntar os sátrapas, os prefeitos e governadores, os juízes, tesoureiros, conselheiros, os oficiais, e a todos os líderes das províncias, para que viessem à consagração da estátua que o rei Nabucodonosor havia erguido."}, {"numero": 3, "texto": "Então se reuniram os sátrapas, os prefeitos e governadores, os juízes, tesoureiros, conselheiros, os oficiais, e todos os líderes das províncias, para a consagração da estátua que o rei Nabucodonosor havia erguido; e estavam em pé diante da estátua que Nabucodonosor havia erguido."}, {"numero": 4, "texto": "E o arauto proclamava em alta voz: Manda-se a vós, ó povos, nações, e línguas,"}, {"numero": 5, "texto": "Que quando ouvirdes o som da trombeta, do pífano, da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, vos prostrareis e adorareis a estátua de ouro que o rei Nabucodonosor ergueu."}, {"numero": 6, "texto": "E qualquer um que não se prostrar e [a] adorar, na mesma hora será lançado dentro de uma fornalha de fogo ardente."}, {"numero": 7, "texto": "Por isso no mesmo instante em todos os povos ouviram o som da trombeta, do pífano, da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, todos os povos, nações, e línguas se prostraram, e adoraram a estátua de ouro que o rei Nabucodonosor havia erguido."}, {"numero": 8, "texto": "Por isso no mesmo instante [alguns] homens caldeus se chegaram, e acusaram dos judeus."}, {"numero": 9, "texto": "Eles falaram ao rei Nabucodonosor: Ó rei, vive para sempre!"}, {"numero": 10, "texto": "Tu, ó rei, fizeste um decreto que todo aquele que ouvisse o som da trombeta, do pífano, do da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, se prostrasse e adorasse a estátua de ouro;"}, {"numero": 11, "texto": "E qualquer um que não se prostrasse e adorasse, fosse lançado dentro de uma fornalha de fogo ardente"}, {"numero": 12, "texto": "Há uns homens judeus, os quais constituíste sobre os negócios da província da Babilônia; Sadraque, Mesaque, e Abednego; estes homens, ó rei, não te respeitaram; não servem a teus deuses, nem adoram a estátua de ouro que tu ergueste."}, {"numero": 13, "texto": "Então Nabucodonosor com ira e furor, mandou trazer a Sadraque, Mesaque, e Abednego. Então trouxeram estes homens diante do rei."}, {"numero": 14, "texto": "Nabucodonosor lhes disse: É verdade, Sadraque, Mesaque, e Abednego, que vós não servis a meus deuses, nem adorais a estátua de ouro que ergui?"}, {"numero": 15, "texto": "Agora pois, se estais prontos, quando ouvirdes o som da trombeta, do pífano, da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, prostrai-vos e adorai a estátua que eu fiz. Porém se não a adorardes, na mesma hora sereis lançados dentro da fornalha de fogo ardente; e quem é o Deus que vos livrará de minhas mãos?"}, {"numero": 16, "texto": "Sadraque, Mesaque, e Abednego responderam ao rei Nabucodonosor: Não necessitamos de responder sobre este negócio."}, {"numero": 17, "texto": "Eis que nosso Deus a quem servimos pode nos livrar da fornalha de fogo ardente; e ele nos livrará de tua mão, ó rei."}, {"numero": 18, "texto": "E se não, sabe tu, ó rei, que não serviremos a teus deuses, nem adoraremos a estátua que ergueste."}, {"numero": 19, "texto": "Então Nabucodonosor se encheu de furor, e o aspecto de seu rosto se mudou contra Sadraque, Mesaque, e Abednego. Então ele falou, e mandou que o forno fosse aceso sete vezes mais do que costumava se acender."}, {"numero": 20, "texto": "E mandou aos homens mais fortes que havia em seu exército, que atassem a Sadraque, Mesaque, e Abednego, para lançá-los na fornalha de fogo ardente."}, {"numero": 21, "texto": "Então estes homens foram atados com suas capas, suas calças, seus turbantes, e suas vestes, e foram lançados dentro da fornalha de fogo ardente."}, {"numero": 22, "texto": "E visto que a palavra do rei era urgente, e a fornalha estava muitíssimo quente, a chama do fogo matou aqueles homens que tinham levantado a Sadraque, Mesaque, e Abednego."}, {"numero": 23, "texto": "E estes três homens, Sadraque, Mesaque, e Abednego, caíram atados dentro da fornalha de fogo ardente."}, {"numero": 24, "texto": "Então o rei Nabucodonosor se espantou, e se levantou depressa, então perguntou aos seus conselheiros: Não lançamos três homens atados dentro do fogo? Eles responderam ao rei: É verdade, ó rei."}, {"numero": 25, "texto": "Ele disse mais: Eis que vejo quatro homens soltos andando no meio do fogo, e não há neles dano algum; e a aparência do quarto é semelhante a um filho de deuses."}, {"numero": 26, "texto": "Então Nabucodonosor se aproximou da porta da fornalha de fogo ardente, e falou: Sadraque, Mesaque, e Abednego, servos do Deus altíssimo, saí e vinde!Então Sadraque, Mesaque, e Abednego saíram do meio do fogo."}, {"numero": 27, "texto": "E juntaram-se os sátrapas, os prefeitos, os governadores, e os conselheiros do rei, para olharem estes homens, como o fogo não havia causado efeito algum em seus corpos, nem o cabelo de seus cabeças fora queimado, nem suas capas se mudaram, nem cheiro de fogo passara por eles."}, {"numero": 28, "texto": "Nabucodonosor falou: Bendito seja o Deus de Sadraque, Mesaque, e Abednego, que enviou seu anjo, e livrou seus servos, que confiaram nele; pois violaram o mandamento do rei, e entregaram seus corpos para que servissem nem adorassem [algum] outro deus, a não ser o seu Deus."}, {"numero": 29, "texto": "Portanto eu faço um decreto, que todo povo, nação, e língua, que disser blasfêmia contra o Deus de Sadraque, Mesaque, e Abednego, seja despedaçado, e sua casa seja se torne um amontoado de entulhos; pois não há outro deus que possa livrar como este."}, {"numero": 30, "texto": "Então o rei fez com que Sadraque, Mesaque, e Abednego fossem prósperos na província da Babilônia."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 3, 'en', '[{"numero": 1, "texto": "Nebuchadnezzar the king made an image of gold, whose height was threescore cubits, and the breadth thereof six cubits: he set it up in the plain of Dura, in the province of Babylon."}, {"numero": 2, "texto": "Then Nebuchadnezzar the king sent to gather together the princes, the governors, and the captains, the judges, the treasurers, the counsellors, the sheriffs, and all the rulers of the provinces, to come to the dedication of the image which Nebuchadnezzar the king had set up."}, {"numero": 3, "texto": "Then the princes, the governors, and captains, the judges, the treasurers, the counsellors, the sheriffs, and all the rulers of the provinces, were gathered together unto the dedication of the image that Nebuchadnezzar the king had set up; and they stood before the image that Nebuchadnezzar had set up."}, {"numero": 4, "texto": "Then an herald cried aloud, To you it is commanded, O people, nations, and languages,"}, {"numero": 5, "texto": "That at what time ye hear the sound of the cornet, flute, harp, sackbut, psaltery, dulcimer, and all kinds of musick, ye fall down and worship the golden image that Nebuchadnezzar the king hath set up:"}, {"numero": 6, "texto": "And whoso falleth not down and worshippeth shall the same hour be cast into the midst of a burning fiery furnace."}, {"numero": 7, "texto": "Therefore at that time, when all the people heard the sound of the cornet, flute, harp, sackbut, psaltery, and all kinds of musick, all the people, the nations, and the languages, fell down and worshipped the golden image that Nebuchadnezzar the king had set up."}, {"numero": 8, "texto": "Wherefore at that time certain Chaldeans came near, and accused the Jews."}, {"numero": 9, "texto": "They spake and said to the king Nebuchadnezzar, O king, live for ever."}, {"numero": 10, "texto": "Thou, O king, hast made a decree, that every man that shall hear the sound of the cornet, flute, harp, sackbut, psaltery, and dulcimer, and all kinds of musick, shall fall down and worship the golden image:"}, {"numero": 11, "texto": "And whoso falleth not down and worshippeth, that he should be cast into the midst of a burning fiery furnace."}, {"numero": 12, "texto": "There are certain Jews whom thou hast set over the affairs of the province of Babylon, Shadrach, Meshach, and Abednego; these men, O king, have not regarded thee: they serve not thy gods, nor worship the golden image which thou hast set up."}, {"numero": 13, "texto": "Then Nebuchadnezzar in his rage and fury commanded to bring Shadrach, Meshach, and Abednego. Then they brought these men before the king."}, {"numero": 14, "texto": "Nebuchadnezzar spake and said unto them, Is it true, O Shadrach, Meshach, and Abednego, do not ye serve my gods, nor worship the golden image which I have set up?"}, {"numero": 15, "texto": "Now if ye be ready that at what time ye hear the sound of the cornet, flute, harp, sackbut, psaltery, and dulcimer, and all kinds of musick, ye fall down and worship the image which I have made; well: but if ye worship not, ye shall be cast the same hour into the midst of a burning fiery furnace; and who is that God that shall deliver you out of my hands?"}, {"numero": 16, "texto": "Shadrach, Meshach, and Abednego, answered and said to the king, O Nebuchadnezzar, we are not careful to answer thee in this matter."}, {"numero": 17, "texto": "If it be so, our God whom we serve is able to deliver us from the burning fiery furnace, and he will deliver us out of thine hand, O king."}, {"numero": 18, "texto": "But if not, be it known unto thee, O king, that we will not serve thy gods, nor worship the golden image which thou hast set up."}, {"numero": 19, "texto": "Then was Nebuchadnezzar full of fury, and the form of his visage was changed against Shadrach, Meshach, and Abednego: therefore he spake, and commanded that they should heat the furnace one seven times more than it was wont to be heated."}, {"numero": 20, "texto": "And he commanded the most mighty men that were in his army to bind Shadrach, Meshach, and Abednego, and to cast them into the burning fiery furnace."}, {"numero": 21, "texto": "Then these men were bound in their coats, their hosen, and their hats, and their other garments, and were cast into the midst of the burning fiery furnace."}, {"numero": 22, "texto": "Therefore because the king''s commandment was urgent, and the furnace exceeding hot, the flames of the fire slew those men that took up Shadrach, Meshach, and Abednego."}, {"numero": 23, "texto": "And these three men, Shadrach, Meshach, and Abednego, fell down bound into the midst of the burning fiery furnace."}, {"numero": 24, "texto": "Then Nebuchadnezzar the king was astonished, and rose up in haste, and spake, and said unto his counsellors, Did not we cast three men bound into the midst of the fire? They answered and said unto the king, True, O king."}, {"numero": 25, "texto": "He answered and said, Lo, I see four men loose, walking in the midst of the fire, and they have no hurt; and the form of the fourth is like the Son of God."}, {"numero": 26, "texto": "Then Nebuchadnezzar came near to the mouth of the burning fiery furnace, and spake, and said, Shadrach, Meshach, and Abednego, ye servants of the most high God, come forth, and come hither. Then Shadrach, Meshach, and Abednego, came forth of the midst of the fire."}, {"numero": 27, "texto": "And the princes, governors, and captains, and the king''s counsellors, being gathered together, saw these men, upon whose bodies the fire had no power, nor was an hair of their head singed, neither were their coats changed, nor the smell of fire had passed on them."}, {"numero": 28, "texto": "Then Nebuchadnezzar spake, and said, Blessed be the God of Shadrach, Meshach, and Abednego, who hath sent his angel, and delivered his servants that trusted in him, and have changed the king''s word, and yielded their bodies, that they might not serve nor worship any god, except their own God."}, {"numero": 29, "texto": "Therefore I make a decree, That every people, nation, and language, which speak any thing amiss against the God of Shadrach, Meshach, and Abednego, shall be cut in pieces, and their houses shall be made a dunghill: because there is no other God that can deliver after this sort."}, {"numero": 30, "texto": "Then the king promoted Shadrach, Meshach, and Abednego, in the province of Babylon."}]'::jsonb, 'King James Version'),
  ('Dn', 3, 'fr', '[{"numero": 1, "texto": "Le roi Nebucadnetsar fit une statue d''''or, haute de soixante coudées et large de six coudées. Il la dressa dans la vallée de Dura, dans la province de Babylone."}, {"numero": 2, "texto": "Le roi Nebucadnetsar fit convoquer les satrapes, les intendants et les gouverneurs, les grands juges, les trésoriers, les jurisconsultes, les juges, et tous les magistrats des provinces, pour qu''''ils se rendissent à la dédicace de la statue qu''''avait élevée le roi Nebucadnetsar."}, {"numero": 3, "texto": "Alors les satrapes, les intendants et les gouverneurs, les grands juges, les trésoriers, les jurisconsultes, les juges, et tous les magistrats des provinces, s''''assemblèrent pour la dédicace de la statue qu''''avait élevée le roi Nebucadnetsar. Ils se placèrent devant la statue qu''''avait élevée Nebucadnetsar."}, {"numero": 4, "texto": "Un héraut cria à haute voix: Voici ce qu''''on vous ordonne, peuples, nations, hommes de toutes langues!"}, {"numero": 5, "texto": "Au moment où vous entendrez le son de la trompette, du chalumeau, de la guitare, de la sambuque, du psaltérion, de la cornemuse, et de toutes sortes d''''instruments de musique, vous vous prosternerez et vous adorerez la statue d''''or qu''''a élevée le roi Nebucadnetsar."}, {"numero": 6, "texto": "Quiconque ne se prosternera pas et n''''adorera pas sera jeté à l''''instant même au milieu d''''une fournaise ardente."}, {"numero": 7, "texto": "C''''est pourquoi, au moment où tous les peuples entendirent le son de la trompette, du chalumeau, de la guitare, de la sambuque, du psaltérion, et de toutes sortes d''''instruments de musique, tous les peuples, les nations, les hommes de toutes langues se prosternèrent et adorèrent la statue d''''or qu''''avait élevée le roi Nebucadnetsar."}, {"numero": 8, "texto": "A cette occasion, et dans le même temps, quelques Chaldéens s''''approchèrent et accusèrent les Juifs."}, {"numero": 9, "texto": "Ils prirent la parole et dirent au roi Nebucadnetsar: O roi, vis éternellement!"}, {"numero": 10, "texto": "Tu as donné un ordre d''''après lequel tous ceux qui entendraient le son de la trompette, du chalumeau, de la guitare, de la sambuque, du psaltérion, de la cornemuse, et de toutes sortes d''''instruments, devraient se prosterner et adorer la statue d''''or,"}, {"numero": 11, "texto": "et d''''après lequel quiconque ne se prosternerait pas et n''''adorerait pas serait jeté au milieu d''''une fournaise ardente."}, {"numero": 12, "texto": "Or, il y a des Juifs à qui tu as remis l''''intendance de la province de Babylone, Schadrac, Méschac et Abed-Nego, hommes qui ne tiennent aucun compte de toi, ô roi; ils ne servent pas tes dieux, et ils n''''adorent point la statue d''''or que tu as élevée."}, {"numero": 13, "texto": "Alors Nebucadnetsar, irrité et furieux, donna l''''ordre qu''''on amenât Schadrac, Méschac et Abed-Nego. Et ces hommes furent amenés devant le roi."}, {"numero": 14, "texto": "Nebucadnetsar prit la parole et leur dit: Est-ce de propos délibéré, Schadrac, Méschac et Abed-Nego, que vous ne servez pas mes dieux, et que vous n''''adorez pas la statue d''''or que j''''ai élevée?"}, {"numero": 15, "texto": "Maintenant tenez-vous prêts, et au moment où vous entendrez le son de la trompette, du chalumeau, de la guitare, de la sambuque, du psaltérion, de la cornemuse, et de toutes sortes d''''instruments, vous vous prosternerez et vous adorerez la statue que j''''ai faite; si vous ne l''''adorez pas, vous serez jetés à l''''instant même au milieu d''''une fournaise ardente. Et quel est le dieu qui vous délivrera de ma main?"}, {"numero": 16, "texto": "Schadrac, Méschac et Abed-Nego répliquèrent au roi Nebucadnetsar: Nous n''''avons pas besoin de te répondre là-dessus."}, {"numero": 17, "texto": "Voici, notre Dieu que nous servons peut nous délivrer de la fournaise ardente, et il nous délivrera de ta main, ô roi."}, {"numero": 18, "texto": "Sinon, sache, ô roi, que nous ne servirons pas tes dieux, et que nous n''''adorerons pas la statue d''''or que tu as élevée."}, {"numero": 19, "texto": "Sur quoi Nebucadnetsar fut rempli de fureur, et il changea de visage en tournant ses regards contre Schadrac, Méschac et Abed-Nego. Il reprit la parole et ordonna de chauffer la fournaise sept fois plus qu''''il ne convenait de la chauffer."}, {"numero": 20, "texto": "Puis il commanda à quelques-uns des plus vigoureux soldats de son armée de lier Schadrac, Méschac et Abed-Nego, et de les jeter dans la fournaise ardente."}, {"numero": 21, "texto": "Ces hommes furent liés avec leurs caleçons, leurs tuniques, leurs manteaux et leurs autres vêtements, et jetés au milieu de la fournaise ardente."}, {"numero": 22, "texto": "Comme l''''ordre du roi était sévère, et que la fournaise était extraordinairement chauffée, la flamme tua les hommes qui y avaient jeté Schadrac, Méschac et Abed-Nego."}, {"numero": 23, "texto": "Et ces trois hommes, Schadrac, Méschac et Abed-Nego, tombèrent liés au milieu de la fournaise ardente."}, {"numero": 24, "texto": "Alors le roi Nebucadnetsar fut effrayé, et se leva précipitamment. Il prit la parole, et dit à ses conseillers: N''''avons-nous pas jeté au milieu du feu trois hommes liés? Ils répondirent au roi: Certainement, ô roi!"}, {"numero": 25, "texto": "Il reprit et dit: Eh bien, je vois quatre hommes sans liens, qui marchent au milieu du feu, et qui n''''ont point de mal; et la figure du quatrième ressemble à celle d''''un fils des dieux."}, {"numero": 26, "texto": "Ensuite Nebucadnetsar s''''approcha de l''''entrée de la fournaise ardente, et prenant la parole, il dit: Schadrac, Méschac et Abed-Nego, serviteurs du Dieu suprême, sortez et venez! Et Schadrac, Méschac et Abed-Nego sortirent du milieu du feu."}, {"numero": 27, "texto": "Les satrapes, les intendants, les gouverneurs, et les conseillers du roi s''''assemblèrent; ils virent que le feu n''''avait eu aucun pouvoir sur le corps de ces hommes, que les cheveux de leur tête n''''avaient pas été brûlés, que leurs caleçons n''''étaient point endommagés, et que l''''odeur du feu ne les avait pas atteints."}, {"numero": 28, "texto": "Nebucadnetsar prit la parole et dit: Béni soit le Dieu de Schadrac, de Méschac et d''''Abed-Nego, lequel a envoyé son ange et délivré ses serviteurs qui ont eu confiance en lui, et qui ont violé l''''ordre du roi et livré leurs corps plutôt que de servir et d''''adorer aucun autre dieu que leur Dieu!"}, {"numero": 29, "texto": "Voici maintenant l''''ordre que je donne: tout homme, à quelque peuple, nation ou langue qu''''il appartienne, qui parlera mal du Dieu de Schadrac, de Méschac et d''''Abed-Nego, sera mis en pièces, et sa maison sera réduite en un tas d''''immondices, parce qu''''il n''''y a aucun autre dieu qui puisse délivrer comme lui."}, {"numero": 30, "texto": "Après cela, le roi fit prospérer Schadrac, Méschac et Abed-Nego, dans la province de Babylone."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 3, 'es', '[{"numero": 1, "texto": "EL rey Nabucodonosor hizo una estatua de oro, la altura de la cual era de sesenta codos, su anchura de seis codos: levantóla en el campo de Dura, en la provincia de Babilonia."}, {"numero": 2, "texto": "Y envió el rey Nabucodonosor á juntar los grandes, los asistentes y capitanes, oidores, receptores, los del consejo, presidentes, y á todos los gobernadores de las provincias, para que viniesen á la dedicación de la estatua que el rey Nabucodonosor había levantado."}, {"numero": 3, "texto": "Fueron pues reunidos los grandes, los asistentes y capitanes, los oidores, receptores, los del consejo, los presidentes, y todos los gobernadores de las provincias, á la dedicación de la estatua que el rey Nabucodonosor había levantado: y estaban en pie delante de la estatua que había levantado el rey Nabucodonosor."}, {"numero": 4, "texto": "Y el pregonero pregonaba en alta voz: Mándase á vosotros, oh pueblos, naciones, y lenguas,"}, {"numero": 5, "texto": "En oyendo el son de la bocina, del pífano, del tamboril, del arpa, del salterio, de la zampoña, y de todo instrumento músico, os postraréis y adoraréis la estatua de oro que el rey Nabucodonosor ha levantado:"}, {"numero": 6, "texto": "Y cualquiera que no se postrare y adorare, en la misma hora será echado dentro de un horno de fuego ardiendo."}, {"numero": 7, "texto": "Por lo cual, en oyendo todos los pueblos el son de la bocina, del pífano, del tamboril, del arpa, del salterio, de la zampoña, y de todo instrumento músico, todos los pueblos, naciones, y lenguas, se postraron, y adoraron la estatua de oro que el rey Nabucodonosor había levantado."}, {"numero": 8, "texto": "Por esto en el mismo tiempo algunos varones Caldeos se llegaron, y denunciaron de los Judíos,"}, {"numero": 9, "texto": "Hablando y diciendo al rey Nabucodonosor: Rey, para siempre vive."}, {"numero": 10, "texto": "Tú, oh rey, pusiste ley que todo hombre en oyendo el son de la bocina, del pífano, del tamboril, del arpa, del salterio, de la zampoña, y de todo instrumento músico, se postrase y adorase la estatua de oro:"}, {"numero": 11, "texto": "Y el que no se postrase y adorase, fuese echado dentro de un horno de fuego ardiendo."}, {"numero": 12, "texto": "Hay unos varones Judíos, los cuales pusiste tú sobre los negocios de la provincia de Babilonia; Sadrach, Mesach, y Abed-nego: estos varones, oh rey, no han hecho cuenta de ti; no adoran tus dioses, no adoran la estatua de oro que tú levantaste."}, {"numero": 13, "texto": "Entonces Nabucodonosor dijo con ira y con enojo que trajesen á Sadrach, Mesach, y Abed-nego. Al punto fueron traídos estos varones delante del rey."}, {"numero": 14, "texto": "Habló Nabucodonosor, y díjoles: ¿Es verdad Sadrach, Mesach, y Abed-nego, que vosotros no honráis á mi dios, ni adoráis la estatua de oro que he levantado?"}, {"numero": 15, "texto": "Ahora pues, ¿estáis prestos para que en oyendo el son de la bocina, del pífano, del tamboril, del arpa, del salterio, de la zampoña, y de todo instrumento músico, os postréis, y adoréis la estatua que he hecho? Porque si no la adorareis, en la misma hora seréis echados en medio de un horno de fuego ardiendo: ¿y qué dios será aquel que os libre de mis manos?"}, {"numero": 16, "texto": "Sadrach, Mesach, y Abed-nego respondieron y dijeron al rey Nabucodonosor: No cuidamos de responderte sobre este negocio."}, {"numero": 17, "texto": "He aquí nuestro Dios á quien honramos, puede librarnos del horno de fuego ardiendo; y de tu mano, oh rey, nos librará."}, {"numero": 18, "texto": "Y si no, sepas, oh rey, que tu dios no adoraremos, ni tampoco honraremos la estatua que has levantado."}, {"numero": 19, "texto": "Entonces Nabucodonosor fué lleno de ira, y demudóse la figura de su rostro sobre Sadrach, Mesach, y Abed-nego: así habló, y ordenó que el horno se encendiese siete veces tanto de lo que cada vez solía."}, {"numero": 20, "texto": "Y mandó á hombres muy vigorosos que tenía en su ejército, que atasen á Sadrach, Mesach, y Abed-nego, para echarlos en el horno de fuego ardiendo."}, {"numero": 21, "texto": "Entonces estos varones fueron atados con sus mantos, y sus calzas, y sus turbantes, y sus vestidos, y fueron echados dentro del horno de fuego ardiendo."}, {"numero": 22, "texto": "Y porque la palabra del rey daba priesa, y había procurado que se encendiese mucho, la llama del fuego mató á aquellos que habían alzado á Sadrach, Mesach, y Abed-nego."}, {"numero": 23, "texto": "Y estos tres varones, Sadrach, Mesach, y Abed-nego, cayeron atados dentro del horno de fuego ardiendo."}, {"numero": 24, "texto": "Entonces el rey Nabucodonosor se espantó, y levantóse apriesa, y habló, y dijo á los de su consejo: ¿No echaron tres varones atados dentro del fuego? Ellos respondieron y dijeron al rey: Es verdad, oh rey."}, {"numero": 25, "texto": "Respondió él y dijo: He aquí que yo veo cuatro varones sueltos, que se pasean en medio del fuego, y ningún daño hay en ellos: y el parecer del cuarto es semejante á hijo de los dioses."}, {"numero": 26, "texto": "Entonces Nabucodonosor se acercó á la puerta del horno de fuego ardiendo, y habló y dijo: Sadrach, Mesach, y Abed-nego, siervos del alto Dios, salid y venid. Entonces Sadrach, Mesach, y Abed-nego, salieron de en medio del fuego."}, {"numero": 27, "texto": "Y juntáronse los grandes, los gobernadores, los capitanes, y los del consejo del rey, para mirar estos varones, como el fuego no se enseñoreó de sus cuerpos, ni cabello de sus cabezas fué quemado, ni sus ropas se mudaron, ni olor de fuego había pasado por ellos."}, {"numero": 28, "texto": "Nabucodonosor habló y dijo: Bendito el Dios de ellos, de Sadrach, Mesach, y Abed-nego, que envió su ángel, y libró sus siervos que esperaron en él, y el mandamiento del rey mudaron, y entregaron sus cuerpos antes que sirviesen ni adorasen otro dios que su Dios."}, {"numero": 29, "texto": "Por mí pues se pone decreto, que todo pueblo, nación, ó lengua, que dijere blasfemia contra el Dios de Sadrach, Mesach, y Abed-nego, sea descuartizado, y su casa sea puesta por muladar; por cuanto no hay dios que pueda librar como éste."}, {"numero": 30, "texto": "Entonces el rey engrandeció á Sadrach, Mesach, y Abed-nego en la provincia de Babilonia."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 4, 'pt', '[{"numero": 1, "texto": "O rei Nabucodonosor, a todos os povos, nações, e línguas, que moram em toda a terra: paz vos seja multiplicada;"}, {"numero": 2, "texto": "Pareceu-me bem fazer conhecidos os sinais e maravilhas que o Deus altíssimo fez comigo."}, {"numero": 3, "texto": "Como são grandes os seus sinais, e como são poderosas as suas maravilhas! O reino dele é um reino eterno, e seu domínio de geração em geração."}, {"numero": 4, "texto": "Eu, Nabucodonosor, estava tranquilo em minha casa, e próspero em meu palácio."}, {"numero": 5, "texto": "Eu vi um sonho que me espantou; e as imaginações em minha cama e as visões da minha cabeça me perturbaram."}, {"numero": 6, "texto": "Por isso eu fiz um decreto para que trouxessem diante de mim todos os sábios da Babilônia, para que me fizessem saber a interpretação do sonho."}, {"numero": 7, "texto": "Então vieram magos, astrólogos, caldeus, e adivinhos; e eu disse o sonho diante deles, mas não conseguiram me mostrar sua interpretação."}, {"numero": 8, "texto": "Porém por fim veio diante de mim Daniel, cujo nome é Beltessazar, segundo o nome de meu deus; e em [Daniel] há o espírito dos deuses santos. Então eu disse o sonho diante dele:"}, {"numero": 9, "texto": "Beltessazar, príncipe dos magos, de quem eu sei que há em ti espírito dos deuses santos, e que nenhum mistério é difícil para ti, dize-me as visões de meu sonho que eu vi, e sua interpretação."}, {"numero": 10, "texto": "Estas foram as visões de minha cabeça em minha cama: eu estava vendo, e eis uma árvore grande em altura, no meio da terra."}, {"numero": 11, "texto": "Esta árvore crescia, e se fortalecia; sua altura chegava até o céu, e podia ser vista até dos confins de toda a terra."}, {"numero": 12, "texto": "Sua folhagem era bela, seu fruto abundante, e havia nela alimento para todos. Debaixo dela os animais do campo achavam sombra, em seus ramos as aves do céu faziam morada, e todos os seres se alimentavam dela."}, {"numero": 13, "texto": "Eu estava vendo nas visões de minha cabeça em minha cama, e eis que um vigilante e santo descia do céu."}, {"numero": 14, "texto": "Ele gritava fortemente e dizia assim: Cortai a árvore, e podai seus ramos; derrubai sua folhagem, e dispersai seu fruto; fujam os animais debaixo dela, e as aves de seus ramos."}, {"numero": 15, "texto": "Porém deixai o tronco [com] suas raízes na terra, e com correntes de ferro e de bronze na erva do campo; e seja molhado com o orvalho do céu, e sua parte seja com os animais na grama da terra."}, {"numero": 16, "texto": "Seu coração seja mudado, para que não seja coração de homem, e seja-lhe dado um coração de animal; e passem sobre ele sete tempos."}, {"numero": 17, "texto": "Esta sentença é por decreto dos vigilantes, esta exigência pela palavra dos santos; para que os viventes saibam que o Altíssimo tem o domínio dos reinos humanos, e ele os dá a quem ele quer, e constitui sobre eles até o mais inferior dos seres humanos."}, {"numero": 18, "texto": "Este foi o sonho que eu, o rei Nabucodonosor, vi. Tu, pois, Beltessazar, dize a interpretação, porque todos os sábios do meu reino não puderam me revelar sua interpretação; mas tu podes, porque há em ti o espírito dos deuses santos."}, {"numero": 19, "texto": "Então Daniel, cujo nome era Beltessazar, ficou atônito por um certo tempo, e seus pensamentos o espantavam. O rei falou: Beltessazar, não fiques espantado com o sonho nem com sua interpretação. Beltessazar respondeu: Meu senhor, que o sonho seja para os que te odeiam, e sua interpretação para teus inimigos."}, {"numero": 20, "texto": "A árvore que viste, que crescera e se fizera forte, cuja altura chegava até o céu, e podia ser vista por toda a terra,"}, {"numero": 21, "texto": "Cuja folhagem era formosa, seu fruto abundante, e em que havia alimento para todos; debaixo da qual moravam os animais do campo, e em seus ramos habitavam as aves do céu,"}, {"numero": 22, "texto": "Ela és tu, ó rei, que cresceste, e te fizeste forte; pois tua grandeza cresceu, e chegou até o céu; e teu domínio até o fim da terra."}, {"numero": 23, "texto": "E quanto ao que o rei viu, um vigilante e santo que descia do céu, e dizia: Cortai a árvore e destruí-a; mas o tronco [com] suas raízes deixai na terra, com correntes de ferro e de bronze na erva do campo; e seja molhado do orvalho do céu, e sua parte seja com os animais do campo, até que passem sobre ele sete tempos,"}, {"numero": 24, "texto": "Esta é a interpretação, ó rei; esta é a sentença do Altíssimo, que virá sobre o rei, meu senhor:"}, {"numero": 25, "texto": "Expulsar-te-ão dentre os homens, e tua morada será com os animais do campo; serás alimentado com erva como aos bois, e serás molhado com orvalho do céu; e sete tempos passarão sobre ti, até que entendas que o Altíssimo tem o domínio sobre os reinos humanos, e ele os dá a quem ele quer."}, {"numero": 26, "texto": "E quanto ao que foi dito, que deixassem o tronco [com] das raízes da árvore, significa que teu reino se te será restabelecido, depois que tiveres entendido que o céu reina."}, {"numero": 27, "texto": "Portanto, ó rei, aceita meu conselho, e desfaze teus pecados por meio da justiça, e tuas maldades por meio da misericórdia para com os pobres; para que talvez haja uma prolongamento de tua paz."}, {"numero": 28, "texto": "Tudo isso veio sobre o rei Nabucodonosor;"}, {"numero": 29, "texto": "[Pois] ao fim de doze meses, enquanto passeava sobre o palácio real da Babilônia,"}, {"numero": 30, "texto": "O rei falou: Não é esta a grande Babilônia, que eu edifiquei para ser a capital do reino, com a força de meu poder, e para a glória de minha majestade?"}, {"numero": 31, "texto": "Enquanto a palavra ainda estava na boca do rei, uma voz caiu do céu: A ti se diz, ó rei Nabucodonosor: perdeste o teu reino,"}, {"numero": 32, "texto": "E te expulsarão dentre os homens. Tua morada será com os animais do campo, e com erva serás alimentado, como os bois; e sete tempos passarão sobre ti, até que entendas que o Altíssimo tem o domínio dos reinos dos homens, e ele os dá a quem ele quer."}, {"numero": 33, "texto": "Na mesma hora a palavra se cumpriu sobre Nabucodonosor, e foi lançado dentre os homens. Ele passou a comer erva como os bois, e seu corpo foi molhado com o orvalho do céu, até que seu pelo cresceu como [as penas] da águia, e suas unhas como [as garras] das aves."}, {"numero": 34, "texto": "Mas ao fim daqueles dias, eu, Nabucodonosor levantei meus olhos ao céu, e meu entendimento voltou a mim; então eu bendisse ao Altíssimo, e louvei e glorifiquei ao que vive para sempre, cujo domínio é eterno, e seu reino de geração em geração."}, {"numero": 35, "texto": "E todos os moradores da terra são contados como nada; e ele faz no exército do céu, e nos habitantes da terra segundo sua vontade; ninguém há que possa deter sua mão, e lhe dizer: Que fazes?"}, {"numero": 36, "texto": "No mesmo tempo meu entendimento voltou a mim, e a dignidade do meu reino, minha majestade e meu resplendor voltaram a mim; e meus conselheiros e meus grandes me buscaram; e eu fui restabelecido em meu reino, e maior glória me foi acrescentada."}, {"numero": 37, "texto": "Agora eu, Nabucodonosor louvo, exalto e glorifico ao Rei do céu, porque todas as suas obras são verdade, e seus caminhos juízo; e ele pode humilhar aos que andam com arrogância."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 4, 'en', '[{"numero": 1, "texto": "Nebuchadnezzar the king, unto all people, nations, and languages, that dwell in all the earth; Peace be multiplied unto you."}, {"numero": 2, "texto": "I thought it good to shew the signs and wonders that the high God hath wrought toward me."}, {"numero": 3, "texto": "How great are his signs! and how mighty are his wonders! his kingdom is an everlasting kingdom, and his dominion is from generation to generation."}, {"numero": 4, "texto": "I Nebuchadnezzar was at rest in mine house, and flourishing in my palace:"}, {"numero": 5, "texto": "I saw a dream which made me afraid, and the thoughts upon my bed and the visions of my head troubled me."}, {"numero": 6, "texto": "Therefore made I a decree to bring in all the wise men of Babylon before me, that they might make known unto me the interpretation of the dream."}, {"numero": 7, "texto": "Then came in the magicians, the astrologers, the Chaldeans, and the soothsayers: and I told the dream before them; but they did not make known unto me the interpretation thereof."}, {"numero": 8, "texto": "But at the last Daniel came in before me, whose name was Belteshazzar, according to the name of my God, and in whom is the spirit of the holy gods: and before him I told the dream, saying,"}, {"numero": 9, "texto": "O Belteshazzar, master of the magicians, because I know that the spirit of the holy gods is in thee, and no secret troubleth thee, tell me the visions of my dream that I have seen, and the interpretation thereof."}, {"numero": 10, "texto": "Thus were the visions of mine head in my bed; I saw, and behold a tree in the midst of the earth, and the height thereof was great."}, {"numero": 11, "texto": "The tree grew, and was strong, and the height thereof reached unto heaven, and the sight thereof to the end of all the earth:"}, {"numero": 12, "texto": "The leaves thereof were fair, and the fruit thereof much, and in it was meat for all: the beasts of the field had shadow under it, and the fowls of the heaven dwelt in the boughs thereof, and all flesh was fed of it."}, {"numero": 13, "texto": "I saw in the visions of my head upon my bed, and, behold, a watcher and an holy one came down from heaven;"}, {"numero": 14, "texto": "He cried aloud, and said thus, Hew down the tree, and cut off his branches, shake off his leaves, and scatter his fruit: let the beasts get away from under it, and the fowls from his branches:"}, {"numero": 15, "texto": "Nevertheless leave the stump of his roots in the earth, even with a band of iron and brass, in the tender grass of the field; and let it be wet with the dew of heaven, and let his portion be with the beasts in the grass of the earth:"}, {"numero": 16, "texto": "Let his heart be changed from man''s, and let a beast''s heart be given unto him; and let seven times pass over him."}, {"numero": 17, "texto": "This matter is by the decree of the watchers, and the demand by the word of the holy ones: to the intent that the living may know that the most High ruleth in the kingdom of men, and giveth it to whomsoever he will, and setteth up over it the basest of men."}, {"numero": 18, "texto": "This dream I king Nebuchadnezzar have seen. Now thou, O Belteshazzar, declare the interpretation thereof, forasmuch as all the wise men of my kingdom are not able to make known unto me the interpretation: but thou art able; for the spirit of the holy gods is in thee."}, {"numero": 19, "texto": "Then Daniel, whose name was Belteshazzar, was astonied for one hour, and his thoughts troubled him. The king spake, and said, Belteshazzar, let not the dream, or the interpretation thereof, trouble thee. Belteshazzar answered and said, My lord, the dream be to them that hate thee, and the interpretation thereof to thine enemies."}, {"numero": 20, "texto": "The tree that thou sawest, which grew, and was strong, whose height reached unto the heaven, and the sight thereof to all the earth;"}, {"numero": 21, "texto": "Whose leaves were fair, and the fruit thereof much, and in it was meat for all; under which the beasts of the field dwelt, and upon whose branches the fowls of the heaven had their habitation:"}, {"numero": 22, "texto": "It is thou, O king, that art grown and become strong: for thy greatness is grown, and reacheth unto heaven, and thy dominion to the end of the earth."}, {"numero": 23, "texto": "And whereas the king saw a watcher and an holy one coming down from heaven, and saying, Hew the tree down, and destroy it; yet leave the stump of the roots thereof in the earth, even with a band of iron and brass, in the tender grass of the field; and let it be wet with the dew of heaven, and let his portion be with the beasts of the field, till seven times pass over him;"}, {"numero": 24, "texto": "This is the interpretation, O king, and this is the decree of the most High, which is come upon my lord the king:"}, {"numero": 25, "texto": "That they shall drive thee from men, and thy dwelling shall be with the beasts of the field, and they shall make thee to eat grass as oxen, and they shall wet thee with the dew of heaven, and seven times shall pass over thee, till thou know that the most High ruleth in the kingdom of men, and giveth it to whomsoever he will."}, {"numero": 26, "texto": "And whereas they commanded to leave the stump of the tree roots; thy kingdom shall be sure unto thee, after that thou shalt have known that the heavens do rule."}, {"numero": 27, "texto": "Wherefore, O king, let my counsel be acceptable unto thee, and break off thy sins by righteousness, and thine iniquities by shewing mercy to the poor; if it may be a lengthening of thy tranquillity."}, {"numero": 28, "texto": "All this came upon the king Nebuchadnezzar."}, {"numero": 29, "texto": "At the end of twelve months he walked in the palace of the kingdom of Babylon."}, {"numero": 30, "texto": "The king spake, and said, Is not this great Babylon, that I have built for the house of the kingdom by the might of my power, and for the honour of my majesty?"}, {"numero": 31, "texto": "While the word was in the king''s mouth, there fell a voice from heaven, saying, O king Nebuchadnezzar, to thee it is spoken; The kingdom is departed from thee."}, {"numero": 32, "texto": "And they shall drive thee from men, and thy dwelling shall be with the beasts of the field: they shall make thee to eat grass as oxen, and seven times shall pass over thee, until thou know that the most High ruleth in the kingdom of men, and giveth it to whomsoever he will."}, {"numero": 33, "texto": "The same hour was the thing fulfilled upon Nebuchadnezzar: and he was driven from men, and did eat grass as oxen, and his body was wet with the dew of heaven, till his hairs were grown like eagles'' feathers, and his nails like birds'' claws."}, {"numero": 34, "texto": "And at the end of the days I Nebuchadnezzar lifted up mine eyes unto heaven, and mine understanding returned unto me, and I blessed the most High, and I praised and honoured him that liveth for ever, whose dominion is an everlasting dominion, and his kingdom is from generation to generation:"}, {"numero": 35, "texto": "And all the inhabitants of the earth are reputed as nothing: and he doeth according to his will in the army of heaven, and among the inhabitants of the earth: and none can stay his hand, or say unto him, What doest thou?"}, {"numero": 36, "texto": "At the same time my reason returned unto me; and for the glory of my kingdom, mine honour and brightness returned unto me; and my counsellors and my lords sought unto me; and I was established in my kingdom, and excellent majesty was added unto me."}, {"numero": 37, "texto": "Now I Nebuchadnezzar praise and extol and honour the King of heaven, all whose works are truth, and his ways judgment: and those that walk in pride he is able to abase."}]'::jsonb, 'King James Version'),
  ('Dn', 4, 'fr', '[{"numero": 1, "texto": "Nebucadnetsar, roi, à tous les peuples, aux nations, aux hommes de toutes langues, qui habitent sur toute la terre. Que la paix vous soit donnée avec abondance!"}, {"numero": 2, "texto": "Il m''''a semblé bon de faire connaître les signes et les prodiges que le Dieu suprême a opérés à mon égard."}, {"numero": 3, "texto": "Que ses signes sont grands! que ses prodiges sont puissants! Son règne est un règne éternel, et sa domination subsiste de génération en génération."}, {"numero": 4, "texto": "Moi, Nebucadnetsar, je vivais tranquille dans ma maison, et heureux dans mon palais."}, {"numero": 5, "texto": "J''''ai eu un songe qui m''''a effrayé; les pensées dont j''''étais poursuivi sur ma couche et les visions de mon esprit me remplissaient d''''épouvante."}, {"numero": 6, "texto": "J''''ordonnai qu''''on fît venir devant moi tous les sages de Babylone, afin qu''''ils me donnassent l''''explication du songe."}, {"numero": 7, "texto": "Alors vinrent les magiciens, les astrologues, les Chaldéens et les devins. Je leur dis le songe, et ils ne m''''en donnèrent point l''''explication."}, {"numero": 8, "texto": "En dernier lieu, se présenta devant moi Daniel, nommé Beltschatsar d''''après le nom de mon dieu, et qui a en lui l''''esprit des dieux saints. Je lui dis le songe:"}, {"numero": 9, "texto": "Beltschatsar, chef des magiciens, qui as en toi, je le sais, l''''esprit des dieux saints, et pour qui aucun secret n''''est difficile, donne-moi l''''explication des visions que j''''ai eues en songe."}, {"numero": 10, "texto": "Voici les visions de mon esprit, pendant que j''''étais sur ma couche. Je regardais, et voici, il y avait au milieu de la terre un arbre d''''une grande hauteur."}, {"numero": 11, "texto": "Cet arbre était devenu grand et fort, sa cime s''''élevait jusqu''''aux cieux, et on le voyait des extrémités de toute la terre."}, {"numero": 12, "texto": "Son feuillage était beau, et ses fruits abondants; il portait de la nourriture pour tous; les bêtes des champs s''''abritaient sous son ombre, les oiseaux du ciel faisaient leur demeure parmi ses branches, et tout être vivant tirait de lui sa nourriture."}, {"numero": 13, "texto": "Dans les visions de mon esprit, que j''''avais sur ma couche, je regardais, et voici, un de ceux qui veillent et qui sont saints descendit des cieux."}, {"numero": 14, "texto": "Il cria avec force et parla ainsi: Abattez l''''arbre, et coupez ses branches; secouez le feuillage, et dispersez les fruits; que les bêtes fuient de dessous, et les oiseaux du milieu de ses branches!"}, {"numero": 15, "texto": "Mais laissez en terre le tronc où se trouvent les racines, et liez-le avec des chaînes de fer et d''''airain, parmi l''''herbe des champs. Qu''''il soit trempé de la rosée du ciel, et qu''''il ait, comme les bêtes, l''''herbe de la terre pour partage."}, {"numero": 16, "texto": "Son coeur d''''homme lui sera ôté, et un coeur de bête lui sera donné; et sept temps passeront sur lui."}, {"numero": 17, "texto": "Cette sentence est un décret de ceux qui veillent, cette résolution est un ordre des saints, afin que les vivants sachent que le Très-Haut domine sur le règne des hommes, qu''''il le donne à qui il lui plaît, et qu''''il y élève le plus vil des hommes."}, {"numero": 18, "texto": "Voilà le songe que j''''ai eu, moi, le roi Nebucadnetsar. Toi, Beltschatsar, donnes-en l''''explication, puisque tous les sages de mon royaume ne peuvent me la donner; toi, tu le peux, car tu as en toi l''''esprit des dieux saints."}, {"numero": 19, "texto": "Alors Daniel, nommé Beltschatsar, fut un moment stupéfait, et ses pensées le troublaient. Le roi reprit et dit: Beltschatsar, que le songe et l''''explication ne te troublent pas! Et Beltschatsar répondit: Mon seigneur, que le songe soit pour tes ennemis, et son explication pour tes adversaires!"}, {"numero": 20, "texto": "L''''arbre que tu as vu, qui était devenu grand et fort, dont la cime s''''élevait jusqu''''aux cieux, et qu''''on voyait de tous les points de la terre;"}, {"numero": 21, "texto": "cet arbre, dont le feuillage était beau et les fruits abondants, qui portait de la nourriture pour tous, sous lequel s''''abritaient les bêtes des champs, et parmi les branches duquel les oiseaux du ciel faisaient leur demeure,"}, {"numero": 22, "texto": "c''''est toi, ô roi, qui es devenu grand et fort, dont la grandeur s''''est accrue et s''''est élevée jusqu''''aux cieux, et dont la domination s''''étend jusqu''''aux extrémités de la terre."}, {"numero": 23, "texto": "Le roi a vu l''''un de ceux qui veillent et qui sont saints descendre des cieux et dire: Abattez l''''arbre, et détruisez-le; mais laissez en terre le tronc où se trouvent les racines, et liez-le avec des chaînes de fer et d''''airain, parmi l''''herbe des champs; qu''''il soit trempé de la rosée du ciel, et que son partage soit avec les bêtes des champs, jusqu''''à ce que sept temps soient passés sur lui."}, {"numero": 24, "texto": "Voici l''''explication, ô roi, voici le décret du Très-Haut, qui s''''accomplira sur mon seigneur le roi."}, {"numero": 25, "texto": "On te chassera du milieu des hommes, tu auras ta demeure avec les bêtes des champs, et l''''on te donnera comme aux boeufs de l''''herbe à manger; tu seras trempé de la rosée du ciel, et sept temps passeront sur toi, jusqu''''à ce que tu saches que le Très-Haut domine sur le règne des hommes et qu''''il le donne à qui il lui plaît."}, {"numero": 26, "texto": "L''''ordre de laisser le tronc où se trouvent les racines de l''''arbre signifie que ton royaume te restera quand tu reconnaîtras que celui qui domine est dans les cieux."}, {"numero": 27, "texto": "C''''est pourquoi, ô roi, puisse mon conseil te plaire! mets un terme à tes péchés en pratiquant la justice, et à tes iniquités en usant de compassion envers les malheureux, et ton bonheur pourra se prolonger."}, {"numero": 28, "texto": "Toutes ces choses se sont accomplies sur le roi Nebucadnetsar."}, {"numero": 29, "texto": "Au bout de douze mois, comme il se promenait dans le palais royal à Babylone,"}, {"numero": 30, "texto": "le roi prit la parole et dit: N''''est-ce pas ici Babylone la grande, que j''''ai bâtie, comme résidence royale, par la puissance de ma force et pour la gloire de ma magnificence?"}, {"numero": 31, "texto": "La parole était encore dans la bouche du roi, qu''''une voix descendit du ciel: Apprends, roi Nebucadnetsar, qu''''on va t''''enlever le royaume."}, {"numero": 32, "texto": "On te chassera du milieu des hommes, tu auras ta demeure avec les bêtes des champs, on te donnera comme aux boeufs de l''''herbe à manger; et sept temps passeront sur toi, jusqu''''à ce que tu saches que le Très-Haut domine sur le règne des hommes et qu''''il le donne à qui il lui plaît."}, {"numero": 33, "texto": "Au même instant la parole s''''accomplit sur Nebucadnetsar. Il fut chassé du milieu des hommes, il mangea de l''''herbe comme les boeufs, son corps fut trempé de la rosée du ciel; jusqu''''à ce que ses cheveux crussent comme les plumes des aigles, et ses ongles comme ceux des oiseaux."}, {"numero": 34, "texto": "Après le temps marqué, moi, Nebucadnetsar, je levai les yeux vers le ciel, et la raison me revint. J''''ai béni le Très-Haut, j''''ai loué et glorifié celui qui vit éternellement, celui dont la domination est une domination éternelle, et dont le règne subsiste de génération en génération."}, {"numero": 35, "texto": "Tous les habitants de la terre ne sont à ses yeux que néant: il agit comme il lui plaît avec l''''armée des cieux et avec les habitants de la terre, et il n''''y a personne qui résiste à sa main et qui lui dise: Que fais-tu?"}, {"numero": 36, "texto": "En ce temps, la raison me revint; la gloire de mon royaume, ma magnificence et ma splendeur me furent rendues; mes conseillers et mes grands me redemandèrent; je fus rétabli dans mon royaume, et ma puissance ne fit que s''''accroître."}, {"numero": 37, "texto": "Maintenant, moi, Nebucadnetsar, je loue, j''''exalte et je glorifie le roi des cieux, dont toutes les oeuvres sont vraies et les voies justes, et qui peut abaisser ceux qui marchent avec orgueil."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 4, 'es', '[{"numero": 1, "texto": "NABUCODONOSOR rey, á todos los pueblos, naciones, y lenguas, que moran en toda la tierra: Paz os sea multiplicada:"}, {"numero": 2, "texto": "Las señales y milagros que el alto Dios ha hecho conmigo, conviene que yo las publique."}, {"numero": 3, "texto": "¡Cuán grandes son sus señales, y cuán potentes sus maravillas! Su reino, reino sempiterno, y su señorío hasta generación y generación."}, {"numero": 4, "texto": "Yo Nabucodonosor estaba quieto en mi casa, y floreciente en mi palacio."}, {"numero": 5, "texto": "Vi un sueño que me espantó, y las imaginaciones y visiones de mi cabeza me turbaron en mi cama."}, {"numero": 6, "texto": "Por lo cual yo puse mandamiento para hacer venir delante de mí todos los sabios de Babilonia, que me mostrasen la declaración del sueño."}, {"numero": 7, "texto": "Y vinieron magos, astrólogos, Caldeos, y adivinos: y dije el sueño delante de ellos, mas nunca me mostraron su declaración;"}, {"numero": 8, "texto": "Hasta tanto que entró delante de mí Daniel, cuyo nombre es Beltsasar, como el nombre de mi dios, y en el cual hay espíritu de los dioses santos, y dije el sueño delante de él, diciendo:"}, {"numero": 9, "texto": "Beltsasar, príncipe de los magos, ya que he entendido que hay en ti espíritu de los dioses santos, y que ningún misterio se te esconde, exprésame las visiones de mi sueño que he visto, y su declaración."}, {"numero": 10, "texto": "Aquestas las visiones de mi cabeza en mi cama: Parecíame que veía un árbol en medio de la tierra, cuya altura era grande."}, {"numero": 11, "texto": "Crecía este árbol, y hacíase fuerte, y su altura llegaba hasta el cielo, y su vista hasta el cabo de toda la tierra."}, {"numero": 12, "texto": "Su copa era hermosa, y su fruto en abundancia, y para todos había en él mantenimiento. Debajo de él se ponían á la sombra las bestias del campo, y en sus ramas hacían morada las aves del cielo, y manteníase de él toda carne."}, {"numero": 13, "texto": "Veía en las visiones de mi cabeza en mi cama, y he aquí que un vigilante y santo descendía del cielo."}, {"numero": 14, "texto": "Y clamaba fuertemente y decía así: Cortad el árbol, y desmochad sus ramas, derribad su copa, y derramad su fruto: váyanse las bestias que están debajo de él, y las aves de sus ramas."}, {"numero": 15, "texto": "Mas la cepa de sus raíces dejaréis en la tierra, y con atadura de hierro y de metal entre la hierba del campo; y sea mojado con el rocío del cielo, y su parte con las bestias en la hierba de la tierra."}, {"numero": 16, "texto": "Su corazón sea mudado de corazón de hombre, y séale dado corazón de bestia, y pasen sobre él siete tiempos."}, {"numero": 17, "texto": "La sentencia es por decreto de los vigilantes, y por dicho de los santos la demanda: para que conozcan los vivientes que el Altísimo se enseñorea del reino de los hombres, y que á quien él quiere lo da, y constituye sobre él al más bajo de los hombres."}, {"numero": 18, "texto": "Yo el rey Nabucodonosor he visto este sueño. Tú pues, Beltsasar, dirás la declaración de él, porque todos los sabios de mi reino nunca pudieron mostrarme su interpretación: mas tú puedes, porque hay en ti espíritu de los dioses santos."}, {"numero": 19, "texto": "Entonces Daniel, cuyo nombre era Beltsasar, estuvo callando casi una hora, y sus pensamientos lo espantaban: El rey habló, y dijo: Beltsasar, el sueño ni su declaración no te espante. Respondió Beltsasar, y dijo: Señor mío, el sueño sea para tus enemigos, y su declaración para los que mal te quieren."}, {"numero": 20, "texto": "El árbol que viste, que crecía y se hacía fuerte, y que su altura llegaba hasta el cielo, y su vista por toda la tierra;"}, {"numero": 21, "texto": "Y cuya copa era hermosa, y su fruto en abundancia, y que para todos había mantenimiento en él; debajo del cual moraban las bestias del campo, y en sus ramas habitaban las aves del cielo,"}, {"numero": 22, "texto": "Tú mismo eres, oh rey, que creciste, y te hiciste fuerte, pues creció tu grandeza, y ha llegado hasta el cielo, y tu señorío hasta el cabo de la tierra."}, {"numero": 23, "texto": "Y cuanto á lo que vió el rey, un vigilante y santo que descendía del cielo, y decía: Cortad el árbol y destruidlo: mas la cepa de sus raíces dejaréis en la tierra, y con atadura de hierro y de metal en la hierba del campo; y sea mojado con el rocío del cielo, y su parte sea con las bestias del campo, hasta que pasen sobre él siete tiempos:"}, {"numero": 24, "texto": "Esta es la declaración, oh rey, y la sentencia del Altísimo, que ha venido sobre el rey mi señor:"}, {"numero": 25, "texto": "Que te echarán de entre los hombres, y con las bestias del campo será tu morada, y con hierba del campo te apacentarán como á los bueyes, y con rocío del cielo serás bañado; y siete tiempos pasarán sobre ti, hasta que entiendas que el Altísimo se enseñorea en el reino de los hombres, y que á quien él quisiere lo dará."}, {"numero": 26, "texto": "Y lo que dijeron, que dejasen en la tierra la cepa de las raíces del mismo árbol, significa que tu reino se te quedará firme, luego que entiendas que el señorío es en los cielos."}, {"numero": 27, "texto": "Por tanto, oh rey, aprueba mi consejo, y redime tus pecados con justicia, y tus iniquidades con misericordias para con los pobres; que tal vez será eso una prolongación de tu tranquilidad."}, {"numero": 28, "texto": "Todo aquesto vino sobre el rey Nabucodonosor."}, {"numero": 29, "texto": "A cabo de doce meses, andándose paseando sobre el palacio del reino de Babilonia,"}, {"numero": 30, "texto": "Habló el rey, y dijo: ¿No es ésta la gran Babilonia, que yo edifiqué para casa del reino, con la fuerza de mi poder, y para gloria de mi grandeza?"}, {"numero": 31, "texto": "Aun estaba la palabra en la boca del rey, cuando cae una voz del cielo: A ti dicen, rey Nabucodonosor; el reino es traspasado de ti:"}, {"numero": 32, "texto": "Y de entre los hombres te echan, y con las bestias del campo será tu morada, y como á los bueyes te apacentarán: y siete tiempos pasarán sobre ti, hasta que conozcas que el Altísimo se enseñorea en el reino de los hombres, y á quien él quisiere lo da."}, {"numero": 33, "texto": "En la misma hora se cumplió la palabra sobre Nabucodonosor, y fué echado de entre los hombres; y comía hierba como los bueyes, y su cuerpo se bañaba con el rocío del cielo, hasta que su pelo creció como de águila, y sus uñas como de aves."}, {"numero": 34, "texto": "Mas al fin del tiempo yo Nabucodonosor alcé mis ojos al cielo, y mi sentido me fué vuelto; y bendije al Altísimo, y alabé y glorifiqué al que vive para siempre; porque su señorío es sempiterno, y su reino por todas las edades."}, {"numero": 35, "texto": "Y todos los moradores de la tierra por nada son contados: y en el ejército del cielo, y en los habitantes de la tierra, hace según su voluntad: ni hay quien estorbe su mano, y le diga: ¿Qué haces?"}, {"numero": 36, "texto": "En el mismo tiempo mi sentido me fué vuelto, y la majestad de mi reino, mi dignidad y mi grandeza volvieron á mí, y mis gobernadores y mis grandes me buscaron; y fuí restituído á mi reino, y mayor grandeza me fué añadida."}, {"numero": 37, "texto": "Ahora yo Nabucodonosor alabo, engrandezco y glorifico al Rey del cielo, porque todas sus obras son verdad, y sus caminos juicio; y humillar puede á los que andan con soberbia."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 5, 'pt', '[{"numero": 1, "texto": "O rei Belsazar fez um grande banquete a mil de seus maiorais, e bebeu vinho diante destes mil."}, {"numero": 2, "texto": "Tendo Belsazar experimentado o vinho, mandou trazer os vasos de ouro e de prata que seu pai Nabucodonosor tirara do templo de Jerusalém, para que bebessem com eles o rei e seus maiorais, suas mulheres e suas concubinas."}, {"numero": 3, "texto": "Então trouxeram os vasos de ouro que foram tirados do templo da casa de Deus, que estava em Jerusalém; e beberam com eles o rei e seus maiorais, suas mulheres e suas concubinas."}, {"numero": 4, "texto": "Beberam vinho, e louvaram aos deuses de ouro e de prata, de bronze, de ferro, de madeira, e de pedra."}, {"numero": 5, "texto": "Naquela mesma hora saíram dedos de uma mão de homem, e escreveram diante do castiçal na caiadura da parede do palácio real, e o rei viu parte da mão que estava escrevendo."}, {"numero": 6, "texto": "Então o semblante do rei se mudou, e seus pensamentos o perturbaram; as juntas de seus lombos se desataram, e seus joelhos se bateram um com o outro."}, {"numero": 7, "texto": "O rei clamou em alta voz que trouxessem astrólogos, caldeus, e adivinhos. O rei falou, e disse aos sábios da Babilônia: Qualquer um que ler esta escritura, e me mostrar sua interpretação, será vestido de púrpura, terá uma corrente de ouro a seu pescoço, e será o terceiro líder no reino."}, {"numero": 8, "texto": "Então vieram todos os sábios do rei, mas não puderam ler a escritura, nem fazer saber ao rei sua interpretação."}, {"numero": 9, "texto": "Então o rei Belsazar ficou muito perturbado, e se mudou seu semblante; seus maiorais estavam perturbados."}, {"numero": 10, "texto": "A rainha, por causa das palavras do rei e de seus maiorais, entrou na casa do banquete. A rainha disse: Ó rei, vive para sempre! Não te perturbem teus pensamentos, nem se mude teu semblante."}, {"numero": 11, "texto": "Em teu reino há um homem no qual mora o espírito dos deuses santos; e nos dias de teu pai se achou nele luz, inteligência e sabedoria, como a sabedoria dos deuses; e teu pai, o rei Nabucodonosor (o rei, teu pai), o constituiu por príncipe sobre os magos, os astrólogos, os caldeus e os adivinhadores."}, {"numero": 12, "texto": "Pois nele foi achado um espírito extraordinário, conhecimento, e entendimento, interpretando sonhos, resolvendo enigmas, e desfazendo dúvidas. Ele é Daniel, a quem o rei pôs por nome Beltessazar. Chame-se agora a Daniel, e ele mostrará a interpretação."}, {"numero": 13, "texto": "Então Daniel foi trazido diante do rei. E o rei disse a Daniel: És tu aquele Daniel dos cativos de Judá, que meu pai trouxe de Judá?"}, {"numero": 14, "texto": "Pois tenho ouvido de ti que o espírito dos deuses está em ti, e que em ti se acha luz, entendimento e extraordinária sabedoria."}, {"numero": 15, "texto": "E agora foram trazidos diante de mim sábios e astrólogos, para que lessem esta escritura, e me fizessem saber sua interpretação; mas eles não puderam mostrar a interpretação destas palavras."}, {"numero": 16, "texto": "Eu, porém, tenho ouvido sobre ti que podes dar interpretações, e solucionar dúvidas. Agora, se puderes puderes ler esta escritura, e fazer-me saber sua interpretação, serás vestido de púrpura, corrente de ouro terás em teu pescoço, e serás o terceiro líder no reino."}, {"numero": 17, "texto": "Então Daniel respondeu, e disse diante do rei: Fiquem contigo tuas dádivas, e dá teus presentes a outro; contudo lerei a escritura ao rei, e lhe farei saber a interpretação."}, {"numero": 18, "texto": "Quanto a ti, ó rei, o Deus Altíssimo deu a teu pai Nabucodonosor o reino, a grandeza, a glória, e a majestade;"}, {"numero": 19, "texto": "E pela grandeza que ele lhe deu, todos os povos, nações, e línguas tremiam e temiam diante dele. Ele matava a quem queria, e concedia vida a quem queria; ele engrandecia a quem queria, e abatia a quem queria."}, {"numero": 20, "texto": "Mas quando seu coração se exaltou, e seu espírito se endureceu em soberba, ele foi deposto do trono de seu reino, e a glória lhe foi tirada."}, {"numero": 21, "texto": "E foi expulso dentre os filhos dos homens; e sua mente se tornou semelhante à dos animais, e com asnos selvagens foi sua morada. Foi alimentado com erva tal como os bois, e seu corpo foi molhado com o orvalho do céu, até que entendeu que o Deus altíssimo tem o domínio sobre os reinos humanos, e constitui sobre eles a quem ele quer."}, {"numero": 22, "texto": "E tu, Belsazar, filho dele, não humilhaste teu coração, mesmo sabendo de tudo isto;"}, {"numero": 23, "texto": "Em vez disso exaltaste a ti mesmo contra o Senhor do céu; pois trouxeram diante de ti os vasos de sua casa, e tu, teus maiorais, tuas mulheres e tuas concubinas, bebestes vinho neles; além disto, louvaste a deuses de prata, ouro, bronze, de ferro, madeira e pedra, que não veem, nem ouvem, nem têm conhecimento algum; porém ao Deus em cuja mão está tua vida e todos os teus caminhos, a ele não glorificaste;"}, {"numero": 24, "texto": "Então dele foi enviada aquela parte da mão que esculpiu esta escritura."}, {"numero": 25, "texto": "E esta é a escritura que foi escrita: MENE, MENE, TEQUEL, PARSIM."}, {"numero": 26, "texto": "Esta é a interpretação daquilo: MENE: Contou Deus o teu reino, e o acabou."}, {"numero": 27, "texto": "TEQUEL: Pesado foste na balança, e foste achado em falta."}, {"numero": 28, "texto": "PERES: Dividido foi teu reino, e entregue aos a medos e aos persas."}, {"numero": 29, "texto": "Então Belsazar deu ordens, e vestiram a Daniel de púrpura, [puseram] uma corrente de ouro em seu pescoço, e anunciaram que ele seria o terceiro líder no reino."}, {"numero": 30, "texto": "Naquela mesma noite Belsazar, rei dos caldeus, foi morto."}, {"numero": 31, "texto": "E Dario, o medo, tomou o reino, sendo da idade de sessenta e dois anos."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 5, 'en', '[{"numero": 1, "texto": "Belshazzar the king made a great feast to a thousand of his lords, and drank wine before the thousand."}, {"numero": 2, "texto": "Belshazzar, whiles he tasted the wine, commanded to bring the golden and silver vessels which his father Nebuchadnezzar had taken out of the temple which was in Jerusalem; that the king, and his princes, his wives, and his concubines, might drink therein."}, {"numero": 3, "texto": "Then they brought the golden vessels that were taken out of the temple of the house of God which was at Jerusalem; and the king, and his princes, his wives, and his concubines, drank in them."}, {"numero": 4, "texto": "They drank wine, and praised the gods of gold, and of silver, of brass, of iron, of wood, and of stone."}, {"numero": 5, "texto": "In the same hour came forth fingers of a man''s hand, and wrote over against the candlestick upon the plaister of the wall of the king''s palace: and the king saw the part of the hand that wrote."}, {"numero": 6, "texto": "Then the king''s countenance was changed, and his thoughts troubled him, so that the joints of his loins were loosed, and his knees smote one against another."}, {"numero": 7, "texto": "The king cried aloud to bring in the astrologers, the Chaldeans, and the soothsayers. And the king spake, and said to the wise men of Babylon, Whosoever shall read this writing, and shew me the interpretation thereof, shall be clothed with scarlet, and have a chain of gold about his neck, and shall be the third ruler in the kingdom."}, {"numero": 8, "texto": "Then came in all the king''s wise men: but they could not read the writing, nor make known to the king the interpretation thereof."}, {"numero": 9, "texto": "Then was king Belshazzar greatly troubled, and his countenance was changed in him, and his lords were astonied."}, {"numero": 10, "texto": "Now the queen by reason of the words of the king and his lords came into the banquet house: and the queen spake and said, O king, live for ever: let not thy thoughts trouble thee, nor let thy countenance be changed:"}, {"numero": 11, "texto": "There is a man in thy kingdom, in whom is the spirit of the holy gods; and in the days of thy father light and understanding and wisdom, like the wisdom of the gods, was found in him; whom the king Nebuchadnezzar thy father, the king, I say, thy father, made master of the magicians, astrologers, Chaldeans, and soothsayers;"}, {"numero": 12, "texto": "Forasmuch as an excellent spirit, and knowledge, and understanding, interpreting of dreams, and shewing of hard sentences, and dissolving of doubts, were found in the same Daniel, whom the king named Belteshazzar: now let Daniel be called, and he will shew the interpretation."}, {"numero": 13, "texto": "Then was Daniel brought in before the king. And the king spake and said unto Daniel, Art thou that Daniel, which art of the children of the captivity of Judah, whom the king my father brought out of Jewry?"}, {"numero": 14, "texto": "I have even heard of thee, that the spirit of the gods is in thee, and that light and understanding and excellent wisdom is found in thee."}, {"numero": 15, "texto": "And now the wise men, the astrologers, have been brought in before me, that they should read this writing, and make known unto me the interpretation thereof: but they could not shew the interpretation of the thing:"}, {"numero": 16, "texto": "And I have heard of thee, that thou canst make interpretations, and dissolve doubts: now if thou canst read the writing, and make known to me the interpretation thereof, thou shalt be clothed with scarlet, and have a chain of gold about thy neck, and shalt be the third ruler in the kingdom."}, {"numero": 17, "texto": "Then Daniel answered and said before the king, Let thy gifts be to thyself, and give thy rewards to another; yet I will read the writing unto the king, and make known to him the interpretation."}, {"numero": 18, "texto": "O thou king, the most high God gave Nebuchadnezzar thy father a kingdom, and majesty, and glory, and honour:"}, {"numero": 19, "texto": "And for the majesty that he gave him, all people, nations, and languages, trembled and feared before him: whom he would he slew; and whom he would he kept alive; and whom he would he set up; and whom he would he put down."}, {"numero": 20, "texto": "But when his heart was lifted up, and his mind hardened in pride, he was deposed from his kingly throne, and they took his glory from him:"}, {"numero": 21, "texto": "And he was driven from the sons of men; and his heart was made like the beasts, and his dwelling was with the wild asses: they fed him with grass like oxen, and his body was wet with the dew of heaven; till he knew that the most high God ruled in the kingdom of men, and that he appointeth over it whomsoever he will."}, {"numero": 22, "texto": "And thou his son, O Belshazzar, hast not humbled thine heart, though thou knewest all this;"}, {"numero": 23, "texto": "But hast lifted up thyself against the Lord of heaven; and they have brought the vessels of his house before thee, and thou, and thy lords, thy wives, and thy concubines, have drunk wine in them; and thou hast praised the gods of silver, and gold, of brass, iron, wood, and stone, which see not, nor hear, nor know: and the God in whose hand thy breath is, and whose are all thy ways, hast thou not glorified:"}, {"numero": 24, "texto": "Then was the part of the hand sent from him; and this writing was written."}, {"numero": 25, "texto": "And this is the writing that was written, Mene, Mene, Tekel, Upharsin."}, {"numero": 26, "texto": "This is the interpretation of the thing: Mene; God hath numbered thy kingdom, and finished it."}, {"numero": 27, "texto": "Tekel; Thou art weighed in the balances, and art found wanting."}, {"numero": 28, "texto": "Peres; Thy kingdom is divided, and given to the Medes and Persians."}, {"numero": 29, "texto": "Then commanded Belshazzar, and they clothed Daniel with scarlet, and put a chain of gold about his neck, and made a proclamation concerning him, that he should be the third ruler in the kingdom."}, {"numero": 30, "texto": "In that night was Belshazzar the king of the Chaldeans slain."}, {"numero": 31, "texto": "And Darius the Median took the kingdom, being about threescore and two years old."}]'::jsonb, 'King James Version'),
  ('Dn', 5, 'fr', '[{"numero": 1, "texto": "Le roi Belschatsar donna un grand festin à ses grands au nombre de mille, et il but du vin en leur présence."}, {"numero": 2, "texto": "Belschatsar, quand il eut goûté au vin, fit apporter les vases d''''or et d''''argent que son père Nebucadnetsar avait enlevés du temple de Jérusalem, afin que le roi et ses grands, ses femmes et ses concubines, s''''en servissent pour boire."}, {"numero": 3, "texto": "Alors on apporta les vases d''''or qui avaient été enlevés du temple, de la maison de Dieu à Jérusalem; et le roi et ses grands, ses femmes et ses concubines, s''''en servirent pour boire."}, {"numero": 4, "texto": "Ils burent du vin, et ils louèrent les dieux d''''or, d''''argent, d''''airain, de fer, de bois et de pierre."}, {"numero": 5, "texto": "En ce moment, apparurent les doigts d''''une main d''''homme, et ils écrivirent, en face du chandelier, sur la chaux de la muraille du palais royal. Le roi vit cette extrémité de main qui écrivait."}, {"numero": 6, "texto": "Alors le roi changea de couleur, et ses pensées le troublèrent; les jointures de ses reins se relâchèrent, et ses genoux se heurtèrent l''''un contre l''''autre."}, {"numero": 7, "texto": "Le roi cria avec force qu''''on fît venir les astrologues, les Chaldéens et les devins; et le roi prit la parole et dit aux sages de Babylone: Quiconque lira cette écriture et m''''en donnera l''''explication sera revêtu de pourpre, portera un collier d''''or à son cou, et aura la troisième place dans le gouvernement du royaume."}, {"numero": 8, "texto": "Tous les sages du roi entrèrent; mais ils ne purent pas lire l''''écriture et en donner au roi l''''explication."}, {"numero": 9, "texto": "Sur quoi le roi Belschatsar, fut très effrayé, il changea de couleur, et ses grands furent consternés."}, {"numero": 10, "texto": "La reine, à cause des paroles du roi et de ses grands, entra dans la salle du festin, et prit ainsi la parole: O roi, vis éternellement! Que tes pensées ne te troublent pas, et que ton visage ne change pas de couleur!"}, {"numero": 11, "texto": "Il y a dans ton royaume un homme qui a en lui l''''esprit des dieux saints; et du temps de ton père, on trouva chez lui des lumières, de l''''intelligence, et une sagesse semblable à la sagesse des dieux. Aussi le roi Nebucadnetsar, ton père, le roi, ton père, l''''établit chef des magiciens, des astrologues, des Chaldéens, des devins,"}, {"numero": 12, "texto": "parce qu''''on trouva chez lui, chez Daniel, nommé par le roi Beltschatsar, un esprit supérieur, de la science et de l''''intelligence, la faculté d''''interpréter les songes, d''''expliquer les énigmes, et de résoudre les questions difficiles. Que Daniel soit donc appelé, et il donnera l''''explication."}, {"numero": 13, "texto": "Alors Daniel fut introduit devant le roi. Le roi prit la parole et dit à Daniel: Es-tu ce Daniel, l''''un des captifs de Juda, que le roi, mon père, a amenés de Juda?"}, {"numero": 14, "texto": "J''''ai appris sur ton compte que tu as en toi l''''esprit des dieux, et qu''''on trouve chez toi des lumières, de l''''intelligence, et une sagesse extraordinaire."}, {"numero": 15, "texto": "On vient d''''amener devant moi les sages et les astrologues, afin qu''''ils lussent cette écriture et m''''en donnassent l''''explication; mais ils n''''ont pas pu donner l''''explication des mots."}, {"numero": 16, "texto": "J''''ai appris que tu peux donner des explications et résoudre des questions difficiles; maintenant, si tu peux lire cette écriture et m''''en donner l''''explication, tu seras revêtu de pourpre, tu porteras un collier d''''or à ton cou, et tu auras la troisième place dans le gouvernement du royaume."}, {"numero": 17, "texto": "Daniel répondit en présence du roi: Garde tes dons, et accorde à un autre tes présents; je lirai néanmoins l''''écriture au roi, et je lui en donnerai l''''explication."}, {"numero": 18, "texto": "O roi, le Dieu suprême avait donné à Nebucadnetsar, ton père, l''''empire, la grandeur, la gloire et la magnificence;"}, {"numero": 19, "texto": "et à cause de la grandeur qu''''il lui avait donnée, tous les peuples, les nations, les hommes de toutes langues étaient dans la crainte et tremblaient devant lui. Le roi faisait mourir ceux qu''''il voulait, et il laissait la vie à ceux qu''''il voulait; il élevait ceux qu''''il voulait, et il abaissait ceux qu''''il voulait."}, {"numero": 20, "texto": "Mais lorsque son coeur s''''éleva et que son esprit s''''endurcit jusqu''''à l''''arrogance, il fut précipité de son trône royal et dépouillé de sa gloire;"}, {"numero": 21, "texto": "il fut chassé du milieu des enfants des hommes, son coeur devint semblable à celui des bêtes, et sa demeure fut avec les ânes sauvages; on lui donna comme aux boeufs de l''''herbe à manger, et son corps fut trempé de la rosée du ciel, jusqu''''à ce qu''''il reconnût que le Dieu suprême domine sur le règne des hommes et qu''''il le donne à qui il lui plaît."}, {"numero": 22, "texto": "Et toi, Belschatsar, son fils, tu n''''as pas humilié ton coeur, quoique tu susses toutes ces choses."}, {"numero": 23, "texto": "Tu t''''es élevé contre le Seigneur des cieux; les vases de sa maison ont été apportés devant toi, et vous vous en êtes servis pour boire du vin, toi et tes grands, tes femmes et tes concubines; tu as loué les dieux d''''argent, d''''or, d''''airain, de fer, de bois et de pierre, qui ne voient point, qui n''''entendent point, et qui ne savent rien, et tu n''''as pas glorifié le Dieu qui a dans sa main ton souffle et toutes tes voies."}, {"numero": 24, "texto": "C''''est pourquoi il a envoyé cette extrémité de main qui a tracé cette écriture."}, {"numero": 25, "texto": "Voici l''''écriture qui a été tracée: Compté, compté, pesé, et divisé."}, {"numero": 26, "texto": "Et voici l''''explication de ces mots. Compté: Dieu a compté ton règne, et y a mis fin."}, {"numero": 27, "texto": "Pesé: Tu as été pesé dans la balance, et tu as été trouvé léger."}, {"numero": 28, "texto": "Divisé: Ton royaume sera divisé, et donné aux Mèdes et aux Perses."}, {"numero": 29, "texto": "Aussitôt Belschatsar donna des ordres, et l''''on revêtit Daniel de pourpre, on lui mit au cou un collier d''''or, et on publia qu''''il aurait la troisième place dans le gouvernement du royaume."}, {"numero": 30, "texto": "Cette même nuit, Belschatsar, roi des Chaldéens, fut tué."}, {"numero": 31, "texto": "Et Darius, le Mède, s''''empara du royaume, étant âgé de soixante-deux ans."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 5, 'es', '[{"numero": 1, "texto": "EL rey Belsasar hizo un gran banquete á mil de sus príncipes, y en presencia de los mil bebía vino."}, {"numero": 2, "texto": "Belsasar, con el gusto del vino, mandó que trajesen los vasos de oro y de plata que Nabucodonosor su padre había traído del templo de Jerusalem; para que bebiesen con ellos el rey y sus príncipes, sus mujeres y sus concubinas."}, {"numero": 3, "texto": "Entonces fueron traídos los vasos de oro que habían traído del templo de la casa de Dios que estaba en Jerusalem, y bebieron con ellos el rey y sus príncipes, sus mujeres y sus concubinas."}, {"numero": 4, "texto": "Bebieron vino, y alabaron á los dioses de oro y de plata, de metal, de hierro, de madera, y de piedra."}, {"numero": 5, "texto": "En aquella misma hora salieron unos dedos de mano de hombre, y escribían delante del candelero sobre lo encalado de la pared del palacio real, y el rey veía la palma de la mano que escribía."}, {"numero": 6, "texto": "Entonces el rey se demudó de su color, y sus pensamientos lo turbaron, y desatáronse las ceñiduras de sus lomos, y sus rodillas se batían la una con la otra."}, {"numero": 7, "texto": "El rey clamó en alta voz que hiciesen venir magos, Caldeos, y adivinos. Habló el rey, y dijo á los sabios de Babilonia: Cualquiera que leyere esta escritura, y me mostrare su declaración, será vestido de púrpura, y tendrá collar de oro á su cuello; y en el reino se enseñoreará el tercero."}, {"numero": 8, "texto": "Entonces fueron introducidos todos los sabios del rey, y no pudieron leer la escritura, ni mostrar al rey su declaración."}, {"numero": 9, "texto": "Entonces el rey Belsasar fué muy turbado, y se le mudaron sus colores y alteráronse sus príncipes."}, {"numero": 10, "texto": "La reina, por las palabras del rey y de sus príncipes, entró á la sala del banquete. Y habló la reina, y dijo: Rey, para siempre vive, no te asombren tus pensamientos, ni tus colores se demuden:"}, {"numero": 11, "texto": "En tu reino hay un varón, en el cual mora el espíritu de los dioses santos; y en los días de tu padre se halló en él luz é inteligencia y sabiduría, como ciencia de los dioses: al cual el rey Nabucodonosor, tu padre, el rey tu padre constituyó príncipe sobre todos los magos, astrólogos, Caldeos, y adivinos:"}, {"numero": 12, "texto": "Por cuanto fué hallado en él mayor espíritu, y ciencia, y entendimiento, interpretando sueños, y declarando preguntas, y deshaciendo dudas, es á saber, en Daniel; al cual el rey puso por nombre Beltsasar. Llámese pues ahora á Daniel, y él mostrará la declaración."}, {"numero": 13, "texto": "Entonces Daniel fué traído delante del rey. Y habló el rey, y dijo á Daniel: ¿Eres tú aquel Daniel de los hijos de la cautividad de Judá, que mi padre trajo de Judea?"}, {"numero": 14, "texto": "Yo he oído de ti que el espíritu de los dioses santos está en ti, y que en ti se halló luz, y entendimiento y mayor sabiduría."}, {"numero": 15, "texto": "Y ahora fueron traídos delante de mí, sabios, astrólogos, que leyesen esta escritura, y me mostrasen su interpretación: pero no han podido mostrar la declaración del negocio."}, {"numero": 16, "texto": "Yo pues he oído de ti que puedes declarar las dudas, y desatar dificultades. Si ahora pudieres leer esta escritura, y mostrarme su interpretación, serás vestido de púrpura, y collar de oro tendrás en tu cuello, y en el reino serás el tercer señor."}, {"numero": 17, "texto": "Entonces Daniel respondió, y dijo delante del rey: Tus dones sean para ti, y tus presentes dalos á otro. La escritura yo la leeré al rey, y le mostraré la declaración."}, {"numero": 18, "texto": "El altísimo Dios, oh rey, dió á Nabucodonosor tu padre el reino, y la grandeza, y la gloria, y la honra:"}, {"numero": 19, "texto": "Y por la grandeza que le dió, todos los pueblos, naciones, y lenguas, temblaban y temían delante de él. Los que él quería mataba, y daba vida á los que quería: engrandecía á los que quería, y á los que quería humillaba."}, {"numero": 20, "texto": "Mas cuando su corazón se ensoberbeció, y su espíritu se endureció en altivez, fué depuesto del trono de su reino, y traspasaron de él la gloria:"}, {"numero": 21, "texto": "Y fué echado de entre los hijos de los hombres; y su corazón fué puesto con las bestias, y con los asnos monteses fué su morada. Hierba le hicieron comer, como á buey, y su cuerpo fué bañado con el rocío del cielo, hasta que conoció que el altísimo Dios se enseñorea del reino de los hombres, y que pondrá sobre él al que quisiere."}, {"numero": 22, "texto": "Y tú, su hijo Belsasar, no has humillado tu corazón, sabiendo todo esto:"}, {"numero": 23, "texto": "Antes contra el Señor del cielo te has ensoberbecido, é hiciste traer delante de ti los vasos de su casa, y tú y tus príncipes, tus mujeres y tus concubinas, bebisteis vino en ellos: demás de esto, á dioses de plata y de oro, de metal, de hierro, de madera, y de piedra, que ni ven, ni oyen, ni saben, diste alabanza: y al Dios en cuya mano está tu vida, y cuyos son todos tus caminos, nunca honraste."}, {"numero": 24, "texto": "Entonces de su presencia fué enviada la palma de la mano que esculpió esta escritura."}, {"numero": 25, "texto": "Y la escritura que esculpió es: MENE, MENE, TEKEL, UPHARSIN."}, {"numero": 26, "texto": "La declaración del negocio es: MENE: Contó Dios tu reino, y halo rematado."}, {"numero": 27, "texto": "TEKEL: Pesado has sido en balanza, y fuiste hallado falto."}, {"numero": 28, "texto": "PERES: Tu reino fué rompido, y es dado á Medos y Persas."}, {"numero": 29, "texto": "Entonces, mandándolo Belsasar, vistieron á Daniel de púrpura, y en su cuello fué puesto un collar de oro, y pregonaron de él que fuese el tercer señor en el reino."}, {"numero": 30, "texto": "La misma noche fué muerto Belsasar, rey de los Caldeos."}, {"numero": 31, "texto": "Y Darío de Media tomó el reino, siendo de sesenta y dos años."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 6, 'pt', '[{"numero": 1, "texto": "Pareceu bem a Dario constituir sobre o reino cento vinte governadores que estivessem em todo o reino."}, {"numero": 2, "texto": "E sobre eles três supervisores, dos quais Daniel era um, a quem estes governadores deviam prestar contas, para que o rei não sofresse dano."}, {"numero": 3, "texto": "Então o mesmo Daniel era superior a estes governadores e supervisores, porque nele havia um espírito extraordinário; por isso o rei pensava em constituí-lo sobre todo o reino."}, {"numero": 4, "texto": "Então os supervisores e governadores procuravam achar alguma acusação contra Daniel a respeito do reino; mas não conseguiram achar acusação ou falta alguma, porque ele era fiel, e nenhum erro nem falta foi achada nele."}, {"numero": 5, "texto": "Então esses homens disseram: Não acharemos acusação alguma contra este Daniel, a não ser se a acharmos contra ele na lei de seu Deus."}, {"numero": 6, "texto": "Então esses supervisores e governadores foram juntos ao rei, e lhe disseram assim: Ó rei Dario, vive para sempre!"}, {"numero": 7, "texto": "Todos os supervisores do reino, os prefeitos, governadores, conselheiros e capitães, concordaram em sugerir a promulgação de um decreto real, e estabelecer um estatuto forte, que qualquer um que, no intervalo de trinta dias, fizer alguma petição a qualquer deus ou humano, a não ser a ti, ó rei, seja lançado na cova dos leões."}, {"numero": 8, "texto": "Agora, ó rei, confirma o decreto, e assina a escritura, para que não se mude, conforme à lei dos medos e dos persas, que não se pode revogar."}, {"numero": 9, "texto": "Por esta causa o rei Dario assinou o decreto por escrito."}, {"numero": 10, "texto": "E Daniel, quando soube que a escritura estava assinada, entrou em sua casa, e com as janelas de seu quarto abertas, voltadas para Jerusalém, punha-se de joelhos três vezes ao dia, e orava, e confessava diante de seu Deus, assim como costumava fazer antes."}, {"numero": 11, "texto": "Então aqueles homens se juntaram, e encontraram Daniel orando e suplicando diante de seu Deus."}, {"numero": 12, "texto": "Então se aproximaram e falaram diante do rei acerca do decreto real: Por acaso não assinaste o decreto que todo aquele que pedir a qualquer deus ou humano no intervalo de trinta dias, a não ser a ti, ó rei, seja lançado na cova dos leões? O rei respondeu: Esta palavra é certa, conforme a lei dos medos e dos persas, que não se pode revogar."}, {"numero": 13, "texto": "Então disseram diante do rei: Daniel, que é um dos cativos de Judá, não respeitou a ti, ó rei, nem ao decreto que assinaste; em vez disso três vezes ao dia ele faz sua oração."}, {"numero": 14, "texto": "Quando o rei ouviu isso, pesou-lhe muito, e tentou pensar em como livrar Daniel; e até o pôr do sol trabalhou para livrá-lo."}, {"numero": 15, "texto": "Então aqueles homens foram juntos ao rei, e disseram ao rei: Sabe, ó rei, que é a lei dos medos e dos persas, que nenhum decreto um ordenança que o rei estabeleceu pode ser mudada."}, {"numero": 16, "texto": "Então o rei mandou trazerem a Daniel, e [o] lançaram na cova dos leões. E o rei falou a Daniel: O teu Deus, a quem tu serves continuamente, ele te livre."}, {"numero": 17, "texto": "E foi trazida uma pedra, e foi posta sobre a abertura da cova, a qual o rei selou com seu anel, e com o anel de seus grandes, para que a sentença acerca de Daniel não fosse mudada."}, {"numero": 18, "texto": "Então o rei foi a seu palácio, e passou a noite em jejum; não permitiu que lhe trouxessem instrumentos musicais diante de si, e ele perdeu o sono."}, {"numero": 19, "texto": "Então o rei se levantou pela manhã cedo, e foi depressa à cova dos leões."}, {"numero": 20, "texto": "E chegando perto da cova, chamou a Daniel com voz triste; e o rei falou a Daniel: Daniel, servo do Deus vivente! O teus Deus, a quem tu continuamente serves, pôde te livrar dos leões?"}, {"numero": 21, "texto": "Então Daniel falou ao rei: Ó rei, vive para sempre!"}, {"numero": 22, "texto": "Meu Deus enviou seu anjo, que fechou a boca dos leões, para que não me fizessem dano; porque diante dele se achou inocência em mim; e também contra ti, ó rei, não cometi delito algum."}, {"numero": 23, "texto": "Então o rei se alegrou muito por causa dele, e mandou tirar a Daniel da cova; assim Daniel foi tirado da cova, e nenhum dano se achou nele, pois havia confiado em seu Deus."}, {"numero": 24, "texto": "Então o rei mandou trazerem aqueles homens que tinham acusado a Daniel, e foram lançados na cova dos leões, eles, seus filhos, e suas mulheres; e nem sequer haviam chegado ao fundo da cova, quando os leões os tomaram, e quebraram todos os seus ossos."}, {"numero": 25, "texto": "Então o rei Dario escreveu a todos os povos, nações, e línguas, que moram em toda a terra: Paz vos seja multiplicada."}, {"numero": 26, "texto": "De minha parte é feito um decreto, que em todo o domínio de meu reino, [todos] tremam e temam a presença do Deus de Daniel; porque ele é o Deus vivente, que permanece para sempre; seu reino não se pode destruir, e seu domínio [dura] até o fim."}, {"numero": 27, "texto": "Ele resgata e livra, e faz sinais e maravilhas no céu e na terra; ele livrou a Daniel do poder dos leões."}, {"numero": 28, "texto": "E este Daniel foi próspero no reino de Dario, e no reinado de Ciro, o persa."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 6, 'en', '[{"numero": 1, "texto": "It pleased Darius to set over the kingdom an hundred and twenty princes, which should be over the whole kingdom;"}, {"numero": 2, "texto": "And over these three presidents; of whom Daniel was first: that the princes might give accounts unto them, and the king should have no damage."}, {"numero": 3, "texto": "Then this Daniel was preferred above the presidents and princes, because an excellent spirit was in him; and the king thought to set him over the whole realm."}, {"numero": 4, "texto": "Then the presidents and princes sought to find occasion against Daniel concerning the kingdom; but they could find none occasion nor fault; forasmuch as he was faithful, neither was there any error or fault found in him."}, {"numero": 5, "texto": "Then said these men, We shall not find any occasion against this Daniel, except we find it against him concerning the law of his God."}, {"numero": 6, "texto": "Then these presidents and princes assembled together to the king, and said thus unto him, King Darius, live for ever."}, {"numero": 7, "texto": "All the presidents of the kingdom, the governors, and the princes, the counsellors, and the captains, have consulted together to establish a royal statute, and to make a firm decree, that whosoever shall ask a petition of any God or man for thirty days, save of thee, O king, he shall be cast into the den of lions."}, {"numero": 8, "texto": "Now, O king, establish the decree, and sign the writing, that it be not changed, according to the law of the Medes and Persians, which altereth not."}, {"numero": 9, "texto": "Wherefore king Darius signed the writing and the decree."}, {"numero": 10, "texto": "Now when Daniel knew that the writing was signed, he went into his house; and his windows being open in his chamber toward Jerusalem, he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime."}, {"numero": 11, "texto": "Then these men assembled, and found Daniel praying and making supplication before his God."}, {"numero": 12, "texto": "Then they came near, and spake before the king concerning the king''s decree; Hast thou not signed a decree, that every man that shall ask a petition of any God or man within thirty days, save of thee, O king, shall be cast into the den of lions? The king answered and said, The thing is true, according to the law of the Medes and Persians, which altereth not."}, {"numero": 13, "texto": "Then answered they and said before the king, That Daniel, which is of the children of the captivity of Judah, regardeth not thee, O king, nor the decree that thou hast signed, but maketh his petition three times a day."}, {"numero": 14, "texto": "Then the king, when he heard these words, was sore displeased with himself, and set his heart on Daniel to deliver him: and he laboured till the going down of the sun to deliver him."}, {"numero": 15, "texto": "Then these men assembled unto the king, and said unto the king, Know, O king, that the law of the Medes and Persians is, That no decree nor statute which the king establisheth may be changed."}, {"numero": 16, "texto": "Then the king commanded, and they brought Daniel, and cast him into the den of lions. Now the king spake and said unto Daniel, Thy God whom thou servest continually, he will deliver thee."}, {"numero": 17, "texto": "And a stone was brought, and laid upon the mouth of the den; and the king sealed it with his own signet, and with the signet of his lords; that the purpose might not be changed concerning Daniel."}, {"numero": 18, "texto": "Then the king went to his palace, and passed the night fasting: neither were instruments of musick brought before him: and his sleep went from him."}, {"numero": 19, "texto": "Then the king arose very early in the morning, and went in haste unto the den of lions."}, {"numero": 20, "texto": "And when he came to the den, he cried with a lamentable voice unto Daniel: and the king spake and said to Daniel, O Daniel, servant of the living God, is thy God, whom thou servest continually, able to deliver thee from the lions?"}, {"numero": 21, "texto": "Then said Daniel unto the king, O king, live for ever."}, {"numero": 22, "texto": "My God hath sent his angel, and hath shut the lions'' mouths, that they have not hurt me: forasmuch as before him innocency was found in me; and also before thee, O king, have I done no hurt."}, {"numero": 23, "texto": "Then was the king exceedingly glad for him, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no manner of hurt was found upon him, because he believed in his God."}, {"numero": 24, "texto": "And the king commanded, and they brought those men which had accused Daniel, and they cast them into the den of lions, them, their children, and their wives; and the lions had the mastery of them, and brake all their bones in pieces or ever they came at the bottom of the den."}, {"numero": 25, "texto": "Then king Darius wrote unto all people, nations, and languages, that dwell in all the earth; Peace be multiplied unto you."}, {"numero": 26, "texto": "I make a decree, That in every dominion of my kingdom men tremble and fear before the God of Daniel: for he is the living God, and stedfast for ever, and his kingdom that which shall not be destroyed, and his dominion shall be even unto the end."}, {"numero": 27, "texto": "He delivereth and rescueth, and he worketh signs and wonders in heaven and in earth, who hath delivered Daniel from the power of the lions."}, {"numero": 28, "texto": "So this Daniel prospered in the reign of Darius, and in the reign of Cyrus the Persian."}]'::jsonb, 'King James Version'),
  ('Dn', 6, 'fr', '[{"numero": 1, "texto": "Darius trouva bon d''''établir sur le royaume cent vingt satrapes, qui devaient être dans tout le royaume."}, {"numero": 2, "texto": "Il mit à leur tête trois chefs, au nombre desquels était Daniel, afin que ces satrapes leur rendissent compte, et que le roi ne souffrît aucun dommage."}, {"numero": 3, "texto": "Daniel surpassait les chefs et les satrapes, parce qu''''il y avait en lui un esprit supérieur; et le roi pensait à l''''établir sur tout le royaume."}, {"numero": 4, "texto": "Alors les chefs et les satrapes cherchèrent une occasion d''''accuser Daniel en ce qui concernait les affaires du royaume. Mais ils ne purent trouver aucune occasion, ni aucune chose à reprendre, parce qu''''il était fidèle, et qu''''on n''''apercevait chez lui ni faute, ni rien de mauvais."}, {"numero": 5, "texto": "Et ces hommes dirent: Nous ne trouverons aucune occasion contre ce Daniel, à moins que nous n''''en trouvions une dans la loi de son Dieu."}, {"numero": 6, "texto": "Puis ces chefs et ces satrapes se rendirent tumultueusement auprès du roi, et lui parlèrent ainsi: Roi Darius, vis éternellement!"}, {"numero": 7, "texto": "Tous les chefs du royaume, les intendants, les satrapes, les conseillers, et les gouverneurs sont d''''avis qu''''il soit publié un édit royal, avec une défense sévère, portant que quiconque, dans l''''espace de trente jours, adressera des prières à quelque dieu ou à quelque homme, excepté à toi, ô roi, sera jeté dans la fosse aux lions."}, {"numero": 8, "texto": "Maintenant, ô roi, confirme la défense, et écris le décret, afin qu''''il soit irrévocable, selon la loi des Mèdes et des Perses, qui est immuable."}, {"numero": 9, "texto": "Là-dessus le roi Darius écrivit le décret et la défense."}, {"numero": 10, "texto": "Lorsque Daniel sut que le décret était écrit, il se retira dans sa maison, où les fenêtres de la chambre supérieure étaient ouvertes dans la direction de Jérusalem; et trois fois le jour il se mettait à genoux, il priait, et il louait son Dieu, comme il le faisait auparavant."}, {"numero": 11, "texto": "Alors ces hommes entrèrent tumultueusement, et ils trouvèrent Daniel qui priait et invoquait son Dieu."}, {"numero": 12, "texto": "Puis ils se présentèrent devant le roi, et lui dirent au sujet de la défense royale: N''''as-tu pas écrit une défense portant que quiconque dans l''''espace de trente jours adresserait des prières à quelque dieu ou à quelque homme, excepté à toi, ô roi, serait jeté dans la fosse aux lions? Le roi répondit: La chose est certaine, selon la loi des Mèdes et des Perses, qui est immuable."}, {"numero": 13, "texto": "Ils prirent de nouveau la parole et dirent au roi: Daniel, l''''un des captifs de Juda, n''''a tenu aucun compte de toi, ô roi, ni de la défense que tu as écrite, et il fait sa prière trois fois le jour."}, {"numero": 14, "texto": "Le roi fut très affligé quand il entendit cela; il prit à coeur de délivrer Daniel, et jusqu''''au coucher du soleil il s''''efforça de le sauver."}, {"numero": 15, "texto": "Mais ces hommes insistèrent auprès du roi, et lui dirent: Sache, ô roi, que la loi des Mèdes et des Perses exige que toute défense ou tout décret confirmé par le roi soit irrévocable."}, {"numero": 16, "texto": "Alors le roi donna l''''ordre qu''''on amenât Daniel, et qu''''on le jetât dans la fosse aux lions. Le roi prit la parole et dit à Daniel: Puisse ton Dieu, que tu sers avec persévérance, te délivrer!"}, {"numero": 17, "texto": "On apporta une pierre, et on la mit sur l''''ouverture de la fosse; le roi la scella de son anneau et de l''''anneau de ses grands, afin que rien ne fût changé à l''''égard de Daniel."}, {"numero": 18, "texto": "Le roi se rendit ensuite dans son palais; il passa la nuit à jeun, il ne fit point venir de concubine auprès de lui, et il ne put se livrer au sommeil."}, {"numero": 19, "texto": "Le roi se leva au point du jour, avec l''''aurore, et il alla précipitamment à la fosse aux lions."}, {"numero": 20, "texto": "En s''''approchant de la fosse, il appela Daniel d''''une voix triste. Le roi prit la parole et dit à Daniel: Daniel, serviteur du Dieu vivant, ton Dieu, que tu sers avec persévérance, a-t-il pu te délivrer des lions?"}, {"numero": 21, "texto": "Et Daniel dit au roi: Roi, vis éternellement?"}, {"numero": 22, "texto": "Mon Dieu a envoyé son ange et fermé la gueule des lions, qui ne m''''ont fait aucun mal, parce que j''''ai été trouvé innocent devant lui; et devant toi non plus, ô roi, je n''''ai rien fait de mauvais."}, {"numero": 23, "texto": "Alors le roi fut très joyeux, et il ordonna qu''''on fît sortir Daniel de la fosse. Daniel fut retiré de la fosse, et on ne trouva sur lui aucune blessure, parce qu''''il avait eu confiance en son Dieu."}, {"numero": 24, "texto": "Le roi ordonna que ces hommes qui avaient accusé Daniel fussent amenés et jetés dans la fosse aux lions, eux, leurs enfants et leurs femmes; et avant qu''''ils fussent parvenus au fond de la fosse, les lions les saisirent et brisèrent tous leurs os."}, {"numero": 25, "texto": "Après cela, le roi Darius écrivit à tous les peuples, à toutes les nations, aux hommes de toutes langues, qui habitaient sur toute la terre: Que la paix vous soit donnée avec abondance!"}, {"numero": 26, "texto": "J''''ordonne que, dans toute l''''étendue de mon royaume, on ait de la crainte et de la frayeur pour le Dieu de Daniel. Car il est le Dieu vivant, et il subsiste éternellement; son royaume ne sera jamais détruit, et sa domination durera jusqu''''à la fin."}, {"numero": 27, "texto": "C''''est lui qui délivre et qui sauve, qui opère des signes et des prodiges dans les cieux et sur la terre. C''''est lui qui a délivré Daniel de la puissance des lions."}, {"numero": 28, "texto": "Daniel prospéra sous le règne de Darius, et sous le règne de Cyrus, le Perse."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 6, 'es', '[{"numero": 1, "texto": "PARECIÓ bien á Darío constituir sobre el reino ciento veinte gobernadores, que estuviesen en todo el reino."}, {"numero": 2, "texto": "Y sobre ellos tres presidentes, de los cuales Daniel era el uno, á quienes estos gobernadores diesen cuenta, porque el rey no recibiese daño."}, {"numero": 3, "texto": "Pero el mismo Daniel era superior á estos gobernadores y presidentes, porque había en él más abundancia de espíritu: y el rey pensaba de ponerlo sobre todo el reino."}, {"numero": 4, "texto": "Entonces los presidentes y gobernadores buscaban ocasiones contra Daniel por parte del reino; mas no podían hallar alguna ocasión ó falta, porque él era fiel, y ningún vicio ni falta fué en él hallado."}, {"numero": 5, "texto": "Entonces dijeron aquellos hombres: No hallaremos contra este Daniel ocasión alguna, si no la hallamos contra él en la ley de su Dios."}, {"numero": 6, "texto": "Entonces estos gobernadores y presidentes se juntaron delante del rey, y le dijeron así: Rey Darío, para siempre vive:"}, {"numero": 7, "texto": "Todos los presidentes del reino, magistrados, gobernadores, grandes, y capitanes, han acordado por consejo promulgar un real edicto, y confirmarlo, que cualquiera que demandare petición de cualquier dios ú hombre en el espacio de treinta días, sino de ti, oh rey, sea echado en el foso de los leones."}, {"numero": 8, "texto": "Ahora, oh rey, confirma el edicto, y firma la escritura, para que no se pueda mudar, conforme á la ley de Media y de Persia, la cual no se revoca."}, {"numero": 9, "texto": "Firmó pues el rey Darío la escritura y el edicto."}, {"numero": 10, "texto": "Y Daniel, cuando supo que la escritura estaba firmada, entróse en su casa, y abiertas las ventanas de su cámara que estaban hacia Jerusalem, hincábase de rodillas tres veces al día, y oraba, y confesaba delante de su Dios, como lo solía hacer antes."}, {"numero": 11, "texto": "Entonces se juntaron aquellos hombres, y hallaron á Daniel orando y rogando delante de su Dios."}, {"numero": 12, "texto": "Llegáronse luego, y hablaron delante del rey acerca del edicto real: ¿No has confirmado edicto que cualquiera que pidiere á cualquier dios ú hombre en el espacio de treinta días, excepto á ti, oh rey, fuese echado en el foso de los leones? Respondió el rey y dijo: Verdad es, conforme á la ley de Media y de Persia, la cual no se abroga."}, {"numero": 13, "texto": "Entonces respondieron y dijeron delante del rey: Daniel que es de los hijos de la cautividad de los Judíos, no ha hecho cuenta de ti, oh rey, ni del edicto que confirmaste; antes tres veces al día hace su petición."}, {"numero": 14, "texto": "El rey entonces, oyendo el negocio, pesóle en gran manera, y sobre Daniel puso cuidado para librarlo; y hasta puestas del sol trabajó para librarle."}, {"numero": 15, "texto": "Empero aquellos hombres se reunieron cerca del rey, y dijeron al rey: Sepas, oh rey, que es ley de Media y de Persia, que ningún decreto ú ordenanza que el rey confirmare pueda mudarse."}, {"numero": 16, "texto": "Entonces el rey mandó, y trajeron á Daniel, y echáronle en el foso de los leones. Y hablando el rey dijo á Daniel: El Dios tuyo, á quien tú continuamente sirves, él te libre."}, {"numero": 17, "texto": "Y fué traída una piedra, y puesta sobre la puerta del foso, la cual selló el rey con su anillo, y con el anillo de sus príncipes, porque el acuerdo acerca de Daniel no se mudase."}, {"numero": 18, "texto": "Fuése luego el rey á su palacio, y acostóse ayuno; ni instrumentos de música fueron traídos delante de él, y se le fué el sueño."}, {"numero": 19, "texto": "El rey, por tanto, se levantó muy de mañana, y fué apriesa al foso de los leones:"}, {"numero": 20, "texto": "Y llegándose cerca del foso llamó á voces á Daniel con voz triste: y hablando el rey dijo á Daniel: Daniel, siervo del Dios viviente, el Dios tuyo, á quien tú continuamente sirves ¿te ha podido librar de los leones?"}, {"numero": 21, "texto": "Entonces habló Daniel con el rey: oh rey, para siempre vive."}, {"numero": 22, "texto": "El Dios mío envió su ángel, el cual cerró la boca de los leones, para que no me hiciesen mal: porque delante de él se halló en mí justicia: y aun delante de ti, oh rey, yo no he hecho lo que no debiese."}, {"numero": 23, "texto": "Entonces se alegró el rey en gran manera á causa de él, y mandó sacar á Daniel del foso: y fué Daniel sacado del foso, y ninguna lesión se halló en él, porque creyó en su Dios."}, {"numero": 24, "texto": "Y mandándolo el rey fueron traídos aquellos hombres que habían acusado á Daniel, y fueron echados en el foso de los leones, ellos, sus hijos, y sus mujeres; y aun no habían llegado al suelo del foso, cuando los leones se apoderaron de ellos, y quebrantaron todos sus huesos."}, {"numero": 25, "texto": "Entonces el rey Darío escribió á todos los pueblos, naciones, y lenguas, que habitan en toda la tierra: Paz os sea multiplicada:"}, {"numero": 26, "texto": "De parte mía es puesta ordenanza, que en todo el señorío de mi reino todos teman y tiemblen de la presencia del Dios de Daniel: porque él es el Dios viviente y permanente por todos los siglos, y su reino tal que no será deshecho, y su señorío hasta el fin."}, {"numero": 27, "texto": "Que salva y libra, y hace señales y maravillas en el cielo y en la tierra; el cual libró á Daniel del poder de los leones."}, {"numero": 28, "texto": "Y este Daniel fué prosperado durante el reinado de Darío, y durante el reinado de Ciro, Persa."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 7, 'pt', '[{"numero": 1, "texto": "No primeiro ano de Belsazar, rei da Babilônia, Daniel viu um sonho, e visões de sua cabeça em sua cama; logo escreveu o sonho, [e] anotou o resumo das coisas."}, {"numero": 2, "texto": "Daniel disse: Eu estava vendo em minha visão de noite, e eis que os quatro ventos do céu atormentavam o grande mar."}, {"numero": 3, "texto": "E quatro grandes animais subiam do mar, diferentes um do outro."}, {"numero": 4, "texto": "O primeiro era como leão, e tinha asas de águia. Eu estava olhando, até que suas asas lhe foram arrancadas; e foi levantado da terra; e posto de pé como um ser humano, e foi lhe dado um coração humano."}, {"numero": 5, "texto": "E eis outra segundo animal, semelhante a um urso, a qual se levantou por um lado, e tinha em sua boca três costelas entre seus dentes; e foi lhe dito assim: Levanta-te, devora muita carne."}, {"numero": 6, "texto": "Depois disto eu estava olhando, e eis outro, semelhante a um leopardo, e tinha quatro asas de ave em suas costas; este animal também tinha quatro cabeças; e foi lhe dado domínio."}, {"numero": 7, "texto": "Depois disto eu estava olhando nas visões da noite, e eis o quarta besta, terrível e espantoso, e muito forte. Ele tinha grandes dentes de ferro; devorava e quebrava em pedaços, e as sobras pisava com seus pés: e era diferente de todos os animais que foram antes dele; e tinha dez chifres."}, {"numero": 8, "texto": "Enquanto eu estava observando os chifres, eis que outro chifre pequeno subia entre eles, e três dos primeiros chifres foram arrancados de diante dele; e eis que neste chifre havia olhos como olhos humanos, e uma boca que falava coisas arrogantes."}, {"numero": 9, "texto": "Eu estive olhando até que foram postos tronos, e um Ancião de dias se sentou; sua veste era branca como a neve, e o cabelo de sua cabeça como lã limpa; seu trono era chamas de fogo, e suas rodas fogo ardente."}, {"numero": 10, "texto": "Um rio de fogo manava e saía de diante dele; milhares de milhares lhe serviam, e milhões de milhões estavam de pé diante dele: o julgamento começou, e os livros foram abertos."}, {"numero": 11, "texto": "Então eu estive olhando por causa da voz das palavras arrogantes que o chifre falava; estive olhando, até que mataram o animal, e seu corpo foi destruído, e entregue para ser queimado no fogo."}, {"numero": 12, "texto": "E quanto aos outros animais, seu domínio foi tirado; porém lhes fora dada prolongação de vida até um certo tempo."}, {"numero": 13, "texto": "Eu estava vendo em minhas visões de noite, e eis que estava vindo nas nuvens do céu como um filho do homem; e ele chegou até o Ancião de dias, e o fizeram chegar diante dele."}, {"numero": 14, "texto": "E foi lhe dado domínio, honra, e reino, de modo que todos os povos, nações e línguas lhe serviram; seu domínio é um domínio eterno, que não passará, e seu reino não será destruído."}, {"numero": 15, "texto": "Quanto a mim, Daniel, meu espírito foi perturbado dentro do corpo, e as visões de minha cabeça me espantaram."}, {"numero": 16, "texto": "Cheguei-me a um dos que estavam em pé, e lhe perguntei a verdade acerca de tudo isto. E ele me disse, e me fez saber a interpretação das coisas."}, {"numero": 17, "texto": "Estas grandes animais, que são quatro, são quatro reis, que se levantarão da terra."}, {"numero": 18, "texto": "Mas os santos do Altíssimo receberão o reino; e possuirão o reino para todo o sempre, eternamente."}, {"numero": 19, "texto": "Então tive desejo de saber a verdade acerca do quarto animal, que era tão diferente de todos os outros, muito terrível, que tinha dentes de ferro, e unhas de bronze, que devorava, quebrava em pedaços, e as sobras pisava com seus pés;"}, {"numero": 20, "texto": "Assim como dos dez chifres que estavam em sua cabeça, e do outro que havia subido, de diante do qual três tinham caído; daquele chifre que tinha olhos, e boca que falava coisas arrogantes, e cuja aparência era maior que a de seus companheiros."}, {"numero": 21, "texto": "Eu estava vendo que este chifre fazia guerra contra os santos, e os vencia,"}, {"numero": 22, "texto": "Até que veio o Ancião de dias, e o juízo foi dado em favor dos santos do Altíssimo; e veio o tempo que os santos possuíram o reino."}, {"numero": 23, "texto": "Ele disse assim: O quarto animal será um quarto reino na terra, o qual será diferente de todos os reinos; e devorará toda a terra, e a pisará, e a quebrará em pedaços."}, {"numero": 24, "texto": "E os dez chifres [significam] que daquele reino se levantarão dez reis; e após deles se levantará outro, o qual será diferente dos primeiros, e humilhará a três reis."}, {"numero": 25, "texto": "E falará palavras contra o Altíssimo, e destruirá os santos do Altíssimo; e pensará em mudar os tempos e a lei; e serão entregues em sua mão por um tempo, e tempos, e metade de um tempo."}, {"numero": 26, "texto": "Porém o julgamento começará, e tirarão seu domínio, para que seja destruído e aniquilado até o fim;"}, {"numero": 27, "texto": "E o reino, o domínio, e a majestade dos reinos debaixo de todo o céu, será dado ao povo dos santos do Altíssimo; seu reino será um reino eterno, e todos os domínios lhe servirão e obedecerão."}, {"numero": 28, "texto": "Até aqui foi o fim do relato. Quanto a mim, Daniel, meus pensamentos me espantavam muito, e mudou-se meu semblante em mim; mas guardei o relato em meu coração."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 7, 'en', '[{"numero": 1, "texto": "In the first year of Belshazzar king of Babylon Daniel had a dream and visions of his head upon his bed: then he wrote the dream, and told the sum of the matters."}, {"numero": 2, "texto": "Daniel spake and said, I saw in my vision by night, and, behold, the four winds of the heaven strove upon the great sea."}, {"numero": 3, "texto": "And four great beasts came up from the sea, diverse one from another."}, {"numero": 4, "texto": "The first was like a lion, and had eagle''s wings: I beheld till the wings thereof were plucked, and it was lifted up from the earth, and made stand upon the feet as a man, and a man''s heart was given to it."}, {"numero": 5, "texto": "And behold another beast, a second, like to a bear, and it raised up itself on one side, and it had three ribs in the mouth of it between the teeth of it: and they said thus unto it, Arise, devour much flesh."}, {"numero": 6, "texto": "After this I beheld, and lo another, like a leopard, which had upon the back of it four wings of a fowl; the beast had also four heads; and dominion was given to it."}, {"numero": 7, "texto": "After this I saw in the night visions, and behold a fourth beast, dreadful and terrible, and strong exceedingly; and it had great iron teeth: it devoured and brake in pieces, and stamped the residue with the feet of it: and it was diverse from all the beasts that were before it; and it had ten horns."}, {"numero": 8, "texto": "I considered the horns, and, behold, there came up among them another little horn, before whom there were three of the first horns plucked up by the roots: and, behold, in this horn were eyes like the eyes of man, and a mouth speaking great things."}, {"numero": 9, "texto": "I beheld till the thrones were cast down, and the Ancient of days did sit, whose garment was white as snow, and the hair of his head like the pure wool: his throne was like the fiery flame, and his wheels as burning fire."}, {"numero": 10, "texto": "A fiery stream issued and came forth from before him: thousand thousands ministered unto him, and ten thousand times ten thousand stood before him: the judgment was set, and the books were opened."}, {"numero": 11, "texto": "I beheld then because of the voice of the great words which the horn spake: I beheld even till the beast was slain, and his body destroyed, and given to the burning flame."}, {"numero": 12, "texto": "As concerning the rest of the beasts, they had their dominion taken away: yet their lives were prolonged for a season and time."}, {"numero": 13, "texto": "I saw in the night visions, and, behold, one like the Son of man came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him."}, {"numero": 14, "texto": "And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed."}, {"numero": 15, "texto": "I Daniel was grieved in my spirit in the midst of my body, and the visions of my head troubled me."}, {"numero": 16, "texto": "I came near unto one of them that stood by, and asked him the truth of all this. So he told me, and made me know the interpretation of the things."}, {"numero": 17, "texto": "These great beasts, which are four, are four kings, which shall arise out of the earth."}, {"numero": 18, "texto": "But the saints of the most High shall take the kingdom, and possess the kingdom for ever, even for ever and ever."}, {"numero": 19, "texto": "Then I would know the truth of the fourth beast, which was diverse from all the others, exceeding dreadful, whose teeth were of iron, and his nails of brass; which devoured, brake in pieces, and stamped the residue with his feet;"}, {"numero": 20, "texto": "And of the ten horns that were in his head, and of the other which came up, and before whom three fell; even of that horn that had eyes, and a mouth that spake very great things, whose look was more stout than his fellows."}, {"numero": 21, "texto": "I beheld, and the same horn made war with the saints, and prevailed against them;"}, {"numero": 22, "texto": "Until the Ancient of days came, and judgment was given to the saints of the most High; and the time came that the saints possessed the kingdom."}, {"numero": 23, "texto": "Thus he said, The fourth beast shall be the fourth kingdom upon earth, which shall be diverse from all kingdoms, and shall devour the whole earth, and shall tread it down, and break it in pieces."}, {"numero": 24, "texto": "And the ten horns out of this kingdom are ten kings that shall arise: and another shall rise after them; and he shall be diverse from the first, and he shall subdue three kings."}, {"numero": 25, "texto": "And he shall speak great words against the most High, and shall wear out the saints of the most High, and think to change times and laws: and they shall be given into his hand until a time and times and the dividing of time."}, {"numero": 26, "texto": "But the judgment shall sit, and they shall take away his dominion, to consume and to destroy it unto the end."}, {"numero": 27, "texto": "And the kingdom and dominion, and the greatness of the kingdom under the whole heaven, shall be given to the people of the saints of the most High, whose kingdom is an everlasting kingdom, and all dominions shall serve and obey him."}, {"numero": 28, "texto": "Hitherto is the end of the matter. As for me Daniel, my cogitations much troubled me, and my countenance changed in me: but I kept the matter in my heart."}]'::jsonb, 'King James Version'),
  ('Dn', 7, 'fr', '[{"numero": 1, "texto": "La première année de Belschatsar, roi de Babylone, Daniel eut un songe et des visions de son esprit, pendant qu''''il était sur sa couche. Ensuite il écrivit le songe, et raconta les principales choses."}, {"numero": 2, "texto": "Daniel commença et dit: Je regardais pendant ma vision nocturne, et voici, les quatre vents des cieux firent irruption sur la grande mer."}, {"numero": 3, "texto": "Et quatre grands animaux sortirent de la mer, différents l''''un de l''''autre."}, {"numero": 4, "texto": "Le premier était semblable à un lion, et avait des ailes d''''aigles; je regardai, jusqu''''au moment où ses ailes furent arrachées; il fut enlevé de terre et mis debout sur ses pieds comme un homme, et un coeur d''''homme lui fut donné."}, {"numero": 5, "texto": "Et voici, un second animal était semblable à un ours, et se tenait sur un côté; il avait trois côtes dans la gueule entre les dents, et on lui disait: Lève-toi, mange beaucoup de chair."}, {"numero": 6, "texto": "Après cela je regardai, et voici, un autre était semblable à un léopard, et avait sur le dos quatre ailes comme un oiseau; cet animal avait quatre têtes, et la domination lui fut donnée."}, {"numero": 7, "texto": "Après cela, je regardai pendant mes visions nocturnes, et voici, il y avait un quatrième animal, terrible, épouvantable et extraordinairement fort; il avait de grandes dents de fer, il mangeait, brisait, et il foulait aux pieds ce qui restait; il était différent de tous les animaux précédents, et il avait dix cornes."}, {"numero": 8, "texto": "Je considérai les cornes, et voici, une autre petite corne sortit du milieu d''''elles, et trois des premières cornes furent arrachées devant cette corne; et voici, elle avait des yeux comme des yeux d''''homme, et une bouche, qui parlait avec arrogance."}, {"numero": 9, "texto": "Je regardai, pendant que l''''on plaçait des trônes. Et l''''ancien des jours s''''assit. Son vêtement était blanc comme la neige, et les cheveux de sa tête étaient comme de la laine pure; son trône était comme des flammes de feu, et les roues comme un feu ardent."}, {"numero": 10, "texto": "Un fleuve de feu coulait et sortait de devant lui. Mille milliers le servaient, et dix mille millions se tenaient en sa présence. Les juges s''''assirent, et les livres furent ouverts."}, {"numero": 11, "texto": "Je regardai alors, à cause des paroles arrogantes que prononçait la corne; et tandis que je regardais, l''''animal fut tué, et son corps fut anéanti, livré au feu pour être brûlé."}, {"numero": 12, "texto": "Les autres animaux furent dépouillés de leur puissance, mais une prolongation de vie leur fut accordée jusqu''''à un certain temps."}, {"numero": 13, "texto": "Je regardai pendant mes visions nocturnes, et voici, sur les nuées des cieux arriva quelqu''''un de semblable à un fils de l''''homme; il s''''avança vers l''''ancien des jours, et on le fit approcher de lui."}, {"numero": 14, "texto": "On lui donna la domination, la gloire et le règne; et tous les peuples, les nations, et les hommes de toutes langues le servirent. Sa domination est une domination éternelle qui ne passera point, et son règne ne sera jamais détruit."}, {"numero": 15, "texto": "Moi, Daniel, j''''eus l''''esprit troublé au dedans de moi, et les visions de ma tête m''''effrayèrent."}, {"numero": 16, "texto": "Je m''''approchai de l''''un de ceux qui étaient là, et je lui demandai ce qu''''il y avait de vrai dans toutes ces choses. Il me le dit, et m''''en donna l''''explication:"}, {"numero": 17, "texto": "Ces quatre grands animaux, ce sont quatre rois qui s''''élèveront de la terre;"}, {"numero": 18, "texto": "mais les saints du Très-Haut recevront le royaume, et ils posséderont le royaume éternellement, d''''éternité en éternité."}, {"numero": 19, "texto": "Ensuite je désirai savoir la vérité sur le quatrième animal, qui était différent de tous les autres, extrêmement terrible, qui avait des dents de fer et des ongles d''''airain, qui mangeait, brisait, et foulait aux pieds ce qui restait;"}, {"numero": 20, "texto": "et sur les dix cornes qu''''il avait à la tête, et sur l''''autre qui était sortie et devant laquelle trois étaient tombées, sur cette corne qui avait des yeux, une bouche parlant avec arrogance, et une plus grande apparence que les autres."}, {"numero": 21, "texto": "Je vis cette corne faire la guerre aux saints, et l''''emporter sur eux,"}, {"numero": 22, "texto": "jusqu''''au moment où l''''ancien des jours vint donner droit aux saints du Très-Haut, et le temps arriva où les saints furent en possession du royaume."}, {"numero": 23, "texto": "Il me parla ainsi: Le quatrième animal, c''''est un quatrième royaume qui existera sur la terre, différent de tous les royaumes, et qui dévorera toute la terre, la foulera et la brisera."}, {"numero": 24, "texto": "Les dix cornes, ce sont dix rois qui s''''élèveront de ce royaume. Un autre s''''élèvera après eux, il sera différent des premiers, et il abaissera trois rois."}, {"numero": 25, "texto": "Il prononcera des paroles contre le Très-Haut, il opprimera les saints du Très Haut, et il espérera changer les temps et la loi; et les saints seront livrés entre ses mains pendant un temps, des temps, et la moitié d''''un temps."}, {"numero": 26, "texto": "Puis viendra le jugement, et on lui ôtera sa domination, qui sera détruite et anéantie pour jamais."}, {"numero": 27, "texto": "Le règne, la domination, et la grandeur de tous les royaumes qui sont sous les cieux, seront donnés au peuple des saints du Très-Haut. Son règne est un règne éternel, et tous les dominateurs le serviront et lui obéiront."}, {"numero": 28, "texto": "Ici finirent les paroles. Moi, Daniel, je fus extrêmement troublé par mes pensées, je changeai de couleur, et je conservai ces paroles dans mon coeur."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 7, 'es', '[{"numero": 1, "texto": "EN el primer año de Belsasar rey de Babilonia, vió Daniel un sueño y visiones de su cabeza en su cama: luego escribió el sueño, y notó la suma de los negocios."}, {"numero": 2, "texto": "Habló Daniel y dijo: Veía yo en mi visión de noche, y he aquí que los cuatro vientos del cielo combatían en la gran mar."}, {"numero": 3, "texto": "Y cuatro bestias grandes, diferentes la una de la otra, subían de la mar."}, {"numero": 4, "texto": "La primera era como león, y tenía alas de águila. Yo estaba mirando hasta tanto que sus alas fueron arrancadas, y fué quitada de la tierra; y púsose enhiesta sobre los pies á manera de hombre, y fuéle dado corazón de hombre."}, {"numero": 5, "texto": "Y he aquí otra segunda bestia, semejante á un oso, la cual se puso al un lado, y tenía en su boca tres costillas entre sus dientes; y fuéle dicho así: Levántate, traga carne mucha."}, {"numero": 6, "texto": "Después de esto yo miraba, y he aquí otra, semejante á un tigre, y tenía cuatro alas de ave en sus espaldas: tenía también esta bestia cuatro cabezas; y fuéle dada potestad."}, {"numero": 7, "texto": "Después de esto miraba yo en las visiones de la noche, y he aquí la cuarta bestia, espantosa y terrible, y en grande manera fuerte; la cual tenía unos dientes grandes de hierro: devoraba y desmenuzaba, y las sobras hollaba con sus pies: y era muy diferente de todas las bestias que habían sido antes de ella, y tenía diez cuernos."}, {"numero": 8, "texto": "Estando yo contemplando los cuernos, he aquí que otro cuerno pequeño subía entre ellos, y delante de él fueron arrancados tres cuernos de los primeros; y he aquí, en este cuerno había ojos como ojos de hombre, y una boca que hablaba grandezas."}, {"numero": 9, "texto": "Estuve mirando hasta que fueron puestas sillas: y un Anciano de grande edad se sentó, cuyo vestido era blanco como la nieve, y el pelo de su cabeza como lana limpia; su silla llama de fuego, sus ruedas fuego ardiente."}, {"numero": 10, "texto": "Un río de fuego procedía y salía de delante de él: millares de millares le servían, y millones de millones asistían delante de él: el Juez se sentó, y los libros se abrieron."}, {"numero": 11, "texto": "Yo entonces miraba á causa de la voz de las grandes palabras que hablaba el cuerno; miraba hasta tanto que mataron la bestia, y su cuerpo fué deshecho, y entregado para ser quemado en el fuego."}, {"numero": 12, "texto": "Habían también quitado á las otras bestias su señorío, y les había sido dada prolongación de vida hasta cierto tiempo."}, {"numero": 13, "texto": "Miraba yo en la visión de la noche, y he aquí en las nubes del cielo como un hijo de hombre que venía, y llegó hasta el Anciano de grande edad, é hiciéronle llegar delante de él."}, {"numero": 14, "texto": "Y fuéle dado señorío, y gloria, y reino; y todos los pueblos, naciones y lenguas le sirvieron; su señorío, señorío eterno, que no será transitorio, y su reino que no se corromperá."}, {"numero": 15, "texto": "Mi espíritu fué turbado, yo Daniel, en medio de mi cuerpo, y las visiones de mi cabeza me asombraron."}, {"numero": 16, "texto": "Lleguéme á uno de los que asistían, y preguntéle la verdad acerca de todo esto. Y hablóme, y declaróme la interpretación de las cosas."}, {"numero": 17, "texto": "Estas grandes bestias, las cuales son cuatro, cuatro reyes son, que se levantarán en la tierra."}, {"numero": 18, "texto": "Después tomarán el reino los santos del Altísimo, y poseerán el reino hasta el siglo, y hasta el siglo de los siglos."}, {"numero": 19, "texto": "Entonces tuve deseo de saber la verdad acerca de la cuarta bestia, que tan diferente era de todas las otras, espantosa en gran manera, que tenía dientes de hierro, y sus uñas de metal, que devoraba y desmenuzaba, y las sobras hollaba con sus pies:"}, {"numero": 20, "texto": "Asimismo acerca de los diez cuernos que tenía en su cabeza, y del otro que había subido, de delante del cual habían caído tres: y este mismo cuerno tenía ojos, y boca que hablaba grandezas, y su parecer mayor que el de sus compañeros."}, {"numero": 21, "texto": "Y veía yo que este cuerno hacía guerra contra los santos, y los vencía,"}, {"numero": 22, "texto": "Hasta tanto que vino el Anciano de grande edad, y se dió el juicio á los santos del Altísimo; y vino el tiempo, y los santos poseyeron el reino."}, {"numero": 23, "texto": "Dijo así: La cuarta bestia será un cuarto reino en la tierra, el cual será más grande que todos los otros reinos, y á toda la tierra devorará, y la hollará, y la despedazará."}, {"numero": 24, "texto": "Y los diez cuernos significan que de aquel reino se levantarán diez reyes; y tras ellos se levantará otro, el cual será mayor que los primeros, y á tres reyes derribará."}, {"numero": 25, "texto": "Y hablará palabras contra el Altísimo, y á los santos del Altísimo quebrantará, y pensará en mudar los tiempos y la ley: y entregados serán en su mano hasta tiempo, y tiempos, y el medio de un tiempo."}, {"numero": 26, "texto": "Empero se sentará el juez, y quitaránle su señorío, para que sea destruído y arruinado hasta el extremo;"}, {"numero": 27, "texto": "Y que el reino, y el señorío, y la majestad de los reinos debajo de todo el cielo, sea dado al pueblo de los santos del Altísimo; cuyo reino es reino eterno, y todos los señoríos le servirán y obedecerán."}, {"numero": 28, "texto": "Hasta aquí fué el fin de la plática. Yo Daniel, mucho me turbaron mis pensamientos, y mi rostro se me mudó: mas guardé en mi corazón el negocio."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 8, 'pt', '[{"numero": 1, "texto": "No terceiro ano do reinado do rei Belsazar, apareceu uma visão a mim, Daniel, depois daquela que tinha me aparecido no princípio."}, {"numero": 2, "texto": "E vi em uma visão, (e aconteceu quando vi, que eu estava na fortaleza de Susã, que é na província de Elão) vi pois em uma visão, enquanto eu estava junto ao rio Ulai."}, {"numero": 3, "texto": "E levantei meus olhos, e vi, e eis um carneiro que estava diante do rio, o qual tinha dois chifres; e os dois chifres eram altos, porém um era mais alto que o outro; e o mais alto subiu por último."}, {"numero": 4, "texto": "Vi que o carneiro dava golpes com os chifres para o ocidente, para o norte, e para o sul; nenhum dos animais podia lhe resistir, nem havia quem se livrasse de seu poder; e fazia conforme sua vontade, e se engrandecia."}, {"numero": 5, "texto": "E enquanto eu estava considerando, eis um bode que vinha do ocidente sobre a face de toda a terra, e ele não tocava a terra; e aquele bode tinha um chifre muito visível entre seus olhos;"}, {"numero": 6, "texto": "E ele veio até o carneiro que tinha os dois chifres, o qual eu havia visto que estava diante do rio, e correu contra ele com o ímpeto de sua força."}, {"numero": 7, "texto": "E o vi chegar junto ao carneiro, e irritou-se contra ele, feriu o carneiro, e quebrou seus dois chifres, pois não havia no carneiro força para resistir-lhe; então o derrubou por terra, e o pisou; não houve quem livrasse o carneiro de seu poder."}, {"numero": 8, "texto": "E o bode se engrandeceu muito; porém, quando estava em sua [maior] força, aquele grande chifre foi quebrado, e em seu lugar subiram [outros] quatro muito visíveis, na direção dos quatro ventos do céu."}, {"numero": 9, "texto": "E de um deles saiu um chifre pequeno, o qual cresceu muito ao sul, ao oriente, e à [terra] formosa."}, {"numero": 10, "texto": "E engrandeceu-se até o exército do céu; e lançou por terra a [alguns] do exército e das estrelas, e as pisou."}, {"numero": 11, "texto": "Engrandeceu-se até contra o príncipe do exército, e por ele foi tirado o contínuo [sacrifício] , e o lugar de seu santuário foi derrubado."}, {"numero": 12, "texto": "E por causa da transgressão, o exército [lhe] foi entregue, assim como o contínuo [sacrifício] ; e lançou a verdade em terra, e teve sucesso naquilo que fez."}, {"numero": 13, "texto": "Depois ouvi um santo que falava; e outro santo disse ao que falava: Até quando [durará] a visão do contínuo [sacrifício] , e da transgressão assoladora, de modo que o santuário e o exército são entregues para serem pisoteados?"}, {"numero": 14, "texto": "E ele me disse: Até duas mil e trezentas tardes e manhãs; e o santuário será purificado."}, {"numero": 15, "texto": "E aconteceu que, tendo eu, Daniel visto a visão, e buscando entendê-la, eis que [alguém] semelhante a um homem se pôs diante de mim."}, {"numero": 16, "texto": "E ouvi uma voz de homem entre as [margens] de Ulai, que gritou e disse: Gabriel, explica a visão a este."}, {"numero": 17, "texto": "Então ele veio para perto de onde eu estava; e quando ele veio, me assombrei, e caí sobre meu rosto. Porém ele me disse: Entende, filho do homem; porque esta visão será para o tempo do fim."}, {"numero": 18, "texto": "E enquanto ele estava falando comigo, adormeci sobre meu rosto em terra; então ele me tocou, e fez ficar de pé."}, {"numero": 19, "texto": "E disse: Eis que eu te farei saber o que irá acontecer no fim da ira; pois será no tempo certo, o fim."}, {"numero": 20, "texto": "Aquele carneiro que viste com dois chifres, são os reis da Média e da Pérsia."}, {"numero": 21, "texto": "Porém o bode peludo é o rei da Grécia; e o chifre grande que tinha entre seus olhos é o primeiro rei."}, {"numero": 22, "texto": "E quanto a ter sido quebrado, e terem surgido quatro em seu lugar, [significa] que quatro reinos surgirão daquela nação, mas não com a força dele."}, {"numero": 23, "texto": "E ao fim do império deles, quando os transgressores se acabarem, se levantará um rei de rosto feroz, e entendido em astúcias."}, {"numero": 24, "texto": "E sua força ganhará vigor, mas não com sua própria força; e destruirá terrivelmente, e terá sucesso naquilo que fizer; e destruirá os fortes e o povo dos santos."}, {"numero": 25, "texto": "E com sua inteligência fará prosperar o engano em seu poder; e em seu coração se engrandecerá, e com tranquilidade destruirá a muitos; e se levantará contra o Príncipe dos príncipes, porém sem mão será quebrantado."}, {"numero": 26, "texto": "E a visão da tarde e a manhã que foi dita é verdadeira; tu, porém guarda em segredo a visão, porque é para muitos dias."}, {"numero": 27, "texto": "E eu, Daniel, enfraqueci, e fiquei doente por [alguns] dias; depois me levantei, e tratei dos negócios do do rei; porém continuei espantado acerca da visão, e não havia quem a entendesse."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 8, 'en', '[{"numero": 1, "texto": "In the third year of the reign of king Belshazzar a vision appeared unto me, even unto me Daniel, after that which appeared unto me at the first."}, {"numero": 2, "texto": "And I saw in a vision; and it came to pass, when I saw, that I was at Shushan in the palace, which is in the province of Elam; and I saw in a vision, and I was by the river of Ulai."}, {"numero": 3, "texto": "Then I lifted up mine eyes, and saw, and, behold, there stood before the river a ram which had two horns: and the two horns were high; but one was higher than the other, and the higher came up last."}, {"numero": 4, "texto": "I saw the ram pushing westward, and northward, and southward; so that no beasts might stand before him, neither was there any that could deliver out of his hand; but he did according to his will, and became great."}, {"numero": 5, "texto": "And as I was considering, behold, an he goat came from the west on the face of the whole earth, and touched not the ground: and the goat had a notable horn between his eyes."}, {"numero": 6, "texto": "And he came to the ram that had two horns, which I had seen standing before the river, and ran unto him in the fury of his power."}, {"numero": 7, "texto": "And I saw him come close unto the ram, and he was moved with choler against him, and smote the ram, and brake his two horns: and there was no power in the ram to stand before him, but he cast him down to the ground, and stamped upon him: and there was none that could deliver the ram out of his hand."}, {"numero": 8, "texto": "Therefore the he goat waxed very great: and when he was strong, the great horn was broken; and for it came up four notable ones toward the four winds of heaven."}, {"numero": 9, "texto": "And out of one of them came forth a little horn, which waxed exceeding great, toward the south, and toward the east, and toward the pleasant land."}, {"numero": 10, "texto": "And it waxed great, even to the host of heaven; and it cast down some of the host and of the stars to the ground, and stamped upon them."}, {"numero": 11, "texto": "Yea, he magnified himself even to the prince of the host, and by him the daily sacrifice was taken away, and the place of the sanctuary was cast down."}, {"numero": 12, "texto": "And an host was given him against the daily sacrifice by reason of transgression, and it cast down the truth to the ground; and it practised, and prospered."}, {"numero": 13, "texto": "Then I heard one saint speaking, and another saint said unto that certain saint which spake, How long shall be the vision concerning the daily sacrifice, and the transgression of desolation, to give both the sanctuary and the host to be trodden under foot?"}, {"numero": 14, "texto": "And he said unto me, Unto two thousand and three hundred days; then shall the sanctuary be cleansed."}, {"numero": 15, "texto": "And it came to pass, when I, even I Daniel, had seen the vision, and sought for the meaning, then, behold, there stood before me as the appearance of a man."}, {"numero": 16, "texto": "And I heard a man''s voice between the banks of Ulai, which called, and said, Gabriel, make this man to understand the vision."}, {"numero": 17, "texto": "So he came near where I stood: and when he came, I was afraid, and fell upon my face: but he said unto me, Understand, O son of man: for at the time of the end shall be the vision."}, {"numero": 18, "texto": "Now as he was speaking with me, I was in a deep sleep on my face toward the ground: but he touched me, and set me upright."}, {"numero": 19, "texto": "And he said, Behold, I will make thee know what shall be in the last end of the indignation: for at the time appointed the end shall be."}, {"numero": 20, "texto": "The ram which thou sawest having two horns are the kings of Media and Persia."}, {"numero": 21, "texto": "And the rough goat is the king of Grecia: and the great horn that is between his eyes is the first king."}, {"numero": 22, "texto": "Now that being broken, whereas four stood up for it, four kingdoms shall stand up out of the nation, but not in his power."}, {"numero": 23, "texto": "And in the latter time of their kingdom, when the transgressors are come to the full, a king of fierce countenance, and understanding dark sentences, shall stand up."}, {"numero": 24, "texto": "And his power shall be mighty, but not by his own power: and he shall destroy wonderfully, and shall prosper, and practise, and shall destroy the mighty and the holy people."}, {"numero": 25, "texto": "And through his policy also he shall cause craft to prosper in his hand; and he shall magnify himself in his heart, and by peace shall destroy many: he shall also stand up against the Prince of princes; but he shall be broken without hand."}, {"numero": 26, "texto": "And the vision of the evening and the morning which was told is true: wherefore shut thou up the vision; for it shall be for many days."}, {"numero": 27, "texto": "And I Daniel fainted, and was sick certain days; afterward I rose up, and did the king''s business; and I was astonished at the vision, but none understood it."}]'::jsonb, 'King James Version'),
  ('Dn', 8, 'fr', '[{"numero": 1, "texto": "La troisième année du règne du roi Belschatsar, moi, Daniel, j''''eus une vision, outre celle que j''''avais eue précédemment."}, {"numero": 2, "texto": "Lorsque j''''eus cette vision, il me sembla que j''''étais à Suse, la capitale, dans la province d''''Elam; et pendant ma vision, je me trouvais près du fleuve d''''Ulaï."}, {"numero": 3, "texto": "Je levai les yeux, je regardai, et voici, un bélier se tenait devant le fleuve, et il avait des cornes; ces cornes étaient hautes, mais l''''une était plus haute que l''''autre, et elle s''''éleva la dernière."}, {"numero": 4, "texto": "Je vis le bélier qui frappait de ses cornes à l''''occident, au septentrion et au midi; aucun animal ne pouvait lui résister, et il n''''y avait personne pour délivrer ses victimes; il faisait ce qu''''il voulait, et il devint puissant."}, {"numero": 5, "texto": "Comme je regardais attentivement, voici, un bouc venait de l''''occident, et parcourait toute la terre à sa surface, sans la toucher; ce bouc avait une grande corne entre les yeux."}, {"numero": 6, "texto": "Il arriva jusqu''''au bélier qui avait des cornes, et que j''''avais vu se tenant devant le fleuve, et il courut sur lui dans toute sa fureur."}, {"numero": 7, "texto": "Je le vis qui s''''approchait du bélier et s''''irritait contre lui; il frappa le bélier et lui brisa les deux cornes, sans que le bélier eût la force de lui résister; il le jeta par terre et le foula, et il n''''y eut personne pour délivrer le bélier."}, {"numero": 8, "texto": "Le bouc devint très puissant; mais lorsqu''''il fut puissant, sa grande corne se brisa. Quatre grandes cornes s''''élevèrent pour la remplacer, aux quatre vents des cieux."}, {"numero": 9, "texto": "De l''''une d''''elles sortit une petite corne, qui s''''agrandit beaucoup vers le midi, vers l''''orient, et vers le plus beau des pays."}, {"numero": 10, "texto": "Elle s''''éleva jusqu''''à l''''armée des cieux, elle fit tomber à terre une partie de cette armée et des étoiles, et elle les foula."}, {"numero": 11, "texto": "Elle s''''éleva jusqu''''au chef de l''''armée, lui enleva le sacrifice perpétuel, et renversa le lieu de son sanctuaire."}, {"numero": 12, "texto": "L''''armée fut livrée avec le sacrifice perpétuel, à cause du péché; la corne jeta la vérité par terre, et réussit dans ses entreprises."}, {"numero": 13, "texto": "J''''entendis parler un saint; et un autre saint dit à celui qui parlait: Pendant combien de temps s''''accomplira la vision sur le sacrifice perpétuel et sur le péché dévastateur? Jusques à quand le sanctuaire et l''''armée seront-ils foulés?"}, {"numero": 14, "texto": "Et il me dit: Deux mille trois cents soirs et matins; puis le sanctuaire sera purifié."}, {"numero": 15, "texto": "Tandis que moi, Daniel, j''''avais cette vision et que je cherchais à la comprendre, voici, quelqu''''un qui avait l''''apparence d''''un homme se tenait devant moi."}, {"numero": 16, "texto": "Et j''''entendis la voix d''''un homme au milieu de l''''Ulaï; il cria et dit: Gabriel, explique-lui la vision."}, {"numero": 17, "texto": "Il vint alors près du lieu où j''''étais; et à son approche, je fus effrayé, et je tombai sur ma face. Il me dit: Sois attentif, fils de l''''homme, car la vision concerne un temps qui sera la fin."}, {"numero": 18, "texto": "Comme il me parlait, je restai frappé d''''étourdissement, la face contre terre. Il me toucha, et me fit tenir debout à la place où je me trouvais."}, {"numero": 19, "texto": "Puis il me dit: Je vais t''''apprendre, ce qui arrivera au terme de la colère, car il y a un temps marqué pour la fin."}, {"numero": 20, "texto": "Le bélier que tu as vu, et qui avait des cornes, ce sont les rois des Mèdes et des Perses."}, {"numero": 21, "texto": "Le bouc, c''''est le roi de Javan, La grande corne entre ses yeux, c''''est le premier roi."}, {"numero": 22, "texto": "Les quatre cornes qui se sont élevées pour remplacer cette corne brisée, ce sont quatre royaumes qui s''''élèveront de cette nation, mais qui n''''auront pas autant de force."}, {"numero": 23, "texto": "A la fin de leur domination, lorsque les pécheurs seront consumés, il s''''élèvera un roi impudent et artificieux."}, {"numero": 24, "texto": "Sa puissance s''''accroîtra, mais non par sa propre force; il fera d''''incroyables ravages, il réussira dans ses entreprises, il détruira les puissants et le peuple des saints."}, {"numero": 25, "texto": "A cause de sa prospérité et du succès de ses ruses, il aura de l''''arrogance dans le coeur, il fera périr beaucoup d''''hommes qui vivaient paisiblement, et il s''''élèvera contre le chef des chefs; mais il sera brisé, sans l''''effort d''''aucune main."}, {"numero": 26, "texto": "Et la vision des soirs et des matins, dont il s''''agit, est véritable. Pour toi, tiens secrète cette vision, car elle se rapporte à des temps éloignés."}, {"numero": 27, "texto": "Moi, Daniel, je fus plusieurs jours languissant et malade; puis je me levai, et je m''''occupai des affaires du roi. J''''étais étonné de la vision, et personne n''''en eut connaissance."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 8, 'es', '[{"numero": 1, "texto": "EN el año tercero del reinado del rey Belsasar, me apareció una visión á mí, Daniel, después de aquella que me había aparecido antes."}, {"numero": 2, "texto": "Vi en visión, (y aconteció cuando vi, que yo estaba en Susán, que es cabecera del reino en la provincia de Persia;) vi pues en visión, estando junto al río Ulai,"}, {"numero": 3, "texto": "Y alcé mis ojos, y miré, y he aquí un carnero que estaba delante del río, el cual tenía dos cuernos: y aunque eran altos, el uno era más alto que el otro; y el más alto subió á la postre."}, {"numero": 4, "texto": "Vi que el carnero hería con los cuernos al poniente, al norte, y al mediodía, y que ninguna bestia podía parar delante de él, ni había quien escapase de su mano: y hacía conforme á su voluntad, y engrandecíase."}, {"numero": 5, "texto": "Y estando yo considerando, he aquí un macho de cabrío venía de la parte del poniente sobre la haz de toda la tierra, el cual no tocaba la tierra: y tenía aquel macho de cabrío un cuerno notable entre sus ojos:"}, {"numero": 6, "texto": "Y vino hasta el carnero que tenía los dos cuernos, al cual había yo visto que estaba delante del río, y corrió contra él con la ira de su fortaleza."}, {"numero": 7, "texto": "Y vilo que llegó junto al carnero, y levantóse contra él, é hiriólo, y quebró sus dos cuernos, porque en el carnero no había fuerzas para parar delante de él: derribólo por tanto en tierra, y hollólo; ni hubo quien librase al carnero de su mano."}, {"numero": 8, "texto": "Y engrandecióse en gran manera el macho de cabrío; y estando en su mayor fuerza, aquel gran cuerno fué quebrado, y en su lugar subieron otros cuatro maravillosos hacia los cuatro vientos del cielo."}, {"numero": 9, "texto": "Y del uno de ellos salió un cuerno pequeño, el cual creció mucho al mediodía, y al oriente, y hacia la tierra deseable."}, {"numero": 10, "texto": "Y engrandecióse hasta el ejército del cielo; y parte del ejército y de las estrellas echó por tierra, y las holló."}, {"numero": 11, "texto": "Aun contra el príncipe de la fortaleza se engrandeció, y por él fué quitado el continuo sacrificio, y el lugar de su santuario fué echado por tierra."}, {"numero": 12, "texto": "Y el ejército fuéle entregado á causa de la prevaricación sobre el continuo sacrificio: y echó por tierra la verdad, é hizo cuanto quiso, y sucedióle prósperamente."}, {"numero": 13, "texto": "Y oí un santo que hablaba; y otro de los santos dijo á aquél que hablaba: ¿Hasta cuándo durará la visión del continuo sacrificio, y la prevaricación asoladora que pone el santuario y el ejército para ser hollados?"}, {"numero": 14, "texto": "Y él me dijo: Hasta dos mil y trescientos días de tarde y mañana; y el santuario será purificado."}, {"numero": 15, "texto": "Y acaeció que estando yo Daniel considerando la visión, y buscando su inteligencia, he aquí, como una semejanza de hombre se puso delante de mí."}, {"numero": 16, "texto": "Y oí una voz de hombre entre las riberas de Ulai, que gritó y dijo: Gabriel, enseña la visión á éste."}, {"numero": 17, "texto": "Vino luego cerca de donde yo estaba; y con su venida me asombré, y caí sobre mi rostro. Empero él me dijo: Entiende, hijo del hombre, porque al tiempo se cumplirá la visión."}, {"numero": 18, "texto": "Y estando él hablando conmigo, caí dormido en tierra sobre mi rostro: y él me tocó, é hízome estar en pie."}, {"numero": 19, "texto": "Y dijo: He aquí yo te enseñaré lo que ha de venir en el fin de la ira: porque al tiempo se cumplirá:"}, {"numero": 20, "texto": "Aquel carnero que viste, que tenía cuernos, son los reyes de Media y de Persia."}, {"numero": 21, "texto": "Y el macho cabrío es el rey de Javán: y el cuerno grande que tenía entre sus ojos es el rey primero."}, {"numero": 22, "texto": "Y que fué quebrado y sucedieron cuatro en su lugar, significa que cuatro reinos sucederán de la nación, mas no en la fortaleza de él."}, {"numero": 23, "texto": "Y al cabo del imperio de éstos, cuando se cumplirán los prevaricadores, levantaráse un rey altivo de rostro, y entendido en dudas."}, {"numero": 24, "texto": "Y su poder se fortalecerá, mas no con fuerza suya; y destruirá maravillosamente, y prosperará; y hará arbitrariamente, y destruirá fuertes y al pueblo de los santos."}, {"numero": 25, "texto": "Y con su sagacidad hará prosperar el engaño en su mano; y en su corazón se engrandecerá, y con paz destruirá á muchos: y contra el príncipe de los príncipes se levantará; mas sin mano será quebrantado."}, {"numero": 26, "texto": "Y la visión de la tarde y la mañana que está dicha, es verdadera: y tú guarda la visión, porque es para muchos días."}, {"numero": 27, "texto": "Y yo Daniel fuí quebrantado, y estuve enfermo algunos días: y cuando convalecí, hice el negocio del rey; mas estaba espantado acerca de la visión, y no había quien la entendiese."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 9, 'pt', '[{"numero": 1, "texto": "No ano primeiro de Dario, filho de Assuero, da nação dos medos, o qual foi posto por rei sobre o reino dos caldeus;"}, {"numero": 2, "texto": "No primeiro ano de seu reinado, eu, Daniel, entendi pelos livros o número de anos, dos quais o SENHOR falara ao profeta Jeremias, que havia de acabar a assolação de Jerusalém, era setenta anos."}, {"numero": 3, "texto": "Então dirigi meu rosto ao Senhor Deus, para [o] buscar com oração e rogos, em jejum, saco, e cinza."}, {"numero": 4, "texto": "E orei ao SENHOR meu Deus, e declarei, dizendo: Ó Senhor, Deus grande e temível, que guarda o pacto e a misericórdia com os que o amam e guardam seus mandamentos;"}, {"numero": 5, "texto": "Nós pecamos, cometemos maldade; agimos perversamente, e fomos rebeldes, por termos nos desviado de teus mandamentos e de teus juízos."}, {"numero": 6, "texto": "Não demos ouvido a teus servos, os profetas, que em teu nome falaram a nossos reis, nossos príncipes, nossos pais, e a todo o povo da terra."}, {"numero": 7, "texto": "A ti, Senhor, pertence a justiça, mas a nós a vergonha de rosto, tal como hoje [estamos] ,todo homem de Judá, os moradores de Jerusalém, e todo Israel, os de perto e os de longe, em todas as terras para onde os tens lançado por causa de sua transgressão com que transgrediram contra ti."}, {"numero": 8, "texto": "Ó SENHOR, a nós [pertence] a vergonha de rosto, a nossos reis, nossos príncipes, e nossos pais; porque contra ti pecamos."}, {"numero": 9, "texto": "Ao SENHOR nosso Deus, pertence a misericórdia e os perdões, ainda que contra ele tenhamos nos rebelado;"}, {"numero": 10, "texto": "E não obedecemos à voz do SENHOR nosso Deus, para andar em suas leis, as quais ele nos deu por meio de seus servos os profetas."}, {"numero": 11, "texto": "E todo Israel transgrediu tua lei, desviando-se para não ouvir tua voz; por isso a maldição, e o juramento que está escrito na lei de Moisés, servo de Deus, foram derramados sobre nós; porque contra ele pecamos."}, {"numero": 12, "texto": "E ele confirmou sua palavra que falou sobre nós, e sobre nossos juízes que nos julgavam, trazendo sobre nós tão grande mal, que nunca havia sido feito debaixo do céu como o que foi feito em Jerusalém."}, {"numero": 13, "texto": "Assim como está escrito na Lei de Moisés, todo aquele mal veio sobre nós; contudo não suplicamos à face do SENHOR nosso Deus, para nos convertermos de nossas maldades, e entender a tua verdade."}, {"numero": 14, "texto": "O SENHOR vigiou sobre o mal, e o trouxe sobre nós; porque justo é o SENHOR nosso Deus em todas suas obras que fez; pois não obedecemos a sua voz."}, {"numero": 15, "texto": "Agora pois, ó Senhor nosso Deus, que tiraste teu povo da terra do Egito com mão poderosa, e fizeste famoso o teu nome até hoje; temos pecado, agimos com maldade."}, {"numero": 16, "texto": "Ó Senhor, segundo todas tuas justiças, desvie agora tua ira e teu furor de sobre a tua cidade Jerusalém, teu santo monte; pois por causa de nossos pecados, e pela maldades de nossos pais, Jerusalém e teu povo foram humilhados por todos os que estão ao nosso redor."}, {"numero": 17, "texto": "Agora pois, ó Deus nosso, ouve a oração de teu servo, e suas súplicas, e faze que teu rosto resplandeça sobre teu santuário assolado, por causa do Senhor."}, {"numero": 18, "texto": "Inclina, ó Deus meu, teus ouvidos, e ouve; abre teus olhos, e olha para nossas assolações, e para a cidade que é chamada pelo teu nome; pois não apresentamos nossas súplicas diante de ti [confiando] em nossas justiças, mas sim em tuas muitas misericórdias."}, {"numero": 19, "texto": "Ouve, Senhor; ó Senhor, perdoa; presta atenção, Senhor, e faze sem demorar, por causa de ti mesmo, Deus meu; pois a tua cidade e teu povo são chamados pelo teu nome."}, {"numero": 20, "texto": "Enquanto eu ainda estava falando e orando, e confessando meu pecado e o pecado de meu povo Israel, e apresentando minha súplica diante do SENHOR meu Deus, pelo monte santo de meu Deus;"}, {"numero": 21, "texto": "Estava eu falando em oração, e aquele varão Gabriel, ao qual eu tinha visto em visão antes, veio voando apressadamente, e me tocou cerca da hora do sacrifício da tarde."}, {"numero": 22, "texto": "E [me] explicou, e falou comigo, dizendo: Daniel, agora saí para te fazer entender o sentido."}, {"numero": 23, "texto": "No princípio de tuas súplicas a palavra saiu, e eu vim para te declarar, pois tu és muito querido. Considera, pois a palavra, e entende a visão."}, {"numero": 24, "texto": "Setenta semanas estão determinadas sobre teu povo e sobre tua santa cidade, para acabar a transgressão, para encerrar o pecado, para expiar a maldade, e para trazer a justiça eterna; para selar a visão e a profecia, e para ungir o Santo dos santos"}, {"numero": 25, "texto": "Sabe pois e entendas: desde a saída da palavra para restaurar e edificar a Jerusalém até o Messias, o Príncipe, haverá sete semanas, e sessenta e duas semanas; voltará a ser construída com praças e muro, porém em tempos angustiosos."}, {"numero": 26, "texto": "E depois das sessenta e duas semanas o Messias será exterminado, e nada terá para si; e o povo do príncipe que virá destruirá à cidade e o santuário; o fim dela será com inundação, e até o fim da guerra estão determinadas assolações."}, {"numero": 27, "texto": "E firmará um pacto com muitos por uma semana; e na metade da semana fará cessar o sacrifício e a oferta de alimentos; depois sobre a asa das abominações será o assolador, e isto até que seja derramado o fim determinado sobre o assolador."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 9, 'en', '[{"numero": 1, "texto": "In the first year of Darius the son of Ahasuerus, of the seed of the Medes, which was made king over the realm of the Chaldeans;"}, {"numero": 2, "texto": "In the first year of his reign I Daniel understood by books the number of the years, whereof the word of the Lord came to Jeremiah the prophet, that he would accomplish seventy years in the desolations of Jerusalem."}, {"numero": 3, "texto": "And I set my face unto the Lord God, to seek by prayer and supplications, with fasting, and sackcloth, and ashes:"}, {"numero": 4, "texto": "And I prayed unto the Lord my God, and made my confession, and said, O Lord, the great and dreadful God, keeping the covenant and mercy to them that love him, and to them that keep his commandments;"}, {"numero": 5, "texto": "We have sinned, and have committed iniquity, and have done wickedly, and have rebelled, even by departing from thy precepts and from thy judgments:"}, {"numero": 6, "texto": "Neither have we hearkened unto thy servants the prophets, which spake in thy name to our kings, our princes, and our fathers, and to all the people of the land."}, {"numero": 7, "texto": "O Lord, righteousness belongeth unto thee, but unto us confusion of faces, as at this day; to the men of Judah, and to the inhabitants of Jerusalem, and unto all Israel, that are near, and that are far off, through all the countries whither thou hast driven them, because of their trespass that they have trespassed against thee."}, {"numero": 8, "texto": "O Lord, to us belongeth confusion of face, to our kings, to our princes, and to our fathers, because we have sinned against thee."}, {"numero": 9, "texto": "To the Lord our God belong mercies and forgivenesses, though we have rebelled against him;"}, {"numero": 10, "texto": "Neither have we obeyed the voice of the Lord our God, to walk in his laws, which he set before us by his servants the prophets."}, {"numero": 11, "texto": "Yea, all Israel have transgressed thy law, even by departing, that they might not obey thy voice; therefore the curse is poured upon us, and the oath that is written in the law of Moses the servant of God, because we have sinned against him."}, {"numero": 12, "texto": "And he hath confirmed his words, which he spake against us, and against our judges that judged us, by bringing upon us a great evil: for under the whole heaven hath not been done as hath been done upon Jerusalem."}, {"numero": 13, "texto": "As it is written in the law of Moses, all this evil is come upon us: yet made we not our prayer before the Lord our God, that we might turn from our iniquities, and understand thy truth."}, {"numero": 14, "texto": "Therefore hath the Lord watched upon the evil, and brought it upon us: for the Lord our God is righteous in all his works which he doeth: for we obeyed not his voice."}, {"numero": 15, "texto": "And now, O Lord our God, that hast brought thy people forth out of the land of Egypt with a mighty hand, and hast gotten thee renown, as at this day; we have sinned, we have done wickedly."}, {"numero": 16, "texto": "O Lord, according to all thy righteousness, I beseech thee, let thine anger and thy fury be turned away from thy city Jerusalem, thy holy mountain: because for our sins, and for the iniquities of our fathers, Jerusalem and thy people are become a reproach to all that are about us."}, {"numero": 17, "texto": "Now therefore, O our God, hear the prayer of thy servant, and his supplications, and cause thy face to shine upon thy sanctuary that is desolate, for the Lord''s sake."}, {"numero": 18, "texto": "O my God, incline thine ear, and hear; open thine eyes, and behold our desolations, and the city which is called by thy name: for we do not present our supplications before thee for our righteousnesses, but for thy great mercies."}, {"numero": 19, "texto": "O Lord, hear; O Lord, forgive; O Lord, hearken and do; defer not, for thine own sake, O my God: for thy city and thy people are called by thy name."}, {"numero": 20, "texto": "And whiles I was speaking, and praying, and confessing my sin and the sin of my people Israel, and presenting my supplication before the Lord my God for the holy mountain of my God;"}, {"numero": 21, "texto": "Yea, whiles I was speaking in prayer, even the man Gabriel, whom I had seen in the vision at the beginning, being caused to fly swiftly, touched me about the time of the evening oblation."}, {"numero": 22, "texto": "And he informed me, and talked with me, and said, O Daniel, I am now come forth to give thee skill and understanding."}, {"numero": 23, "texto": "At the beginning of thy supplications the commandment came forth, and I am come to shew thee; for thou art greatly beloved: therefore understand the matter, and consider the vision."}, {"numero": 24, "texto": "Seventy weeks are determined upon thy people and upon thy holy city, to finish the transgression, and to make an end of sins, and to make reconciliation for iniquity, and to bring in everlasting righteousness, and to seal up the vision and prophecy, and to anoint the most Holy."}, {"numero": 25, "texto": "Know therefore and understand, that from the going forth of the commandment to restore and to build Jerusalem unto the Messiah the Prince shall be seven weeks, and threescore and two weeks: the street shall be built again, and the wall, even in troublous times."}, {"numero": 26, "texto": "And after threescore and two weeks shall Messiah be cut off, but not for himself: and the people of the prince that shall come shall destroy the city and the sanctuary; and the end thereof shall be with a flood, and unto the end of the war desolations are determined."}, {"numero": 27, "texto": "And he shall confirm the covenant with many for one week: and in the midst of the week he shall cause the sacrifice and the oblation to cease, and for the overspreading of abominations he shall make it desolate, even until the consummation, and that determined shall be poured upon the desolate."}]'::jsonb, 'King James Version'),
  ('Dn', 9, 'fr', '[{"numero": 1, "texto": "La première année de Darius, fils d''''Assuérus, de la race des Mèdes, lequel était devenu roi du royaume des Chaldéens,"}, {"numero": 2, "texto": "la première année de son règne, moi, Daniel, je vis par les livres qu''''il devait s''''écouler soixante-dix ans pour les ruines de Jérusalem, d''''après le nombre des années dont l''''Eternel avait parlé à Jérémie, le prophète."}, {"numero": 3, "texto": "Je tournai ma face vers le Seigneur Dieu, afin de recourir à la prière et aux supplications, en jeûnant et en prenant le sac et la cendre."}, {"numero": 4, "texto": "Je priai l''''Eternel, mon Dieu, et je lui fis cette confession: Seigneur, Dieu grand et redoutable, toi qui gardes ton alliance et qui fais miséricorde à ceux qui t''''aiment et qui observent tes commandements!"}, {"numero": 5, "texto": "Nous avons péché, nous avons commis l''''iniquité, nous avons été méchants et rebelles, nous nous sommes détournés de tes commandements et de tes ordonnances."}, {"numero": 6, "texto": "Nous n''''avons pas écouté tes serviteurs, les prophètes, qui ont parlé en ton nom à nos rois, à nos chefs, à nos pères, et à tout le peuple du pays."}, {"numero": 7, "texto": "A toi, Seigneur, est la justice, et à nous la confusion de face, en ce jour, aux hommes de Juda, aux habitants de Jérusalem, et à tout Israël, à ceux qui sont près et à ceux qui sont loin, dans tous les pays où tu les as chassés à cause des infidélités dont ils se sont rendus coupables envers toi."}, {"numero": 8, "texto": "Seigneur, à nous la confusion de face, à nos rois, à nos chefs, et à nos pères, parce que nous avons péché contre toi."}, {"numero": 9, "texto": "Auprès du Seigneur, notre Dieu, la miséricorde et le pardon, car nous avons été rebelles envers lui."}, {"numero": 10, "texto": "Nous n''''avons pas écouté la voix de l''''Eternel, notre Dieu, pour suivre ses lois qu''''il avait mises devant nous par ses serviteurs, les prophètes."}, {"numero": 11, "texto": "Tout Israël a transgressé ta loi, et s''''est détourné pour ne pas écouter ta voix. Alors se sont répandues sur nous les malédictions et les imprécations qui sont écrites dans la loi de Moïse, serviteur de Dieu, parce que nous avons péché contre Dieu."}, {"numero": 12, "texto": "Il a accompli les paroles qu''''il avait prononcées contre nous et contre nos chefs qui nous ont gouvernés, il a fait venir sur nous une grande calamité, et il n''''en est jamais arrivé sous le ciel entier une semblable à celle qui est arrivée à Jérusalem."}, {"numero": 13, "texto": "Comme cela est écrit dans la loi de Moïse, toute cette calamité est venue sur nous; et nous n''''avons pas imploré l''''Eternel, notre Dieu, nous ne nous sommes pas détournés de nos iniquités, nous n''''avons pas été attentifs à ta vérité."}, {"numero": 14, "texto": "L''''Eternel a veillé sur cette calamité, et l''''a fait venir sur nous; car l''''Eternel, notre Dieu, est juste dans toutes les choses qu''''il a faites, mais nous n''''avons pas écouté sa voix."}, {"numero": 15, "texto": "Et maintenant, Seigneur, notre Dieu, toi qui as fait sortir ton peuple du pays d''''Egypte par ta main puissante, et qui t''''es fait un nom comme il l''''est aujourd''''hui, nous avons péché, nous avons commis l''''iniquité."}, {"numero": 16, "texto": "Seigneur, selon ta grande miséricorde, que ta colère et ta fureur se détournent de ta ville de Jérusalem, de ta montagne sainte; car, à cause de nos péchés et des iniquités de nos pères, Jérusalem et ton peuple sont en opprobre à tous ceux qui nous entourent."}, {"numero": 17, "texto": "Maintenant donc, ô notre Dieu, écoute la prière et les supplications de ton serviteur, et, pour l''''amour du Seigneur, fais briller ta face sur ton sanctuaire dévasté!"}, {"numero": 18, "texto": "Mon Dieu, prête l''''oreille et écoute! ouvre les yeux et regarde nos ruines, regarde la ville sur laquelle ton nom est invoqué! Car ce n''''est pas à cause de notre justice que nous te présentons nos supplications, c''''est à cause de tes grandes compassions."}, {"numero": 19, "texto": "Seigneur, écoute! Seigneur, pardonne! Seigneur, sois attentif! agis et ne tarde pas, par amour pour toi, ô mon Dieu! Car ton nom est invoqué sur ta ville et sur ton peuple."}, {"numero": 20, "texto": "Je parlais encore, je priais, je confessais mon péché et le péché de mon peuple d''''Israël, et je présentais mes supplications à l''''Eternel, mon Dieu, en faveur de la sainte montagne de mon Dieu;"}, {"numero": 21, "texto": "je parlais encore dans ma prière, quand l''''homme, Gabriel, que j''''avais vu précédemment dans une vision, s''''approcha de moi d''''un vol rapide, au moment de l''''offrande du soir."}, {"numero": 22, "texto": "Il m''''instruisit, et s''''entretint avec moi. Il me dit: Daniel, je suis venu maintenant pour ouvrir ton intelligence."}, {"numero": 23, "texto": "Lorsque tu as commencé à prier, la parole est sortie, et je viens pour te l''''annoncer; car tu es un bien-aimé. Sois attentif à la parole, et comprends la vision!"}, {"numero": 24, "texto": "Soixante-dix semaines ont été fixées sur ton peuple et sur ta ville sainte, pour faire cesser les transgressions et mettre fin aux péchés, pour expier l''''iniquité et amener la justice éternelle, pour sceller la vision et le prophète, et pour oindre le Saint des saints."}, {"numero": 25, "texto": "Sache-le donc, et comprends! Depuis le moment où la parole a annoncé que Jérusalem sera rebâtie jusqu''''à l''''Oint, au Conducteur, il y a sept semaines; dans soixante-deux semaines, les places et les fossés seront rétablis, mais en des temps fâcheux."}, {"numero": 26, "texto": "Après les soixante-deux semaines, un Oint sera retranché, et il n''''aura pas de successeur. Le peuple d''''un chef qui viendra détruira la ville et le sanctuaire, et sa fin arrivera comme par une inondation; il est arrêté que les dévastations dureront jusqu''''au terme de la guerre."}, {"numero": 27, "texto": "Il fera une solide alliance avec plusieurs pour une semaine, et durant la moitié de la semaine il fera cesser le sacrifice et l''''offrande; le dévastateur commettra les choses les plus abominables, jusqu''''à ce que la ruine et ce qui a été résolu fondent sur le dévastateur."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 9, 'es', '[{"numero": 1, "texto": "EN el año primero de Darío hijo de Assuero, de la nación de los Medos, el cual fué puesto por rey sobre el reino de los Caldeos;"}, {"numero": 2, "texto": "En el año primero de su reinado, yo Daniel miré atentamente en los libros el número de los años, del cual habló Jehová al profeta Jeremías, que había de concluir la asolación de Jerusalem en setenta años."}, {"numero": 3, "texto": "Y volví mi rostro al Señor Dios, buscándole en oración y ruego, en ayuno, y cilicio, y ceniza."}, {"numero": 4, "texto": "Y oré á Jehová mi Dios, y confesé, y dije: Ahora Señor, Dios grande, digno de ser temido, que guardas el pacto y la misericordia con los que te aman y guardan tus mandamientos;"}, {"numero": 5, "texto": "Hemos pecado, hemos hecho iniquidad, hemos obrado impíamente, y hemos sido rebeldes, y nos hemos apartado de tus mandamientos y de tus juicios."}, {"numero": 6, "texto": "No hemos obedecido á tus siervos los profetas, que en tu nombre hablaron á nuestros reyes, y á nuestros príncipes, á nuestros padres, y á todo el pueblo de la tierra."}, {"numero": 7, "texto": "Tuya es, Señor, la justicia, y nuestra la confusión de rostro, como en el día de hoy á todo hombre de Judá, y á los moradores de Jerusalem, y á todo Israel, á los de cerca y á los de lejos, en todas las tierras á donde los has echado á causa de su rebelión con que contra ti se rebelaron."}, {"numero": 8, "texto": "Oh Jehová, nuestra es la confusión de rostro, de nuestros reyes, de nuestros príncipes, y de nuestros padres; porque contra ti pecamos."}, {"numero": 9, "texto": "De Jehová nuestro Dios es el tener misericordia, y el perdonar, aunque contra él nos hemos rebelado;"}, {"numero": 10, "texto": "Y no obedecimos á la voz de Jehová nuestro Dios, para andar en sus leyes, las cuales puso él delante de nosotros por mano de sus siervos los profetas."}, {"numero": 11, "texto": "Y todo Israel traspasó tu ley apartándose para no oir tu voz: por lo cual ha fluído sobre nosotros la maldición, y el juramento que está escrito en la ley de Moisés, siervo de Dios; porque contra él pecamos."}, {"numero": 12, "texto": "Y él ha verificado su palabra que habló sobre nosotros, y sobre nuestros jueces que nos gobernaron, trayendo sobre nosotros tan grande mal; que nunca fué hecho debajo del cielo como el que fué hecho en Jerusalem."}, {"numero": 13, "texto": "Según está escrito en la ley de Moisés, todo aqueste mal vino sobre nosotros: y no hemos rogado á la faz de Jehová nuestro Dios, para convertirnos de nuestras maldades, y entender tu verdad."}, {"numero": 14, "texto": "Veló por tanto Jehová sobre el mal, y trájolo sobre nosotros; porque justo es Jehová nuestro Dios en todas sus obras que hizo, porque no obedecimos á su voz."}, {"numero": 15, "texto": "Ahora pues, Señor Dios nuestro, que sacaste tu pueblo de la tierra de Egipto con mano poderosa, y te hiciste nombre cual en este día; hemos pecado, impíamente hemos hecho."}, {"numero": 16, "texto": "Oh Señor, según todas tus justicias, apártese ahora tu ira y tu furor de sobre tu ciudad Jerusalem, tu santo monte: porque á causa de nuestros pecados, y por la maldad de nuestros padres, Jerusalem y tu pueblo dados son en oprobio á todos en derredor nuestro."}, {"numero": 17, "texto": "Ahora pues, Dios nuestro, oye la oración de tu siervo, y sus ruegos, y haz que tu rostro resplandezca sobre tu santuario asolado, por amor del Señor."}, {"numero": 18, "texto": "Inclina, oh Dios mío, tu oído, y oye; abre tus ojos, y mira nuestros asolamientos, y la ciudad sobre la cual es llamado tu nombre: porque no derramamos nuestros ruegos ante tu acatamiento confiados en nuestras justicias, sino en tus muchas miseraciones."}, {"numero": 19, "texto": "Oye, Señor; oh Señor, perdona; presta oído, Señor, y haz; no pongas dilación, por amor de ti mismo, Dios mío: porque tu nombre es llamado sobre tu ciudad y sobre tu pueblo."}, {"numero": 20, "texto": "Aun estaba hablando, y orando, y confesando mi pecado y el pecado de mi pueblo Israel, y derramaba mi ruego delante de Jehová mi Dios por el monte santo de mi Dios;"}, {"numero": 21, "texto": "Aun estaba hablando en oración, y aquel varón Gabriel, al cual había visto en visión al principio, volando con presteza, me tocó como á la hora del sacrificio de la tarde."}, {"numero": 22, "texto": "E hízome entender, y habló conmigo, y dijo: Daniel, ahora he salido para hacerte entender la declaración."}, {"numero": 23, "texto": "Al principio de tus ruegos salió la palabra, y yo he venido para enseñártela, porque tú eres varón de deseos. Entiende pues la palabra, y entiende la visión."}, {"numero": 24, "texto": "Setenta semanas están determinadas sobre tu pueblo y sobre tu santa ciudad, para acabar la prevaricación, y concluir el pecado, y expiar la iniquidad; y para traer la justicia de los siglos, y sellar la visión y la profecía, y ungir al Santo de los santos."}, {"numero": 25, "texto": "Sepas pues y entiendas, que desde la salida de la palabra para restaurar y edificar á Jerusalem hasta el Mesías Príncipe, habrá siete semanas, y sesenta y dos semanas; tornaráse á edificar la plaza y el muro en tiempos angustiosos."}, {"numero": 26, "texto": "Y después de las sesenta y dos semanas se quitará la vida al Mesías, y no por sí: y el pueblo de un príncipe que ha de venir, destruirá á la ciudad y el santuario; con inundación será el fin de ella, y hasta el fin de la guerra será talada con asolamientos."}, {"numero": 27, "texto": "Y en otra semana confirmará el pacto á muchos, y á la mitad de la semana hará cesar el sacrificio y la ofrenda: después con la muchedumbre de las abominaciones será el desolar, y esto hasta una entera consumación; y derramaráse la ya determinada sobre el pueblo asolado."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 10, 'pt', '[{"numero": 1, "texto": "No terceiro ano de Ciro rei da Pérsia, foi revelada uma palavra a Daniel, cujo nome era chamado Beltessazar; e a palavra é verdadeira, e sobre uma grande guerra; e ele entendeu a palavra, e teve entendimento da visão."}, {"numero": 2, "texto": "Naqueles dias eu, Daniel, me entristeci durante três semanas completas."}, {"numero": 3, "texto": "Não comi alimento agradável, nem carne nem vinho entrou em minha boca, nem me untei com unguento, até que se completassem três semanas."}, {"numero": 4, "texto": "E aos vinte e quatro dias do primeiro mês, estava eu na margem do grande rio Tigre;"}, {"numero": 5, "texto": "Então levantei meus olhos, e olhei, e eis um homem vestido de linho, e cingidos seus lombos de ouro fino de Ufaz;"}, {"numero": 6, "texto": "E seu corpo era como berilo, seu rosto parecia um relâmpago; seus olhos eram como tochas de fogo, e seus braços e seus pés como de cor de bronze polido; e a voz de suas palavras era como a voz de uma multidão."}, {"numero": 7, "texto": "E somente eu, Daniel, vi aquela visão, e os homens que estavam comigo não a viram; porém caiu sobre eles um grande temor, de tal modo que fugiram e se esconderam."}, {"numero": 8, "texto": "Fiquei, pois, eu só, e vi esta grande visão, e não ficou em mim força alguma; antes minha boa aparência se tornou em palidez, sem reter força alguma."}, {"numero": 9, "texto": "Porém ouvi a voz de suas palavras; e enquanto ouvia a voz de suas palavras, eu caí em profundo sono sobre meu rosto, com meu rosto em terra."}, {"numero": 10, "texto": "E eis que uma mão me tocou, e fez que eu me movesse sobre meus joelhos, e sobre as palmas de minhas mãos."}, {"numero": 11, "texto": "E disse-me: Daniel, homem muito querido, entende as palavras que falarei contigo, e levanta-te sobre teus pés; porque agora sou enviado a ti. E enquanto ele falava comigo esta palavra, eu estava tremendo."}, {"numero": 12, "texto": "E ele me disse: Não temas, Daniel; porque desde o primeiro dia em que deste teu coração a entender, e a te afligir na presença de teu Deus, foram ouvidas tuas palavras; e foi por causa de tuas palavras que eu vim."}, {"numero": 13, "texto": "Mas o príncipe do reino da Pérsia se pôs contra mim por vinte e um dias; e eis que Miguel, um dos principais chefes, veio para me ajudar, e eu fiquei ali com os reis da Pérsia."}, {"numero": 14, "texto": "Agora vim para te fazer entender o que irá acontecer a teu povo nos últimos dias; porque a visão ainda é para [muitos] dias;"}, {"numero": 15, "texto": "E tendo ele falado comigo estas palavras, abaixei meu rosto em terra, e emudeci."}, {"numero": 16, "texto": "E eis que [alguém] semelhante aos filhos dos homens tocou meus lábios. Então abri minha boca, e falei, e disse ao que estava diante de mim: Meu senhor, por causa da visão minhas dores se tornam sobre mim, sem que eu retenha força alguma."}, {"numero": 17, "texto": "Como pode, pois, o servo de meu senhor falar com este meu senhor? Pois desde agora não resta força em mim, e não me ficou fôlego."}, {"numero": 18, "texto": "E [aquele] que parecia com um homem me tocou outra vez, e me confortou;"}, {"numero": 19, "texto": "E disse: Não temas, homem querido, paz seja contigo; sê forte! Sê forte! E tendo ele falado comigo, fortaleci-me, e disse: Fale meu senhor, pois tu me fortaleceste."}, {"numero": 20, "texto": "E ele disse: Sabes por que vim ti? Pois agora voltarei para lutar contra o príncipe da Pérsia; e quando eu sair, eis que virá o príncipe da Grécia."}, {"numero": 21, "texto": "Porém eu te declararei o que está escrito na escritura de verdade; e ninguém há que se esforce comigo contra eles, a não ser Miguel, vosso príncipe."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 10, 'en', '[{"numero": 1, "texto": "In the third year of Cyrus king of Persia a thing was revealed unto Daniel, whose name was called Belteshazzar; and the thing was true, but the time appointed was long: and he understood the thing, and had understanding of the vision."}, {"numero": 2, "texto": "In those days I Daniel was mourning three full weeks."}, {"numero": 3, "texto": "I ate no pleasant bread, neither came flesh nor wine in my mouth, neither did I anoint myself at all, till three whole weeks were fulfilled."}, {"numero": 4, "texto": "And in the four and twentieth day of the first month, as I was by the side of the great river, which is Hiddekel;"}, {"numero": 5, "texto": "Then I lifted up mine eyes, and looked, and behold a certain man clothed in linen, whose loins were girded with fine gold of Uphaz:"}, {"numero": 6, "texto": "His body also was like the beryl, and his face as the appearance of lightning, and his eyes as lamps of fire, and his arms and his feet like in colour to polished brass, and the voice of his words like the voice of a multitude."}, {"numero": 7, "texto": "And I Daniel alone saw the vision: for the men that were with me saw not the vision; but a great quaking fell upon them, so that they fled to hide themselves."}, {"numero": 8, "texto": "Therefore I was left alone, and saw this great vision, and there remained no strength in me: for my comeliness was turned in me into corruption, and I retained no strength."}, {"numero": 9, "texto": "Yet heard I the voice of his words: and when I heard the voice of his words, then was I in a deep sleep on my face, and my face toward the ground."}, {"numero": 10, "texto": "And, behold, an hand touched me, which set me upon my knees and upon the palms of my hands."}, {"numero": 11, "texto": "And he said unto me, O Daniel, a man greatly beloved, understand the words that I speak unto thee, and stand upright: for unto thee am I now sent. And when he had spoken this word unto me, I stood trembling."}, {"numero": 12, "texto": "Then said he unto me, Fear not, Daniel: for from the first day that thou didst set thine heart to understand, and to chasten thyself before thy God, thy words were heard, and I am come for thy words."}, {"numero": 13, "texto": "But the prince of the kingdom of Persia withstood me one and twenty days: but, lo, Michael, one of the chief princes, came to help me; and I remained there with the kings of Persia."}, {"numero": 14, "texto": "Now I am come to make thee understand what shall befall thy people in the latter days: for yet the vision is for many days."}, {"numero": 15, "texto": "And when he had spoken such words unto me, I set my face toward the ground, and I became dumb."}, {"numero": 16, "texto": "And, behold, one like the similitude of the sons of men touched my lips: then I opened my mouth, and spake, and said unto him that stood before me, O my lord, by the vision my sorrows are turned upon me, and I have retained no strength."}, {"numero": 17, "texto": "For how can the servant of this my lord talk with this my lord? for as for me, straightway there remained no strength in me, neither is there breath left in me."}, {"numero": 18, "texto": "Then there came again and touched me one like the appearance of a man, and he strengthened me,"}, {"numero": 19, "texto": "And said, O man greatly beloved, fear not: peace be unto thee, be strong, yea, be strong. And when he had spoken unto me, I was strengthened, and said, Let my lord speak; for thou hast strengthened me."}, {"numero": 20, "texto": "Then said he, Knowest thou wherefore I come unto thee? and now will I return to fight with the prince of Persia: and when I am gone forth, lo, the prince of Grecia shall come."}, {"numero": 21, "texto": "But I will shew thee that which is noted in the scripture of truth: and there is none that holdeth with me in these things, but Michael your prince."}]'::jsonb, 'King James Version'),
  ('Dn', 10, 'fr', '[{"numero": 1, "texto": "La troisième année de Cyrus, roi de Perse, une parole fut révélée à Daniel, qu''''on nommait Beltschatsar. Cette parole, qui est véritable, annonce une grande calamité. Il fut attentif à cette parole, et il eut l''''intelligence de la vision."}, {"numero": 2, "texto": "En ce temps-là, moi, Daniel, je fus trois semaines dans le deuil."}, {"numero": 3, "texto": "Je ne mangeai aucun mets délicat, il n''''entra ni viande ni vin dans ma bouche, et je ne m''''oignis point jusqu''''à ce que les trois semaines fussent accomplies."}, {"numero": 4, "texto": "Le vingt-quatrième jour du premier mois, j''''étais au bord du grand fleuve qui est Hiddékel."}, {"numero": 5, "texto": "Je levai les yeux, je regardai, et voici, il y avait un homme vêtu de lin, et ayant sur les reins une ceinture d''''or d''''Uphaz."}, {"numero": 6, "texto": "Son corps était comme de chrysolithe, son visage brillait comme l''''éclair, ses yeux étaient comme des flammes de feu, ses bras et ses pieds ressemblaient à de l''''airain poli, et le son de sa voix était comme le bruit d''''une multitude."}, {"numero": 7, "texto": "Moi, Daniel, je vis seul la vision, et les hommes qui étaient avec moi ne la virent point, mais ils furent saisis d''''une grande frayeur, et ils prirent la fuite pour se cacher."}, {"numero": 8, "texto": "Je restai seul, et je vis cette grande vision; les forces me manquèrent, mon visage changea de couleur et fut décomposé, et je perdis toute vigueur."}, {"numero": 9, "texto": "J''''entendis le son de ses paroles; et comme j''''entendais le son de ses paroles, je tombai frappé d''''étourdissement, la face contre terre."}, {"numero": 10, "texto": "Et voici, une main me toucha, et secoua mes genoux et mes mains."}, {"numero": 11, "texto": "Puis il me dit: Daniel, homme bien-aimé, sois attentif aux paroles que je vais te dire, et tiens-toi debout à la place où tu es; car je suis maintenant envoyé vers toi. Lorsqu''''il m''''eut ainsi parlé, je me tins debout en tremblant."}, {"numero": 12, "texto": "Il me dit: Daniel, ne crains rien; car dès le premier jour où tu as eu à coeur de comprendre, et de t''''humilier devant ton Dieu, tes paroles ont été entendues, et c''''est à cause de tes paroles que je viens."}, {"numero": 13, "texto": "Le chef du royaume de Perse m''''a résisté vingt et un jours; mais voici, Micaël, l''''un des principaux chefs, est venu à mon secours, et je suis demeuré là auprès des rois de Perse."}, {"numero": 14, "texto": "Je viens maintenant pour te faire connaître ce qui doit arriver à ton peuple dans la suite des temps; car la vision concerne encore ces temps-là."}, {"numero": 15, "texto": "Tandis qu''''il m''''adressait ces paroles, je dirigeai mes regards vers la terre, et je gardai le silence."}, {"numero": 16, "texto": "Et voici, quelqu''''un qui avait l''''apparence des fils de l''''homme toucha mes lèvres. J''''ouvris la bouche, je parlai, et je dis à celui qui se tenait devant moi: Mon seigneur, la vision m''''a rempli d''''effroi, et j''''ai perdu toute vigueur."}, {"numero": 17, "texto": "Comment le serviteur de mon seigneur pourrait-il parler à mon seigneur? Maintenant les forces me manquent, et je n''''ai plus de souffle."}, {"numero": 18, "texto": "Alors celui qui avait l''''apparence d''''un homme me toucha de nouveau, et me fortifia."}, {"numero": 19, "texto": "Puis il me dit: Ne crains rien, homme bien-aimé, que la paix soit avec toi! courage, courage! Et comme il me parlait, je repris des forces, et je dis: Que mon seigneur parle, car tu m''''as fortifié."}, {"numero": 20, "texto": "Il me dit: Sais-tu pourquoi je suis venu vers toi? Maintenant je m''''en retourne pour combattre le chef de la Perse; et quand je partirai, voici, le chef de Javan viendra."}, {"numero": 21, "texto": "Mais je veux te faire connaître ce qui est écrit dans le livre de la vérité. Personne ne m''''aide contre ceux-là, excepté Micaël, votre chef."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 10, 'es', '[{"numero": 1, "texto": "EN el tercer año de Ciro rey de Persia, fué revelada palabra á Daniel, cuyo nombre era Beltsasar; y la palabra era verdadera, mas el tiempo fijado era largo: él empero comprendió la palabra, y tuvo inteligencia en la visión."}, {"numero": 2, "texto": "En aquellos días yo Daniel me contristé por espacio de tres semanas."}, {"numero": 3, "texto": "No comí pan delicado, ni entró carne ni vino en mi boca, ni me unté con ungüento, hasta que se cumplieron tres semanas de días."}, {"numero": 4, "texto": "Y á los veinte y cuatro días del mes primero estaba yo á la orilla del gran río Hiddekel;"}, {"numero": 5, "texto": "Y alzando mis ojos miré, y he aquí un varón vestido de lienzos, y ceñidos sus lomos de oro de Uphaz:"}, {"numero": 6, "texto": "Y su cuerpo era como piedra de Tarsis, y su rostro parecía un relámpago, y sus ojos como antorchas de fuego, y sus brazos y sus pies como de color de metal resplandeciente, y la voz de sus palabras como la voz de ejército."}, {"numero": 7, "texto": "Y sólo yo, Daniel, vi aquella visión, y no la vieron los hombres que estaban conmigo; sino que cayó sobre ellos un gran temor, y huyeron, y escondiéronse."}, {"numero": 8, "texto": "Quedé pues yo solo, y vi esta gran visión, y no quedó en mí esfuerzo; antes mi fuerza se me trocó en desmayo, sin retener vigor alguno."}, {"numero": 9, "texto": "Empero oí la voz de sus palabras: y oyendo la voz de sus palabras, estaba yo adormecido sobre mi rostro, y mi rostro en tierra."}, {"numero": 10, "texto": "Y, he aquí, una mano me tocó, é hizo que me moviese sobre mis rodillas, y sobre las palmas de mis manos."}, {"numero": 11, "texto": "Y díjome: Daniel, varón de deseos, está atento á las palabras que te hablaré, y levántate sobre tus pies; porque á ti he sido enviado ahora. Y estando hablando conmigo esto, yo estaba temblando."}, {"numero": 12, "texto": "Y díjome: Daniel, no temas: porque desde el primer día que diste tu corazón á entender, y á afligirte en la presencia de tu Dios, fueron oídas tus palabras; y á causa de tus palabras yo soy venido."}, {"numero": 13, "texto": "Mas el príncipe del reino de Persia se puso contra mí veintiún días: y he aquí, Miguel, uno de los principales príncipes, vino para ayudarme, y yo quedé allí con los reyes de Persia."}, {"numero": 14, "texto": "Soy pues venido para hacerte saber lo que ha de venir á tu pueblo en los postreros días; porque la visión es aún para días."}, {"numero": 15, "texto": "Y estando hablando conmigo semejantes palabras, puse mis ojos en tierra, y enmudecí."}, {"numero": 16, "texto": "Mas he aquí, como una semejanza de hijo de hombre tocó mis labios. Entonces abrí mi boca, y hablé, y dije á aquel que estaba delante de mí: Señor mío, con la visión se revolvieron mis dolores sobre mí, y no me quedó fuerza."}, {"numero": 17, "texto": "¿Cómo pues podrá el siervo de mi señor hablar con este mi señor? porque al instante me faltó la fuerza, y no me ha quedado aliento."}, {"numero": 18, "texto": "Y aquella como semejanza de hombre me tocó otra vez, y me confortó;"}, {"numero": 19, "texto": "Y díjome: Varón de deseos, no temas: paz á ti; ten buen ánimo, y aliéntate. Y hablando él conmigo cobré yo vigor, y dije: Hable mi señor, porque me has fortalecido."}, {"numero": 20, "texto": "Y dijo: ¿Sabes por qué he venido á ti? Porque luego tengo de volver para pelear con el príncipe de los Persas; y en saliendo yo, luego viene el príncipe de Grecia."}, {"numero": 21, "texto": "Empero yo te declararé lo que está escrito en la escritura de verdad: y ninguno hay que se esfuerce conmigo en estas cosas, sino Miguel vuestro príncipe."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 11, 'pt', '[{"numero": 1, "texto": "E eu, no primeiro ano de Dario o medo, estive para confortá-lo e fortalecê-lo."}, {"numero": 2, "texto": "E agora eu te declararei a verdade. Eis que ainda haverá três reis na Pérsia, e o quarto acumulará mais riquezas que todos; e fortificando-se com suas riquezas, despertará a todos contra o reino da Grécia."}, {"numero": 3, "texto": "Depois se levantará um rei poderoso, que reinará com grande domínio, e fará conforme sua vontade."}, {"numero": 4, "texto": "Mas quando ele estiver erguido, seu reino será quebrantado, e repartido nos quatro ventos do céu; porém não a seus descendentes, nem conforme seu domínio com que ele reinou; porque seu reino será arrancado, e será para outros fora destes."}, {"numero": 5, "texto": "E o rei do sul se fortalecerá; mas um de seus príncipes se fortalecerá mais que ele, e reinará; e seus domínio será um grande domínio."}, {"numero": 6, "texto": "Mas ao fim de [alguns] anos eles se aliarão, e a filha do rei do sul virá ao rei do norte para fazer os acordos. Porém ela não poderá reter a força de seu poder; por isso nem ele, nem seu poder persistirá; porque ela será entregue, e os que a tiverem trazido, e seu pai, e ao que a fortalecia naqueles tempos."}, {"numero": 7, "texto": "Mas do renovo de suas raízes um se levantará em seu lugar; e virá com exército, e entrará na fortaleza do rei do norte, e agirá contra eles, e prevalecerá."}, {"numero": 8, "texto": "E até seus deuses com seus príncipes, com seus vasos preciosos de prata e de ouro, levará cativos ao Egito; e por [alguns] anos ele deixará de atacar o rei do norte;"}, {"numero": 9, "texto": "O qual virá ao reino o rei do sul, e voltará para sua terra."}, {"numero": 10, "texto": "Porém os filhos dele se agitarão [para a guerra] ,e ajuntarão uma multidão de grandes exércitos; e certamente avançará, inundará, e passará; e quando voltar, se agitará [em guerra] até sua fortaleza."}, {"numero": 11, "texto": "Então o rei do sul se enfurecerá, e sairá, e lutará contra ele, o rei do norte; e mobiliza uma grande multidão, porém toda aquela multidão será entregue em sua mão."}, {"numero": 12, "texto": "Quando for perdida aquele multidão, seu coração se exaltará; e ainda que derrube muitos milhares; contudo não prevalecerá."}, {"numero": 13, "texto": "E o rei do norte voltará, e porá em campo uma multidão maior que a primeira, e a fim do tempo de [alguns] anos avançará com grande exército e com muitos suprimentos."}, {"numero": 14, "texto": "E naqueles tempos muitos se levantarão contra o rei do sul; e filhos dos violentos de teu povo se levantarão para confirmar a visão, e cairão."}, {"numero": 15, "texto": "Então o rei do norte virá, e levantará cerco, e tomará a cidade forte; e os poderes do sul não poderão subsistir, nem os melhores de seu povo, nem haverá força que possa subsistir."}, {"numero": 16, "texto": "E o que virá contra ele fará sua própria vontade, e não haverá quem possa subsistir diante dele; ele estará na terra gloriosa, e o poder de destruir estará em sua mão."}, {"numero": 17, "texto": "Ele decidirá vir com o poder de todo seu reino; e os corretos com ele, e [assim] fará; e lhe dará uma filha de mulheres para destruir [o reino] ; mas ela não terá sucesso, nem será para proveito dele."}, {"numero": 18, "texto": "Depois virará seu rosto para as terras costeiras, e tomará muitas; mas um príncipe fará cessar sua humilhação por ele, e ainda fará tornar sobre ele sua humilhação."}, {"numero": 19, "texto": "Então virará seu rosto para as fortalezas de sua terra; mas tropeçará e cairá, e não será mais achado."}, {"numero": 20, "texto": "E em seu lugar se levantará um que fará passar um cobrador de impostos para glória real; mas em poucos dias será quebrantado, não por causa de ira nem de batalha."}, {"numero": 21, "texto": "Depois se levantará em seu lugar um ser desprezível, ao qual não darão a honra real; mas virá durante a quietude, e tomará o reino por meio de enganos."}, {"numero": 22, "texto": "E exércitos em grande volume serão repelidos diante dele, e serão quebrantados; assim como também o príncipe do pacto."}, {"numero": 23, "texto": "E depois de fizerem acordos com ele, ele usará engano, e subirá; será fortalecido [mesmo] com pouca gente."}, {"numero": 24, "texto": "Quando houver tranquilidade nas mais prósperas [regiões] da província, ele virá e fará o que nunca fizeram seus pais, nem os pais de seus pais; ele repartirá presa, despojos, e riquezas entre os seus; e voltará seus pensamentos contra as fortalezas; porém [somente] por um tempo."}, {"numero": 25, "texto": "E despertará sua forças e sua coragem contra o rei do sul, com grande exército; e o rei do sul se agitará para a guerra com grande e muito poderoso exército; mas não prevalecerá, porque tramarão planos contra ele."}, {"numero": 26, "texto": "Até os que comerem de sua comida o destruirão; e seu exército será repelido, e muitos cairão mortos."}, {"numero": 27, "texto": "E o coração destes dois reis será para fazer mal, e em uma mesma mesa falarão mentiras; mas isto não terá sucesso, pois ainda [haverá] o fim no tempo determinado."}, {"numero": 28, "texto": "E voltará para sua terra com grande riqueza, e seu coração será contra o pacto santo; e ele fará [o que decidir] , e voltará a sua terra."}, {"numero": 29, "texto": "A certo tempo voltará a vir ao sul; mas a última [vinda] não será como a primeira."}, {"numero": 30, "texto": "Porque navios de Quitim virão contra ele, de modo que ele se entristecerá, voltará, e se indignará contra o pacto santo, e ele fará [o que decidir] ; pois quando voltar, ele dará atenção aos que tiverem abandonado o pacto santo."}, {"numero": 31, "texto": "E tropas virão da parte dele, e profanarão o santuário e a fortaleza; tirarão o contínuo [sacrifício] , e porão uma abominação assoladora."}, {"numero": 32, "texto": "E com lisonjas ele perverterá aos violadores do pacto; mas o povo que conhece a seu Deus com força resistirá."}, {"numero": 33, "texto": "E os entendidos do povo ensinarão a muitos; porém cairão à espada e a fogo, por meio de cativeiro e de despojo, por [muitos] dias."}, {"numero": 34, "texto": "E quando eles caírem, serão ajudados por um pequeno socorro; contudo muitos se aliarão a eles através de enganos."}, {"numero": 35, "texto": "E alguns dos sábios cairão para serem refinados, purificados e limpos, até o tempo do fim; porque [isto] ainda será para o tempo determinado."}, {"numero": 36, "texto": "E o rei fará a sua vontade; e se exaltará, e se engrandecerá sobre todo deus; ele falará coisas arrogantes contra o Deus dos deuses, e será próspero, até que a ira se complete; pois o que está determinado será feito."}, {"numero": 37, "texto": "Ele não respeitará os deuses de seus pais, nem para o preferido das mulheres; nem respeitará deus algum, pois se engrandecerá sobre todos."}, {"numero": 38, "texto": "Mas em seu lugar honrará ao deus das fortalezas, um deus que seus pais nem sequer conheceram; ele o horará com ouro, prata, pedras preciosas, e com coisas de grande valor."}, {"numero": 39, "texto": "E ele atacará fortes fortalezas com o deus estrangeiro; aos que o reconhecerem, ele aumentará a honra; e ele os fará terem domínio sobre muitos, e repartirá a terra por preço."}, {"numero": 40, "texto": "E no tempo do fim o rei do sul lutará contra ele; e o rei do norte levantará como tempestade contra ele, com carruagens, cavaleiros, e muitos navios; e entrará pelas terras, arruinará como se fosse inundação, e passará."}, {"numero": 41, "texto": "E virá à terra gloriosa, e muitos [povos] cairão; mas estes escaparão de sua mão: Edom, Moabe, e os líderes dos filhos de Amom."}, {"numero": 42, "texto": "E estenderá sua mão a [outras] terras, e a terra do Egito não escapará."}, {"numero": 43, "texto": "E se apoderará dos tesouros de ouro e prata, e de todas as coisas valiosas do Egito, os líbios e os cuxitas o seguirão."}, {"numero": 44, "texto": "Porém notícias do oriente e do norte o espantarão; e ele sairá com grande furor para destruir e matar muitos."}, {"numero": 45, "texto": "E armará a tendas de seu palácio entre os mares, no glorioso monte santo; mas ele virá a seu fim, e não haverá quem o ajude."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 11, 'en', '[{"numero": 1, "texto": "Also I in the first year of Darius the Mede, even I, stood to confirm and to strengthen him."}, {"numero": 2, "texto": "And now will I shew thee the truth. Behold, there shall stand up yet three kings in Persia; and the fourth shall be far richer than they all: and by his strength through his riches he shall stir up all against the realm of Grecia."}, {"numero": 3, "texto": "And a mighty king shall stand up, that shall rule with great dominion, and do according to his will."}, {"numero": 4, "texto": "And when he shall stand up, his kingdom shall be broken, and shall be divided toward the four winds of heaven; and not to his posterity, nor according to his dominion which he ruled: for his kingdom shall be plucked up, even for others beside those."}, {"numero": 5, "texto": "And the king of the south shall be strong, and one of his princes; and he shall be strong above him, and have dominion; his dominion shall be a great dominion."}, {"numero": 6, "texto": "And in the end of years they shall join themselves together; for the king''s daughter of the south shall come to the king of the north to make an agreement: but she shall not retain the power of the arm; neither shall he stand, nor his arm: but she shall be given up, and they that brought her, and he that begat her, and he that strengthened her in these times."}, {"numero": 7, "texto": "But out of a branch of her roots shall one stand up in his estate, which shall come with an army, and shall enter into the fortress of the king of the north, and shall deal against them, and shall prevail:"}, {"numero": 8, "texto": "And shall also carry captives into Egypt their gods, with their princes, and with their precious vessels of silver and of gold; and he shall continue more years than the king of the north."}, {"numero": 9, "texto": "So the king of the south shall come into his kingdom, and shall return into his own land."}, {"numero": 10, "texto": "But his sons shall be stirred up, and shall assemble a multitude of great forces: and one shall certainly come, and overflow, and pass through: then shall he return, and be stirred up, even to his fortress."}, {"numero": 11, "texto": "And the king of the south shall be moved with choler, and shall come forth and fight with him, even with the king of the north: and he shall set forth a great multitude; but the multitude shall be given into his hand."}, {"numero": 12, "texto": "And when he hath taken away the multitude, his heart shall be lifted up; and he shall cast down many ten thousands: but he shall not be strengthened by it."}, {"numero": 13, "texto": "For the king of the north shall return, and shall set forth a multitude greater than the former, and shall certainly come after certain years with a great army and with much riches."}, {"numero": 14, "texto": "And in those times there shall many stand up against the king of the south: also the robbers of thy people shall exalt themselves to establish the vision; but they shall fall."}, {"numero": 15, "texto": "So the king of the north shall come, and cast up a mount, and take the most fenced cities: and the arms of the south shall not withstand, neither his chosen people, neither shall there be any strength to withstand."}, {"numero": 16, "texto": "But he that cometh against him shall do according to his own will, and none shall stand before him: and he shall stand in the glorious land, which by his hand shall be consumed."}, {"numero": 17, "texto": "He shall also set his face to enter with the strength of his whole kingdom, and upright ones with him; thus shall he do: and he shall give him the daughter of women, corrupting her: but she shall not stand on his side, neither be for him."}, {"numero": 18, "texto": "After this shall he turn his face unto the isles, and shall take many: but a prince for his own behalf shall cause the reproach offered by him to cease; without his own reproach he shall cause it to turn upon him."}, {"numero": 19, "texto": "Then he shall turn his face toward the fort of his own land: but he shall stumble and fall, and not be found."}, {"numero": 20, "texto": "Then shall stand up in his estate a raiser of taxes in the glory of the kingdom: but within few days he shall be destroyed, neither in anger, nor in battle."}, {"numero": 21, "texto": "And in his estate shall stand up a vile person, to whom they shall not give the honour of the kingdom: but he shall come in peaceably, and obtain the kingdom by flatteries."}, {"numero": 22, "texto": "And with the arms of a flood shall they be overflown from before him, and shall be broken; yea, also the prince of the covenant."}, {"numero": 23, "texto": "And after the league made with him he shall work deceitfully: for he shall come up, and shall become strong with a small people."}, {"numero": 24, "texto": "He shall enter peaceably even upon the fattest places of the province; and he shall do that which his fathers have not done, nor his fathers'' fathers; he shall scatter among them the prey, and spoil, and riches: yea, and he shall forecast his devices against the strong holds, even for a time."}, {"numero": 25, "texto": "And he shall stir up his power and his courage against the king of the south with a great army; and the king of the south shall be stirred up to battle with a very great and mighty army; but he shall not stand: for they shall forecast devices against him."}, {"numero": 26, "texto": "Yea, they that feed of the portion of his meat shall destroy him, and his army shall overflow: and many shall fall down slain."}, {"numero": 27, "texto": "And both of these kings'' hearts shall be to do mischief, and they shall speak lies at one table; but it shall not prosper: for yet the end shall be at the time appointed."}, {"numero": 28, "texto": "Then shall he return into his land with great riches; and his heart shall be against the holy covenant; and he shall do exploits, and return to his own land."}, {"numero": 29, "texto": "At the time appointed he shall return, and come toward the south; but it shall not be as the former, or as the latter."}, {"numero": 30, "texto": "For the ships of Chittim shall come against him: therefore he shall be grieved, and return, and have indignation against the holy covenant: so shall he do; he shall even return, and have intelligence with them that forsake the holy covenant."}, {"numero": 31, "texto": "And arms shall stand on his part, and they shall pollute the sanctuary of strength, and shall take away the daily sacrifice, and they shall place the abomination that maketh desolate."}, {"numero": 32, "texto": "And such as do wickedly against the covenant shall he corrupt by flatteries: but the people that do know their God shall be strong, and do exploits."}, {"numero": 33, "texto": "And they that understand among the people shall instruct many: yet they shall fall by the sword, and by flame, by captivity, and by spoil, many days."}, {"numero": 34, "texto": "Now when they shall fall, they shall be holpen with a little help: but many shall cleave to them with flatteries."}, {"numero": 35, "texto": "And some of them of understanding shall fall, to try them, and to purge, and to make them white, even to the time of the end: because it is yet for a time appointed."}, {"numero": 36, "texto": "And the king shall do according to his will; and he shall exalt himself, and magnify himself above every god, and shall speak marvellous things against the God of gods, and shall prosper till the indignation be accomplished: for that that is determined shall be done."}, {"numero": 37, "texto": "Neither shall he regard the God of his fathers, nor the desire of women, nor regard any god: for he shall magnify himself above all."}, {"numero": 38, "texto": "But in his estate shall he honour the God of forces: and a god whom his fathers knew not shall he honour with gold, and silver, and with precious stones, and pleasant things."}, {"numero": 39, "texto": "Thus shall he do in the most strong holds with a strange god, whom he shall acknowledge and increase with glory: and he shall cause them to rule over many, and shall divide the land for gain."}, {"numero": 40, "texto": "And at the time of the end shall the king of the south push at him: and the king of the north shall come against him like a whirlwind, with chariots, and with horsemen, and with many ships; and he shall enter into the countries, and shall overflow and pass over."}, {"numero": 41, "texto": "He shall enter also into the glorious land, and many countries shall be overthrown: but these shall escape out of his hand, even Edom, and Moab, and the chief of the children of Ammon."}, {"numero": 42, "texto": "He shall stretch forth his hand also upon the countries: and the land of Egypt shall not escape."}, {"numero": 43, "texto": "But he shall have power over the treasures of gold and of silver, and over all the precious things of Egypt: and the Libyans and the Ethiopians shall be at his steps."}, {"numero": 44, "texto": "But tidings out of the east and out of the north shall trouble him: therefore he shall go forth with great fury to destroy, and utterly to make away many."}, {"numero": 45, "texto": "And he shall plant the tabernacles of his palace between the seas in the glorious holy mountain; yet he shall come to his end, and none shall help him."}]'::jsonb, 'King James Version'),
  ('Dn', 11, 'fr', '[{"numero": 1, "texto": "Et moi, la première année de Darius, le Mède, j''''étais auprès de lui pour l''''aider et le soutenir."}, {"numero": 2, "texto": "Maintenant, je vais te faire connaître la vérité. Voici, il y aura encore trois rois en Perse. Le quatrième amassera plus de richesses que tous les autres; et quand il sera puissant par ses richesses, il soulèvera tout contre le royaume de Javan."}, {"numero": 3, "texto": "Mais il s''''élèvera un vaillant roi, qui dominera avec une grande puissance, et fera ce qu''''il voudra."}, {"numero": 4, "texto": "Et lorsqu''''il se sera élevé, son royaume se brisera et sera divisé vers les quatre vents des cieux; il n''''appartiendra pas à ses descendants, et il ne sera pas aussi puissant qu''''il était, car il sera déchiré, et il passera à d''''autres qu''''à eux."}, {"numero": 5, "texto": "Le roi du midi deviendra fort. Mais un de ses chefs sera plus fort que lui, et dominera; sa domination sera puissante."}, {"numero": 6, "texto": "Au bout de quelques années ils s''''allieront, et la fille du roi du midi viendra vers le roi du septentrion pour rétablir la concorde. Mais elle ne conservera pas la force de son bras, et il ne résistera pas, ni lui, ni son bras; elle sera livrée avec ceux qui l''''auront amenée, avec son père et avec celui qui aura été son soutien dans ce temps-là."}, {"numero": 7, "texto": "Un rejeton de ses racines s''''élèvera à sa place; il viendra à l''''armée, il entrera dans les forteresses du roi du septentrion, il en disposera à son gré, et il se rendra puissant."}, {"numero": 8, "texto": "Il enlèvera même et transportera en Egypte leurs dieux et leurs images de fonte, et leurs objets précieux d''''argent et d''''or. Puis il restera quelques années éloigné du roi du septentrion."}, {"numero": 9, "texto": "Et celui-ci marchera contre le royaume du roi du midi, et reviendra dans son pays."}, {"numero": 10, "texto": "Ses fils se mettront en campagne et rassembleront une multitude nombreuse de troupes; l''''un d''''eux s''''avancera, se répandra comme un torrent, débordera, puis reviendra; et ils pousseront les hostilités jusqu''''à la forteresse du roi du midi."}, {"numero": 11, "texto": "Le roi du midi s''''irritera, il sortira et attaquera le roi du septentrion; il soulèvera une grande multitude, et les troupes du roi du septentrion seront livrées entre ses mains."}, {"numero": 12, "texto": "Cette multitude sera fière, et le coeur du roi s''''enflera; il fera tomber des milliers, mais il ne triomphera pas."}, {"numero": 13, "texto": "Car le roi du septentrion reviendra et rassemblera une multitude plus nombreuse que la première; au bout de quelques temps, de quelques années, il se mettra en marche avec une grande armée et de grandes richesses."}, {"numero": 14, "texto": "En ce temps-là, plusieurs s''''élèveront contre le roi du midi, et des hommes violents parmi ton peuple se révolteront pour accomplir la vision, et ils succomberont."}, {"numero": 15, "texto": "Le roi du septentrion s''''avancera, il élèvera des terrasses, et s''''emparera des villes fortes. Les troupes du midi et l''''élite du roi ne résisteront pas, elles manqueront de force pour résister."}, {"numero": 16, "texto": "Celui qui marchera contre lui fera ce qu''''il voudra, et personne ne lui résistera; il s''''arrêtera dans le plus beau des pays, exterminant ce qui tombera sous sa main."}, {"numero": 17, "texto": "Il se proposera d''''arriver avec toutes les forces de son royaume, et de conclure la paix avec le roi du midi; il lui donnera sa fille pour femme, dans l''''intention d''''amener sa ruine; mais cela n''''aura pas lieu, et ne lui réussira pas."}, {"numero": 18, "texto": "Il tournera ses vues du côté des îles, et il en prendra plusieurs; mais un chef mettra fin à l''''opprobre qu''''il voulait lui attirer, et le fera retomber sur lui."}, {"numero": 19, "texto": "Il se dirigera ensuite vers les forteresses de son pays; et il chancellera, il tombera, et on ne le trouvera plus."}, {"numero": 20, "texto": "Celui qui le remplacera fera venir un exacteur dans la plus belle partie du royaume, mais en quelques jours il sera brisé, et ce ne sera ni par la colère ni par la guerre."}, {"numero": 21, "texto": "Un homme méprisé prendra sa place, sans être revêtu de la dignité royale; il paraîtra au milieu de la paix, et s''''emparera du royaume par l''''intrigue."}, {"numero": 22, "texto": "Les troupes qui se répandront comme un torrent seront submergées devant lui, et anéanties, de même qu''''un chef de l''''alliance."}, {"numero": 23, "texto": "Après qu''''on se sera joint à lui, il usera de tromperie; il se mettra en marche, et il aura le dessus avec peu de monde."}, {"numero": 24, "texto": "Il entrera, au sein de la paix, dans les lieux les plus fertiles de la province; il fera ce que n''''avaient pas fait ses pères, ni les pères de ses pères; il distribuera le butin, les dépouilles et les richesses; il formera des projets contre les forteresses, et cela pendant un certain temps."}, {"numero": 25, "texto": "A la tête d''''une grande armée il emploiera sa force et son ardeur contre le roi du midi. Et le roi du midi s''''engagera dans la guerre avec une armée nombreuse et très puissante; mais il ne résistera pas, car on méditera contre lui de mauvais desseins."}, {"numero": 26, "texto": "Ceux qui mangeront des mets de sa table causeront sa perte; ses troupes se répandront comme un torrent, et les morts tomberont en grand nombre."}, {"numero": 27, "texto": "Les deux rois chercheront en leur coeur à faire le mal, et à la même table ils parleront avec fausseté. Mais cela ne réussira pas, car la fin n''''arrivera qu''''au temps marqué."}, {"numero": 28, "texto": "Il retournera dans son pays avec de grandes richesses; il sera dans son coeur hostile à l''''alliance sainte, il agira contre elle, puis retournera dans son pays."}, {"numero": 29, "texto": "A une époque fixée, il marchera de nouveau contre le midi; mais cette dernière fois les choses ne se passeront pas comme précédemment."}, {"numero": 30, "texto": "Des navires de Kittim s''''avanceront contre lui; découragé, il rebroussera. Puis, furieux contre l''''alliance sainte, il ne restera pas inactif; à son retour, il portera ses regards sur ceux qui auront abandonné l''''alliance sainte."}, {"numero": 31, "texto": "Des troupes se présenteront sur son ordre; elles profaneront le sanctuaire, la forteresse, elles feront cesser le sacrifice perpétuel, et dresseront l''''abomination du dévastateur."}, {"numero": 32, "texto": "Il séduira par des flatteries les traîtres de l''''alliance. Mais ceux du peuple qui connaîtront leur Dieu agiront avec fermeté,"}, {"numero": 33, "texto": "et les plus sages parmi eux donneront instruction à la multitude. Il en est qui succomberont pour un temps à l''''épée et à la flamme, à la captivité et au pillage."}, {"numero": 34, "texto": "Dans le temps où ils succomberont, ils seront un peu secourus, et plusieurs se joindront à eux par hypocrisie."}, {"numero": 35, "texto": "Quelques-uns des hommes sages succomberont, afin qu''''ils soient épurés, purifiés et blanchis, jusqu''''au temps de la fin, car elle n''''arrivera qu''''au temps marqué."}, {"numero": 36, "texto": "Le roi fera ce qu''''il voudra; il s''''élèvera, il se glorifiera au-dessus de tous les dieux, et il dira des choses incroyables contre le Dieu des dieux; il prospérera jusqu''''à ce que la colère soit consommée, car ce qui est arrêté s''''accomplira."}, {"numero": 37, "texto": "Il n''''aura égard ni aux dieux de ses pères, ni à la divinité qui fait les délices des femmes; il n''''aura égard à aucun dieu, car il se glorifiera au-dessus de tous."}, {"numero": 38, "texto": "Toutefois il honorera le dieu des forteresses sur son piédestal; à ce dieu, que ne connaissaient pas ses pères, il rendra des hommages avec de l''''or et de l''''argent, avec des pierres précieuses et des objets de prix."}, {"numero": 39, "texto": "C''''est avec le dieu étranger qu''''il agira contre les lieux fortifiés; et il comblera d''''honneurs ceux qui le reconnaîtront, il les fera dominer sur plusieurs, il leur distribuera des terres pour récompense."}, {"numero": 40, "texto": "Au temps de la fin, le roi du midi se heurtera contre lui. Et le roi du septentrion fondra sur lui comme une tempête, avec des chars et des cavaliers, et avec de nombreux navires; il s''''avancera dans les terres, se répandra comme un torrent et débordera."}, {"numero": 41, "texto": "Il entrera dans le plus beau des pays, et plusieurs succomberont; mais Edom, Moab, et les principaux des enfants d''''Ammon seront délivrés de sa main."}, {"numero": 42, "texto": "Il étendra sa main sur divers pays, et le pays d''''Egypte n''''échappera point."}, {"numero": 43, "texto": "Il se rendra maître des trésors d''''or et d''''argent, et de toutes les choses précieuses de l''''Egypte; les Libyens et les Ethiopiens seront à sa suite."}, {"numero": 44, "texto": "Des nouvelles de l''''orient et du septentrion viendront l''''effrayer, et il partira avec une grande fureur pour détruire et exterminer des multitudes."}, {"numero": 45, "texto": "Il dressera les tentes de son palais entre les mers, vers la glorieuse et sainte montagne Puis il arrivera à la fin, sans que personne lui soit en aide."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 11, 'es', '[{"numero": 1, "texto": "Y EN el año primero de Darío el de Media, yo estuve para animarlo y fortalecerlo."}, {"numero": 2, "texto": "Y ahora yo te mostraré la verdad. He aquí que aun habrá tres reyes en Persia, y el cuarto se hará de grandes riquezas más que todos; y fortificándose con sus riquezas, despertará á todos contra el reino de Javán."}, {"numero": 3, "texto": "Levantaráse luego un rey valiente, el cual se enseñoreará sobre gran dominio, y hará su voluntad."}, {"numero": 4, "texto": "Pero cuando estará enseñoreado, será quebrantado su reino, y repartido por los cuatro vientos del cielo; y no á sus descendientes, ni según el señorío con que él se enseñoreó: porque su reino será arrancado, y para otros fuera de aquellos."}, {"numero": 5, "texto": "Y haráse fuerte el rey del mediodía: mas uno de los príncipes de aquél le sobrepujará, y se hará poderoso; su señorío será grande señorío."}, {"numero": 6, "texto": "Y al cabo de años se concertarán, y la hija del rey del mediodía vendrá al rey del norte para hacer los conciertos. Empero ella no podrá retener la fuerza del brazo: ni permanecerá él, ni su brazo; porque será entregada ella, y los que la habían traído, asimismo su hijo, y los que estaban de parte de ella en aquel tiempo."}, {"numero": 7, "texto": "Mas del renuevo de sus raíces se levantará uno sobre su silla, y vendrá con ejército, y entrará en la fortaleza del rey del norte, y hará en ellos á su arbitrio, y predominará."}, {"numero": 8, "texto": "Y aun los dioses de ellos, con sus príncipes, con sus vasos preciosos de plata y de oro, llevará cautivos á Egipto: y por años se mantendrá él contra el rey del norte."}, {"numero": 9, "texto": "Así entrará en el reino el rey del mediodía, y volverá á su tierra."}, {"numero": 10, "texto": "Mas los hijos de aquél se airarán, y reunirán multitud de grandes ejércitos: y vendrá á gran priesa, é inundará, y pasará, y tornará, y llegará con ira hasta su fortaleza."}, {"numero": 11, "texto": "Por lo cual se enfurecerá el rey del mediodía, y saldrá, y peleará con el mismo rey del norte; y pondrá en campo gran multitud, y toda aquella multitud será entregada en su mano."}, {"numero": 12, "texto": "Y la multitud se ensoberbecerá, elevaráse su corazón, y derribará muchos millares; mas no prevalecerá."}, {"numero": 13, "texto": "Y el rey del norte volverá á poner en campo mayor multitud que primero, y á cabo del tiempo de años vendrá á gran priesa con grande ejército y con muchas riquezas."}, {"numero": 14, "texto": "Y en aquellos tiempos se levantarán muchos contra el rey del mediodía; é hijos de disipadores de tu pueblo se levantarán para confirmar la profecía, y caerán."}, {"numero": 15, "texto": "Vendrá pues el rey del norte, y fundará baluartes, y tomará la ciudad fuerte; y los brazos del mediodía no podrán permanecer, ni su pueblo escogido, ni habrá fortaleza que pueda resistir."}, {"numero": 16, "texto": "Y el que vendrá contra él, hará á su voluntad, ni habrá quien se le pueda parar delante; y estará en la tierra deseable, la cual será consumida en su poder."}, {"numero": 17, "texto": "Pondrá luego su rostro para venir con el poder de todo su reino; y hará con aquél cosas rectas, y darále una hija de mujeres para trastornarla: mas no estará ni será por él."}, {"numero": 18, "texto": "Volverá después su rostro á las islas, y tomará muchas; mas un príncipe le hará parar su afrenta, y aun tornará sobre él su oprobio."}, {"numero": 19, "texto": "Luego volverá su rostro á las fortalezas de su tierra: mas tropezará y caerá, y no parecerá más."}, {"numero": 20, "texto": "Entonces sucederá en su silla uno que hará pasar exactor por la gloria del reino; mas en pocos días será quebrantado, no en enojo, ni en batalla."}, {"numero": 21, "texto": "Y sucederá en su lugar un vil, al cual no darán la honra del reino: vendrá empero con paz, y tomará el reino con halagos."}, {"numero": 22, "texto": "Y con los brazos de inundación serán inundados delante de él, y serán quebrantados; y aun también el príncipe del pacto."}, {"numero": 23, "texto": "Y después de los conciertos con él, él hará engaño, y subirá, y saldrá vencedor con poca gente."}, {"numero": 24, "texto": "Estando la provincia en paz y en abundancia, entrará y hará lo que no hicieron sus padres, ni los padres de sus padres; presa, y despojos, y riquezas repartirá á sus soldados; y contra las fortalezas formará sus designios: y esto por tiempo."}, {"numero": 25, "texto": "Y despertará sus fuerzas y su corazón contra el rey del mediodía con grande ejército: y el rey del mediodía se moverá á la guerra con grande y muy fuerte ejército; mas no prevalecerá, porque le harán traición."}, {"numero": 26, "texto": "Aun los que comerán su pan, le quebrantarán; y su ejército será destruído, y caerán muchos muertos."}, {"numero": 27, "texto": "Y el corazón de estos dos reyes será para hacer mal, y en una misma mesa tratarán mentira: mas no servirá de nada, porque el plazo aun no es llegado."}, {"numero": 28, "texto": "Y volveráse á su tierra con grande riqueza, y su corazón será contra el pacto santo: hará pues, y volveráse á su tierra."}, {"numero": 29, "texto": "Al tiempo señalado tornará al mediodía; mas no será la postrera venida como la primera."}, {"numero": 30, "texto": "Porque vendrán contra él naves de Chîttim, y él se contristará, y se volverá, y enojaráse contra el pacto santo, y hará: volveráse pues, y pensará en los que habrán desamparado el santo pacto."}, {"numero": 31, "texto": "Y serán puestos brazos de su parte; y contaminarán el santuario de fortaleza, y quitarán el continuo sacrificio, y pondrán la abominación espantosa."}, {"numero": 32, "texto": "Y con lisonjas hará pecar á los violadores del pacto: mas el pueblo que conoce á su Dios, se esforzará, y hará."}, {"numero": 33, "texto": "Y los sabios del pueblo darán sabiduría á muchos: y caerán á cuchillo y á fuego, en cautividad y despojo, por días."}, {"numero": 34, "texto": "Y en su caer serán ayudados de pequeño socorro: y muchos se juntarán á ellos con lisonjas."}, {"numero": 35, "texto": "Y algunos de los sabios caerán para ser purgados, y limpiados, y emblanquecidos, hasta el tiempo determinado: porque aun para esto hay plazo."}, {"numero": 36, "texto": "Y el rey hará á su voluntad; y se ensoberbecerá, y se engrandecerá sobre todo dios: y contra el Dios de los dioses hablará maravillas, y será prosperado, hasta que sea consumada la ira: porque hecha está determinación."}, {"numero": 37, "texto": "Y del Dios de sus padres no se cuidará, ni del amor de las mujeres: ni se cuidará de dios alguno, porque sobre todo se engrandecerá."}, {"numero": 38, "texto": "Mas honrará en su lugar al dios Mauzim, dios que sus padres no conocieron: honrarálo con oro, y plata, y piedras preciosas, y con cosas de gran precio."}, {"numero": 39, "texto": "Y con el dios ajeno que conocerá, hará á los baluartes de Mauzim crecer en gloria: y harálos enseñorear sobre muchos, y por interés repartirá la tierra."}, {"numero": 40, "texto": "Empero al cabo del tiempo el rey del mediodía se acorneará con él; y el rey del norte levantará contra él como tempestad, con carros y gente de á caballo, y muchos navíos; y entrará por las tierras, é inundará, y pasará."}, {"numero": 41, "texto": "Y vendrá á la tierra deseable, y muchas provincias caerán; mas éstas escaparán de su mano: Edom, y Moab, y lo primero de los hijos de Ammón."}, {"numero": 42, "texto": "Asimismo extenderá su mano á las otras tierras, y no escapará el país de Egipto."}, {"numero": 43, "texto": "Y se apoderará de los tesoros de oro y plata, y de todas las cosas preciosas de Egipto, de Libia, y Etiopía por donde pasará."}, {"numero": 44, "texto": "Mas nuevas de oriente y del norte lo espantarán; y saldrá con grande ira para destruir y matar muchos."}, {"numero": 45, "texto": "Y plantará las tiendas de su palacio entre los mares, en el monte deseable del santuario; y vendrá hasta su fin, y no tendrá quien le ayude."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dn', 12, 'pt', '[{"numero": 1, "texto": "E naquele tempo se levantará Miguel, o grande príncipe que está a favor dos filhos de teu povo; e será tempo de angústia tal que nunca houve desde que as nações surgiram até aquele tempo; mas naquele tempo o teu povo será livrado, todo aquele os que se achar escrito no livro."}, {"numero": 2, "texto": "E muitos dos que dormem no pó da terra ressuscitarão, uns para a vida eterna, e outros para a vergonha e o desprezo eterno."}, {"numero": 3, "texto": "E os sábios brilharão como o resplendor do céu; e os que conduzem muitos à justiça [brilharão] como as estrelas, para todo o sempre."}, {"numero": 4, "texto": "Porém tu, Daniel, guarda em segredo estas palavras e sela o livro até o tempo do fim; muitos correrão de um lado para o outro, e o conhecimento se multiplicará."}, {"numero": 5, "texto": "Então eu, Daniel, olhei, e eis outros dois que estavam de pé, um à margem do rio, e o outro à outra margem do rio."}, {"numero": 6, "texto": "E ele disse ao homem vestido de linho, que estava sobre as águas do rio: Quando será o fim destas maravilhas?"}, {"numero": 7, "texto": "E ouvi o homem vestido de linho, que estava sobre as águas do rio, e levantou sua mão direita e sua esquerda ao céu, e jurou por aquele que vive eternamente; que será depois de um tempo, tempos, e a metade [de um tempo] . Quando acabarem de despedaçar o poder do povo santo, todas estas coisas serão cumpridas."}, {"numero": 8, "texto": "E eu ouvi, mas não entendi. Por isso eu disse: Meu senhor, o que será o cumprimento destas coisas?"}, {"numero": 9, "texto": "E ele disse: Caminha, Daniel, pois estas palavras estão guardadas em segredo e seladas até o tempo do fim."}, {"numero": 10, "texto": "Muitos serão purificados, limpos, e refinados; porém os maus agirão malignamente, e nenhum dos maus entenderá, porém os sábios entenderão."}, {"numero": 11, "texto": "E desde o tempo em que o contínuo [sacrifício] for tirado, e posta a abominação assoladora, haverá mil duzentos e noventa dias."}, {"numero": 12, "texto": "Bem-aventurado o que esperar, e chegar até mil trezentos e trinta e cinco dias."}, {"numero": 13, "texto": "Tu, porém, caminha até o fim; porque repousarás, e ressuscitarás em tua herança no fim dos dias."}]'::jsonb, 'Almeida Livre'),
  ('Dn', 12, 'en', '[{"numero": 1, "texto": "And at that time shall Michael stand up, the great prince which standeth for the children of thy people: and there shall be a time of trouble, such as never was since there was a nation even to that same time: and at that time thy people shall be delivered, every one that shall be found written in the book."}, {"numero": 2, "texto": "And many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt."}, {"numero": 3, "texto": "And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever."}, {"numero": 4, "texto": "But thou, O Daniel, shut up the words, and seal the book, even to the time of the end: many shall run to and fro, and knowledge shall be increased."}, {"numero": 5, "texto": "Then I Daniel looked, and, behold, there stood other two, the one on this side of the bank of the river, and the other on that side of the bank of the river."}, {"numero": 6, "texto": "And one said to the man clothed in linen, which was upon the waters of the river, How long shall it be to the end of these wonders?"}, {"numero": 7, "texto": "And I heard the man clothed in linen, which was upon the waters of the river, when he held up his right hand and his left hand unto heaven, and sware by him that liveth for ever that it shall be for a time, times, and an half; and when he shall have accomplished to scatter the power of the holy people, all these things shall be finished."}, {"numero": 8, "texto": "And I heard, but I understood not: then said I, O my Lord, what shall be the end of these things?"}, {"numero": 9, "texto": "And he said, Go thy way, Daniel: for the words are closed up and sealed till the time of the end."}, {"numero": 10, "texto": "Many shall be purified, and made white, and tried; but the wicked shall do wickedly: and none of the wicked shall understand; but the wise shall understand."}, {"numero": 11, "texto": "And from the time that the daily sacrifice shall be taken away, and the abomination that maketh desolate set up, there shall be a thousand two hundred and ninety days."}, {"numero": 12, "texto": "Blessed is he that waiteth, and cometh to the thousand three hundred and five and thirty days."}, {"numero": 13, "texto": "But go thou thy way till the end be: for thou shalt rest, and stand in thy lot at the end of the days."}]'::jsonb, 'King James Version'),
  ('Dn', 12, 'fr', '[{"numero": 1, "texto": "En ce temps-là se lèvera Micaël, le grand chef, le défenseur des enfants de ton peuple; et ce sera une époque de détresse, telle qu''''il n''''y en a point eu de semblable depuis que les nations existent jusqu''''à cette époque. En ce temps-là, ceux de ton peuple qui seront trouvés inscrits dans le livre seront sauvés."}, {"numero": 2, "texto": "Plusieurs de ceux qui dorment dans la poussière de la terre se réveilleront, les uns pour la vie éternelle, et les autres pour l''''opprobre, pour la honte éternelle."}, {"numero": 3, "texto": "Ceux qui auront été intelligents brilleront comme la splendeur du ciel, et ceux qui auront enseigné la justice, à la multitude brilleront comme les étoiles, à toujours et à perpétuité."}, {"numero": 4, "texto": "Toi, Daniel, tiens secrètes ces paroles, et scelle le livre jusqu''''au temps de la fin. Plusieurs alors le liront, et la connaissance augmentera."}, {"numero": 5, "texto": "Et moi, Daniel, je regardai, et voici, deux autres hommes se tenaient debout, l''''un en deçà du bord du fleuve, et l''''autre au delà du bord du fleuve."}, {"numero": 6, "texto": "L''''un d''''eux dit à l''''homme vêtu de lin, qui se tenait au-dessus des eaux du fleuve: Quand sera la fin de ces prodiges?"}, {"numero": 7, "texto": "Et j''''entendis l''''homme vêtu de lin, qui se tenait au-dessus des eaux du fleuve; il leva vers les cieux sa main droite et sa main gauche, et il jura par celui qui vit éternellement que ce sera dans un temps, des temps, et la moitié d''''un temps, et que toutes ces choses finiront quand la force du peuple saint sera entièrement brisée."}, {"numero": 8, "texto": "J''''entendis, mais je ne compris pas; et je dis: Mon seigneur, quelle sera l''''issue de ces choses?"}, {"numero": 9, "texto": "Il répondit: Va, Daniel, car ces paroles seront tenues secrètes et scellées jusqu''''au temps de la fin."}, {"numero": 10, "texto": "Plusieurs seront purifiés, blanchis et épurés; les méchants feront le mal et aucun des méchants ne comprendra, mais ceux qui auront de l''''intelligence comprendront."}, {"numero": 11, "texto": "Depuis le temps où cessera le sacrifice perpétuel, et où sera dressée l''''abomination du dévastateur, il y aura mille deux cent quatre-vingt-dix jours."}, {"numero": 12, "texto": "Heureux celui qui attendra, et qui arrivera jusqu''''à mille trois cent trente-cinq jours!"}, {"numero": 13, "texto": "Et toi, marche vers ta fin; tu te reposeras, et tu seras debout pour ton héritage à la fin des jours."}]'::jsonb, 'Louis Segond 1910'),
  ('Dn', 12, 'es', '[{"numero": 1, "texto": "Y EN aquel tiempo se levantará Miguel, el gran príncipe que está por los hijos de tu pueblo; y será tiempo de angustia, cual nunca fué después que hubo gente hasta entonces: mas en aquel tiempo será libertado tu pueblo, todos los que se hallaren escritos en el libro."}, {"numero": 2, "texto": "Y muchos de los que duermen en el polvo de la tierra serán despertados, unos para vida eterna, y otros para vergüenza y confusión perpetua."}, {"numero": 3, "texto": "Y los entendidos resplandecerán como el resplandor del firmamento; y los que enseñan á justicia la multitud, como las estrellas á perpetua eternidad."}, {"numero": 4, "texto": "Tú empero Daniel, cierra las palabras y sella el libro hasta el tiempo del fin: pasarán muchos, y multiplicaráse la ciencia."}, {"numero": 5, "texto": "Y yo, Daniel, miré, y he aquí otros dos que estaban, el uno de esta parte á la orilla del río, y el otro de la otra parte á la orilla del río."}, {"numero": 6, "texto": "Y dijo uno al varón vestido de lienzos, que estaba sobre las aguas del río: ¿Cuándo será el fin de estas maravillas?"}, {"numero": 7, "texto": "Y oía al varón vestido de lienzos, que estaba sobre las aguas del río, el cual alzó su diestra y su siniestra al cielo, y juró por el Viviente en los siglos, que será por tiempo, tiempos, y la mitad. Y cuando se acabare el esparcimiento del escuadrón del pueblo santo, todas estas cosas serán cumplidas."}, {"numero": 8, "texto": "Y yo oí, mas no entendí. Y dije: Señor mío, ¿qué será el cumplimiento de estas cosas?"}, {"numero": 9, "texto": "Y dijo: Anda, Daniel, que estas palabras están cerradas y selladas hasta el tiempo del cumplimiento."}, {"numero": 10, "texto": "Muchos serán limpios, y emblanquecidos, y purificados; mas los impíos obrarán impíamente, y ninguno de los impíos entenderá, pero entenderán los entendidos."}, {"numero": 11, "texto": "Y desde el tiempo que fuere quitado el continuo sacrificio hasta la abominación espantosa, habrá mil doscientos y noventa días."}, {"numero": 12, "texto": "Bienaventurado el que esperare, y llegare hasta mil trescientos treinta y cinco días."}, {"numero": 13, "texto": "Y tú irás al fin, y reposarás, y te levantarás en tu suerte al fin de los días."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dt', 1, 'pt', '[{"numero": 1, "texto": "Estas são as palavras que falou Moisés a todo Israel desta parte do Jordão no deserto, na planície diante do mar Vermelho, entre Parã, e Tofel, e Labã, e Hazerote, e Di-Zaabe."}, {"numero": 2, "texto": "Onze jornadas há desde Horebe, caminho do monte de Seir, até Cades-Barneia."}, {"numero": 3, "texto": "E foi, que aos quarenta anos, no mês décimo primeiro, ao primeiro dia do mês, Moisés falou aos filhos de Israel conforme todas as coisas que o SENHOR lhe havia mandado acerca deles;"}, {"numero": 4, "texto": "Depois que feriu a Seom rei dos amorreus, que habitava em Hesbom, e a Ogue rei de Basã, que habitava em Astarote em Edrei:"}, {"numero": 5, "texto": "Desta parte do Jordão, em terra de Moabe, resolveu Moisés declarar esta lei, dizendo:"}, {"numero": 6, "texto": "O SENHOR nosso Deus nos falou em Horebe, dizendo: Demais haveis estado neste monte;"}, {"numero": 7, "texto": "Voltai-vos, parti-vos e ide ao monte dos amorreus, e a todos seus vizinhos, na planície, no monte, e nos vales, e ao sul, e à costa do mar, à terra dos cananeus, e o Líbano, até o grande rio, o rio Eufrates."}, {"numero": 8, "texto": "Olhai, eu dei a terra em vossa presença; entrai e possuí a terra que o SENHOR jurou a vossos pais Abraão, Isaque, e Jacó, que lhes daria a eles e à sua descendência depois deles."}, {"numero": 9, "texto": "E eu vos falei então, dizendo: Eu não posso vos levar só:"}, {"numero": 10, "texto": "O SENHOR vosso Deus vos multiplicou, e eis que sois hoje vós como as estrelas do céu em abundância."}, {"numero": 11, "texto": "O SENHOR Deus de vossos pais acrescente sobre vós como sois mil vezes, e vos abençoe, como vos prometeu!"}, {"numero": 12, "texto": "Como levarei eu só vossos problemas, vossas cargas, e vossos pleitos?"}, {"numero": 13, "texto": "Dai-me dentre vós, de vossas tribos, homens sábios e entendidos e experientes, para que eu os ponha por vossos chefes."}, {"numero": 14, "texto": "E me respondestes, e dissestes: Bom é fazer o que disseste."}, {"numero": 15, "texto": "E tomei os principais de vossas tribos, homens sábios e experientes, e os pus por chefes sobre vós, chefes de milhares, e chefes de centenas, e chefes de cinquenta, e líderes de dez, e governadores a vossas tribos."}, {"numero": 16, "texto": "E então mandei a vossos juízes, dizendo: Ouvi entre vossos irmãos, e julgai justamente entre o homem e seu irmão, e o que lhe é estrangeiro."}, {"numero": 17, "texto": "Não tenhais acepção de pessoas no juízo: tanto ao pequeno como ao grande ouvireis: não tereis temor de ninguém, porque o juízo é de Deus: e a causa que vos for difícil, a trareis a mim, e eu a ouvirei."}, {"numero": 18, "texto": "Eu vos mandei, pois, naquele tempo tudo o que havíeis de fazer."}, {"numero": 19, "texto": "Então partimos de Horebe, e andamos por todo aquele grande e temível deserto que vistes, pelo caminho montanhoso dos amorreus, como o SENHOR, nosso Deus, havia nos mandado; e chegamos a Cades-Barneia."}, {"numero": 20, "texto": "Então eu vos disse: ‘Chegastes à região montanhosa dos amorreus, a qual o SENHOR, nosso Deus, nos dá."}, {"numero": 21, "texto": "Eis que o SENHOR, teu Deus, deu diante de ti esta terra; sobe e tomai posse dela, como o SENHOR, o Deus dos teus pais, te disse; não temas nem te apavores.’"}, {"numero": 22, "texto": "Então todos vós vos aproximastes de mim, e dissestes: ‘Enviemos homens adiante de nós, que nos reconheçam a terra, e nos tragam de volta relato de qual caminho por onde devemos subir, e das cidades aonde devemos ir.’"}, {"numero": 23, "texto": "E isso me pareceu bem. Então tomei doze homens de vós, um homem de cada tribo."}, {"numero": 24, "texto": "Eles se foram, subiram às montanhas, chegaram ao vale de Escol, e o reconheceram."}, {"numero": 25, "texto": "E tomaram em suas mãos do fruto daquela terra, e o trouxeram a nós, e nos contaram, e disseram: ‘A terra que o SENHOR, nosso Deus, nos dá, é boa.’"}, {"numero": 26, "texto": "Porém não quisestes subir, mas fostes rebeldes à ordem do SENHOR, vosso Deus;"}, {"numero": 27, "texto": "E murmurastes em vossas tendas, dizendo: ‘É porque o SENHOR nos odeia que ele nos tirou da terra do Egito, para nos entregar nas mãos dos amorreus, para nos destruir."}, {"numero": 28, "texto": "Para onde subiremos? Nossos irmãos fizeram derreter o nosso coração, dizendo: Este povo é maior e mais alto que nós, as cidades são grandes e muradas até o céu; e também vimos ali filhos de gigantes.’"}, {"numero": 29, "texto": "Então vos disse: Não temais, nem tenhais medo deles."}, {"numero": 30, "texto": "O SENHOR vosso Deus, o qual vai diante de vós, ele lutará por vós, conforme todas as coisas que fez por vós no Egito diante vossos olhos;"}, {"numero": 31, "texto": "E no deserto viste que o SENHOR teu Deus te trouxe, como traz o homem a seu filho, por todo o caminho que andastes, até que viestes a este lugar."}, {"numero": 32, "texto": "E ainda com isto não crestes no SENHOR vosso Deus,"}, {"numero": 33, "texto": "O qual ia diante de vós pelo caminho, para reconhecer-vos o lugar onde havíeis de assentar o acampamento, com fogo de noite para vos mostrar o caminho por onde andásseis, e com nuvem de dia."}, {"numero": 34, "texto": "E ouviu o SENHOR a voz de vossas palavras, e irou-se, e jurou dizendo:"}, {"numero": 35, "texto": "Não verá homem algum destes desta má geração, a boa terra que jurei havia de dar a vossos pais,"}, {"numero": 36, "texto": "Exceto Calebe filho de Jefoné: ele a verá, e a ele lhe darei a terra que pisou, e a seus filhos; porque cumpriu em seguir ao SENHOR."}, {"numero": 37, "texto": "E também contra mim se irou o SENHOR por vós, dizendo: Tampouco tu entrarás ali:"}, {"numero": 38, "texto": "Josué filho de Num, que está diante de ti, ele entrará ali: anima-o; porque ele a fará herdar a Israel."}, {"numero": 39, "texto": "E vossas crianças, das quais dissestes serão por presa, e vossos filhos que não sabem hoje bem nem mal, eles entrarão ali, e a eles a darei, e eles a herdarão."}, {"numero": 40, "texto": "E vós voltai-vos, e parti-vos ao deserto caminho do mar Vermelho."}, {"numero": 41, "texto": "Então respondestes e me dissestes: Pecado temos contra o SENHOR; nós subiremos e lutaremos, conforme tudo o que o SENHOR nosso Deus nos mandou. E vos armastes cada um de suas armas de guerra, e vos preparastes para subir ao monte."}, {"numero": 42, "texto": "E o SENHOR me disse: Dize-lhes: Não subais, nem luteis, pois não estou entre vós; para que não sejais feridos diante de vossos inimigos."}, {"numero": 43, "texto": "E vos falei, e não destes ouvido; antes fostes rebeldes ao dito do SENHOR, e persistindo com altivez, subistes ao monte."}, {"numero": 44, "texto": "E saíram os amorreus, que habitavam naquele monte, a vosso encontro, e vos perseguiram, como fazem as vespas, e vos derrotaram em Seir, perseguindo-vos até Hormá."}, {"numero": 45, "texto": "E voltastes, e chorastes diante do SENHOR; mas o SENHOR não escutou vossa voz, nem vos prestou ouvido."}, {"numero": 46, "texto": "E estivestes em Cades por muitos dias, como nos dias que estivestes."}]'::jsonb, 'Almeida Livre'),
  ('Dt', 1, 'en', '[{"numero": 1, "texto": "These be the words which Moses spake unto all Israel on this side Jordan in the wilderness, in the plain over against the Red sea, between Paran, and Tophel, and Laban, and Hazeroth, and Dizahab."}, {"numero": 2, "texto": "(There are eleven days'' journey from Horeb by the way of mount Seir unto Kadeshbarnea.)"}, {"numero": 3, "texto": "And it came to pass in the fortieth year, in the eleventh month, on the first day of the month, that Moses spake unto the children of Israel, according unto all that the Lord had given him in commandment unto them;"}, {"numero": 4, "texto": "After he had slain Sihon the king of the Amorites, which dwelt in Heshbon, and Og the king of Bashan, which dwelt at Astaroth in Edrei:"}, {"numero": 5, "texto": "On this side Jordan, in the land of Moab, began Moses to declare this law, saying,"}, {"numero": 6, "texto": "The Lord our God spake unto us in Horeb, saying, Ye have dwelt long enough in this mount:"}, {"numero": 7, "texto": "Turn you, and take your journey, and go to the mount of the Amorites, and unto all the places nigh thereunto, in the plain, in the hills, and in the vale, and in the south, and by the sea side, to the land of the Canaanites, and unto Lebanon, unto the great river, the river Euphrates."}, {"numero": 8, "texto": "Behold, I have set the land before you: go in and possess the land which the Lord sware unto your fathers, Abraham, Isaac, and Jacob, to give unto them and to their seed after them."}, {"numero": 9, "texto": "And I spake unto you at that time, saying, I am not able to bear you myself alone:"}, {"numero": 10, "texto": "The Lord your God hath multiplied you, and, behold, ye are this day as the stars of heaven for multitude."}, {"numero": 11, "texto": "(The Lord God of your fathers make you a thousand times so many more as ye are, and bless you, as he hath promised you!)"}, {"numero": 12, "texto": "How can I myself alone bear your cumbrance, and your burden, and your strife?"}, {"numero": 13, "texto": "Take you wise men, and understanding, and known among your tribes, and I will make them rulers over you."}, {"numero": 14, "texto": "And ye answered me, and said, The thing which thou hast spoken is good for us to do."}, {"numero": 15, "texto": "So I took the chief of your tribes, wise men, and known, and made them heads over you, captains over thousands, and captains over hundreds, and captains over fifties, and captains over tens, and officers among your tribes."}, {"numero": 16, "texto": "And I charged your judges at that time, saying, Hear the causes between your brethren, and judge righteously between every man and his brother, and the stranger that is with him."}, {"numero": 17, "texto": "Ye shall not respect persons in judgment; but ye shall hear the small as well as the great; ye shall not be afraid of the face of man; for the judgment is God''s: and the cause that is too hard for you, bring it unto me, and I will hear it."}, {"numero": 18, "texto": "And I commanded you at that time all the things which ye should do."}, {"numero": 19, "texto": "And when we departed from Horeb, we went through all that great and terrible wilderness, which ye saw by the way of the mountain of the Amorites, as the Lord our God commanded us; and we came to Kadeshbarnea."}, {"numero": 20, "texto": "And I said unto you, Ye are come unto the mountain of the Amorites, which the Lord our God doth give unto us."}, {"numero": 21, "texto": "Behold, the Lord thy God hath set the land before thee: go up and possess it, as the Lord God of thy fathers hath said unto thee; fear not, neither be discouraged."}, {"numero": 22, "texto": "And ye came near unto me every one of you, and said, We will send men before us, and they shall search us out the land, and bring us word again by what way we must go up, and into what cities we shall come."}, {"numero": 23, "texto": "And the saying pleased me well: and I took twelve men of you, one of a tribe:"}, {"numero": 24, "texto": "And they turned and went up into the mountain, and came unto the valley of Eshcol, and searched it out."}, {"numero": 25, "texto": "And they took of the fruit of the land in their hands, and brought it down unto us, and brought us word again, and said, It is a good land which the Lord our God doth give us."}, {"numero": 26, "texto": "Notwithstanding ye would not go up, but rebelled against the commandment of the Lord your God:"}, {"numero": 27, "texto": "And ye murmured in your tents, and said, Because the Lord hated us, he hath brought us forth out of the land of Egypt, to deliver us into the hand of the Amorites, to destroy us."}, {"numero": 28, "texto": "Whither shall we go up? our brethren have discouraged our heart, saying, The people is greater and taller than we; the cities are great and walled up to heaven; and moreover we have seen the sons of the Anakims there."}, {"numero": 29, "texto": "Then I said unto you, Dread not, neither be afraid of them."}, {"numero": 30, "texto": "The Lord your God which goeth before you, he shall fight for you, according to all that he did for you in Egypt before your eyes;"}, {"numero": 31, "texto": "And in the wilderness, where thou hast seen how that the Lord thy God bare thee, as a man doth bear his son, in all the way that ye went, until ye came into this place."}, {"numero": 32, "texto": "Yet in this thing ye did not believe the Lord your God,"}, {"numero": 33, "texto": "Who went in the way before you, to search you out a place to pitch your tents in, in fire by night, to shew you by what way ye should go, and in a cloud by day."}, {"numero": 34, "texto": "And the Lord heard the voice of your words, and was wroth, and sware, saying,"}, {"numero": 35, "texto": "Surely there shall not one of these men of this evil generation see that good land, which I sware to give unto your fathers."}, {"numero": 36, "texto": "Save Caleb the son of Jephunneh; he shall see it, and to him will I give the land that he hath trodden upon, and to his children, because he hath wholly followed the Lord."}, {"numero": 37, "texto": "Also the Lord was angry with me for your sakes, saying, Thou also shalt not go in thither."}, {"numero": 38, "texto": "But Joshua the son of Nun, which standeth before thee, he shall go in thither: encourage him: for he shall cause Israel to inherit it."}, {"numero": 39, "texto": "Moreover your little ones, which ye said should be a prey, and your children, which in that day had no knowledge between good and evil, they shall go in thither, and unto them will I give it, and they shall possess it."}, {"numero": 40, "texto": "But as for you, turn you, and take your journey into the wilderness by the way of the Red sea."}, {"numero": 41, "texto": "Then ye answered and said unto me, We have sinned against the Lord, we will go up and fight, according to all that the Lord our God commanded us. And when ye had girded on every man his weapons of war, ye were ready to go up into the hill."}, {"numero": 42, "texto": "And the Lord said unto me, Say unto them. Go not up, neither fight; for I am not among you; lest ye be smitten before your enemies."}, {"numero": 43, "texto": "So I spake unto you; and ye would not hear, but rebelled against the commandment of the Lord, and went presumptuously up into the hill."}, {"numero": 44, "texto": "And the Amorites, which dwelt in that mountain, came out against you, and chased you, as bees do, and destroyed you in Seir, even unto Hormah."}, {"numero": 45, "texto": "And ye returned and wept before the Lord; but the Lord would not hearken to your voice, nor give ear unto you."}, {"numero": 46, "texto": "So ye abode in Kadesh many days, according unto the days that ye abode there."}]'::jsonb, 'King James Version'),
  ('Dt', 1, 'fr', '[{"numero": 1, "texto": "Voici les paroles que Moïse adressa à tout Israël, de l''''autre côté du Jourdain, dans le désert, dans la plaine, vis-à-vis de Suph, entre Paran, Tophel, Laban, Hatséroth et Di-Zahab."}, {"numero": 2, "texto": "Il y a onze journées depuis Horeb, par le chemin de la montagne de Séir, jusqu''''à Kadès-Barnéa."}, {"numero": 3, "texto": "Dans la quarantième année, au onzième mois, le premier du mois, Moïse parla aux enfants d''''Israël selon tout ce que l''''Eternel lui avait ordonné de leur dire."}, {"numero": 4, "texto": "C''''était après qu''''il eut battu Sihon, roi des Amoréens, qui habitait à Hesbon, et Og, roi de Basan, qui habitait à Aschtaroth et à Edréi."}, {"numero": 5, "texto": "De l''''autre côté du Jourdain, dans le pays de Moab, Moïse commença à expliquer cette loi, et dit:"}, {"numero": 6, "texto": "L''''Eternel, notre Dieu, nous a parlé à Horeb, en disant: Vous avez assez demeuré dans cette montagne."}, {"numero": 7, "texto": "Tournez-vous, et partez; allez à la montagne des Amoréens et dans tout le voisinage, dans la plaine, sur la montagne, dans la vallée, dans le midi, sur la côte de la mer, au pays des Cananéens et au Liban, jusqu''''au grand fleuve, au fleuve d''''Euphrate."}, {"numero": 8, "texto": "Voyez, j''''ai mis le pays devant vous; allez, et prenez possession du pays que l''''Eternel a juré à vos pères, Abraham, Isaac et Jacob, de donner à eux et à leur postérité après eux."}, {"numero": 9, "texto": "Dans ce temps-là, je vous dis: Je ne puis pas, à moi seul, vous porter."}, {"numero": 10, "texto": "L''''Eternel, votre Dieu, vous a multipliés, et vous êtes aujourd''''hui aussi nombreux que les étoiles du ciel."}, {"numero": 11, "texto": "Que l''''Eternel, le Dieu de vos pères, vous augmente mille fois autant, et qu''''il vous bénisse comme il vous l''''a promis!"}, {"numero": 12, "texto": "Comment porterais-je, à moi seul, votre charge, votre fardeau et vos contestations?"}, {"numero": 13, "texto": "Prenez dans vos tribus des hommes sages, intelligents et connus, et je les mettrai à votre tête."}, {"numero": 14, "texto": "Vous me répondîtes, en disant: Ce que tu proposes de faire est une bonne chose."}, {"numero": 15, "texto": "Je pris alors les chefs de vos tribus, des hommes sages et connus, et je les mis à votre tête comme chefs de mille, chefs de cent, chefs de cinquante, et chefs de dix, et comme ayant autorité dans vos tribus."}, {"numero": 16, "texto": "Je donnai, dans le même temps, cet ordre à vos juges: Ecoutez vos frères, et jugez selon la justice les différends de chacun avec son frère ou avec l''''étranger."}, {"numero": 17, "texto": "Vous n''''aurez point égard à l''''apparence des personnes dans vos jugements; vous écouterez le petit comme le grand; vous ne craindrez aucun homme, car c''''est Dieu qui rend la justice. Et lorsque vous trouverez une cause trop difficile, vous la porterez devant moi, pour que je l''''entende."}, {"numero": 18, "texto": "C''''est ainsi que je vous prescrivis, dans ce temps-là, tout ce que vous aviez à faire."}, {"numero": 19, "texto": "Nous partîmes d''''Horeb, et nous parcourûmes en entier ce grand et affreux désert que vous avez vu; nous prîmes le chemin de la montagne des Amoréens, comme l''''Eternel, notre Dieu, nous l''''avait ordonné, et nous arrivâmes à Kadès-Barnéa."}, {"numero": 20, "texto": "Je vous dis: Vous êtes arrivés à la montagne des Amoréens, que l''''Eternel, notre Dieu, nous donne."}, {"numero": 21, "texto": "Vois, l''''Eternel, ton Dieu, met le pays devant toi; monte, prends-en possession, comme te l''''a dit l''''Eternel, le Dieu de tes pères; ne crains point, et ne t''''effraie point."}, {"numero": 22, "texto": "Vous vous approchâtes tous de moi, et vous dîtes: Envoyons des hommes devant nous, pour explorer le pays, et pour nous faire un rapport sur le chemin par lequel nous y monterons et sur les villes où nous arriverons."}, {"numero": 23, "texto": "Cet avis me parut bon; et je pris douze hommes parmi vous, un homme par tribu."}, {"numero": 24, "texto": "Ils partirent, traversèrent la montagne, et arrivèrent jusqu''''à la vallée d''''Eschcol, qu''''ils explorèrent."}, {"numero": 25, "texto": "Ils prirent dans leurs mains des fruits du pays, et nous les présentèrent; ils nous firent un rapport, et dirent: C''''est un bon pays, que l''''Eternel, notre Dieu, nous donne."}, {"numero": 26, "texto": "Mais vous ne voulûtes point y monter, et vous fûtes rebelles à l''''ordre de l''''Eternel, votre Dieu."}, {"numero": 27, "texto": "Vous murmurâtes dans vos tentes, et vous dîtes: C''''est parce que l''''Eternel nous hait, qu''''il nous a fait sortir du pays d''''Egypte, afin de nous livrer entre les mains des Amoréens et de nous détruire."}, {"numero": 28, "texto": "Où monterions-nous? Nos frères nous ont fait perdre courage, en disant: C''''est un peuple plus grand et de plus haute taille que nous; ce sont des villes grandes et fortifiées jusqu''''au ciel; nous y avons même vu des enfants d''''Anak."}, {"numero": 29, "texto": "Je vous dis: Ne vous épouvantez pas, et n''''ayez pas peur d''''eux."}, {"numero": 30, "texto": "L''''Eternel, votre Dieu, qui marche devant vous, combattra lui-même pour vous, selon tout ce qu''''il a fait pour vous sous vos yeux en Egypte,"}, {"numero": 31, "texto": "puis au désert, où tu as vu que l''''Eternel, ton Dieu, t''''a porté comme un homme porte son fils, pendant toute la route que vous avez faite jusqu''''à votre arrivée en ce lieu."}, {"numero": 32, "texto": "Malgré cela, vous n''''eûtes point confiance en l''''Eternel, votre Dieu,"}, {"numero": 33, "texto": "qui allait devant vous sur la route pour vous chercher un lieu de campement, la nuit dans un feu afin de vous montrer le chemin où vous deviez marcher, et le jour dans une nuée."}, {"numero": 34, "texto": "L''''Eternel entendit le bruit de vos paroles. Il s''''irrita, et jura, en disant:"}, {"numero": 35, "texto": "Aucun des hommes de cette génération méchante ne verra le bon pays que j''''ai juré de donner à vos pères,"}, {"numero": 36, "texto": "excepté Caleb, fils de Jephunné; il le verra, lui, et je donnerai à lui et à ses enfants le pays sur lequel il a marché, parce qu''''il a pleinement suivi la voie de l''''Eternel."}, {"numero": 37, "texto": "L''''Eternel s''''irrita aussi contre moi, à cause de vous, et il dit: Toi non plus, tu n''''y entreras point."}, {"numero": 38, "texto": "Josué, fils de Nun, ton serviteur, y entrera; fortifie-le, car c''''est lui qui mettra Israël en possession de ce pays."}, {"numero": 39, "texto": "Et vos petits enfants, dont vous avez dit: Ils deviendront une proie! et vos fils, qui ne connaissent aujourd''''hui ni le bien ni le mal, ce sont eux qui y entreront, c''''est à eux que je le donnerai, et ce sont eux qui le posséderont."}, {"numero": 40, "texto": "Mais vous, tournez-vous, et partez pour le désert, dans la direction de la mer Rouge."}, {"numero": 41, "texto": "Vous répondîtes, en me disant: Nous avons péché contre l''''Eternel; nous monterons et nous combattrons, comme l''''Eternel, notre Dieu, nous l''''a ordonné. Et vous ceignîtes chacun vos armes, et vous fîtes le projet téméraire de monter à la montagne."}, {"numero": 42, "texto": "L''''Eternel me dit: Dis-leur: Ne montez pas et ne combattez pas, car je ne suis pas au milieu de vous; ne vous faites pas battre par vos ennemis."}, {"numero": 43, "texto": "Je vous parlai, mais vous n''''écoutâtes point; vous fûtes rebelles à l''''ordre de l''''Eternel, et vous montâtes audacieusement à la montagne."}, {"numero": 44, "texto": "Alors les Amoréens, qui habitent cette montagne, sortirent à votre rencontre, et vous poursuivirent comme font les abeilles; ils vous battirent en Séir, jusqu''''à Horma."}, {"numero": 45, "texto": "A votre retour, vous pleurâtes devant l''''Eternel; mais l''''Eternel n''''écouta point votre voix, et ne vous prêta point l''''oreille."}, {"numero": 46, "texto": "Vous restâtes à Kadès, où le temps que vous y avez passé fut de longue durée."}]'::jsonb, 'Louis Segond 1910'),
  ('Dt', 1, 'es', '[{"numero": 1, "texto": "ESTAS son las palabras que habló Moisés á todo Israel de esta parte del Jordán en el desierto, en el llano delante del mar Bermejo, entre Parán, y Thopel, y Labán, y Haseroth, y Dizahab."}, {"numero": 2, "texto": "Once jornadas hay desde Horeb, camino del monte de Seir, hasta Cades-barnea."}, {"numero": 3, "texto": "Y fué, que á los cuarenta años, en el mes undécimo, al primero del mes, Moisés habló á los hijos de Israel conforme á todas las cosas que Jehová le había mandado acerca de ellos;"}, {"numero": 4, "texto": "Después que hirió á Sehón rey de los Amorrheos, que habitaba en Hesbón, y á Og rey de Basán, que habitaba en Astarot en Edrei:"}, {"numero": 5, "texto": "De esta parte del Jordán, en tierra de Moab, resolvió Moisés declarar esta ley, diciendo:"}, {"numero": 6, "texto": "Jehová nuestro Dios nos habló en Horeb, diciendo: Harto habéis estado en este monte;"}, {"numero": 7, "texto": "Volveos, partíos é id al monte del Amorrheo, y á todas sus comarcas, en el llano, en el monte, y en los valles, y al mediodía, y á la costa de la mar, á la tierra del Cananeo, y el Líbano, hasta el gran río, el río Eufrates."}, {"numero": 8, "texto": "Mirad, yo he dado la tierra en vuestra presencia; entrad y poseed la tierra que Jehová juró á vuestros padres Abraham, Isaac, y Jacob, que les daría á ellos y á su simiente después de ellos."}, {"numero": 9, "texto": "Y yo os hablé entonces, diciendo: Yo no puedo llevaros solo:"}, {"numero": 10, "texto": "Jehová vuestro Dios os ha multiplicado, y he aquí sois hoy vosotros como las estrellas del cielo en multitud."}, {"numero": 11, "texto": "¡Jehová Dios de vuestros padres añada sobre vosotros como sois mil veces, y os bendiga, como os ha prometido!"}, {"numero": 12, "texto": "¿Cómo llevaré yo solo vuestras molestias, vuestras cargas, y vuestros pleitos?"}, {"numero": 13, "texto": "Dadme de entre vosotros, de vuestras tribus, varones sabios y entendidos y expertos, para que yo los ponga por vuestros jefes."}, {"numero": 14, "texto": "Y me respondisteis, y dijisteis: Bueno es hacer lo que has dicho."}, {"numero": 15, "texto": "Y tomé los principales de vuestras tribus, varones sabios y expertos, y púselos por jefes sobre vosotros, jefes de millares, y jefes de cientos, y jefes de cincuenta, y cabos de diez, y gobernadores á vuestras tribus."}, {"numero": 16, "texto": "Y entonces mandé á vuestros jueces, diciendo: Oid entre vuestros hermanos, y juzgad justamente entre el hombre y su hermano, y el que le es extranjero."}, {"numero": 17, "texto": "No tengáis respeto de personas en el juicio: así al pequeño como al grande oiréis: no tendréis temor de ninguno, porque el juicio es de Dios: y la causa que os fuere difícil, la traeréis á mí, y yo la oiré."}, {"numero": 18, "texto": "Os mandé, pues, en aquel tiempo todo lo que habíais de hacer."}, {"numero": 19, "texto": "Y partidos de Horeb, anduvimos todo aquel grande y terrible desierto que habéis visto, por el camino del monte del Amorrheo, como Jehová nuestro Dios nos lo mandó; y llegamos hasta Cades-barnea."}, {"numero": 20, "texto": "Entonces os dije: Llegado habéis al monte del Amorrheo, el cual Jehová nuestro Dios nos da."}, {"numero": 21, "texto": "Mira, Jehová tu Dios ha dado delante de ti la tierra: sube y poséela, como Jehová el Dios de tus padres te ha dicho; no temas ni desmayes."}, {"numero": 22, "texto": "Y llegasteis á mí todos vosotros, y dijisteis: Enviemos varones delante de nosotros, que nos reconozcan la tierra y nos traigan de vuelta razón del camino por donde hemos de subir, y de las ciudades adonde hemos de llegar."}, {"numero": 23, "texto": "Y el dicho me pareció bien: y tomé doce varones de vosotros, un varón por tribu:"}, {"numero": 24, "texto": "Y se encaminaron, y subieron al monte, y llegaron hasta la arroyada de Escol, y reconocieron la tierra."}, {"numero": 25, "texto": "Y tomaron en sus manos del fruto del país, y nos lo trajeron, y diéronnos cuenta, y dijeron: Es buena la tierra que Jehová nuestro Dios nos da."}, {"numero": 26, "texto": "Empero no quisisteis subir, antes fuisteis rebeldes al dicho de Jehová vuestro Dios;"}, {"numero": 27, "texto": "Y murmurasteis en vuestras tiendas, diciendo: Porque Jehová nos aborrecía, nos ha sacado de tierra de Egipto, para entregarnos en mano del Amorrheo para destruirnos."}, {"numero": 28, "texto": "¿A dónde subimos? Nuestros hermanos han hecho desfallecer nuestro corazón, diciendo: Este pueblo es mayor y más alto que nosotros, las ciudades grandes y muradas hasta el cielo; y también vimos allí hijos de gigantes."}, {"numero": 29, "texto": "Entonces os dije: No temáis, ni tengáis miedo de ellos."}, {"numero": 30, "texto": "Jehová vuestro Dios, el cual va delante de vosotros, él peleará por vosotros, conforme á todas las cosas que hizo por vosotros en Egipto delante de vuestros ojos;"}, {"numero": 31, "texto": "Y en el desierto has visto que Jehová tu Dios te ha traído, como trae el hombre á su hijo, por todo el camino que habéis andado, hasta que habéis venido á este lugar."}, {"numero": 32, "texto": "Y aun con esto no creisteis en Jehová vuestro Dios,"}, {"numero": 33, "texto": "El cual iba delante de vosotros por el camino, para reconoceros el lugar donde habíais de asentar el campo, con fuego de noche para mostraros el camino por donde anduvieseis, y con nube de día."}, {"numero": 34, "texto": "Y oyó Jehová la voz de vuestras palabras, y enojóse, y juró diciendo:"}, {"numero": 35, "texto": "No verá hombre alguno de estos de esta mala generación, la buena tierra que juré había de dar á vuestros padres,"}, {"numero": 36, "texto": "Excepto Caleb hijo de Jephone: él la verá, y á él le daré la tierra que pisó, y á sus hijos; porque cumplió en pos de Jehová."}, {"numero": 37, "texto": "Y también contra mí se airó Jehová por vosotros, diciendo: Tampoco tú entrarás allá:"}, {"numero": 38, "texto": "Josué hijo de Nun, que está delante de ti, él entrará allá: anímale; porque él la hará heredar á Israel."}, {"numero": 39, "texto": "Y vuestros chiquitos, de los cuales dijisteis serán por presa, y vuestros hijos que no saben hoy bueno ni malo, ellos entrarán allá, y á ellos la daré, y ellos la heredarán."}, {"numero": 40, "texto": "Y vosotros volveos, y partíos al desierto camino del mar Bermejo."}, {"numero": 41, "texto": "Entonces respondisteis y me dijisteis: Pecado hemos contra Jehová; nosotros subiremos y pelearemos, conforme á todo lo que Jehová nuestro Dios nos ha mandado. Y os armasteis cada uno de sus armas de guerra, y os apercibisteis para subir al monte."}, {"numero": 42, "texto": "Y Jehová me dijo: Diles: No subáis, ni peleéis, pues no estoy entre vosotros; porque no seáis heridos delante de vuestros enemigos."}, {"numero": 43, "texto": "Y os hablé, y no disteis oído; antes fuisteis rebeldes al dicho de Jehová, y persistiendo con altivez, subisteis al monte."}, {"numero": 44, "texto": "Y salió el Amorrheo, que habitaba en aquel monte, á vuestro encuentro, y os persiguieron, como hacen las avispas, y os derrotaron en Seir, persiguiéndoos hasta Horma."}, {"numero": 45, "texto": "Y volvisteis, y llorasteis delante de Jehová; pero Jehová no escuchó vuestra voz, ni os prestó oído."}, {"numero": 46, "texto": "Y estuvisteis en Cades por muchos días, como en los días que habéis estado."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dt', 5, 'pt', '[{"numero": 1, "texto": "E chamou Moisés a todo Israel, e disse-lhes: Ouve, Israel, os estatutos e regulamentos que eu pronuncio hoje em vossos ouvidos: e aprendei-os, e guardai-os, para praticá-los."}, {"numero": 2, "texto": "O SENHOR nosso Deus fez pacto conosco em Horebe."}, {"numero": 3, "texto": "Não com nossos pais fez o SENHOR este pacto, a não ser conosco todos os que estamos aqui hoje vivos."}, {"numero": 4, "texto": "Face a face falou o SENHOR convosco no monte do meio do fogo,"}, {"numero": 5, "texto": "(Eu estava então entre o SENHOR e vós, para vos anunciar a palavra do SENHOR; porque vós tivestes temor do fogo, e não subistes ao monte;) dizendo:"}, {"numero": 6, "texto": "Eu sou o SENHOR teu Deus, que te tirei da terra do Egito, de casa de servos."}, {"numero": 7, "texto": "Não terás deuses estranhos diante de mim."}, {"numero": 8, "texto": "Não farás para ti escultura, nem imagem alguma de coisa que está acima nos céus, ou abaixo na terra, ou nas águas debaixo da terra:"}, {"numero": 9, "texto": "Não te inclinarás a elas nem lhes servirás: porque eu sou o SENHOR teu Deus, forte, zeloso, que visito a iniquidade dos pais sobre os filhos, e sobre a terceira geração, e sobre a quarta, aos que me aborrecem,"}, {"numero": 10, "texto": "E que faço misericórdia a milhares aos que me amam, e guardam meus mandamentos."}, {"numero": 11, "texto": "Não tomarás em vão o nome do SENHOR teu Deus; porque o SENHOR não dará por inocente ao que tomar em vão seu nome."}, {"numero": 12, "texto": "Guardarás o dia do repouso para santificá-lo, como o SENHOR teu Deus te mandou."}, {"numero": 13, "texto": "Seis dias trabalharás e farás toda tua obra:"}, {"numero": 14, "texto": "Mas no sétimo é repouso ao SENHOR teu Deus: nenhuma obra farás tu, nem teu filho, nem tua filha, nem teu servo, nem tua serva, nem tua boi, nem tua asno, nem nenhum animal teu, nem tua peregrino que está dentro de tuas portas: para que descanse teu servo e tua serva como"}, {"numero": 15, "texto": "E lembra-te que foste servo em terra do Egito, e que o SENHOR teu Deus te tirou dali com mão forte e braço estendido: pelo qual o SENHOR teu Deus te mandou que guardes no dia do repouso."}, {"numero": 16, "texto": "Honra a teu pai e a tua mãe, como o SENHOR teu Deus te mandou, para que sejam prolongados teus dias, e para que te vá bem sobre a terra que o SENHOR teu Deus te dá."}, {"numero": 17, "texto": "Não cometerás homicídio."}, {"numero": 18, "texto": "Não adulterarás."}, {"numero": 19, "texto": "Não furtarás."}, {"numero": 20, "texto": "Não dirás falso testemunho contra teu próximo."}, {"numero": 21, "texto": "Não cobiçarás a mulher de teu próximo, nem desejarás a casa de teu próximo, nem sua terra, nem seu servo, nem sua serva, nem seu boi, nem seu asno, nem nenhuma coisa que seja de teu próximo."}, {"numero": 22, "texto": "Estas palavras falou o SENHOR a toda vossa congregação no monte, do meio do fogo, da nuvem e da escuridão, a grande voz: e não acrescentou mais. E escreveu-os em duas tábuas de pedra, as quais deu a mim."}, {"numero": 23, "texto": "E aconteceu, que como vós ouvistes a voz do meio das trevas, e vistes ao monte que ardia em fogo, aproximastes a mim todos os príncipes de vossas tribos, e vossos anciãos;"}, {"numero": 24, "texto": "E dissestes: Eis que, o SENHOR nosso Deus nos mostrou sua glória e sua grandeza, e ouvimos sua voz do meio do fogo: hoje vimos que o SENHOR fala ao homem, e este vive."}, {"numero": 25, "texto": "Agora pois, por que morreremos? Que este grande fogo nos consumirá: se voltarmos a ouvir a voz do SENHOR nosso Deus, morreremos."}, {"numero": 26, "texto": "Porque, que é toda carne, para que ouça a voz do Deus vivente que fala do meio do fogo, como nós a ouvimos, e viva?"}, {"numero": 27, "texto": "Chega tu, e ouve todas as coisas que disser o SENHOR nosso Deus; e tu nos dirás todo o que o SENHOR nosso Deus te disser, e nós ouviremos e faremos."}, {"numero": 28, "texto": "E ouviu o SENHOR a voz de vossas palavras, quando me faláveis; e disse-me o SENHOR: Ouvi a voz das palavras deste povo, que eles te falaram: bem está tudo o que disseram."}, {"numero": 29, "texto": "Quem dera que tivessem tal coração, que me temessem, e guardassem todos os dias todos meus mandamentos, para que a eles e a seus filhos lhes fosse bem para sempre!"}, {"numero": 30, "texto": "Vai, dize-lhes: Voltai-vos a vossas tendas."}, {"numero": 31, "texto": "E tu fica aqui comigo, e te direi todos os mandamentos, e estatutos, e regulamentos que lhes hás de ensinar, a fim que os ponham agora por obra na terra que eu lhes dou para possuí-la."}, {"numero": 32, "texto": "Olhai, pois, que façais como o SENHOR vosso Deus vos mandou: não vos desvieis à direita nem à esquerda;"}, {"numero": 33, "texto": "Andai em todo caminho que o SENHOR vosso Deus vos mandou, para que vivais, e vos vá bem, e tenhais longos dias na terra que haveis de possuir."}]'::jsonb, 'Almeida Livre'),
  ('Dt', 5, 'en', '[{"numero": 1, "texto": "And Moses called all Israel, and said unto them, Hear, O Israel, the statutes and judgments which I speak in your ears this day, that ye may learn them, and keep, and do them."}, {"numero": 2, "texto": "The Lord our God made a covenant with us in Horeb."}, {"numero": 3, "texto": "The Lord made not this covenant with our fathers, but with us, even us, who are all of us here alive this day."}, {"numero": 4, "texto": "The Lord talked with you face to face in the mount out of the midst of the fire,"}, {"numero": 5, "texto": "(I stood between the Lord and you at that time, to shew you the word of the Lord: for ye were afraid by reason of the fire, and went not up into the mount;) saying,"}, {"numero": 6, "texto": "I am the Lord thy God, which brought thee out of the land of Egypt, from the house of bondage."}, {"numero": 7, "texto": "Thou shalt have none other gods before me."}, {"numero": 8, "texto": "Thou shalt not make thee any graven image, or any likeness of any thing that is in heaven above, or that is in the earth beneath, or that is in the waters beneath the earth:"}, {"numero": 9, "texto": "Thou shalt not bow down thyself unto them, nor serve them: for I the Lord thy God am a jealous God, visiting the iniquity of the fathers upon the children unto the third and fourth generation of them that hate me,"}, {"numero": 10, "texto": "And shewing mercy unto thousands of them that love me and keep my commandments."}, {"numero": 11, "texto": "Thou shalt not take the name of the Lord thy God in vain: for the Lord will not hold him guiltless that taketh his name in vain."}, {"numero": 12, "texto": "Keep the sabbath day to sanctify it, as the Lord thy God hath commanded thee."}, {"numero": 13, "texto": "Six days thou shalt labour, and do all thy work:"}, {"numero": 14, "texto": "But the seventh day is the sabbath of the Lord thy God: in it thou shalt not do any work, thou, nor thy son, nor thy daughter, nor thy manservant, nor thy maidservant, nor thine ox, nor thine ass, nor any of thy cattle, nor thy stranger that is within thy gates; that thy manservant and thy maidservant may rest as well as thou."}, {"numero": 15, "texto": "And remember that thou wast a servant in the land of Egypt, and that the Lord thy God brought thee out thence through a mighty hand and by a stretched out arm: therefore the Lord thy God commanded thee to keep the sabbath day."}, {"numero": 16, "texto": "Honour thy father and thy mother, as the Lord thy God hath commanded thee; that thy days may be prolonged, and that it may go well with thee, in the land which the Lord thy God giveth thee."}, {"numero": 17, "texto": "Thou shalt not kill."}, {"numero": 18, "texto": "Neither shalt thou commit adultery."}, {"numero": 19, "texto": "Neither shalt thou steal."}, {"numero": 20, "texto": "Neither shalt thou bear false witness against thy neighbour."}, {"numero": 21, "texto": "Neither shalt thou desire thy neighbour''s wife, neither shalt thou covet thy neighbour''s house, his field, or his manservant, or his maidservant, his ox, or his ass, or any thing that is thy neighbour''s."}, {"numero": 22, "texto": "These words the Lord spake unto all your assembly in the mount out of the midst of the fire, of the cloud, and of the thick darkness, with a great voice: and he added no more. And he wrote them in two tables of stone, and delivered them unto me."}, {"numero": 23, "texto": "And it came to pass, when ye heard the voice out of the midst of the darkness, (for the mountain did burn with fire,) that ye came near unto me, even all the heads of your tribes, and your elders;"}, {"numero": 24, "texto": "And ye said, Behold, the Lord our God hath shewed us his glory and his greatness, and we have heard his voice out of the midst of the fire: we have seen this day that God doth talk with man, and he liveth."}, {"numero": 25, "texto": "Now therefore why should we die? for this great fire will consume us: if we hear the voice of the Lord our God any more, then we shall die."}, {"numero": 26, "texto": "For who is there of all flesh, that hath heard the voice of the living God speaking out of the midst of the fire, as we have, and lived?"}, {"numero": 27, "texto": "Go thou near, and hear all that the Lord our God shall say: and speak thou unto us all that the Lord our God shall speak unto thee; and we will hear it, and do it."}, {"numero": 28, "texto": "And the Lord heard the voice of your words, when ye spake unto me; and the Lord said unto me, I have heard the voice of the words of this people, which they have spoken unto thee: they have well said all that they have spoken."}, {"numero": 29, "texto": "O that there were such an heart in them, that they would fear me, and keep all my commandments always, that it might be well with them, and with their children for ever!"}, {"numero": 30, "texto": "Go say to them, Get you into your tents again."}, {"numero": 31, "texto": "But as for thee, stand thou here by me, and I will speak unto thee all the commandments, and the statutes, and the judgments, which thou shalt teach them, that they may do them in the land which I give them to possess it."}, {"numero": 32, "texto": "Ye shall observe to do therefore as the Lord your God hath commanded you: ye shall not turn aside to the right hand or to the left."}, {"numero": 33, "texto": "Ye shall walk in all the ways which the Lord your God hath commanded you, that ye may live, and that it may be well with you, and that ye may prolong your days in the land which ye shall possess."}]'::jsonb, 'King James Version'),
  ('Dt', 5, 'fr', '[{"numero": 1, "texto": "Moïse convoqua tout Israël, et leur dit: Ecoute, Israël, les lois et les ordonnances que je vous fais entendre aujourd''''hui. Apprenez-les, et mettez-les soigneusement en pratique."}, {"numero": 2, "texto": "L''''Eternel, notre Dieu, a traité avec nous une alliance à Horeb."}, {"numero": 3, "texto": "Ce n''''est point avec nos pères que l''''Eternel a traité cette alliance; c''''est avec nous, qui sommes ici aujourd''''hui, tous vivants."}, {"numero": 4, "texto": "L''''Eternel vous parla face à face sur la montagne, du milieu du feu."}, {"numero": 5, "texto": "Je me tins alors entre l''''Eternel et vous, pour vous annoncer la parole de l''''Eternel; car vous aviez peur du feu, et vous ne montâtes point sur la montagne. Il dit:"}, {"numero": 6, "texto": "Je suis l''''Eternel, ton Dieu, qui t''''ai fait sortir du pays d''''Egypte, de la maison de servitude."}, {"numero": 7, "texto": "Tu n''''auras point d''''autres dieux devant ma face."}, {"numero": 8, "texto": "Tu ne te feras point d''''image taillée, de représentation quelconque des choses qui sont en haut dans les cieux, qui sont en bas sur la terre, et qui sont dans les eaux plus bas que la terre."}, {"numero": 9, "texto": "Tu ne te prosterneras point devant elles, et tu ne les serviras point; car moi, l''''Eternel, ton Dieu, je suis un Dieu jaloux, qui punis l''''iniquité des pères sur les enfants jusqu''''à la troisième et à la quatrième génération de ceux qui me haïssent,"}, {"numero": 10, "texto": "et qui fais miséricorde jusqu''''en mille générations à ceux qui m''''aiment et qui gardent mes commandements."}, {"numero": 11, "texto": "Tu ne prendras point le nom de l''''Eternel, ton Dieu, en vain; car l''''Eternel ne laissera point impuni celui qui prendra son nom en vain."}, {"numero": 12, "texto": "Observe le jour du repos, pour le sanctifier, comme l''''Eternel, ton Dieu, te l''''a ordonné."}, {"numero": 13, "texto": "Tu travailleras six jours, et tu feras tout ton ouvrage."}, {"numero": 14, "texto": "Mais le septième jour est le jour du repos de l''''Eternel, ton Dieu: tu ne feras aucun ouvrage, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton boeuf, ni ton âne, ni aucune de tes bêtes, ni l''''étranger qui est dans tes portes, afin que ton serviteur et ta servante se reposent comme toi."}, {"numero": 15, "texto": "Tu te souviendras que tu as été esclave au pays d''''Egypte, et que l''''Eternel, ton Dieu, t''''en a fait sortir à main forte et à bras étendu: c''''est pourquoi l''''Eternel, ton Dieu, t''''a ordonné d''''observer le jour du repos."}, {"numero": 16, "texto": "Honore ton père et ta mère, comme l''''Eternel, ton Dieu, te l''''a ordonné, afin que tes jours se prolongent et que tu sois heureux dans le pays que l''''Eternel, ton Dieu, te donne."}, {"numero": 17, "texto": "Tu ne tueras point."}, {"numero": 18, "texto": "Tu ne commettras point d''''adultère."}, {"numero": 19, "texto": "Tu ne déroberas point."}, {"numero": 20, "texto": "Tu ne porteras point de faux témoignage contre ton prochain."}, {"numero": 21, "texto": "Tu ne convoiteras point la femme de ton prochain; tu ne désireras point la maison de ton prochain, ni son champ, ni son serviteur, ni sa servante, ni son boeuf, ni son âne, ni aucune chose qui appartienne à ton prochain."}, {"numero": 22, "texto": "Telles sont les paroles que prononça l''''Eternel à haute voix sur la montagne, du milieu du feu, des nuées et de l''''obscurité, et qu''''il adressa à toute votre assemblée, sans rien ajouter. Il les écrivit sur deux tables de pierre, qu''''il me donna."}, {"numero": 23, "texto": "Lorsque vous eûtes entendu la voix du milieu des ténèbres, et tandis que la montagne était toute en feu, vos chefs de tribus et vos anciens s''''approchèrent tous de moi,"}, {"numero": 24, "texto": "et vous dîtes: Voici, l''''Eternel, notre Dieu, nous a montré sa gloire et sa grandeur, et nous avons entendu sa voix du milieu du feu; aujourd''''hui, nous avons vu que Dieu a parlé à des hommes, et qu''''ils sont demeurés vivants."}, {"numero": 25, "texto": "Et maintenant pourquoi mourrions-nous? car ce grand feu nous dévorera; si nous continuons à entendre la voix de l''''Eternel, notre Dieu, nous mourrons."}, {"numero": 26, "texto": "Quel est l''''homme, en effet, qui ait jamais entendu, comme nous, la voix du Dieu vivant parlant du milieu du feu, et qui soit demeuré vivant?"}, {"numero": 27, "texto": "Approche, toi, et écoute tout ce que dira l''''Eternel, notre Dieu; tu nous rapporteras toi-même tout ce que te dira l''''Eternel, notre Dieu; nous l''''écouterons, et nous le ferons."}, {"numero": 28, "texto": "L''''Eternel entendit les paroles que vous m''''adressâtes. Et l''''Eternel me dit: J''''ai entendu les paroles que ce peuple t''''a adressées: tout ce qu''''ils ont dit est bien."}, {"numero": 29, "texto": "Oh! s''''ils avaient toujours ce même coeur pour me craindre et pour observer tous mes commandements, afin qu''''ils fussent heureux à jamais, eux et leurs enfants!"}, {"numero": 30, "texto": "Va, dis-leur: Retournez dans vos tentes."}, {"numero": 31, "texto": "Mais toi, reste ici avec moi, et je te dirai tous les commandements, les lois et les ordonnances, que tu leur enseigneras, afin qu''''ils les mettent en pratique dans le pays dont je leur donne la possession."}, {"numero": 32, "texto": "Vous ferez avec soin ce que l''''Eternel, votre Dieu, vous a ordonné; vous ne vous en détournerez ni à droite, ni à gauche."}, {"numero": 33, "texto": "Vous suivrez entièrement la voie que l''''Eternel, votre Dieu, vous a prescrite, afin que vous viviez et que vous soyez heureux, afin que vous prolongiez vos jours dans le pays dont vous aurez la possession."}]'::jsonb, 'Louis Segond 1910'),
  ('Dt', 5, 'es', '[{"numero": 1, "texto": "Y LLAMÓ Moisés á todo Israel, y díjoles: Oye, Israel, los estatutos y derechos que yo pronuncio hoy en vuestros oídos: y aprendedlos, y guardadlos, para ponerlos por obra."}, {"numero": 2, "texto": "Jehová nuestro Dios hizo pacto con nosotros en Horeb."}, {"numero": 3, "texto": "No con nuestros padres hizo Jehová este pacto, sino con nosotros todos los que estamos aquí hoy vivos."}, {"numero": 4, "texto": "Cara á cara habló Jehová con vosotros en el monte de en medio del fuego,"}, {"numero": 5, "texto": "(Yo estaba entonces entre Jehová y vosotros, para denunciaros la palabra de Jehová; porque vosotros tuvisteis temor del fuego, y no subisteis al monte;) diciendo:"}, {"numero": 6, "texto": "Yo soy Jehová tu Dios, que te saqué de tierra de Egipto, de casa de siervos."}, {"numero": 7, "texto": "No tendrás dioses extraños delante de mí."}, {"numero": 8, "texto": "No harás para ti escultura, ni imagen alguna de cosa que está arriba en los cielos, ó abajo en la tierra, ó en las aguas debajo de la tierra:"}, {"numero": 9, "texto": "No te inclinarás á ellas ni les servirás: porque yo soy Jehová tu Dios, fuerte, celoso, que visito la iniquidad de los padres sobre los hijos, y sobre los terceros, y sobre los cuartos, á los que me aborrecen,"}, {"numero": 10, "texto": "Y que hago misericordia á millares á los que me aman, y guardan mis mandamientos."}, {"numero": 11, "texto": "No tomarás en vano el nombre de Jehová tu Dios; porque Jehová no dará por inocente al que tomare en vano su nombre."}, {"numero": 12, "texto": "Guardarás el día del reposo para santificarlo, como Jehová tu Dios te ha mandado."}, {"numero": 13, "texto": "Seis días trabajarás y harás toda tu obra:"}, {"numero": 14, "texto": "Mas el séptimo es reposo á Jehová tu Dios: ninguna obra harás tú, ni tu hijo, ni tu hija, ni tu siervo, ni tu sierva, ni tu buey, ni tu asno, ni ningún animal tuyo, ni tu peregrino que está dentro de tus puertas: porque descanse tu siervo y tu sierva como tú."}, {"numero": 15, "texto": "Y acuérdate que fuiste siervo en tierra de Egipto, y que Jehová tu Dios te sacó de allá con mano fuerte y brazo extendido: por lo cual Jehová tu Dios te ha mandado que guardes el día del reposo."}, {"numero": 16, "texto": "Honra á tu padre y á tu madre, como Jehová tu Dios te ha mandado, para que sean prolongados tus días, y para que te vaya bien sobre la tierra que Jehová tu Dios te da."}, {"numero": 17, "texto": "No matarás."}, {"numero": 18, "texto": "No adulterarás."}, {"numero": 19, "texto": "No hurtarás."}, {"numero": 20, "texto": "No dirás falso testimonio contra tu prójimo."}, {"numero": 21, "texto": "No codiciarás la mujer de tu prójimo, ni desearás la casa de tu prójimo, ni su tierra, ni su siervo, ni su sierva, ni su buey, ni su asno, ni ninguna cosa que sea de tu prójimo."}, {"numero": 22, "texto": "Estas palabras habló Jehová á toda vuestra congregación en el monte, de en medio del fuego, de la nube y de la oscuridad, á gran voz: y no añadió más. Y escribiólas en dos tablas de piedra, las cuales me dió á mí."}, {"numero": 23, "texto": "Y aconteció, que como vosotros oisteis la voz de en medio de las tinieblas, y visteis al monte que ardía en fuego, llegasteis á mí todos los príncipes de vuestras tribus, y vuestros ancianos;"}, {"numero": 24, "texto": "Y dijisteis: He aquí, Jehová nuestro Dios nos ha mostrado su gloria y su grandeza, y hemos oído su voz de en medio del fuego: hoy hemos visto que Jehová habla al hombre, y éste vive."}, {"numero": 25, "texto": "Ahora pues, ¿por qué moriremos? que este gran fuego nos consumirá: si tornáremos á oir la voz de Jehová nuestro Dios, moriremos."}, {"numero": 26, "texto": "Porque, ¿qué es toda carne, para que oiga la voz del Dios viviente que habla de en medio del fuego, como nosotros la oímos, y viva?"}, {"numero": 27, "texto": "Llega tú, y oye todas las cosas que dijere Jehová nuestro Dios; y tú nos dirás todo lo que Jehová nuestro Dios te dijere, y nosotros oiremos y haremos."}, {"numero": 28, "texto": "Y oyó Jehová la voz de vuestras palabras, cuando me hablabais; y díjome Jehová: He oído la voz de las palabras de este pueblo, que ellos te han hablado: bien está todo lo que han dicho."}, {"numero": 29, "texto": "¡Quién diera que tuviesen tal corazón, que me temiesen, y guardasen todos los días todos mis mandamientos, para que á ellos y á sus hijos les fuese bien para siempre!"}, {"numero": 30, "texto": "Ve, diles: Volveos á vuestras tiendas."}, {"numero": 31, "texto": "Y tú estáte aquí conmigo, y te diré todos los mandamientos, y estatutos, y derechos, que les has de enseñar, á fin que los pongan ahora por obra en la tierra que yo les doy para poseerla."}, {"numero": 32, "texto": "Mirad, pues, que hagáis como Jehová vuestro Dios os ha mandado: no os apartéis á diestra ni á siniestra;"}, {"numero": 33, "texto": "Andad en todo camino que Jehová vuestro Dios os ha mandado, para que viváis, y os vaya bien, y tengáis largos días en la tierra que habéis de poseer."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dt', 32, 'pt', '[{"numero": 1, "texto": "Escutai, céus, e falarei; E ouça a terra os ditos de minha boca."}, {"numero": 2, "texto": "Gotejará como a chuva minha doutrina; Destilará como o orvalho meu discurso; Como o chuvisco sobre a grama, E como as gotas sobre a erva:"}, {"numero": 3, "texto": "Porque invocarei o nome do SENHOR; Engrandecei ao nosso Deus."}, {"numero": 4, "texto": "[Ele é] a Rocha, sua obra é perfeita, pois todos os seus caminhos são justos. Deus fiel, e sem imoralidade; justo e correto ele é."}, {"numero": 5, "texto": "Corromperam-se contra ele; não são seus filhos, a falha é deles. São uma geração perversa e distorcida."}, {"numero": 6, "texto": "É assim que pagais ao SENHOR, ó povo tolo e insensato? Não é ele teu pai que te adquiriu, te fez, e te estabeleceu?"}, {"numero": 7, "texto": "Lembra-te dos tempos antigos; Considerai os anos de geração e geração: Pergunta a teu pai, que ele te declarará; A teus anciãos, e eles te dirão."}, {"numero": 8, "texto": "Quando o Altíssimo fez herdar às nações, Quando fez dividir os filhos dos homens, Estabeleceu os termos dos povos Segundo o número dos filhos de Israel."}, {"numero": 9, "texto": "Porque a parte do SENHOR é seu povo; Jacó a medida de sua herança."}, {"numero": 10, "texto": "Achou-o em terra de deserto, E em deserto horrível e ermo; Cercou-o, instruiu-o, Guardou-o como a menina de seu olho."}, {"numero": 11, "texto": "Como a água desperta sua ninhada, paira sobre seus passarinhos, estende suas asas, os toma, os leva sobre suas penas;"}, {"numero": 12, "texto": "o SENHOR sozinho o guiou, e nenhum deus estrangeiro esteve com ele."}, {"numero": 13, "texto": "Ele o fez cavalgar sobre os lugares altos da terra; alimentou-o com os frutos do campo, e o fez sugar mel da rocha e azeite da dura pederneira;"}, {"numero": 14, "texto": "manteiga de vacas e leite de ovelhas, com gordura de cordeiros, e carneiros de Basã; também machos de bode, com o melhor do trigo; e bebeste o sangue das uvas, o vinho puro."}, {"numero": 15, "texto": "E engordou Jesurum, e deu coices: engordaste-te, engrossaste-te, cobriste-te: e deixou ao Deus que lhe fez, e menosprezou a Rocha de sua salvação."}, {"numero": 16, "texto": "Provocaram-lhe ciúmes com os deuses alheios; irritaram-lhe com abominações."}, {"numero": 17, "texto": "Sacrificaram aos demônios, não a Deus; a deuses que não conheciam, a novos deuses vindos de perto, Que não haviam temido vossos pais."}, {"numero": 18, "texto": "Abandonaste a Rocha que te gerou; e te esqueceste do Deus que te criou."}, {"numero": 19, "texto": "E o SENHOR o viu, e acendeu-se em ira, pelo menosprezo de seus filhos e de suas filhas."}, {"numero": 20, "texto": "E disse: esconderei deles meu rosto, verei qual será seu fim; pois são geração de perversidades, filhos sem fidelidade."}, {"numero": 21, "texto": "Eles me provocaram ciúmes com o que não é Deus; com suas vaidades provocaram-me à ira; eu também provocarei os ciúmes com aqueles que não são povo, e com uma nação insensata eu os provocarei à ira."}, {"numero": 22, "texto": "Porque um fogo se acendeu em meu furor, e arderá até as profundezas do Xeol; e consumirá a terra e seus frutos, e abrasará os fundamentos dos montes."}, {"numero": 23, "texto": "Eu trarei males sobre eles; gastarei neles minhas flechas."}, {"numero": 24, "texto": "Consumidos serão de fome, e comidos de febre ardente E de amarga pestilência; Dente de animais enviarei também sobre eles, Com veneno de serpente da terra."}, {"numero": 25, "texto": "De fora desolará a espada, E dentro das câmaras o espanto: Tanto ao rapaz como à virgem, Ao que mama como o homem grisalho."}, {"numero": 26, "texto": "Disse: Eu os dispersaria do mundo, Faria cessar dentre os homens a memória deles,"}, {"numero": 27, "texto": "Se não temesse a ira do inimigo, Não seja que se envaideçam seus adversários, Não seja que digam: Nossa mão alta fez tudo isto, não o SENHOR."}, {"numero": 28, "texto": "Porque são gente de perdidos conselhos, E não há neles entendimento."}, {"numero": 29, "texto": "Bom seria se fossem sábios, que compreendessem isto, E entendessem seu fim!"}, {"numero": 30, "texto": "Como poderia perseguir um a mil, E dois fariam fugir a dez mil, Se sua Rocha não os houvesse vendido, E o SENHOR não os houvesse entregue?"}, {"numero": 31, "texto": "Que a rocha deles não é como nossa Rocha: E nossos inimigos sejam disso juízes."}, {"numero": 32, "texto": "Porque da vide de Sodoma é a vide deles, E dos sarmentos de Gomorra: As uvas deles são uvas venenosas, cachos muito amargos têm."}, {"numero": 33, "texto": "Veneno de serpentes é seu vinho, e peçonha cruel de áspides."}, {"numero": 34, "texto": "Não tenho eu isto guardado, Selado em meus tesouros?"}, {"numero": 35, "texto": "Minha é a vingança e o pagamento, Ao tempo que seu pé vacilará; Porque o dia de sua aflição está próximo, E o que lhes está preparado se apressa."}, {"numero": 36, "texto": "Porque o SENHOR julgará a seu povo, E por causa de seus servos se arrependerá, Quando vir que a força pereceu, E que não há prisioneiro nem livre."}, {"numero": 37, "texto": "E dirá: Onde estão seus deuses, A rocha em que se refugiavam;"}, {"numero": 38, "texto": "Que comiam a gordura de seus sacrifícios, Bebiam o veio de suas libações? Levante-se, que vos ajudem E vos defendam."}, {"numero": 39, "texto": "Vede agora que Eu, Eu Sou, e não há deus além de mim; eu trago a morte, e eu faço viver; eu firo, e eu curo; e não há quem possa escapar da minha mão."}, {"numero": 40, "texto": "Quando eu erguer aos céus minha mão, e disser: “Tão certo como eu vivo para sempre”,"}, {"numero": 41, "texto": "Se eu afiar minha espada reluzente, e minha mão agarrar o juízo, devolverei a vingança sobre os meus adversários, e retribuirei aos que me odeiam."}, {"numero": 42, "texto": "Embriagarei de sangue minhas flechas, e minha espada devorará carne, no sangue dos mortos e dos cativos, das cabeças dos líderes inimigos."}, {"numero": 43, "texto": "Jubilai, ó nações, com o povo dele, porque ele vingará o sangue dos seus servos, e devolverá a vingança sobre os seus inimigos, e expiará sua terra, pelo seu povo."}, {"numero": 44, "texto": "E Moisés veio, e recitou todas as palavras deste cântico aos ouvidos do povo, ele, e Josué filho de Num."}, {"numero": 45, "texto": "E acabou Moisés de recitar todas estas palavras a todo Israel;"}, {"numero": 46, "texto": "E disse-lhes: Ponde vosso coração a todas as palavras que eu vos declaro hoje, para que as mandeis a vossos filhos, e cuidem de praticar todas as palavras desta lei."}, {"numero": 47, "texto": "Porque não vos é coisa vã, mas é vossa vida: e por elas fareis prolongar os dias sobre a terra, para possuir a qual passais o Jordão."}, {"numero": 48, "texto": "E falou o SENHOR a Moisés aquele mesmo dia, dizendo:"}, {"numero": 49, "texto": "Sobe a este monte de Abarim, ao monte Nebo, que está na terra de Moabe, que está em frente de Jericó, e olha a terra de Canaã, que eu dou por herança aos filhos de Israel;"}, {"numero": 50, "texto": "E morre no monte ao qual sobes, e sê reunido a teus povos; ao modo que morreu Arão teu irmão no monte de Hor, e foi reunido a seus povos:"}, {"numero": 51, "texto": "Porquanto transgredistes contra mim em meio dos filhos de Israel nas águas da briga de Cades, no deserto de Zim; porque não me santificastes em meio dos filhos de Israel."}, {"numero": 52, "texto": "Verás, portanto, diante de ti a terra; mas não entrarás ali, à terra que dou aos filhos de Israel."}]'::jsonb, 'Almeida Livre'),
  ('Dt', 32, 'en', '[{"numero": 1, "texto": "Give ear, O ye heavens, and I will speak; and hear, O earth, the words of my mouth."}, {"numero": 2, "texto": "My doctrine shall drop as the rain, my speech shall distil as the dew, as the small rain upon the tender herb, and as the showers upon the grass:"}, {"numero": 3, "texto": "Because I will publish the name of the Lord: ascribe ye greatness unto our God."}, {"numero": 4, "texto": "He is the Rock, his work is perfect: for all his ways are judgment: a God of truth and without iniquity, just and right is he."}, {"numero": 5, "texto": "They have corrupted themselves, their spot is not the spot of his children: they are a perverse and crooked generation."}, {"numero": 6, "texto": "Do ye thus requite the Lord, O foolish people and unwise? is not he thy father that hath bought thee? hath he not made thee, and established thee?"}, {"numero": 7, "texto": "Remember the days of old, consider the years of many generations: ask thy father, and he will shew thee; thy elders, and they will tell thee."}, {"numero": 8, "texto": "When the Most High divided to the nations their inheritance, when he separated the sons of Adam, he set the bounds of the people according to the number of the children of Israel."}, {"numero": 9, "texto": "For the Lord''s portion is his people; Jacob is the lot of his inheritance."}, {"numero": 10, "texto": "He found him in a desert land, and in the waste howling wilderness; he led him about, he instructed him, he kept him as the apple of his eye."}, {"numero": 11, "texto": "As an eagle stirreth up her nest, fluttereth over her young, spreadeth abroad her wings, taketh them, beareth them on her wings:"}, {"numero": 12, "texto": "So the Lord alone did lead him, and there was no strange god with him."}, {"numero": 13, "texto": "He made him ride on the high places of the earth, that he might eat the increase of the fields; and he made him to suck honey out of the rock, and oil out of the flinty rock;"}, {"numero": 14, "texto": "Butter of kine, and milk of sheep, with fat of lambs, and rams of the breed of Bashan, and goats, with the fat of kidneys of wheat; and thou didst drink the pure blood of the grape."}, {"numero": 15, "texto": "But Jeshurun waxed fat, and kicked: thou art waxen fat, thou art grown thick, thou art covered with fatness; then he forsook God which made him, and lightly esteemed the Rock of his salvation."}, {"numero": 16, "texto": "They provoked him to jealousy with strange gods, with abominations provoked they him to anger."}, {"numero": 17, "texto": "They sacrificed unto devils, not to God; to gods whom they knew not, to new gods that came newly up, whom your fathers feared not."}, {"numero": 18, "texto": "Of the Rock that begat thee thou art unmindful, and hast forgotten God that formed thee."}, {"numero": 19, "texto": "And when the Lord saw it, he abhorred them, because of the provoking of his sons, and of his daughters."}, {"numero": 20, "texto": "And he said, I will hide my face from them, I will see what their end shall be: for they are a very froward generation, children in whom is no faith."}, {"numero": 21, "texto": "They have moved me to jealousy with that which is not God; they have provoked me to anger with their vanities: and I will move them to jealousy with those which are not a people; I will provoke them to anger with a foolish nation."}, {"numero": 22, "texto": "For a fire is kindled in mine anger, and shall burn unto the lowest hell, and shall consume the earth with her increase, and set on fire the foundations of the mountains."}, {"numero": 23, "texto": "I will heap mischiefs upon them; I will spend mine arrows upon them."}, {"numero": 24, "texto": "They shall be burnt with hunger, and devoured with burning heat, and with bitter destruction: I will also send the teeth of beasts upon them, with the poison of serpents of the dust."}, {"numero": 25, "texto": "The sword without, and terror within, shall destroy both the young man and the virgin, the suckling also with the man of gray hairs."}, {"numero": 26, "texto": "I said, I would scatter them into corners, I would make the remembrance of them to cease from among men:"}, {"numero": 27, "texto": "Were it not that I feared the wrath of the enemy, lest their adversaries should behave themselves strangely, and lest they should say, Our hand is high, and the Lord hath not done all this."}, {"numero": 28, "texto": "For they are a nation void of counsel, neither is there any understanding in them."}, {"numero": 29, "texto": "O that they were wise, that they understood this, that they would consider their latter end!"}, {"numero": 30, "texto": "How should one chase a thousand, and two put ten thousand to flight, except their Rock had sold them, and the Lord had shut them up?"}, {"numero": 31, "texto": "For their rock is not as our Rock, even our enemies themselves being judges."}, {"numero": 32, "texto": "For their vine is of the vine of Sodom, and of the fields of Gomorrah: their grapes are grapes of gall, their clusters are bitter:"}, {"numero": 33, "texto": "Their wine is the poison of dragons, and the cruel venom of asps."}, {"numero": 34, "texto": "Is not this laid up in store with me, and sealed up among my treasures?"}, {"numero": 35, "texto": "To me belongeth vengeance and recompence; their foot shall slide in due time: for the day of their calamity is at hand, and the things that shall come upon them make haste."}, {"numero": 36, "texto": "For the Lord shall judge his people, and repent himself for his servants, when he seeth that their power is gone, and there is none shut up, or left."}, {"numero": 37, "texto": "And he shall say, Where are their gods, their rock in whom they trusted,"}, {"numero": 38, "texto": "Which did eat the fat of their sacrifices, and drank the wine of their drink offerings? let them rise up and help you, and be your protection."}, {"numero": 39, "texto": "See now that I, even I, am he, and there is no god with me: I kill, and I make alive; I wound, and I heal: neither is there any that can deliver out of my hand."}, {"numero": 40, "texto": "For I lift up my hand to heaven, and say, I live for ever."}, {"numero": 41, "texto": "If I whet my glittering sword, and mine hand take hold on judgment; I will render vengeance to mine enemies, and will reward them that hate me."}, {"numero": 42, "texto": "I will make mine arrows drunk with blood, and my sword shall devour flesh; and that with the blood of the slain and of the captives, from the beginning of revenges upon the enemy."}, {"numero": 43, "texto": "Rejoice, O ye nations, with his people: for he will avenge the blood of his servants, and will render vengeance to his adversaries, and will be merciful unto his land, and to his people."}, {"numero": 44, "texto": "And Moses came and spake all the words of this song in the ears of the people, he, and Hoshea the son of Nun."}, {"numero": 45, "texto": "And Moses made an end of speaking all these words to all Israel:"}, {"numero": 46, "texto": "And he said unto them, Set your hearts unto all the words which I testify among you this day, which ye shall command your children to observe to do, all the words of this law."}, {"numero": 47, "texto": "For it is not a vain thing for you; because it is your life: and through this thing ye shall prolong your days in the land, whither ye go over Jordan to possess it."}, {"numero": 48, "texto": "And the Lord spake unto Moses that selfsame day, saying,"}, {"numero": 49, "texto": "Get thee up into this mountain Abarim, unto mount Nebo, which is in the land of Moab, that is over against Jericho; and behold the land of Canaan, which I give unto the children of Israel for a possession:"}, {"numero": 50, "texto": "And die in the mount whither thou goest up, and be gathered unto thy people; as Aaron thy brother died in mount Hor, and was gathered unto his people:"}, {"numero": 51, "texto": "Because ye trespassed against me among the children of Israel at the waters of MeribahKadesh, in the wilderness of Zin; because ye sanctified me not in the midst of the children of Israel."}, {"numero": 52, "texto": "Yet thou shalt see the land before thee; but thou shalt not go thither unto the land which I give the children of Israel."}]'::jsonb, 'King James Version'),
  ('Dt', 32, 'fr', '[{"numero": 1, "texto": "Cieux! prêtez l''''oreille, et je parlerai; Terre! écoute les paroles de ma bouche."}, {"numero": 2, "texto": "Que mes instructions se répandent comme la pluie, Que ma parole tombe comme la rosée, Comme des ondées sur la verdure, Comme des gouttes d''''eau sur l''''herbe!"}, {"numero": 3, "texto": "Car je proclamerai le nom de l''''Eternel. Rendez gloire à notre Dieu!"}, {"numero": 4, "texto": "Il est le rocher; ses oeuvres sont parfaites, Car toutes ses voies sont justes; C''''est un Dieu fidèle et sans iniquité, Il est juste et droit."}, {"numero": 5, "texto": "S''''ils se sont corrompus, à lui n''''est point la faute; La honte est à ses enfants, Race fausse et perverse."}, {"numero": 6, "texto": "Est-ce l''''Eternel que vous en rendrez responsable, Peuple insensé et dépourvu de sagesse? N''''est-il pas ton père, ton créateur? N''''est-ce pas lui qui t''''a formé, et qui t''''a affermi?"}, {"numero": 7, "texto": "Rappelle à ton souvenir les anciens jours, Passe en revue les années, génération par génération, Interroge ton père, et il te l''''apprendra, Tes vieillards, et ils te le diront."}, {"numero": 8, "texto": "Quand le Très-Haut donna un héritage aux nations, Quand il sépara les enfants des hommes, Il fixa les limites des peuples D''''après le nombre des enfants d''''Israël,"}, {"numero": 9, "texto": "Car la portion de l''''Eternel, c''''est son peuple, Jacob est la part de son héritage."}, {"numero": 10, "texto": "Il l''''a trouvé dans une contrée déserte, Dans une solitude aux effroyables hurlements; Il l''''a entouré, il en a pris soin, Il l''''a gardé comme la prunelle de son oeil,"}, {"numero": 11, "texto": "Pareil à l''''aigle qui éveille sa couvée, Voltige sur ses petits, Déploie ses ailes, les prend, Les porte sur ses plumes."}, {"numero": 12, "texto": "L''''Eternel seul a conduit son peuple, Et il n''''y avait avec lui aucun dieu étranger."}, {"numero": 13, "texto": "Il l''''a fait monter sur les hauteurs du pays, Et Israël a mangé les fruits des champs; Il lui a fait sucer le miel du rocher, L''''huile qui sort du rocher le plus dur,"}, {"numero": 14, "texto": "La crème des vaches et le lait des brebis, Avec la graisse des agneaux, Des béliers de Basan et des boucs, Avec la fleur du froment; Et tu as bu le sang du raisin, le vin."}, {"numero": 15, "texto": "Israël est devenu gras, et il a regimbé; Tu es devenu gras, épais et replet! -Et il a abandonné Dieu, son créateur, Il a méprisé le rocher de son salut,"}, {"numero": 16, "texto": "Ils ont excité sa jalousie par des dieux étrangers, Ils l''''ont irrité par des abominations;"}, {"numero": 17, "texto": "Ils ont sacrifié à des idoles qui ne sont pas Dieu, A des dieux qu''''ils ne connaissaient point, Nouveaux, venus depuis peu, Et que vos pères n''''avaient pas craints."}, {"numero": 18, "texto": "Tu as abandonné le rocher qui t''''a fait naître, Et tu as oublié le Dieu qui t''''a engendré."}, {"numero": 19, "texto": "L''''Eternel l''''a vu, et il a été irrité, Indigné contre ses fils et ses filles."}, {"numero": 20, "texto": "Il a dit: Je leur cacherai ma face, Je verrai quelle sera leur fin; Car c''''est une race perverse, Ce sont des enfants infidèles."}, {"numero": 21, "texto": "Ils ont excité ma jalousie par ce qui n''''est point Dieu, Ils m''''ont irrité par leurs vaines idoles; Et moi, j''''exciterai leur jalousie par ce qui n''''est point un peuple, Je les irriterai par une nation insensée."}, {"numero": 22, "texto": "Car le feu de ma colère s''''est allumé, Et il brûlera jusqu''''au fond du séjour des morts; Il dévorera la terre et ses produits, Il embrasera les fondements des montagnes."}, {"numero": 23, "texto": "J''''accumulerai sur eux les maux, J''''épuiserai mes traits contre eux."}, {"numero": 24, "texto": "Ils seront desséchés par la faim, consumés par la fièvre Et par des maladies violentes; J''''enverrai parmi eux la dent des bêtes féroces Et le venin des serpents."}, {"numero": 25, "texto": "Au dehors, on périra par l''''épée, Et au dedans, par d''''effrayantes calamités: Il en sera du jeune homme comme de la jeune fille, De l''''enfant à la mamelle comme du vieillard."}, {"numero": 26, "texto": "Je voudrais dire: Je les emporterai d''''un souffle, Je ferai disparaître leur mémoire d''''entre les hommes!"}, {"numero": 27, "texto": "Mais je crains les insultes de l''''ennemi, Je crains que leurs adversaires ne se méprennent, Et qu''''ils ne disent: Notre main a été puissante, Et ce n''''est pas l''''Eternel qui a fait toutes ces choses."}, {"numero": 28, "texto": "C''''est une nation qui a perdu le bon sens, Et il n''''y a point en eux d''''intelligence."}, {"numero": 29, "texto": "S''''ils étaient sages, voici ce qu''''ils comprendraient, Et ils penseraient à ce qui leur arrivera."}, {"numero": 30, "texto": "Comment un seul en poursuivrait-il mille, Et deux en mettraient-ils dix mille en fuite, Si leur Rocher ne les avait vendus, Si l''''Eternel ne les avait livrés?"}, {"numero": 31, "texto": "Car leur rocher n''''est pas comme notre Rocher, Nos ennemis en sont juges."}, {"numero": 32, "texto": "Mais leur vigne est du plant de Sodome Et du terroir de Gomorrhe; Leurs raisins sont des raisins empoisonnés, Leurs grappes sont amères;"}, {"numero": 33, "texto": "Leur vin, c''''est le venin des serpents, C''''est le poison cruel des aspics."}, {"numero": 34, "texto": "Cela n''''est-il pas caché près de moi, Scellé dans mes trésors?"}, {"numero": 35, "texto": "A moi la vengeance et la rétribution, Quand leur pied chancellera! Car le jour de leur malheur est proche, Et ce qui les attend ne tardera pas."}, {"numero": 36, "texto": "L''''Eternel jugera son peuple; Mais il aura pitié de ses serviteurs, En voyant que leur force est épuisée, Et qu''''il n''''y a plus ni esclave ni homme libre."}, {"numero": 37, "texto": "Il dira: Où sont leurs dieux, Le rocher qui leur servait de refuge,"}, {"numero": 38, "texto": "Ces dieux qui mangeaient la graisse de leurs victimes, Qui buvaient le vin de leurs libations? Qu''''ils se lèvent, qu''''ils vous secourent, Qu''''ils vous couvrent de leur protection!"}, {"numero": 39, "texto": "Sachez donc que c''''est moi qui suis Dieu, Et qu''''il n''''y a point de dieu près de moi; Je fais vivre et je fais mourir, Je blesse et je guéris, Et personne ne délivre de ma main."}, {"numero": 40, "texto": "Car je lève ma main vers le ciel, Et je dis: Je vis éternellement!"}, {"numero": 41, "texto": "Si j''''aiguise l''''éclair de mon épée Et si ma main saisit la justice, Je me vengerai de mes adversaires Et je punirai ceux qui me haïssent;"}, {"numero": 42, "texto": "Mon épée dévorera leur chair, Et j''''enivrerai mes flèches de sang, Du sang des blessés et des captifs, De la tête des chefs de l''''ennemi."}, {"numero": 43, "texto": "Nations, chantez les louanges de son peuple! Car l''''Eternel venge le sang de ses serviteurs, Il se venge de ses adversaires, Et il fait l''''expiation pour son pays, pour son peuple."}, {"numero": 44, "texto": "Moïse vint et prononça toutes les paroles de ce cantique en présence du peuple; Josué, fils de Nun, était avec lui."}, {"numero": 45, "texto": "Lorsque Moïse eut achevé de prononcer toutes ces paroles devant tout Israël,"}, {"numero": 46, "texto": "il leur dit: Prenez à coeur toutes les paroles que je vous conjure aujourd''''hui de recommander à vos enfants, afin qu''''ils observent et mettent en pratique toutes les paroles de cette loi."}, {"numero": 47, "texto": "Car ce n''''est pas une chose sans importance pour vous; c''''est votre vie, et c''''est par là que vous prolongerez vos jours dans le pays dont vous aurez la possession, après avoir passé le Jourdain."}, {"numero": 48, "texto": "Ce même jour, l''''Eternel parla à Moïse, et dit:"}, {"numero": 49, "texto": "Monte sur cette montagne d''''Abarim, sur le mont Nebo, au pays de Moab, vis-à-vis de Jéricho; et regarde le pays de Canaan que je donne en propriété aux enfants d''''Israël."}, {"numero": 50, "texto": "Tu mourras sur la montagne où tu vas monter, et tu seras recueilli auprès de ton peuple, comme Aaron, ton frère, est mort sur la montagne de Hor et a été recueilli auprès de son peuple,"}, {"numero": 51, "texto": "parce que vous avez péché contre moi au milieu des enfants d''''Israël, près des eaux de Meriba, à Kadès, dans le désert de Tsin, et que vous ne m''''avez point sanctifié au milieu des enfants d''''Israël."}, {"numero": 52, "texto": "Tu verras le pays devant toi; mais tu n''''entreras point dans le pays que je donne aux enfants d''''Israël."}]'::jsonb, 'Louis Segond 1910'),
  ('Dt', 32, 'es', '[{"numero": 1, "texto": "ESCUCHAD, cielos, y hablaré; y oiga la tierra los dichos de mi boca."}, {"numero": 2, "texto": "Goteará como la lluvia mi doctrina; destilará como el rocío mi razonamiento; como la llovizna sobre la grama, y como las gotas sobre la hierba:"}, {"numero": 3, "texto": "Porque el nombre de Jehová invocaré: engrandeced á nuestro Dios."}, {"numero": 4, "texto": "El es la Roca, cuya obra es perfecta, porque todos sus caminos son rectitud: Dios de verdad, y ninguna iniquidad en él: es justo y recto."}, {"numero": 5, "texto": "La corrupción no es suya: á sus hijos la mancha de ellos, generación torcida y perversa."}, {"numero": 6, "texto": "¿Así pagáis á Jehová, pueblo loco é ignorante? ¿no es él tu padre que te poseyó? él te hizo y te ha organizado."}, {"numero": 7, "texto": "Acuérdate de los tiempos antiguos; considerad los años de generación y generación: pregunta á tu padre, que él te declarará; á tus viejos, y ellos te dirán."}, {"numero": 8, "texto": "Cuando el Altísimo hizo heredar á las gentes, cuando hizo dividir los hijos de los hombres, estableció los términos de los pueblos según el número de los hijos de Israel."}, {"numero": 9, "texto": "Porque la parte de Jehová es su pueblo; Jacob la cuerda de su heredad."}, {"numero": 10, "texto": "Hallólo en tierra de desierto, y en desierto horrible y yermo; trájolo alrededor, instruyólo, guardólo como la niña de su ojo."}, {"numero": 11, "texto": "Como el águila despierta su nidada, revolotea sobre sus pollos, extiende sus alas, los toma, los lleva sobre sus plumas:"}, {"numero": 12, "texto": "Jehová solo le guió, que no hubo con él dios ajeno."}, {"numero": 13, "texto": "Hízolo subir sobre las alturas de la tierra, y comió los frutos del campo, é hizo que chupase miel de la peña, y aceite del duro pedernal;"}, {"numero": 14, "texto": "Manteca de vacas y leche de ovejas, con grosura de corderos, y carneros de Basán; también machos de cabrío, con grosura de riñones de trigo: y sangre de uva bebiste, vino puro."}, {"numero": 15, "texto": "Y engrosó Jeshurun, y tiró coces: engordástete, engrosástete, cubrístete: y dejó al Dios que le hizo, y menospreció la Roca de su salud."}, {"numero": 16, "texto": "Despertáronle á celos con los dioses ajenos; ensañáronle con abominaciones."}, {"numero": 17, "texto": "Sacrificaron á los diablos, no á Dios; á dioses que no habían conocido, á nuevos dioses venidos de cerca, que no habían temido vuestros padres."}, {"numero": 18, "texto": "De la Roca que te crió te olvidaste: te has olvidado del Dios tu criador."}, {"numero": 19, "texto": "Y viólo Jehová, y encendióse en ira, por el menosprecio de sus hijos y de sus hijas."}, {"numero": 20, "texto": "Y dijo: Esconderé de ellos mi rostro, veré cuál será su postrimería: que son generación de perversidades, hijos sin fe."}, {"numero": 21, "texto": "Ellos me movieron á celos con lo que no es Dios; hiciéronme ensañar con sus vanidades: yo también los moveré á celos con un pueblo que no es pueblo, con gente insensata los haré ensañar."}, {"numero": 22, "texto": "Porque fuego se encenderá en mi furor, y arderá hasta el profundo; y devorará la tierra y sus frutos, y abrasará los fundamentos de los montes."}, {"numero": 23, "texto": "Yo allegaré males sobre ellos; emplearé en ellos mis saetas."}, {"numero": 24, "texto": "Consumidos serán de hambre, y comidos de fiebre ardiente y de amarga pestilencia; diente de bestias enviaré también sobre ellos, con veneno de serpiente de la tierra."}, {"numero": 25, "texto": "De fuera desolará la espada, y dentro de las cámaras el espanto; así al mancebo como á la doncella, al que mama como el hombre cano."}, {"numero": 26, "texto": "Dije: Echaríalos yo del mundo, haría cesar de entre los hombres la memoria de ellos,"}, {"numero": 27, "texto": "Si no temiese la ira del enemigo, no sea que se envanezcan sus adversarios, no sea que digan: Nuestra mano alta ha hecho todo esto, no Jehová."}, {"numero": 28, "texto": "Porque son gente de perdidos consejos, y no hay en ellos entendimiento."}, {"numero": 29, "texto": "¡Ojalá fueran sabios, que comprendieran esto, y entendieran su postrimería!"}, {"numero": 30, "texto": "¿Cómo podría perseguir uno á mil, y dos harían huir á diez mil, si su Roca no los hubiese vendido, y Jehová no los hubiera entregado?"}, {"numero": 31, "texto": "Que la roca de ellos no es como nuestra Roca: y nuestros enemigos sean de ello jueces."}, {"numero": 32, "texto": "Porque de la vid de Sodoma es la vid de ellos, y de los sarmientos de Gomorra: las uvas de ellos son uvas ponzoñosas, racimos muy amargos tienen."}, {"numero": 33, "texto": "Veneno de dragones es su vino, y ponzoña cruel de áspides."}, {"numero": 34, "texto": "¿No tengo yo esto guardado, sellado en mis tesoros?"}, {"numero": 35, "texto": "Mía es la venganza y el pago, al tiempo que su pie vacilará; porque el día de su aflicción está cercano, y lo que les está preparado se apresura."}, {"numero": 36, "texto": "Porque Jehová juzgará á su pueblo, y por amor de sus siervos se arrepentirá, cuando viere que la fuerza pereció, y que no hay guardado, mas desamparado."}, {"numero": 37, "texto": "Y dirá: ¿Dónde están sus dioses, la roca en que se guarecían;"}, {"numero": 38, "texto": "Que comían el sebo de sus sacrificios, bebían el vino de sus libaciones? Levántense, que os ayuden y os defiendan."}, {"numero": 39, "texto": "Ved ahora que yo, yo soy, y no hay dioses conmigo: yo hago morir, y yo hago vivir: yo hiero, y yo curo: y no hay quien pueda librar de mi mano."}, {"numero": 40, "texto": "Cuando yo alzaré á los cielos mi mano, y diré: Vivo yo para siempre,"}, {"numero": 41, "texto": "Si afilare mi reluciente espada, y mi mano arrebatare el juicio, yo volveré la venganza á mis enemigos, y daré el pago á los que me aborrecen."}, {"numero": 42, "texto": "Embriagaré de sangre mis saetas, y mi espada devorará carne: en la sangre de los muertos y de los cautivos de las cabezas, con venganzas de enemigo."}, {"numero": 43, "texto": "Alabad, gentes, á su pueblo, porque él vengará la sangre de sus siervos, y volverá la venganza á sus enemigos, y expiará su tierra, á su pueblo."}, {"numero": 44, "texto": "Y vino Moisés, y recitó todas las palabras de este cántico á oídos del pueblo, él, y Josué hijo de Nun."}, {"numero": 45, "texto": "Y acabó Moisés de recitar todas estas palabras á todo Israel;"}, {"numero": 46, "texto": "Y díjoles: Poned vuestro corazón á todas las palabras que yo os protesto hoy, para que las mandéis á vuestros hijos, y cuiden de poner por obra todas las palabras de esta ley."}, {"numero": 47, "texto": "Porque no os es cosa vana, mas es vuestra vida: y por ellas haréis prolongar los días sobre la tierra, para poseer la cual pasáis el Jordán."}, {"numero": 48, "texto": "Y habló Jehová á Moisés aquel mismo día, diciendo:"}, {"numero": 49, "texto": "Sube á este monte de Abarim, al monte Nebo, que está en la tierra de Moab, que está en derecho de Jericó, y mira la tierra de Canaán, que yo doy por heredad á los hijos de Israel;"}, {"numero": 50, "texto": "Y muere en el monte al cual subes, y sé reunido á tus pueblos; al modo que murió Aarón tu hermano en el monte de Hor, y fué reunido á sus pueblos:"}, {"numero": 51, "texto": "Por cuanto prevaricasteis contra mí en medio de los hijos de Israel en las aguas de la rencilla de Cades, en el desierto de Zin; porque no me santificasteis en medio de los hijos de Israel."}, {"numero": 52, "texto": "Verás por tanto delante de ti la tierra; mas no entrarás allá, á la tierra que doy á los hijos de Israel."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dt', 33, 'pt', '[{"numero": 1, "texto": "E esta é a bênção com a qual abençoou Moisés homem de Deus aos filhos de Israel, antes que morresse."}, {"numero": 2, "texto": "E disse: O SENHOR veio de Sinai, E de Seir lhes iluminou; Resplandeceu do monte de Parã, E veio com dez mil santos: À sua direita a lei de fogo para eles."}, {"numero": 3, "texto": "Ainda amou os povos; Todos seus santos em tua mão: Eles também se chegaram a teus pés: Receberam de teus ditos."}, {"numero": 4, "texto": "Lei nos mandou Moisés, Herança à congregação de Jacó."}, {"numero": 5, "texto": "E foi rei em Jesurum, quando se congregaram os chefes do povo com as tribos de Israel."}, {"numero": 6, "texto": "Viva Rúben, e não morra; sejam seus homens em número."}, {"numero": 7, "texto": "E esta bênção para Judá. Disse assim: Ouve, ó SENHOR, a voz de Judá, e leva-o ao seu povo; suas mãos lhe bastem, e tu sejas ajuda contra seus inimigos."}, {"numero": 8, "texto": "E a Levi disse: Teu Tumim e teu Urim, com teu bom homem ao qual tentaste em Massá, e lhe fizeste brigar nas águas da briga;"}, {"numero": 9, "texto": "O que disse a seu pai e a sua mãe: Nunca os vi: nem conheceu a seus irmãos, nem conheceu a seus filhos; por isso eles guardarão as tuas palavras, e observarão o teu pacto."}, {"numero": 10, "texto": "Eles ensinarão teus juízos a Jacó, e tua lei a Israel; porão o incenso diante de ti, e holocaustos sobre o teu altar."}, {"numero": 11, "texto": "Abençoa, ó SENHOR, o que fizerem, e recebe com agrado a obra de suas mãos; fere os lombos de seus inimigos, e dos que lhe odiarem; para que nunca se levantem."}, {"numero": 12, "texto": "E a Benjamim disse: O amado do SENHOR habitará confiante próximo dele; Ele o cobrirá sempre, E entre seus ombros morará."}, {"numero": 13, "texto": "E a José disse: Bendita do SENHOR [seja] a sua terra, com as dádivas dos céus, com o orvalho, e com o abismo que jaz abaixo,"}, {"numero": 14, "texto": "com excelentes frutos do sol, e com os excelentes produtos de cada lua,"}, {"numero": 15, "texto": "e com o que há de mais excelente dos montes antigos, e com os excelentes produtos das colinas eternas,"}, {"numero": 16, "texto": "e com os excelentes produtos da terra e sua plenitude; e que a benevolência daquele que habitou na sarça venha sobre a cabeça de José, e sobre ao topo da cabeça do que foi separado dos seus irmãos."}, {"numero": 17, "texto": "Ele é preeminente como o primogênito de seu touro, e suas pontas, chifres de boi selvagem; com eles chifrará os povos juntamente até os confins da terra; e estes são as dezenas de milhares de Efraim, e estes os milhares de Manassés."}, {"numero": 18, "texto": "E a Zebulom disse: Alegra-te, Zebulom, quando saíres; e tu Issacar, em tuas tendas."}, {"numero": 19, "texto": "Eles chamarão os povos ao monte; ali oferecerão sacrifícios de justiça; porque sugarão a abundância dos mares, e os tesouros escondidos da areia."}, {"numero": 20, "texto": "E a Gade disse: Bendito o que fez alargar a Gade: Como leão habitará, e arrebatará braço e testa."}, {"numero": 21, "texto": "E ele se proveu da primeira parte, porque ali uma porção do legislador foi-lhe reservada, e veio na dianteira do povo; executará a justiça do SENHOR, e seus juízos com Israel."}, {"numero": 22, "texto": "E a Dã disse: Dã [é] um leão jovem; saltará desde Basã."}, {"numero": 23, "texto": "E a Naftali disse: Naftali, saciado de benevolência, e cheio da bênção do SENHOR, possui o ocidente e o sul,"}, {"numero": 24, "texto": "E a Aser disse: Bendito [seja] Aser em filhos; agradável será aos seus irmãos, e molhará em azeite o seu pé."}, {"numero": 25, "texto": "ferro e bronze [será] o teu calçado, e tua força [será] como os teus dias."}, {"numero": 26, "texto": "Não há como o Deus de Jesurum, montado sobre os céus para tua ajuda, e sobre as nuvens com sua grandeza."}, {"numero": 27, "texto": "O eterno Deus é o teu refúgio, e abaixo os braços eternos; ele expulsará de diante de ti o inimigo, e dirá: Destrói."}, {"numero": 28, "texto": "E Israel, fonte de Jacó, habitará confiante sozinho na terra do grão e do vinho; também seus céus destilarão orvalho."}, {"numero": 29, "texto": "Bem-aventurado és tu, ó Israel! Quem é como tu, povo salvo pelo SENHOR, o escudo de teu socorro, e a espada da tua excelência? Por isso os teus inimigos serão subjugados, e tu pisarás sobre as suas alturas."}]'::jsonb, 'Almeida Livre'),
  ('Dt', 33, 'en', '[{"numero": 1, "texto": "And this is the blessing, wherewith Moses the man of God blessed the children of Israel before his death."}, {"numero": 2, "texto": "And he said, The Lord came from Sinai, and rose up from Seir unto them; he shined forth from mount Paran, and he came with ten thousands of saints: from his right hand went a fiery law for them."}, {"numero": 3, "texto": "Yea, he loved the people; all his saints are in thy hand: and they sat down at thy feet; every one shall receive of thy words."}, {"numero": 4, "texto": "Moses commanded us a law, even the inheritance of the congregation of Jacob."}, {"numero": 5, "texto": "And he was king in Jeshurun, when the heads of the people and the tribes of Israel were gathered together."}, {"numero": 6, "texto": "Let Reuben live, and not die; and let not his men be few."}, {"numero": 7, "texto": "And this is the blessing of Judah: and he said, Hear, Lord, the voice of Judah, and bring him unto his people: let his hands be sufficient for him; and be thou an help to him from his enemies."}, {"numero": 8, "texto": "And of Levi he said, Let thy Thummim and thy Urim be with thy holy one, whom thou didst prove at Massah, and with whom thou didst strive at the waters of Meribah;"}, {"numero": 9, "texto": "Who said unto his father and to his mother, I have not seen him; neither did he acknowledge his brethren, nor knew his own children: for they have observed thy word, and kept thy covenant."}, {"numero": 10, "texto": "They shall teach Jacob thy judgments, and Israel thy law: they shall put incense before thee, and whole burnt sacrifice upon thine altar."}, {"numero": 11, "texto": "Bless, Lord, his substance, and accept the work of his hands; smite through the loins of them that rise against him, and of them that hate him, that they rise not again."}, {"numero": 12, "texto": "And of Benjamin he said, The beloved of the Lord shall dwell in safety by him; and the Lord shall cover him all the day long, and he shall dwell between his shoulders."}, {"numero": 13, "texto": "And of Joseph he said, Blessed of the Lord be his land, for the precious things of heaven, for the dew, and for the deep that coucheth beneath,"}, {"numero": 14, "texto": "And for the precious fruits brought forth by the sun, and for the precious things put forth by the moon,"}, {"numero": 15, "texto": "And for the chief things of the ancient mountains, and for the precious things of the lasting hills,"}, {"numero": 16, "texto": "And for the precious things of the earth and fulness thereof, and for the good will of him that dwelt in the bush: let the blessing come upon the head of Joseph, and upon the top of the head of him that was separated from his brethren."}, {"numero": 17, "texto": "His glory is like the firstling of his bullock, and his horns are like the horns of unicorns: with them he shall push the people together to the ends of the earth: and they are the ten thousands of Ephraim, and they are the thousands of Manasseh."}, {"numero": 18, "texto": "And of Zebulun he said, Rejoice, Zebulun, in thy going out; and, Issachar, in thy tents."}, {"numero": 19, "texto": "They shall call the people unto the mountain; there they shall offer sacrifices of righteousness: for they shall suck of the abundance of the seas, and of treasures hid in the sand."}, {"numero": 20, "texto": "And of Gad he said, Blessed be he that enlargeth Gad: he dwelleth as a lion, and teareth the arm with the crown of the head."}, {"numero": 21, "texto": "And he provided the first part for himself, because there, in a portion of the lawgiver, was he seated; and he came with the heads of the people, he executed the justice of the Lord, and his judgments with Israel."}, {"numero": 22, "texto": "And of Dan he said, Dan is a lion''s whelp: he shall leap from Bashan."}, {"numero": 23, "texto": "And of Naphtali he said, O Naphtali, satisfied with favour, and full with the blessing of the Lord: possess thou the west and the south."}, {"numero": 24, "texto": "And of Asher he said, Let Asher be blessed with children; let him be acceptable to his brethren, and let him dip his foot in oil."}, {"numero": 25, "texto": "Thy shoes shall be iron and brass; and as thy days, so shall thy strength be."}, {"numero": 26, "texto": "There is none like unto the God of Jeshurun, who rideth upon the heaven in thy help, and in his excellency on the sky."}, {"numero": 27, "texto": "The eternal God is thy refuge, and underneath are the everlasting arms: and he shall thrust out the enemy from before thee; and shall say, Destroy them."}, {"numero": 28, "texto": "Israel then shall dwell in safety alone: the fountain of Jacob shall be upon a land of corn and wine; also his heavens shall drop down dew."}, {"numero": 29, "texto": "Happy art thou, O Israel: who is like unto thee, O people saved by the Lord, the shield of thy help, and who is the sword of thy excellency! and thine enemies shall be found liars unto thee; and thou shalt tread upon their high places."}]'::jsonb, 'King James Version'),
  ('Dt', 33, 'fr', '[{"numero": 1, "texto": "Voici la bénédiction par laquelle Moïse, homme de Dieu, bénit les enfants d''''Israël, avant sa mort."}, {"numero": 2, "texto": "Il dit: L''''Eternel est venu du Sinaï, Il s''''est levé sur eux de Séir, Il a resplendi de la montagne de Paran, Et il est sorti du milieu des saintes myriades: Il leur a de sa droite envoyé le feu de la loi."}, {"numero": 3, "texto": "Oui, il aime les peuples; Tous ses saints sont dans ta main. Ils se sont tenus à tes pieds, Ils ont reçu tes paroles."}, {"numero": 4, "texto": "Moïse nous a donné la loi, Héritage de l''''assemblée de Jacob."}, {"numero": 5, "texto": "Il était roi en Israël, Quand s''''assemblaient les chefs du peuple Et les tribus d''''Israël."}, {"numero": 6, "texto": "Que Ruben vive et qu''''il ne meure point, Et que ses hommes soient nombreux!"}, {"numero": 7, "texto": "Voici sur Juda ce qu''''il dit: Ecoute, ô Eternel! la voix de Juda, Et ramène-le vers son peuple. Que ses mains soient puissantes, Et que tu lui sois en aide contre ses ennemis!"}, {"numero": 8, "texto": "Sur Lévi il dit: Les thummim et les urim ont été confiés à l''''homme saint, Que tu as tenté à Massa, Et avec qui tu as contesté aux eaux de Meriba."}, {"numero": 9, "texto": "Lévi dit de son père et de sa mère: Je ne les ai point vus! Il ne distingue point ses frères, Il ne connaît point ses enfants. Car ils observent ta parole, Et ils gardent ton alliance;"}, {"numero": 10, "texto": "Ils enseignent tes ordonnances à Jacob, Et ta loi à Israël; Ils mettent l''''encens sous tes narines, Et l''''holocauste sur ton autel."}, {"numero": 11, "texto": "Bénis sa force, ô Eternel! Agrée l''''oeuvre de ses mains! Brise les reins de ses adversaires, Et que ses ennemis ne se relèvent plus!"}, {"numero": 12, "texto": "Sur Benjamin il dit: C''''est le bien-aimé de l''''Eternel, Il habitera en sécurité auprès de lui; L''''Eternel le couvrira toujours, Et résidera entre ses épaules."}, {"numero": 13, "texto": "Sur Joseph il dit: Son pays recevra de l''''Eternel, en signe de bénédiction, Le meilleur don du ciel, la rosée, Les meilleures eaux qui sont en bas,"}, {"numero": 14, "texto": "Les meilleurs fruits du soleil, Les meilleurs fruits de chaque mois,"}, {"numero": 15, "texto": "Les meilleurs produits des antiques montagnes, Les meilleurs produits des collines éternelles,"}, {"numero": 16, "texto": "Les meilleurs produits de la terre et de ce qu''''elle renferme. Que la grâce de celui qui apparut dans le buisson Vienne sur la tête de Joseph, Sur le sommet de la tête du prince de ses frères!"}, {"numero": 17, "texto": "De son taureau premier-né il a la majesté; Ses cornes sont les cornes du buffle; Avec elles il frappera tous les peuples, Jusqu''''aux extrémités de la terre: Elles sont les myriades d''''Ephraïm, Elles sont les milliers de Manassé."}, {"numero": 18, "texto": "Sur Zabulon il dit: Réjouis-toi, Zabulon, dans tes courses, Et toi, Issacar, dans tes tentes!"}, {"numero": 19, "texto": "Ils appelleront les peuples sur la montagne; Là, ils offriront des sacrifices de justice, Car ils suceront l''''abondance de la mer, Et les trésors cachés dans le sable."}, {"numero": 20, "texto": "Sur Gad il dit: Béni soit celui qui met Gad au large! Gad repose comme une lionne, Il déchire le bras et la tête."}, {"numero": 21, "texto": "Il a choisi les prémices du pays, Car là est caché l''''héritage du législateur; Il a marché en tête du peuple, Il a exécuté la justice de l''''Eternel, Et ses ordonnances envers Israël."}, {"numero": 22, "texto": "Sur Dan il dit: Dan est un jeune lion, Qui s''''élance de Basan."}, {"numero": 23, "texto": "Sur Nephthali il dit: Nephthali, rassasié de faveurs Et comblé des bénédictions de l''''Eternel, Prends possession de l''''occident et du midi!"}, {"numero": 24, "texto": "Sur Aser il dit: Béni soit Aser entre les enfants d''''Israël! Qu''''il soit agréable à ses frères, Et qu''''il plonge son pied dans l''''huile!"}, {"numero": 25, "texto": "Que tes verrous soient de fer et d''''airain, Et que ta vigueur dure autant que tes jours!"}, {"numero": 26, "texto": "Nul n''''est semblable au Dieu d''''Israël, Il est porté sur les cieux pour venir à ton aide, Il est avec majesté porté sur les nuées."}, {"numero": 27, "texto": "Le Dieu d''''éternité est un refuge, Et sous ses bras éternels est une retraite. Devant toi il a chassé l''''ennemi, Et il a dit: Extermine."}, {"numero": 28, "texto": "Israël est en sécurité dans sa demeure, La source de Jacob est à part Dans un pays de blé et de moût, Et son ciel distille la rosée."}, {"numero": 29, "texto": "Que tu es heureux, Israël! Qui est comme toi, Un peuple sauvé par l''''Eternel, Le bouclier de ton secours Et l''''épée de ta gloire? Tes ennemis feront défaut devant toi, Et tu fouleras leurs lieux élevés."}]'::jsonb, 'Louis Segond 1910'),
  ('Dt', 33, 'es', '[{"numero": 1, "texto": "Y ESTA es la bendición con la cual bendijo Moisés varón de Dios á los hijos de Israel, antes que muriese."}, {"numero": 2, "texto": "Y dijo: Jehová vino de Sinaí, y de Seir les esclareció; resplandeció del monte de Parán, y vino con diez mil santos: á su diestra la ley de fuego para ellos."}, {"numero": 3, "texto": "Aun amó los pueblos; todos sus santos en tu mano: ellos también se llegaron á tus pies: recibieron de tus dichos."}, {"numero": 4, "texto": "Ley nos mandó Moisés, heredad á la congregación de Jacob."}, {"numero": 5, "texto": "Y fué rey en Jeshurun, cuando se congregaron las cabezas del pueblo con las tribus de Israel."}, {"numero": 6, "texto": "Viva Rubén, y no muera; y sean sus varones en número."}, {"numero": 7, "texto": "Y esta bendición para Judá. Dijo así: Oye, oh Jehová, la voz de Judá, y llévalo á su pueblo; sus manos le basten, y tú seas ayuda contra sus enemigos."}, {"numero": 8, "texto": "Y á Leví dijo: Tu Thummim y tu Urim, con tu buen varón, al cual tentaste en Massa, y le hiciste reñir en las aguas de la rencilla;"}, {"numero": 9, "texto": "El que dijo á su padre y á su madre: Nunca los vi: ni conoció á sus hermanos, ni conoció á sus hijos: por lo cual ellos guardarán tus palabras, y observarán tu pacto."}, {"numero": 10, "texto": "Ellos enseñarán tus juicios á Jacob, y tu ley á Israel; pondrán el perfume delante de ti, y el holocausto sobre tu altar."}, {"numero": 11, "texto": "Bendice, oh Jehová, lo que hicieren, y recibe con agrado la obra de sus manos: hiere los lomos de sus enemigos, y de los que le aborrecieren; para que nunca se levanten."}, {"numero": 12, "texto": "Y á Benjamín dijo: El amado de Jehová habitará confiado cerca de él; cubrirálo siempre, y entre sus hombros morará."}, {"numero": 13, "texto": "Y á José dijo: Bendita de Jehová su tierra, por los regalos de los cielos, por el rocío, y por el abismo que abajo yace,"}, {"numero": 14, "texto": "Y por los regalados frutos del sol, y por los regalos de las influencias de las lunas,"}, {"numero": 15, "texto": "Y por la cumbre de los montes antiguos, y por los regalos de los collados eternos,"}, {"numero": 16, "texto": "Y por los regalos de la tierra y su plenitud; y la gracia del que habitó en la zarza venga sobre la cabeza de José, y sobre la mollera del apartado de sus hermanos."}, {"numero": 17, "texto": "El es aventajado como el primogénito de su toro, y sus cuernos, cuernos de unicornio: con ellos acorneará los pueblos juntos hasta los fines de la tierra: y estos son los diez millares de Ephraim, y estos los millares de Manasés."}, {"numero": 18, "texto": "Y á Zabulón dijo: Alégrate, Zabulón, cuando salieres: y tú, Issachâr, en tus tiendas."}, {"numero": 19, "texto": "Llamarán los pueblos al monte; allí sacrificarán sacrificios de justicia: por lo cual chuparán la abundancia de los mares, y los tesoros escondidos de la arena."}, {"numero": 20, "texto": "Y á Gad dijo: Bendito el que hizo ensanchar á Gad: como león habitará, y arrebatará brazo y testa."}, {"numero": 21, "texto": "Y él se ha provisto de la parte primera, porque allí una porción del legislador fuéle reservada, y vino en la delantera del pueblo; la justicia de Jehová ejecutará, y sus juicios con Israel."}, {"numero": 22, "texto": "Y á Dan dijo: Dan, cachorro de león: saltará desde Basán."}, {"numero": 23, "texto": "Y á Nephtalí dijo: Nephtalí, saciado de benevolencia, y lleno de la bendición de Jehová, posee el occidente y el mediodía."}, {"numero": 24, "texto": "Y á Aser dijo: Bendito Aser en hijos: agradable será á sus hermanos, y mojará en aceite su pie."}, {"numero": 25, "texto": "Hierro y metal tu calzado, y como tus días tu fortaleza."}, {"numero": 26, "texto": "No hay como el Dios de Jeshurun, montado sobre los cielos para tu ayuda, y sobre las nubes con su grandeza."}, {"numero": 27, "texto": "El eterno Dios es tu refugio, y acá abajo los brazos eternos; él echará de delante de ti al enemigo, y dirá: Destruye."}, {"numero": 28, "texto": "E Israel, fuente de Jacob, habitará confiado solo en tierra de grano y de vino: también sus cielos destilarán rocío."}, {"numero": 29, "texto": "Bienaventurado tú, oh Israel, ¿quién como tú, pueblo salvo por Jehová, escudo de tu socorro, y espada de tu excelencia? Así que tus enemigos serán humillados, y tú hollarás sobre sus alturas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Dt', 34, 'pt', '[{"numero": 1, "texto": "E Moisés subiu dos campos de Moabe ao monte Nebo, ao cume de Pisga, que está em frente de Jericó; e o SENHOR mostrou-lhe toda a terra de Gileade até Dã,"}, {"numero": 2, "texto": "E a todo Naftali, e a terra de Efraim e de Manassés, toda a terra de Judá até o mar mais distante;"}, {"numero": 3, "texto": "E a parte sul, e a campina, o vale de Jericó, cidade das palmeiras, até Zoar."}, {"numero": 4, "texto": "E disse-lhe o SENHOR: Esta é a terra de que jurei a Abraão, a Isaque, e a Jacó, dizendo: À tua descendência a darei. Eu a fiz ver com teus olhos, mas não passarás ali."}, {"numero": 5, "texto": "E morreu ali Moisés, servo do SENHOR, na terra de Moabe, conforme o dito do SENHOR."}, {"numero": 6, "texto": "E enterrou-o no vale, em terra de Moabe, em frente de Bete-Peor; e ninguém sabe seu sepulcro até hoje."}, {"numero": 7, "texto": "E era Moisés de idade de cento e vinte anos quando morreu: seus olhos nunca se escureceram, nem perdeu o seu vigor."}, {"numero": 8, "texto": "E choraram os filhos de Israel a Moisés nos campos de Moabe trinta dias: E assim se cumpriram os dias do choro do luto de Moisés."}, {"numero": 9, "texto": "E Josué filho de Num foi cheio de espírito de sabedoria, porque Moisés havia posto suas mãos sobre ele: e os filhos de Israel lhe obedeceram, e fizeram como o SENHOR mandou a Moisés."}, {"numero": 10, "texto": "E nunca mais se levantou profeta em Israel como Moisés, a quem haja conhecido o SENHOR face a face;"}, {"numero": 11, "texto": "Em todos os sinais e prodígios que lhe enviou o SENHOR a fazer em terra do Egito a Faraó, e a todos os seus servos, e a toda sua terra;"}, {"numero": 12, "texto": "E em toda aquela mão poderosa, e em todo o grande espanto que Moisés causou à vista de todo Israel."}]'::jsonb, 'Almeida Livre'),
  ('Dt', 34, 'en', '[{"numero": 1, "texto": "And Moses went up from the plains of Moab unto the mountain of Nebo, to the top of Pisgah, that is over against Jericho. And the Lord shewed him all the land of Gilead, unto Dan,"}, {"numero": 2, "texto": "And all Naphtali, and the land of Ephraim, and Manasseh, and all the land of Judah, unto the utmost sea,"}, {"numero": 3, "texto": "And the south, and the plain of the valley of Jericho, the city of palm trees, unto Zoar."}, {"numero": 4, "texto": "And the Lord said unto him, This is the land which I sware unto Abraham, unto Isaac, and unto Jacob, saying, I will give it unto thy seed: I have caused thee to see it with thine eyes, but thou shalt not go over thither."}, {"numero": 5, "texto": "So Moses the servant of the Lord died there in the land of Moab, according to the word of the Lord."}, {"numero": 6, "texto": "And he buried him in a valley in the land of Moab, over against Bethpeor: but no man knoweth of his sepulchre unto this day."}, {"numero": 7, "texto": "And Moses was an hundred and twenty years old when he died: his eye was not dim, nor his natural force abated."}, {"numero": 8, "texto": "And the children of Israel wept for Moses in the plains of Moab thirty days: so the days of weeping and mourning for Moses were ended."}, {"numero": 9, "texto": "And Joshua the son of Nun was full of the spirit of wisdom; for Moses had laid his hands upon him: and the children of Israel hearkened unto him, and did as the Lord commanded Moses."}, {"numero": 10, "texto": "And there arose not a prophet since in Israel like unto Moses, whom the Lord knew face to face,"}, {"numero": 11, "texto": "In all the signs and the wonders, which the Lord sent him to do in the land of Egypt to Pharaoh, and to all his servants, and to all his land,"}, {"numero": 12, "texto": "And in all that mighty hand, and in all the great terror which Moses shewed in the sight of all Israel."}]'::jsonb, 'King James Version'),
  ('Dt', 34, 'fr', '[{"numero": 1, "texto": "Moïse monta des plaines de Moab sur le mont Nebo, au sommet du Pisga, vis-à-vis de Jéricho. Et l''''Eternel lui fit voir tout le pays: Galaad jusqu''''à Dan,"}, {"numero": 2, "texto": "tout Nephthali, le pays d''''Ephraïm et de Manassé, tout le pays de Juda jusqu''''à la mer occidentale,"}, {"numero": 3, "texto": "le midi, les environs du Jourdain, la vallée de Jéricho, la ville des palmiers, jusqu''''à Tsoar."}, {"numero": 4, "texto": "L''''Eternel lui dit: C''''est là le pays que j''''ai juré de donner à Abraham, à Isaac et à Jacob, en disant: Je le donnerai à ta postérité. Je te l''''ai fait voir de tes yeux; mais tu n''''y entreras point."}, {"numero": 5, "texto": "Moïse, serviteur de l''''Eternel, mourut là, dans le pays de Moab, selon l''''ordre de l''''Eternel."}, {"numero": 6, "texto": "Et l''''Eternel l''''enterra dans la vallée, au pays de Moab, vis-à-vis de Beth-Peor. Personne n''''a connu son sépulcre jusqu''''à ce jour."}, {"numero": 7, "texto": "Moïse était âgé de cent vingt ans lorsqu''''il mourut; sa vue n''''était point affaiblie, et sa vigueur n''''était point passée."}, {"numero": 8, "texto": "Les enfants d''''Israël pleurèrent Moïse pendant trente jours, dans les plaines de Moab; et ces jours de pleurs et de deuil sur Moïse arrivèrent à leur terme."}, {"numero": 9, "texto": "Josué, fils de Nun, était rempli de l''''esprit de sagesse, car Moïse avait posé ses mains sur lui. Les enfants d''''Israël lui obéirent, et se conformèrent aux ordres que l''''Eternel avait donnés à Moïse."}, {"numero": 10, "texto": "Il n''''a plus paru en Israël de prophète semblable à Moïse, que l''''Eternel connaissait face à face."}, {"numero": 11, "texto": "Nul ne peut lui être comparé pour tous les signes et les miracles que Dieu l''''envoya faire au pays d''''Egypte contre Pharaon, contre ses serviteurs et contre tout son pays,"}, {"numero": 12, "texto": "et pour tous les prodiges de terreur que Moïse accomplit à main forte sous les yeux de tout Israël."}]'::jsonb, 'Louis Segond 1910'),
  ('Dt', 34, 'es', '[{"numero": 1, "texto": "Y SUBIÓ Moisés de los campos de Moab al monte de Nebo, á la cumbre de Pisga, que está enfrente de Jericó: y mostróle Jehová toda la tierra de Galaad hasta Dan,"}, {"numero": 2, "texto": "Y á todo Nephtalí, y la tierra de Ephraim y de Manasés, toda la tierra de Judá hasta la mar postrera;"}, {"numero": 3, "texto": "Y la parte meridional, y la campiña, la vega de Jericó, ciudad de las palmas, hasta Soar."}, {"numero": 4, "texto": "Y díjole Jehová: Esta es la tierra de que juré á Abraham, á Isaac, y á Jacob, diciendo: A tu simiente la daré. Hétela hecho ver con tus ojos, mas no pasarás allá."}, {"numero": 5, "texto": "Y murió allí Moisés siervo de Jehová, en la tierra de Moab, conforme al dicho de Jehová."}, {"numero": 6, "texto": "Y enterrólo en el valle, en tierra de Moab, enfrente de Bethpeor; y ninguno sabe su sepulcro hasta hoy."}, {"numero": 7, "texto": "Y era Moisés de edad de ciento y veinte años cuando murió: sus ojos nunca se oscurecieron, ni perdió su vigor."}, {"numero": 8, "texto": "Y lloraron los hijos de Israel á Moisés en los campos de Moab treinta días: y así se cumplieron los días del lloro del luto de Moisés."}, {"numero": 9, "texto": "Y Josué hijo de Nun fué lleno de espíritu de sabiduría, porque Moisés había puesto sus manos sobre él: y los hijos de Israel le obedecieron, é hicieron como Jehová mandó á Moisés."}, {"numero": 10, "texto": "Y nunca más se levantó profeta en Israel como Moisés, á quien haya conocido Jehová cara á cara;"}, {"numero": 11, "texto": "En todas las señales y prodigios que le envió Jehová á hacer en tierra de Egipto á Faraón, y á todos sus siervos, y á toda su tierra;"}, {"numero": 12, "texto": "Y en toda aquella mano esforzada, y en todo el espanto grande que causó Moisés á ojos de todo Israel."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ec', 5, 'pt', '[{"numero": 1, "texto": "Guarda os teus passos quando entrares na casa de Deus, e te achegues a ouvir em vez de oferecer sacrifícios de tolos, pois não sabem que fazem mal."}, {"numero": 2, "texto": "Não te precipites com tua boca, nem te apresses com teu coração, a pronunciar palavra alguma perante a face de Deus; porque Deus está nos céus, e tu estás na terra; por isso, que tuas palavras sejam poucas."}, {"numero": 3, "texto": "Pois, como os sonhos vêm das muitas ocupações, assim também o excesso de palavras vem da voz do tolo."}, {"numero": 4, "texto": "Quando fizeres algum voto a Deus, não demores em pagá-lo; porque ele não se agrada de tolos. Paga o voto que fizeres."}, {"numero": 5, "texto": "Melhor é que não faças voto, do que fazeres um voto, e não o pagares."}, {"numero": 6, "texto": "Não permitas que a tua boca faça a tua carne pecar; nem digas perante o mensageiro que foi um mero erro; por que provocarias a ira de Deus com a tua voz, para que ele destrua a obra de tuas mãos?"}, {"numero": 7, "texto": "Porque, como na abundância de sonhos há futilidades, assim, também, há abundância de palavras; tu, porém, teme a Deus."}, {"numero": 8, "texto": "Se vires em algum território a opressão dos pobres, e a violência contra o direito e a justiça, não te surpreendas de tal caso; porque o oficial tem uma autoridade maior que o supervisiona; e acima de ambos há outros que têmautoridade ainda maior."}, {"numero": 9, "texto": "E o proveito da terra é para todos; até o rei se serve do campo."}, {"numero": 10, "texto": "O que amar o dinheiro nunca se saciará do dinheiro; e quem amar a riqueza, nunca [se saciará] do lucro; isso também é futilidade."}, {"numero": 11, "texto": "Onde os bens se multiplicam, ali se multiplicam também os que os cosomem; e que proveito pois tem seus donos, a não ser somente ver [as riquezas] com seus próprios olhos?"}, {"numero": 12, "texto": "Doce é o sono do trabalhador, quer coma pouco, quer muito; porém a fartura do rico não o deixa dormir."}, {"numero": 13, "texto": "Há um mal causador de sofrimentos que vi abaixo do sol: as riquezas que seus donos guardam para seu próprio mal."}, {"numero": 14, "texto": "Porque as mesmas riquezas se perdem com negócios malsucedidos; e quando gera algum filho, nada lhe fica em sua mão."}, {"numero": 15, "texto": "Assim como ele saiu do ventre de sua mãe, nu ele voltará, indo-se como veio; e nada tomará de seu trabalho, que possa levar em sua mão."}, {"numero": 16, "texto": "De maneira que isto também é um mal causador de sofrimentos, que exatamente como veio, assim se vai; e que proveito ele teve em trabalhar para o vento?"}, {"numero": 17, "texto": "Além disso, ele comeu em trevas todos os seus dias; sofreu muito, e teve enfermidades e irritações."}, {"numero": 18, "texto": "Eis o que eu vi, algo bom e belo: comer, beber, e experimentar o que é bom de todo o seu trabalho em que trabalhou abaixo do sol, durante os dias de sua vida, que Deus lhe deu; porque isto é a parte que lhe pertence."}, {"numero": 19, "texto": "E todo homem a quem Deus deu riquezas e bens, e lhe deu poder para comer delas, e tomar sua parte, e se alegrar de seu trabalho; isto é presente de Deus."}, {"numero": 20, "texto": "Pois ele não se lembrará muito dos dias de sua vida, porque Deus lhe responde com alegria de seu coração."}]'::jsonb, 'Almeida Livre'),
  ('Ec', 5, 'en', '[{"numero": 1, "texto": "Keep thy foot when thou goest to the house of God, and be more ready to hear, than to give the sacrifice of fools: for they consider not that they do evil."}, {"numero": 2, "texto": "Be not rash with thy mouth, and let not thine heart be hasty to utter any thing before God: for God is in heaven, and thou upon earth: therefore let thy words be few."}, {"numero": 3, "texto": "For a dream cometh through the multitude of business; and a fool''s voice is known by multitude of words."}, {"numero": 4, "texto": "When thou vowest a vow unto God, defer not to pay it; for he hath no pleasure in fools: pay that which thou hast vowed."}, {"numero": 5, "texto": "Better is it that thou shouldest not vow, than that thou shouldest vow and not pay."}, {"numero": 6, "texto": "Suffer not thy mouth to cause thy flesh to sin; neither say thou before the angel, that it was an error: wherefore should God be angry at thy voice, and destroy the work of thine hands?"}, {"numero": 7, "texto": "For in the multitude of dreams and many words there are also divers vanities: but fear thou God."}, {"numero": 8, "texto": "If thou seest the oppression of the poor, and violent perverting of judgment and justice in a province, marvel not at the matter: for he that is higher than the highest regardeth; and there be higher than they."}, {"numero": 9, "texto": "Moreover the profit of the earth is for all: the king himself is served by the field."}, {"numero": 10, "texto": "He that loveth silver shall not be satisfied with silver; nor he that loveth abundance with increase: this is also vanity."}, {"numero": 11, "texto": "When goods increase, they are increased that eat them: and what good is there to the owners thereof, saving the beholding of them with their eyes?"}, {"numero": 12, "texto": "The sleep of a labouring man is sweet, whether he eat little or much: but the abundance of the rich will not suffer him to sleep."}, {"numero": 13, "texto": "There is a sore evil which I have seen under the sun, namely, riches kept for the owners thereof to their hurt."}, {"numero": 14, "texto": "But those riches perish by evil travail: and he begetteth a son, and there is nothing in his hand."}, {"numero": 15, "texto": "As he came forth of his mother''s womb, naked shall he return to go as he came, and shall take nothing of his labour, which he may carry away in his hand."}, {"numero": 16, "texto": "And this also is a sore evil, that in all points as he came, so shall he go: and what profit hath he that hath laboured for the wind?"}, {"numero": 17, "texto": "All his days also he eateth in darkness, and he hath much sorrow and wrath with his sickness."}, {"numero": 18, "texto": "Behold that which I have seen: it is good and comely for one to eat and to drink, and to enjoy the good of all his labour that he taketh under the sun all the days of his life, which God giveth him: for it is his portion."}, {"numero": 19, "texto": "Every man also to whom God hath given riches and wealth, and hath given him power to eat thereof, and to take his portion, and to rejoice in his labour; this is the gift of God."}, {"numero": 20, "texto": "For he shall not much remember the days of his life; because God answereth him in the joy of his heart."}]'::jsonb, 'King James Version'),
  ('Ec', 5, 'fr', '[{"numero": 1, "texto": "Prends garde à ton pied, lorsque tu entres dans la maison de Dieu; approche-toi pour écouter, plutôt que pour offrir le sacrifice des insensés, car ils ne savent pas qu''''ils font mal."}, {"numero": 2, "texto": "Ne te presse pas d''''ouvrir la bouche, et que ton coeur ne se hâte pas d''''exprimer une parole devant Dieu; car Dieu est au ciel, et toi sur la terre: que tes paroles soient donc peu nombreuses."}, {"numero": 3, "texto": "Car, si les songes naissent de la multitude des occupations, la voix de l''''insensé se fait entendre dans la multitude des paroles."}, {"numero": 4, "texto": "Lorsque tu as fait un voeu à Dieu, ne tarde pas à l''''accomplir, car il n''''aime pas les insensés: accomplis le voeu que tu as fait."}, {"numero": 5, "texto": "Mieux vaut pour toi ne point faire de voeu, que d''''en faire un et de ne pas l''''accomplir."}, {"numero": 6, "texto": "Ne permets pas à ta bouche de faire pécher ta chair, et ne dis pas en présence de l''''envoyé que c''''est une inadvertance. Pourquoi Dieu s''''irriterait-il de tes paroles, et détruirait-il l''''ouvrage de tes mains?"}, {"numero": 7, "texto": "Car, s''''il y a des vanités dans la multitude des songes, il y en a aussi dans beaucoup de paroles; c''''est pourquoi, crains Dieu."}, {"numero": 8, "texto": "Si tu vois dans une province le pauvre opprimé et la violation du droit et de la justice, ne t''''en étonne point; car un homme élevé est placé sous la surveillance d''''un autre plus élevé, et au-dessus d''''eux il en est de plus élevés encore."}, {"numero": 9, "texto": "Un avantage pour le pays à tous égards, c''''est un roi honoré du pays."}, {"numero": 10, "texto": "Celui qui aime l''''argent n''''est pas rassasié par l''''argent, et celui qui aime les richesses n''''en profite pas. C''''est encore là une vanité."}, {"numero": 11, "texto": "Quand le bien abonde, ceux qui le mangent abondent; et quel avantage en revient-il à son possesseur, sinon qu''''il le voit de ses yeux?"}, {"numero": 12, "texto": "Le sommeil du travailleur est doux, qu''''il ait peu ou beaucoup à manger; mais le rassasiement du riche ne le laisse pas dormir."}, {"numero": 13, "texto": "Il est un mal grave que j''''ai vu sous le soleil: des richesses conservées, pour son malheur, par celui qui les possède."}, {"numero": 14, "texto": "Ces richesses se perdent par quelque événement fâcheux; il a engendré un fils, et il ne reste rien entre ses mains."}, {"numero": 15, "texto": "Comme il est sorti du ventre de sa mère, il s''''en retourne nu ainsi qu''''il était venu, et pour son travail n''''emporte rien qu''''il puisse prendre dans sa main."}, {"numero": 16, "texto": "C''''est encore là un mal grave. Il s''''en va comme il était venu; et quel avantage lui revient-il d''''avoir travaillé pour du vent?"}, {"numero": 17, "texto": "De plus, toute sa vie il mange dans les ténèbres, et il a beaucoup de chagrin, de maux et d''''irritation."}, {"numero": 18, "texto": "Voici ce que j''''ai vu: c''''est pour l''''homme une chose bonne et belle de manger et de boire, et de jouir du bien-être au milieu de tout le travail qu''''il fait sous le soleil, pendant le nombre des jours de vie que Dieu lui a donnés; car c''''est là sa part."}, {"numero": 19, "texto": "Mais, si Dieu a donné à un homme des richesses et des biens, s''''il l''''a rendu maître d''''en manger, d''''en prendre sa part, et de se réjouir au milieu de son travail, c''''est là un don de Dieu."}, {"numero": 20, "texto": "Car il ne se souviendra pas beaucoup des jours de sa vie, parce que Dieu répand la joie dans son coeur."}]'::jsonb, 'Louis Segond 1910'),
  ('Ec', 5, 'es', '[{"numero": 1, "texto": "CUANDO fueres á la casa de Dios, guarda tu pie; y acércate más para oir que para dar el sacrificio de los necios: porque no saben que hacen mal."}, {"numero": 2, "texto": "No te des priesa con tu boca, ni tu corazón se apresure á proferir palabra delante de Dios; porque Dios está en el cielo, y tú sobre la tierra: por tanto, sean pocas tus palabras."}, {"numero": 3, "texto": "Porque de la mucha ocupación viene el sueño, y de la multitud de las palabras la voz del necio."}, {"numero": 4, "texto": "Cuando á Dios hicieres promesa, no tardes en pagarla; porque no se agrada de los insensatos. Paga lo que prometieres."}, {"numero": 5, "texto": "Mejor es que no prometas, que no que prometas y no pagues."}, {"numero": 6, "texto": "No sueltes tu boca para hacer pecar á tu carne; ni digas delante del ángel, que fué ignorancia. ¿Por qué harás que Dios se aire á causa de tu voz, y que destruya la obra de tus manos?"}, {"numero": 7, "texto": "Donde los sueños son en multitud, también lo son las vanidades y muchas las palabras; mas tú teme á Dios."}, {"numero": 8, "texto": "Si violencias de pobres, y extorsión de derecho y de justicia vieres en la provincia, no te maravilles de esta licencia; porque alto está mirando sobre alto, y uno más alto está sobre ellos."}, {"numero": 9, "texto": "Además el provecho de la tierra es para todos: el rey mismo está sujeto á los campos."}, {"numero": 10, "texto": "El que ama el dinero, no se hartará de dinero; y el que ama el mucho tener, no sacará fruto. También esto es vanidad."}, {"numero": 11, "texto": "Cuando los bienes se aumentan, también se aumentan sus comedores. ¿Qué bien, pues, tendrá su dueño, sino verlos con sus ojos?"}, {"numero": 12, "texto": "Dulce es el sueño del trabajador, ora coma mucho ó poco; mas al rico no le deja dormir la hartura."}, {"numero": 13, "texto": "Hay una trabajosa enfermedad que he visto debajo del sol: las riquezas guardadas de sus dueños para su mal;"}, {"numero": 14, "texto": "Las cuales se pierden en malas ocupaciones, y á los hijos que engendraron nada les queda en la mano."}, {"numero": 15, "texto": "Como salió del vientre de su madre, desnudo, así se vuelve, tornando como vino; y nada tuvo de su trabajo para llevar en su mano."}, {"numero": 16, "texto": "Este también es un gran mal, que como vino, así haya de volver. ¿Y de qué le aprovechó trabajar al viento?"}, {"numero": 17, "texto": "Demás de esto, todos los días de su vida comerá en tinieblas, con mucho enojo y dolor y miseria."}, {"numero": 18, "texto": "He aquí pues el bien que yo he visto: Que lo bueno es comer y beber, y gozar uno del bien de todo su trabajo con que se fatiga debajo del sol, todos los días de su vida que Dios le ha dado; porque esta es su parte."}, {"numero": 19, "texto": "Asimismo, á todo hombre á quien Dios dió riquezas y hacienda, y le dió también facultad para que coma de ellas, y tome su parte, y goce su trabajo; esto es don de Dios."}, {"numero": 20, "texto": "Porque no se acordará mucho de los días de su vida; pues Dios le responderá con alegría de su corazón."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ec', 7, 'pt', '[{"numero": 1, "texto": "Melhor é uma boa reputação do que o bom óleo perfumado; e o dia da morte [é melhor] que o dia de seu nascimento"}, {"numero": 2, "texto": "Melhor é ir à casa do luto do que a casa do banquete, [porque] isto é o fim de todos os homens; e os vivos tomam isto em seus corações."}, {"numero": 3, "texto": "Melhor é o sofrimento do que o riso, porque com a tristeza do rosto o coração se aperfeiçoa."}, {"numero": 4, "texto": "O coração dos sábios está na casa do luto, mas o coração dos tolos [está] na casa da alegria."}, {"numero": 5, "texto": "Melhor é ouvir a repreensão do sábio do que alguém ouvir a canção dos tolos;"}, {"numero": 6, "texto": "Pois o riso dos tolos é como o ruído de espinhos debaixo de uma panela; também isto é futilidade."}, {"numero": 7, "texto": "Verdadeiramente a opressão faz até o sábio enlouquecer, e o suborno corrompe o coração."}, {"numero": 8, "texto": "Melhor é o fim das coisas do que o princípio delas; melhor é o paciente de espírito do que o arrogante de espírito."}, {"numero": 9, "texto": "Não te apresses em teu espírito para te irares, porque a ira repousa no colo dos tolos."}, {"numero": 10, "texto": "Nunca digas: Por que os dias passados foram melhores que os atuais? Pois nunca com sabedoria perguntarias isso."}, {"numero": 11, "texto": "A sabedoria é tão boa quanto uma herança; ela é um proveito para os que veem a luz do sol;"}, {"numero": 12, "texto": "porque a sabedoria serve de proteção, assim como o dinheiro serve de proteção; mas a vantagem do conhecimento é que a sabedoria dá vida ao seu dono."}, {"numero": 13, "texto": "Observa a obra de Deus, pois quem poderá endireitar o que ele entortou?"}, {"numero": 14, "texto": "No dia da prosperidade, alegra-te; mas no dia da adversidade, considera; pois Deus faz um em contraposição ao outro, para que o homem não consiga descobrir o que haverá depois dele."}, {"numero": 15, "texto": "Tudo [isto] vi nos meus dias de futilidade: há justo que perece em sua justiça, e há perverso que prolonga [sua vida] em sua maldade."}, {"numero": 16, "texto": "Não sejas justo demais, nem sejas sábio demais; para que destruirias a ti mesmo?"}, {"numero": 17, "texto": "Não sejas perverso demais, nem sejas tolo; para que morrerias antes de teu tempo?"}, {"numero": 18, "texto": "É bom que retenhas isto, e também não retires tua mão disto, pois quem teme a Deus escapa de tudo isto."}, {"numero": 19, "texto": "A sabedoria fortalece ao sábio, mais do que dez homens de autoridade que estejam na cidade."}, {"numero": 20, "texto": "Verdadeiramente não há homem justo sobre a terra, que faça o bem, e nunca peque."}, {"numero": 21, "texto": "Além disso, não dês atenção a todas as palavras que forem ditas, para que não venhas a ouvir que teu servo te amaldiçoa;"}, {"numero": 22, "texto": "Pois teu coração sabe que também tu já amaldiçoaste a outros."}, {"numero": 23, "texto": "Tudo isto investiguei com sabedoria. Eu disse: Terei para mim mais sabedoria;porém ela ficava [ainda] mais longe de mim."}, {"numero": 24, "texto": "Quem pode encontrar o que está distante e tão profundo?"}, {"numero": 25, "texto": "Decidi em meu coração conhecer, investigar e buscar a sabedoria e a razão; e saber o mal que há na tolice e na loucura das maluquices."}, {"numero": 26, "texto": "E eu encontrei uma coisa mais amarga que a morte: a mulher cujo coração são redes e armadilhas, e suas mãos são amarras; quem for bom perante Deus escapará dela; mas o pecador ficará preso nela."}, {"numero": 27, "texto": "Olha isto:(diz o pregador, enquanto ele procurava entender [as coisas] ,uma por uma)"}, {"numero": 28, "texto": "Aquilo que minha alma tem buscado, ainda não achei; um homem entre mil eu achei; mas uma mulher entre todas estas não achei."}, {"numero": 29, "texto": "Eis que somente achei isto: que Deus fez os homens corretos, porém foram eles que buscaram muitos desejos ruins."}]'::jsonb, 'Almeida Livre'),
  ('Ec', 7, 'en', '[{"numero": 1, "texto": "A good name is better than precious ointment; and the day of death than the day of one''s birth."}, {"numero": 2, "texto": "It is better to go to the house of mourning, than to go to the house of feasting: for that is the end of all men; and the living will lay it to his heart."}, {"numero": 3, "texto": "Sorrow is better than laughter: for by the sadness of the countenance the heart is made better."}, {"numero": 4, "texto": "The heart of the wise is in the house of mourning; but the heart of fools is in the house of mirth."}, {"numero": 5, "texto": "It is better to hear the rebuke of the wise, than for a man to hear the song of fools."}, {"numero": 6, "texto": "For as the crackling of thorns under a pot, so is the laughter of the fool: this also is vanity."}, {"numero": 7, "texto": "Surely oppression maketh a wise man mad; and a gift destroyeth the heart."}, {"numero": 8, "texto": "Better is the end of a thing than the beginning thereof: and the patient in spirit is better than the proud in spirit."}, {"numero": 9, "texto": "Be not hasty in thy spirit to be angry: for anger resteth in the bosom of fools."}, {"numero": 10, "texto": "Say not thou, What is the cause that the former days were better than these? for thou dost not enquire wisely concerning this."}, {"numero": 11, "texto": "Wisdom is good with an inheritance: and by it there is profit to them that see the sun."}, {"numero": 12, "texto": "For wisdom is a defence, and money is a defence: but the excellency of knowledge is, that wisdom giveth life to them that have it."}, {"numero": 13, "texto": "Consider the work of God: for who can make that straight, which he hath made crooked?"}, {"numero": 14, "texto": "In the day of prosperity be joyful, but in the day of adversity consider: God also hath set the one over against the other, to the end that man should find nothing after him."}, {"numero": 15, "texto": "All things have I seen in the days of my vanity: there is a just man that perisheth in his righteousness, and there is a wicked man that prolongeth his life in his wickedness."}, {"numero": 16, "texto": "Be not righteous over much; neither make thyself over wise: why shouldest thou destroy thyself ?"}, {"numero": 17, "texto": "Be not over much wicked, neither be thou foolish: why shouldest thou die before thy time?"}, {"numero": 18, "texto": "It is good that thou shouldest take hold of this; yea, also from this withdraw not thine hand: for he that feareth God shall come forth of them all."}, {"numero": 19, "texto": "Wisdom strengtheneth the wise more than ten mighty men which are in the city."}, {"numero": 20, "texto": "For there is not a just man upon earth, that doeth good, and sinneth not."}, {"numero": 21, "texto": "Also take no heed unto all words that are spoken; lest thou hear thy servant curse thee:"}, {"numero": 22, "texto": "For oftentimes also thine own heart knoweth that thou thyself likewise hast cursed others."}, {"numero": 23, "texto": "All this have I proved by wisdom: I said, I will be wise; but it was far from me."}, {"numero": 24, "texto": "That which is far off, and exceeding deep, who can find it out?"}, {"numero": 25, "texto": "I applied mine heart to know, and to search, and to seek out wisdom, and the reason of things, and to know the wickedness of folly, even of foolishness and madness:"}, {"numero": 26, "texto": "And I find more bitter than death the woman, whose heart is snares and nets, and her hands as bands: whoso pleaseth God shall escape from her; but the sinner shall be taken by her."}, {"numero": 27, "texto": "Behold, this have I found, saith the preacher, counting one by one, to find out the account:"}, {"numero": 28, "texto": "Which yet my soul seeketh, but I find not: one man among a thousand have I found; but a woman among all those have I not found."}, {"numero": 29, "texto": "Lo, this only have I found, that God hath made man upright; but they have sought out many inventions."}]'::jsonb, 'King James Version'),
  ('Ec', 7, 'fr', '[{"numero": 1, "texto": "Une bonne réputation vaut mieux que le bon parfum, et le jour de la mort que le jour de la naissance."}, {"numero": 2, "texto": "Mieux vaut aller dans une maison de deuil que d''''aller dans une maison de festin; car c''''est là la fin de tout homme, et celui qui vit prend la chose à coeur."}, {"numero": 3, "texto": "Mieux vaut le chagrin que le rire; car avec un visage triste le coeur peut être content."}, {"numero": 4, "texto": "Le coeur des sages est dans la maison de deuil, et le coeur des insensés dans la maison de joie."}, {"numero": 5, "texto": "Mieux vaut entendre la réprimande du sage que d''''entendre le chant des insensés."}, {"numero": 6, "texto": "Car comme le bruit des épines sous la chaudière, ainsi est le rire des insensés. C''''est encore là une vanité."}, {"numero": 7, "texto": "L''''oppression rend insensé le sage, et les présents corrompent le coeur."}, {"numero": 8, "texto": "Mieux vaut la fin d''''une chose que son commencement; mieux vaut un esprit patient qu''''un esprit hautain."}, {"numero": 9, "texto": "Ne te hâte pas en ton esprit de t''''irriter, car l''''irritation repose dans le sein des insensés."}, {"numero": 10, "texto": "Ne dis pas: D''''où vient que les jours passés étaient meilleurs que ceux ci? Car ce n''''est point par sagesse que tu demandes cela."}, {"numero": 11, "texto": "La sagesse vaut autant qu''''un héritage, et même plus pour ceux qui voient le soleil."}, {"numero": 12, "texto": "Car à l''''ombre de la sagesse on est abrité comme à l''''ombre de l''''argent; mais un avantage de la science, c''''est que la sagesse fait vivre ceux qui la possèdent."}, {"numero": 13, "texto": "Regarde l''''oeuvre de Dieu: qui pourra redresser ce qu''''il a courbé?"}, {"numero": 14, "texto": "Au jour du bonheur, sois heureux, et au jour du malheur, réfléchis: Dieu a fait l''''un comme l''''autre, afin que l''''homme ne découvre en rien ce qui sera après lui."}, {"numero": 15, "texto": "J''''ai vu tout cela pendant les jours de ma vanité. Il y a tel juste qui périt dans sa justice, et il y a tel méchant qui prolonge son existence dans sa méchanceté."}, {"numero": 16, "texto": "Ne sois pas juste à l''''excès, et ne te montre pas trop sage: pourquoi te détruirais-tu?"}, {"numero": 17, "texto": "Ne sois pas méchant à l''''excès, et ne sois pas insensé: pourquoi mourrais-tu avant ton temps?"}, {"numero": 18, "texto": "Il est bon que tu retiennes ceci, et que tu ne négliges point cela; car celui qui craint Dieu échappe à toutes ces choses."}, {"numero": 19, "texto": "La sagesse rend le sage plus fort que dix chefs qui sont dans une ville."}, {"numero": 20, "texto": "Non, il n''''y a sur la terre point d''''homme juste qui fasse le bien et qui ne pèche jamais."}, {"numero": 21, "texto": "Ne fais donc pas attention à toutes les paroles qu''''on dit, de peur que tu n''''entendes ton serviteur te maudire;"}, {"numero": 22, "texto": "car ton coeur a senti bien des fois que tu as toi-même maudit les autres."}, {"numero": 23, "texto": "J''''ai éprouvé tout cela par la sagesse. J''''ai dit: Je serai sage. Et la sagesse est restée loin de moi."}, {"numero": 24, "texto": "Ce qui est loin, ce qui est profond, profond, qui peut l''''atteindre?"}, {"numero": 25, "texto": "Je me suis appliqué dans mon coeur à connaître, à sonder, et à chercher la sagesse et la raison des choses, et à connaître la folie de la méchanceté et la stupidité de la sottise."}, {"numero": 26, "texto": "Et j''''ai trouvé plus amère que la mort la femme dont le coeur est un piège et un filet, et dont les mains sont des liens; celui qui est agréable à Dieu lui échappe, mais le pécheur est pris par elle."}, {"numero": 27, "texto": "Voici ce que j''''ai trouvé, dit l''''Ecclésiaste, en examinant les choses une à une pour en saisir la raison;"}, {"numero": 28, "texto": "voici ce que mon âme cherche encore, et que je n''''ai point trouvé. J''''ai trouvé un homme entre mille; mais je n''''ai pas trouvé une femme entre elles toutes."}, {"numero": 29, "texto": "Seulement, voici ce que j''''ai trouvé, c''''est que Dieu a fait les hommes droits; mais ils ont cherché beaucoup de détours."}]'::jsonb, 'Louis Segond 1910'),
  ('Ec', 7, 'es', '[{"numero": 1, "texto": "MEJOR es la buena fama que el buen ungüento; y el día de la muerte que el día del nacimiento."}, {"numero": 2, "texto": "Mejor es ir á la casa del luto que á la casa del convite: porque aquello es el fin de todos los hombres; y el que vive parará mientes."}, {"numero": 3, "texto": "Mejor es el enojo que la risa: porque con la tristeza del rostro se enmendará el corazón."}, {"numero": 4, "texto": "El corazón de los sabios, en la casa del luto; mas el corazón de los insensatos, en la casa del placer."}, {"numero": 5, "texto": "Mejor es oir la reprensión del sabio, que la canción de los necios."}, {"numero": 6, "texto": "Porque la risa del necio es como el estrépito de las espinas debajo de la olla. Y también esto es vanidad."}, {"numero": 7, "texto": "Ciertamente la opresión hace enloquecer al sabio: y el presente corrompe el corazón."}, {"numero": 8, "texto": "Mejor es el fin del negocio que su principio: mejor es el sufrido de espíritu que el altivo de espíritu."}, {"numero": 9, "texto": "No te apresures en tu espíritu á enojarte: porque la ira en el seno de los necios reposa."}, {"numero": 10, "texto": "Nunca digas: ¿Qué es la causa que los tiempos pasados fueron mejores que éstos? Porque nunca de esto preguntarás con sabiduría."}, {"numero": 11, "texto": "Buena es la ciencia con herencia; y más á los que ven el sol."}, {"numero": 12, "texto": "Porque escudo es la ciencia, y escudo es el dinero: mas la sabiduría excede en que da vida á sus poseedores."}, {"numero": 13, "texto": "Mira la obra de Dios; porque ¿quién podrá enderezar lo que él torció?"}, {"numero": 14, "texto": "En el día del bien goza del bien; y en el día del mal considera. Dios también hizo esto delante de lo otro, porque el hombre no halle nada tras de él."}, {"numero": 15, "texto": "Todo esto he visto en los días de mi vanidad. Justo hay que perece por su justicia, y hay impío que por su maldad alarga sus días."}, {"numero": 16, "texto": "No seas demasiado justo, ni seas sabio con exceso: ¿por qué te destruirás?"}, {"numero": 17, "texto": "No hagas mal mucho, ni seas insensato: ¿por qué morirás antes de tu tiempo?"}, {"numero": 18, "texto": "Bueno es que tomes esto, y también de estotro no apartes tu mano; porque el que á Dios teme, saldrá con todo."}, {"numero": 19, "texto": "La sabiduría fortifica al sabio más que diez poderosos la ciudad en que fueron."}, {"numero": 20, "texto": "Ciertamente no hay hombre justo en la tierra, que haga bien y nunca peque."}, {"numero": 21, "texto": "Tampoco apliques tu corazón á todas las cosas que se hablaren, porque no oigas á tu siervo que dice mal de ti:"}, {"numero": 22, "texto": "Porque tu corazón sabe, como tú también dijiste mal de otros muchas veces."}, {"numero": 23, "texto": "Todas estas cosas probé con sabiduría, diciendo: Hacerme he sabio: mas ella se alejó de mí."}, {"numero": 24, "texto": "Lejos está lo que fué; y lo muy profundo ¿quién lo hallará?"}, {"numero": 25, "texto": "Yo he rodeado con mi corazón por saber, y examinar, é inquirir la sabiduría, y la razón; y por conocer la maldad de la insensatez, y el desvarío del error;"}, {"numero": 26, "texto": "Y yo he hallado más amarga que la muerte la mujer, la cual es redes, y lazos su corazón; sus manos como ligaduras. El que agrada á Dios escapará de ella; mas el pecador será preso en ella."}, {"numero": 27, "texto": "He aquí, esto he hallado, dice el Predicador, pesando las cosas una por una para hallar la razón;"}, {"numero": 28, "texto": "Lo que aun busca mi alma, y no encuentro: un hombre entre mil he hallado; mas mujer de todas éstas nunca hallé."}, {"numero": 29, "texto": "He aquí, solamente he hallado esto: que Dios hizo al hombre recto, mas ellos buscaron muchas cuentas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ec', 11, 'pt', '[{"numero": 1, "texto": "Lança teu pão sobre as águas, porque depois de muitos dias tu o encontrarás."}, {"numero": 2, "texto": "Dá uma parte a sete, e até a oito; porque não sabes que mal haverá sobre a terra."}, {"numero": 3, "texto": "Se as nuvens estiverem cheias, há chuva sobre a terra; e se a árvore cair, seja para ou sul ou seja para o norte, no lugar em que a árvore cair, ali ela ficará."}, {"numero": 4, "texto": "Quem ficar dando atenção ao vento, nunca semeará; e o que olhar para as nuvens nunca ceifará."}, {"numero": 5, "texto": "Assim como tu não sabes qual é o caminho do vento, [nem] como se formam os ossos [do feto] no ventre da grávida, assim também tu não sabes a obra de Deus, que faz todas as coisas."}, {"numero": 6, "texto": "Pela manhã semeia tua semente, e à tarde não retires tua mão; pois tu não sabes qual [tentativa] dará certo, se uma, se outra, ou se ambas [as tentativas] serão boas."}, {"numero": 7, "texto": "Certamente a luz é agradável, e ver o sol é bom para os olhos."}, {"numero": 8, "texto": "Mesmo se o homem viver muitos anos, [e] em todos eles se alegrar, ele também deve se lembrar dos dias de trevas, porque serão muitos. Tudo o que acontece é futilidade."}, {"numero": 9, "texto": "Alegra-te, rapaz, em tua juventude; e agrada o teu coração nos dias de tua juventude; e anda pelos caminhos do teu coração, e na vista de teus olhos; sabe, porém, que por todas estas coisas, Deus te trará a julgamento."}, {"numero": 10, "texto": "[Portanto] afasta o desagrado de teu coração, e tira de tua carne o mal; pois a adolescência e a juventude são futilidade."}]'::jsonb, 'Almeida Livre'),
  ('Ec', 11, 'en', '[{"numero": 1, "texto": "Cast thy bread upon the waters: for thou shalt find it after many days."}, {"numero": 2, "texto": "Give a portion to seven, and also to eight; for thou knowest not what evil shall be upon the earth."}, {"numero": 3, "texto": "If the clouds be full of rain, they empty themselves upon the earth: and if the tree fall toward the south, or toward the north, in the place where the tree falleth, there it shall be."}, {"numero": 4, "texto": "He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap."}, {"numero": 5, "texto": "As thou knowest not what is the way of the spirit, nor how the bones do grow in the womb of her that is with child: even so thou knowest not the works of God who maketh all."}, {"numero": 6, "texto": "In the morning sow thy seed, and in the evening withhold not thine hand: for thou knowest not whether shall prosper, either this or that, or whether they both shall be alike good."}, {"numero": 7, "texto": "Truly the light is sweet, and a pleasant thing it is for the eyes to behold the sun:"}, {"numero": 8, "texto": "But if a man live many years, and rejoice in them all; yet let him remember the days of darkness; for they shall be many. All that cometh is vanity."}, {"numero": 9, "texto": "Rejoice, O young man, in thy youth; and let thy heart cheer thee in the days of thy youth, and walk in the ways of thine heart, and in the sight of thine eyes: but know thou, that for all these things God will bring thee into judgment."}, {"numero": 10, "texto": "Therefore remove sorrow from thy heart, and put away evil from thy flesh: for childhood and youth are vanity."}]'::jsonb, 'King James Version'),
  ('Ec', 11, 'fr', '[{"numero": 1, "texto": "Jette ton pain sur la face des eaux, car avec le temps tu le retrouveras;"}, {"numero": 2, "texto": "donnes-en une part à sept et même à huit, car tu ne sais pas quel malheur peut arriver sur la terre."}, {"numero": 3, "texto": "Quand les nuages sont pleins de pluie, ils la répandent sur la terre; et si un arbre tombe, au midi ou au nord, il reste à la place où il est tombé."}, {"numero": 4, "texto": "Celui qui observe le vent ne sèmera point, et celui qui regarde les nuages ne moissonnera point."}, {"numero": 5, "texto": "Comme tu ne sais pas quel est le chemin du vent, ni comment se forment les os dans le ventre de la femme enceinte, tu ne connais pas non plus l''''oeuvre de Dieu qui fait tout."}, {"numero": 6, "texto": "Dès le matin sème ta semence, et le soir ne laisse pas reposer ta main; car tu ne sais point ce qui réussira, ceci ou cela, ou si l''''un et l''''autre sont également bons."}, {"numero": 7, "texto": "La lumière est douce, et il est agréable aux yeux de voir le soleil."}, {"numero": 8, "texto": "Si donc un homme vit beaucoup d''''années, qu''''il se réjouisse pendant toutes ces années, et qu''''il pense aux jours de ténèbres qui seront nombreux; tout ce qui arrivera est vanité."}, {"numero": 9, "texto": "Jeune homme, réjouis-toi dans ta jeunesse, livre ton coeur à la joie pendant les jours de ta jeunesse, marche dans les voies de ton coeur et selon les regards de tes yeux; mais sache que pour tout cela Dieu t''''appellera en jugement."}, {"numero": 10, "texto": "Bannis de ton coeur le chagrin, et éloigne le mal de ton corps; car la jeunesse et l''''aurore sont vanité."}]'::jsonb, 'Louis Segond 1910'),
  ('Ec', 11, 'es', '[{"numero": 1, "texto": "ECHA tu pan sobre las aguas; que después de muchos días lo hallarás."}, {"numero": 2, "texto": "Reparte á siete, y aun á ocho: porque no sabes el mal que vendrá sobre la tierra."}, {"numero": 3, "texto": "Si las nubes fueren llenas de agua, sobre la tierra la derramarán: y si el árbol cayere al mediodía, ó al norte, al lugar que el árbol cayere, allí quedará."}, {"numero": 4, "texto": "El que al viento mira, no sembrará; y el que mira á las nubes, no segará."}, {"numero": 5, "texto": "Como tú no sabes cuál es el camino del viento, ó cómo se crían los huesos en el vientre de la mujer preñada, así ignoras la obra de Dios, el cual hace todas las cosas."}, {"numero": 6, "texto": "Por la mañana siembra tu simiente, y á la tarde no dejes reposar tu mano: porque tú no sabes cuál es lo mejor, si esto ó lo otro, ó si ambas á dos cosas son buenas."}, {"numero": 7, "texto": "Suave ciertamente es la luz, y agradable á los ojos ver el sol:"}, {"numero": 8, "texto": "Mas si el hombre viviere muchos años, y en todos ellos hubiere gozado alegría; si después trajere á la memoria los días de las tinieblas, que serán muchos, todo lo que le habrá pasado, dirá haber sido vanidad."}, {"numero": 9, "texto": "Alégrate, mancebo, en tu mocedad, y tome placer tu corazón en los días de tu juventud; y anda en los caminos de tu corazón, y en la vista de tus ojos: mas sabe, que sobre todas estas cosas te traerá Dios á juicio."}, {"numero": 10, "texto": "Quita pues el enojo de tu corazón, y aparta el mal de tu carne: porque la mocedad y la juventud son vanidad."}]'::jsonb, 'Reina-Valera 1909')
